    void routeToStartSpot() {
        PluginConfigResponse cfg = pluginConfig;
        WorldPoint target = cfg == null ? null : StartSpotMarker.target(cfg.startProof);
        clientThread.invokeLater(() -> startSpotMarker.route(target));
