		capH(modes);
		styleLookupModes();
		lookupPanel.add(modes);
		lookupPanel.add(gap(6));
		lookupPanel.add(lookupBox);
		lookupPanel.add(gap(6));
		lookupPanel.add(lookupRecentRow);
		lookupPanel.add(lookupResult);
		lookupResult.add(cardMessage(LOOKUP_HINT));
