	private void addGoal()
	{
		GoalsView.NewGoal goal = GoalsView.ask(this, youCard);
		if (goal == null)
		{
			return;
		}
		async(() -> dataSource.addGoal(goal.kind, goal.metric, goal.target, goal.dueOn), r -> applyGoals(r, true));
