	/**
	 * POST /api/events/{eventId}/submissions — submits a drop with image proof.
	 */
	/**
	 * A submission the server rejected for good — the tile's already complete, the event ended, the
	 * data's invalid — so retrying it will never succeed. The retry loop drops these instead of
	 * looping forever (the "Get 5M in PvP Loot already complete, keeps retrying" bug).
	 */
	public static class PermanentSubmissionException extends IOException
	{
		PermanentSubmissionException(String message)
		{
			super(message);
		}
	}

	/** 4xx client errors are permanent (don't retry) — except auth (401, token may refresh), request
	 *  timeout (408) and rate-limit (429), which can clear on their own. 5xx / network = retryable. */
	private static boolean isPermanentFailure(int code)
	{
		return RetryPolicy.isPermanent(code);
	}

	/**
	 * The one 4xx that is NOT permanent: the site requires a starting shot (site lib/startProof) and
	 * this player hasn't filed one yet. The drop really happened — throwing it away because a
	 * screenshot is outstanding is the worst possible outcome — so it stays in the pending store and
	 * goes up on a later retry, once they've taken their shot.
	 */
	static final String START_PROOF_REQUIRED = "start_proof_required";

	/**
	 * A server that told us to wait, and for how long.
	 *
	 * The site limits a whole-log push to one a minute per member; a client that keeps firing into
	 * that learns nothing and costs the clan's server a request every time. Carrying the wait means
	 * the plugin can hold off instead of guessing, and tell the player a number.
	 */
	public static class RateLimitedException extends IOException
	{
		public final long retryAfterMs;

		RateLimitedException(String message, long retryAfterMs)
		{
			super(message);
			this.retryAfterMs = retryAfterMs;
		}
	}

	/**
	 * The server's own words, or a plain sentence when it didn't offer any.
	 *
	 * Responses are JSON; players are not. "HTTP 429 — {"error":"...","retryAfterMs":49445}" in a
	 * chat box is the shape of a bug report, not an explanation, so the message field is unwrapped
	 * and everything else gets a sentence written for a person.
	 */
	static String friendlyError(int code, String body)
	{
		// Not JSON, or not the shape we expect — fall through to the generic wording.
		String serverSaid = jsonString(jsonObject(body), "error");
		if (serverSaid != null && !serverSaid.isEmpty())
		{
			return serverSaid;
		}
		switch (code)
		{
			case 401:
			case 403:
				return "your account token isn't valid for this clan's site";
			case 404:
				return "this clan's site doesn't have that endpoint yet";
			case 413:
				return "that was too large for the site to accept";
			case 429:
				return "the site is asking us to slow down";
			default:
				return code >= 500 ? "the clan's site is having trouble" : "the site refused it (HTTP " + code + ")";
		}
	}

	/** Milliseconds the server asked us to wait, or 0 when it didn't say. */
	static long retryAfterFrom(String body)
	{
		// No hint; the caller falls back to its own backoff.
		try
		{
			return Math.max(0, jsonObject(body).get("retryAfterMs").getAsLong());
		}
		catch (RuntimeException e)
		{
			return 0;
		}
	}

	/**
	 * A failure a player will read: the site's own sentence, classified the same way as any other.
	 *
	 * The diagnostic form (status, body) still goes to the log via the caller — this is what ends up
	 * in a chat box, where a JSON blob is worse than saying nothing.
	 */
	private static IOException friendlyFailure(int code, String body)
	{
		return classified(friendlyError(code, body), code, body);
	}

	/** "context: HTTP n — body", classified for the retry loop (the rule is pinned in StartProofTest). */
	static IOException submissionError(String context, int code, String responseBody)
	{
		return classified(context + ": HTTP " + code + " — " + responseBody, code, responseBody);
	}

	private static IOException classified(String message, int code, String body)
	{
		boolean awaitingStartProof = body != null && body.contains(START_PROOF_REQUIRED);
		return isPermanentFailure(code) && !awaitingStartProof
			? new PermanentSubmissionException(message)
			: new IOException(message);
	}

	/**
	 * POST a JSON body to a clan route and return the response text.
	 *
	 * A refusal throws "{@code what}: HTTP n — body", classified for the retry loop when
	 * {@code classify} is set. A null {@code what} is the whole-log push's wording: the site's own
	 * sentence, not its JSON — a player reading chat should be told what to do, and
	 * "{"error":...,"retryAfterMs":49445}" tells them to file a bug.
	 */
	private String postJson(String path, JsonObject payload, String what, boolean classify) throws IOException
	{
		Request request = authedRequest(clanUrl(path)).post(json(payload)).build();
		try (Response response = httpClient.newCall(request).execute())
		{
			String body = bodyText(response);
			int code = response.code();
			if (response.isSuccessful())
			{
				return body;
			}
			if (what == null)
			{
				if (code == 429)
				{
					throw new RateLimitedException(friendlyError(429, body), retryAfterFrom(body));
				}
				log.debug("Collection log push refused: HTTP {} — {}", code, body);
				throw friendlyFailure(code, body);
			}
			String shown = body.isEmpty() ? "no body" : body;
			throw classify ? submissionError(what, code, shown) : new IOException(what + ": HTTP " + code + " — " + shown);
		}
	}

	/** {@code [{k: key, v: value}, …]} for every entry with both halves present. */
	private JsonArray pairs(Map<?, ? extends Number> map, String k, String v)
	{
		JsonArray out = new JsonArray();
		for (Map.Entry<?, ? extends Number> e : map.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null)
			{
				continue;
			}
			JsonObject o = new JsonObject();
			o.add(k, gson.toJsonTree(e.getKey()));
			o.addProperty(v, e.getValue());
			out.add(o);
		}
		return out;
	}

	/**
	 * POST /api/plugin/clog — push the WHOLE collection log as a flat obtained-item list.
	 *
	 * The page-by-page route sends what the player has drawn; this sends everything the server
	 * transmitted (see {@link ClogFullSync}). No page names travel: the site owns the catalogue and
	 * maps ids onto pages, so a Jagex reshuffle is a dataset rebuild there rather than a release here.
	 */
	/** What a whole-log push changed, so an automatic sync can stay quiet when it changed nothing. */
	public static final class ClogPushResult
	{
		public int added;
	}

	public ClogPushResult submitClogItems(Map<Integer, Integer> items) throws IOException
	{
		if (items == null || items.isEmpty())
		{
			return new ClogPushResult();
		}
		JsonObject payload = new JsonObject();
		payload.add("items", pairs(items, "id", "q"));
		String body = postJson("/api/plugin/clog", payload, null, false);
		try
		{
			ClogPushResult result = gson.fromJson(body, ClogPushResult.class);
			return result != null ? result : new ClogPushResult();
		}
		catch (RuntimeException ignored)
		{
			// An older site doesn't report counts. The push still worked; we just can't say what
			// it did, so an automatic sync stays quiet rather than guessing.
			return new ClogPushResult();
		}
	}

	/**
	 * POST /api/events/:id/start-proof — file this account's STARTING SHOT (site lib/startProof).
	 *
	 * The image has already been through {@link #uploadImage}; this hands over its URL plus the
	 * keyword we baked into the banner, which the server recomputes. A capture from an authenticated
	 * plugin whose keyword matches is accepted outright; anything else waits for staff.
	 *
	 * <p>The world position and session start ride along so the server can record what the two
	 * client-side checks (StartProofRules) saw — it re-measures both rather than trusting our
	 * verdict, and a shot that fails one lands `pending` instead of accepted. Both are optional:
	 * pass null when we can't answer, and the server simply doesn't run that check.
	 */
	public void submitStartProof(int eventId, String imageUrl, String keyword, String capturedAt,
		Integer x, Integer y, String loginAt) throws IOException
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("imageUrl", imageUrl);
		if (keyword != null)
		{
			payload.addProperty("keyword", keyword);
		}
		if (capturedAt != null)
		{
			payload.addProperty("capturedAt", capturedAt);
		}
		if (x != null && y != null)
		{
			payload.addProperty("x", x);
			payload.addProperty("y", y);
		}
		if (loginAt != null)
		{
			payload.addProperty("loginAt", loginAt);
		}
		postJson("/api/events/" + eventId + "/start-proof", payload, "Starting shot failed", true);
		log.info("Starting shot filed for event {}", eventId);
	}

	/**
	 * POST /api/events/{eventId}/submissions — submits a drop with image proof. {@code coop} is the
	 * shared-kill fingerprint (what this client could see of its company; the server correlates
	 * reports of the SAME kill, lib/coopRuns), null on everything else. {@code itemId} may be an item
	 * the plugin worked out rather than saw — a duplicate pet or champion's scroll, which the game
	 * never names. {@code inferred} is the reason the site stores so staff
	 * check it ("inferred_duplicate_pet" / "inferred_duplicate_scroll"); the credit still counts.
	 */
	public void submitDrop(int eventId, int tileId, int teamId, int amount, String imageUrl, String note,
		int creditPlayerId, Integer itemId, CoopFingerprint coop, String inferred) throws IOException
	{
		JsonObject payload = submission(tileId, teamId, amount, imageUrl, note, creditPlayerId);
		if (inferred != null)
		{
			payload.addProperty("inferred", inferred);
		}
		if (itemId != null)
		{
			payload.addProperty("itemId", itemId);
		}
		if (coop != null)
		{
			if (coop.teammates != null && !coop.teammates.isEmpty())
			{
				payload.add("coopGroup", gson.toJsonTree(coop.teammates));
			}
			if (coop.partySize > 1)
			{
				payload.addProperty("coopPartySize", coop.partySize);
			}
		}
		postJson("/api/events/" + eventId + "/submissions", payload, "Submission failed", true);
		log.info("Drop submitted successfully for tile {}", tileId);
	}

	/**
	 * POST /api/events/{eventId}/submissions — submits a timed-clear with image proof.
	 * amount is fixed at 1; the clear time (seconds) rides in durationSeconds. The server
	 * completes the tile when durationSeconds ≤ the tile's threshold.
	 */
	public void submitTimed(int eventId, int tileId, int teamId, int durationSeconds, String imageUrl, String note, int creditPlayerId) throws IOException
	{
		JsonObject payload = submission(tileId, teamId, 1, imageUrl, note, creditPlayerId);
		payload.addProperty("durationSeconds", durationSeconds);
		postJson("/api/events/" + eventId + "/submissions", payload, "Timed submission failed", true);
		log.info("Timed clear submitted successfully for tile {}", tileId);
	}

	private static JsonObject submission(int tileId, int teamId, int amount, String imageUrl, String note, int creditPlayerId)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("tileId", tileId);
		payload.addProperty("teamId", teamId);
		payload.addProperty("amount", amount);
		payload.addProperty("imageUrl", imageUrl);
		payload.addProperty("note", note);
		payload.addProperty("creditPlayerId", creditPlayerId);
		return payload;
	}

	/** What a client could see of its company at kill time. Both halves are best-effort. */
	public static final class CoopFingerprint
	{
		/** Lowercased RSNs of ROSTER teammates seen in the instance — empty when none could be named. */
		public final List<String> teammates;
		/** Instance/raid party headcount, which is reliable exactly where names aren't. 0 = unknown. */
		public final int partySize;

		public CoopFingerprint(List<String> teammates, int partySize)
		{
			this.teammates = teammates;
			this.partySize = partySize;
		}

		public boolean isEmpty()
		{
			return (teammates == null || teammates.isEmpty()) && partySize <= 1;
		}
	}

	/**
	 * POST /api/plugin/stats — real-time push of ABSOLUTE (idempotent) values, no screenshot. The
	 * event, team and player are resolved server-side from the account-token auth (Bearer + X-RSN +
	 * X-Account-Hash), so a caller can only ever report its own numbers; the server keeps
	 * max(hiscores, pushed) and the hourly hiscores cron reconciles, so a debounced "latest value" is
	 * all that's needed. Completes stat tiles instantly instead of waiting on the ~1h hiscores lag.
	 */
	private void submitStats(Map<String, Integer> values, String field, String key, String value, String what,
		String logged) throws IOException
	{
		if (values == null || values.isEmpty())
		{
			return;
		}
		JsonObject payload = new JsonObject();
		payload.add(field, pairs(values, key, value));
		// Classified: a permanent refusal (PermanentSubmissionException) stops CoalescedPush resending
		// the batch; a 401 (fired before X-RSN was stamped), 429 or 5xx stays a plain, retryable failure.
		postJson("/api/plugin/stats", payload, what, true);
		log.debug(logged, values.size());
	}

	/** Boss KC: {@code {"stats":[{"name":"<in-game boss name>","kc":<absolute count>}]}}. */
	public void submitStatKc(Map<String, Integer> counts) throws IOException
	{
		submitStats(counts, "stats", "name", "kc", "KC push failed", "Real-time KC pushed for {} boss(es)");
	}

	/** Skill XP: {@code {"skills":[{"name":"<skill>","xp":<absolute xp>}]}}. */
	public void submitStatXp(Map<String, Integer> xp) throws IOException
	{
		submitStats(xp, "skills", "name", "xp", "Skill XP push failed", "Real-time XP pushed for {} skill(s)");
	}

	/**
	 * The hiscores counters that are neither a boss nor a skill — clue completions per tier, Colosseum
	 * glory, collection-log slots: {@code {"activities":[{"key":"<site stat key>","value":<n>}]}}.
	 *
	 * <p>Unlike KC and XP, which send the name the game printed and let the server map it, these go by
	 * the site's own key — they're read from named varbits, so the plugin already knows which counter
	 * it holds. Unknown keys are dropped server-side rather than stored.
	 */
	public void submitStatActivities(Map<String, Integer> values) throws IOException
	{
		submitStats(values, "activities", "key", "value", "Activity push failed", "Real-time activity counts pushed for {} key(s)");
	}

	/**
	 * POST /api/plugin/coffer — one absolute in-game Clan Coffer transition. The event key makes a
	 * retry idempotent; the server also serializes distinct clients observing the same final balance.
	 */
	public void submitClanCoffer(String eventKey, ClanCofferTracker.Observation observation) throws IOException
	{
		if (observation == null)
		{
			return;
		}
		JsonObject payload = new JsonObject();
		payload.addProperty("eventKey", eventKey);
		payload.addProperty("kind", observation.kind.wire);
		payload.addProperty("beforeBalance", observation.beforeBalance);
		payload.addProperty("afterBalance", observation.afterBalance);
		payload.addProperty("actorConfirmed", observation.actorConfirmed);
		postJson("/api/plugin/coffer", payload, "Coffer sync failed", false);
		log.info("Clan Coffer {} synced: {} -> {}{}", observation.kind.wire,
			observation.beforeBalance, observation.afterBalance,
			observation.actorConfirmed ? " (local actor confirmed)" : "");
	}

	/**
	 * POST /api/plugin/counters — the fun end-of-event recap counters (total deaths, total loot GP and
	 * PvP kills for the active event). Body is {@code {"deaths":<n>,"lootGp":<gp>,"pvpKills":<n>}} with
	 * ABSOLUTE per-event totals.
	 * Idempotent like {@link #submitStatKc}: event/team/player resolved from the token, the server keeps
	 * max(stored, pushed) per counter, so a retry or client restart never double-counts. No screenshot.
	 * Purely cosmetic (superlatives only — never scoring).
	 */
	public void submitEventCounters(int deaths, long lootGp, int pvpKills, int biggestHit, int minutesPlayed, int caTasks) throws IOException
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("deaths", deaths);
		payload.addProperty("lootGp", lootGp);
		payload.addProperty("pvpKills", pvpKills);
		// Newer counters. A site that predates them ignores unknown JSON keys, so an updated plugin
		// keeps working against an older instance — the extra awards simply don't appear there.
		payload.addProperty("biggestHit", biggestHit);
		payload.addProperty("minutesPlayed", minutesPlayed);
		payload.addProperty("caTasks", caTasks);
		postJson("/api/plugin/counters", payload, "Counter push failed", false);
		log.debug("Recap counters pushed (deaths={}, lootGp={}, pvpKills={}, biggestHit={}, minutes={}, caTasks={})",
			deaths, lootGp, pvpKills, biggestHit, minutesPlayed, caTasks);
	}

	/**
	 * POST /api/plugin/progress — quest points, combat-achievement points/tier, diary counts.
	 *
	 * <p>Account state the hiscores never publish (site: lib/memberProgress). Only keys whose value
	 * actually moved since the last successful push are sent, so the steady state is no request at
	 * all; the server max-merges what does arrive, which makes a retry free and stops a client that
	 * read a varbit before the game populated it from walking somebody's account backwards.
	 *
	 * <p>This form carries an item list — every quest with its state, so the site can show which
	 * are left rather than only how many are done. Sent whole and only when it changed, since half a
	 * list is worse than none.
	 *
	 * <p>Never scoring: nothing here completes a tile or moves a standing.
	 */
	public void submitProgress(Map<String, Integer> progress, String itemCategory,
		List<AccountProgress.Item> items) throws IOException
	{
		submitProgress(progress, itemCategory, items, null, 0);
	}

	/**
	 * The same push, carrying the raw combat-achievement varps.
	 *
	 * <p>We send the numbers and the game's own point total; the site decodes which task each bit is
	 * and refuses the lot if the points don't reconcile. Nothing here knows what a combat task is,
	 * which is the point: the catalogue lives where it can be updated without a release.
	 */
	public void submitProgress(Map<String, Integer> progress, String itemCategory,
		List<AccountProgress.Item> items, Map<Integer, Integer> caVarps,
		int caPoints) throws IOException
	{
		boolean hasItems = itemCategory != null && items != null && !items.isEmpty();
		boolean hasVarps = caVarps != null && !caVarps.isEmpty() && caPoints > 0;
		// The game mode is not a progress row: rows are max-merged, and a mode goes down. It has
		// its own top-level field, which a server that doesn't know it simply ignores.
		Map<String, Integer> rest = new LinkedHashMap<>(progress == null ? Collections.emptyMap() : progress);
		Integer accountType = rest.remove(AccountProgress.ACCOUNT_TYPE_KEY);
		JsonArray rows = pairs(rest, "key", "value");
		if (rows.size() == 0 && !hasItems && !hasVarps && accountType == null)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("progress", rows);
		if (accountType != null)
		{
			payload.addProperty("accountType", accountType);
		}
		if (hasItems)
		{
			JsonArray itemRows = new JsonArray();
			for (AccountProgress.Item item : items)
			{
				if (item == null || item.name == null || item.name.isEmpty())
				{
					continue;
				}
				itemRows.add(gson.toJsonTree(item)); // {id, name, state}
			}
			JsonObject set = new JsonObject();
			set.addProperty("category", itemCategory);
			set.add("items", itemRows);
			JsonArray sets = new JsonArray();
			sets.add(set);
			payload.add("items", sets);
		}
		if (hasVarps)
		{
			payload.add("caVarps", gson.toJsonTree(caVarps)); // {"<varp id>": value}
			payload.addProperty("caPoints", caPoints);
		}
		String reply = postJson("/api/plugin/progress", payload, "Progress push failed", false);
		// The reply says what the server made of it — including, for combat achievements, whether
		// the bits reconciled against the point total and how many tasks it couldn't name. Logged
		// at INFO because when this feature is quiet the only alternative is guessing which half
		// went wrong, which has cost a day already.
		log.debug("Anvil progress pushed ({} key(s), {} varps): {}", rows.size(), hasVarps ? caVarps.size() : 0, reply);
	}

	/**
	 * POST /api/plugin/clog — collection-log pages the player has actually opened.
	 *
	 * <p>Sends ONLY obtained items, and only pages whose contents changed since the last successful
	 * push ({@link ClogSync} owns that decision). The site already ships the full item catalogue, so
	 * the missing half is derivable — transmitting it would double every payload to say "still
	 * nothing here".
	 *
	 * <p>Idempotent: the server keys on (member, page) and replaces, so a retry or a client restart
	 * mid-sync costs nothing. Profile data only — never scoring.
	 */
	public void submitClogPages(List<ClogPage> pages, int syncedPages) throws IOException
	{
		if (pages == null || pages.isEmpty())
		{
			return;
		}
		JsonArray out = new JsonArray();
		for (ClogPage page : pages)
		{
			if (page == null || page.name == null || page.name.isEmpty())
			{
				continue;
			}
			JsonArray items = new JsonArray();
			for (int i = 0; i < page.itemIds.length; i++)
			{
				JsonObject item = new JsonObject();
				item.addProperty("id", page.itemIds[i]);
				item.addProperty("q", page.quantities[i]);
				items.add(item);
			}
			JsonObject p = new JsonObject();
			p.addProperty("name", page.name);
			p.addProperty("obtained", page.obtained);
			p.addProperty("total", page.total);
			p.add("items", items);
			if (!page.counts.isEmpty())
			{
				p.add("counts", gson.toJsonTree(page.counts));
			}
			out.add(p);
		}
		if (out.size() == 0)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("pages", out);
		// How much of the log this account has opened at all — drives the site's "68% synced" note.
		payload.addProperty("syncedPages", syncedPages);
		postJson("/api/plugin/clog", payload, "Collection log push failed", true);
		log.debug("Collection log pushed: {} page(s), {} synced", out.size(), syncedPages);
	}

	/**
	 * POST /api/plugin/pb — the account's best times, in centiseconds.
	 *
	 * <p>Centiseconds because the game separates runs by hundredths; whole seconds would tie times
	 * the game itself doesn't. The server keeps the FASTEST of stored and pushed, so a retry, a
	 * stale client or an out-of-order request can never raise somebody's record.
	 */
	public void submitPersonalBests(Map<String, Integer> bests) throws IOException
	{
		if (bests == null || bests.isEmpty())
		{
			return;
		}
		Map<String, Integer> valid = new LinkedHashMap<>();
		bests.forEach((k, v) ->
		{
			if (k != null && !k.isEmpty() && v != null && v > 0)
			{
				valid.put(k, v);
			}
		});
		if (valid.isEmpty())
		{
			return;
		}
		JsonObject payload = new JsonObject();
		payload.add("bests", pairs(valid, "activity", "centis"));
		postJson("/api/plugin/pb", payload, "Personal best push failed", true);
		log.debug("Personal bests pushed: {}", valid.size());
	}

	/**
	 * POST /api/plugin/moments — the clan's highlight feed: pets, uniques, big hauls and deaths.
	 *
	 * <p>Reports what the client SAW; the site decides what it meant. It knows which competition
	 * week or board is running, what counts as a unique, and which pets belong to which skill — so
	 * most of what goes up here is discarded there, on purpose, and a clan changing its mind about
	 * any of it costs no plugin release.
	 *
	 * <p>Idempotent: every entry carries a key derived from what happened, so the two loot events
	 * and three chat lines one occurrence fires — and a retry after a timeout — collapse into one
	 * row. A failure therefore just retries with the queue intact.
	 *
	 * <p>Never scoring: nothing here completes a tile or moves a standing.
	 */
	public void submitMoments(List<AnvilMoments.Moment> batch) throws IOException
	{
		if (batch == null || batch.isEmpty())
		{
			return;
		}
		JsonArray out = new JsonArray();
		for (AnvilMoments.Moment m : batch)
		{
			if (m == null || m.kind == null || m.key == null)
			{
				continue;
			}
			JsonObject o = new JsonObject();
			o.addProperty("kind", m.kind);
			o.addProperty("key", m.key);
			o.addProperty("at", java.time.Instant.ofEpochMilli(m.at).toString());
			o.addProperty("quantity", Math.max(1, m.quantity));
			// Everything below is best-effort — a skilling pet has no source, no KC and no price, and
			// inventing any of them would be worse than a shorter line on the feed.
			if (m.itemId != null)
			{
				o.addProperty("itemId", m.itemId);
			}
			if (m.valueGp != null && m.valueGp > 0)
			{
				o.addProperty("valueGp", m.valueGp);
			}
			if (m.kc != null && m.kc > 0)
			{
				o.addProperty("kc", m.kc);
			}
			addText(o, "itemName", m.itemName);
			addText(o, "source", m.source);
			addText(o, "taskName", m.taskName);
			addText(o, "tier", m.tier);
			addText(o, "sourceKind", m.sourceKind);
			out.add(o);
		}
		if (out.size() == 0)
		{
			return;
		}
		JsonObject payload = new JsonObject();
		payload.add("moments", out);
		postJson("/api/plugin/moments", payload, "Moment push failed", true);
		log.debug("Moments pushed: {}", out.size());
	}

	/** Adds {@code value} when it is non-blank. */
	private static void addText(JsonObject o, String key, String value)
	{
		if (value != null && !value.isEmpty())
		{
			o.addProperty(key, value);
		}
	}
}

package com.anvil;

import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * Collection-log "unlock" banner. 178x100 base panel (source PNG is 3x), three centred lines at
 * text-tops y=10/40/64, all 16px with a 1px black shadow and no font smoothing. Open animation:
 * a 1px line draws out horizontally, the background unsquishes to full height, holds, then reverses.
 */
public class BingoClogBannerOverlay extends Overlay
{
	// Design space (matches Skeldoor's .collection-log-panel). 1.0 = original asset size.
	private static final int BASE_W = 178;
	private static final int BASE_H = 100;

	// Text tops (design px) + size. Tuned for even vertical rhythm on the small panel: the header sits
	// just under the top of the frame (11), the "Tile complete!/Progress:" line clears the divider (36),
	// and the label sits close under it (52) so the middle→label gap matches the ~15px gap between the
	// two wrapped label lines — otherwise the body reads as two disconnected zones.
	private static final int TOP_Y = 11;
	private static final int MID_Y = 36;
	private static final int BOTTOM_Y = 52;
	private static final float FONT_PX = 16f;
	// The bottom label wraps onto a second line at full size when it's too wide — the RS font is a
	// bitmap face that pixelates when scaled, so we never shrink glyphs. WRAP_LINE_H is the vertical
	// advance (design px) between the two lines, kept tight so both clear the 100px panel.
	private static final int WRAP_LINE_H = 15;
	private static final int BOTTOM_MAX_LINES = 2;

	// Horizontal padding (design px) kept clear inside the panel; text wider than the inner width wraps
	// onto up to BOTTOM_MAX_LINES lines (bottom label) and is ellipsised only if it overflows the last.
	private static final int TEXT_MARGIN_X = 12;

	// Animation (matches the reference gif): a thin line grows to full WIDTH, then the whole
	// background unsquishes to full HEIGHT; close reverses it. Linear motion, no fade.
	private static final long H_EXPAND_MS = 800;    // line grows to full width
	private static final long V_EXPAND_MS = 800;    // unsquish to full height
	private static final long HOLD_MS = 2500;
	private static final long V_COLLAPSE_MS = 650;  // squish back down to the line
	private static final long H_COLLAPSE_MS = 650;  // line shrinks to nothing
	private static final int LINE_H = 1;            // design-px height of the thin opening line

	private static final Color ORANGE = new Color(255, 152, 31);
	private static final Color WHITE = new Color(255, 255, 255);
	private static final Color SHADOW = new Color(0, 0, 0, 255);
	private static final Color LINE_COLOR = Color.BLACK; // the thin opening/closing line

	private final ConcurrentLinkedQueue<String[]> queue = new ConcurrentLinkedQueue<>();
	private final BufferedImage background;
	private final Font headerFont;
	private final Font bodyFont;
	private String[] active; // {top, middle, bottom}
	private long startedAt;

	@Inject
	public BingoClogBannerOverlay(AnvilPlugin plugin)
	{
		super(plugin);
		setPosition(OverlayPosition.TOP_CENTER);
		setPriority(OverlayPriority.HIGHEST);
		this.background = loadBackground();
		this.headerFont = FontManager.getRunescapeBoldFont().deriveFont(FONT_PX);
		// Detail lines use the natively-smaller RS bitmap (the XP-counter/minimap face) at its own
		// crisp size — the standard chat font read too large on the small panel. No deriveFont: scaling
		// a bitmap font off its native grid pixelates (see the wrap-not-shrink note above).
		this.bodyFont = FontManager.getRunescapeSmallFont();
	}

	private static BufferedImage loadBackground()
	{
		try (InputStream in = BingoClogBannerOverlay.class.getResourceAsStream("/com/anvil/clog_banner.png"))
		{
			return in == null ? null : ImageIO.read(in);
		}
		catch (IOException e)
		{
			return null;
		}
	}

	/** Backwards-compatible entry point used by the existing drop call site. */
	public void show(String label, int current, int required)
	{
		boolean complete = current >= required;
		String middle = complete ? "Tile complete!" : "Progress:";
		String bottom = required > 1 ? label + " (" + current + "/" + required + ")" : label;
		show("Anvil Bingo", middle, bottom);
	}

	/** Full three-line control. */
	public void show(String top, String middle, String bottom)
	{
		queue.add(new String[]{top, middle, bottom});
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (background == null)
		{
			return null;
		}

		long now = System.currentTimeMillis();
		long hEnd = H_EXPAND_MS;
		long vEnd = hEnd + V_EXPAND_MS;
		long holdEnd = vEnd + HOLD_MS;
		long vCollapseEnd = holdEnd + V_COLLAPSE_MS;
		long total = vCollapseEnd + H_COLLAPSE_MS;

		if (active == null || now - startedAt >= total)
		{
			active = queue.poll();
			if (active == null)
			{
				return null;
			}
			startedAt = now;
			now = System.currentTimeMillis();
		}

		long e = now - startedAt;

		// w/h = current panel size; line = just the thin opening/closing line (no bg/text yet).
		boolean line = e < hEnd || e >= vCollapseEnd;
		float w = BASE_W;
		float h = line ? LINE_H : BASE_H;
		if (e < hEnd)
		{
			// P1: thin line grows to full width.
			w = BASE_W * (e / (float) H_EXPAND_MS);
		}
		else if (e < vEnd)
		{
			// P2: whole background unsquishes from the line up to full height.
			h = LINE_H + (BASE_H - LINE_H) * ((e - hEnd) / (float) V_EXPAND_MS);
		}
		else if (e >= holdEnd && e < vCollapseEnd)
		{
			// P4: squish back down to the line.
			h = BASE_H - (BASE_H - LINE_H) * ((e - holdEnd) / (float) V_COLLAPSE_MS);
		}
		else if (line)
		{
			// P5: line shrinks horizontally to nothing.
			w = BASE_W * (1f - (e - vCollapseEnd) / (float) H_COLLAPSE_MS);
		}

		int iw = Math.max(1, Math.round(w));
		int ih = Math.max(1, Math.round(h));
		int x = (BASE_W - iw) / 2; // centre the (partly-open) panel within the reserved area
		int y = (BASE_H - ih) / 2;

		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);

		if (line)
		{
			// Opening/closing line: a plain strip in the banner's interior tone (not the bg, no text).
			g2.setColor(LINE_COLOR);
			g2.fillRect(x, y, iw, ih);
		}
		else
		{
			// Squish the WHOLE background into the current height (full width); it unsquishes to full.
			g2.drawImage(background, x, y, iw, ih, null);

			// Text only while opening/holding (e < holdEnd). On close it's dropped immediately so the
			// panel collapses cleanly instead of a centre sliver of text lingering. Full-size, fixed
			// in place, clipped to the opened region so it's revealed centre-out as the bg unsquishes.
			if (e < holdEnd)
			{
				g2.clipRect(x, y, iw, ih);
				int maxTextW = BASE_W - 2 * TEXT_MARGIN_X;
				drawWrapped(g2, active[0], headerFont, ORANGE, maxTextW, TOP_Y, 1);
				drawWrapped(g2, active[1], bodyFont, ORANGE, maxTextW, MID_Y, 1);
				drawWrapped(g2, active[2], bodyFont, WHITE, maxTextW, BOTTOM_Y, BOTTOM_MAX_LINES);
			}
		}

		g2.dispose();

		return new Dimension(BASE_W, BASE_H);
	}

	/** Draws text centred horizontally, {@code topY} being the CSS-style top of the line (line-height 1),
	 *  wrapped onto up to {@code maxLines} lines at the full font size (the RS bitmap font pixelates when
	 *  scaled, so we wrap rather than shrink), ellipsising only the final line if it still overflows.
	 *  Extra lines advance downward by {@link #WRAP_LINE_H}. */
	private static void drawWrapped(Graphics2D g, String text, Font font, Color color, int maxWidth, int topY, int maxLines)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		List<String> lines = wrap(text, fm, maxWidth, maxLines);
		for (int i = 0; i < lines.size(); i++)
		{
			String shown = lines.get(i);
			int x = (BASE_W - fm.stringWidth(shown)) / 2;
			int baseline = topY + i * WRAP_LINE_H + fm.getAscent();
			g.setColor(SHADOW);
			g.drawString(shown, x + 1, baseline + 1);
			g.setColor(color);
			g.drawString(shown, x, baseline);
		}
	}

	/** Greedy word-wrap into at most {@code maxLines} lines that each fit {@code maxWidth}; any overflow
	 *  past the last line is folded into it, and every kept line is ellipsised if it still overflows
	 *  (covers a lone over-long word too). */
	private static List<String> wrap(String text, FontMetrics fm, int maxWidth, int maxLines)
	{
		List<String> lines = new ArrayList<>();
		if (maxWidth <= 0 || fm.stringWidth(text) <= maxWidth)
		{
			lines.add(text);
			return lines;
		}
		StringBuilder line = new StringBuilder();
		for (String word : text.split("\\s+"))
		{
			String trial = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(trial) <= maxWidth)
			{
				line.setLength(0);
				line.append(trial);
				continue;
			}
			if (line.length() > 0)
			{
				lines.add(line.toString());
				line.setLength(0);
			}
			line.append(word);
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		if (lines.size() > maxLines)
		{
			// Fold every line past the cap into the last kept line (it gets ellipsised below).
			StringBuilder tail = new StringBuilder(lines.get(maxLines - 1));
			for (int i = maxLines; i < lines.size(); i++)
			{
				tail.append(' ').append(lines.get(i));
			}
			lines = new ArrayList<>(lines.subList(0, maxLines - 1));
			lines.add(tail.toString());
		}
		for (int i = 0; i < lines.size(); i++)
		{
			if (fm.stringWidth(lines.get(i)) > maxWidth)
			{
				lines.set(i, truncate(lines.get(i), fm, maxWidth));
			}
		}
		return lines;
	}

	/** Trims {@code text} with a trailing ellipsis so it fits within {@code maxWidth} px. */
	private static String truncate(String text, FontMetrics fm, int maxWidth)
	{
		if (maxWidth <= 0 || fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		final String ellipsis = "...";
		int ellipsisW = fm.stringWidth(ellipsis);
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end)) + ellipsisW > maxWidth)
		{
			end--;
		}
		return end <= 0 ? ellipsis : text.substring(0, end).trim() + ellipsis;
	}
}

package com.anvil;

/**
 * Opens a URL in the member's system browser.
 *
 * An interface rather than a direct {@link net.runelite.client.util.LinkBrowser} call so the
 * sign-in flow can be unit-tested without launching anything: production binds
 * {@code LinkBrowser::browse}, tests bind a recorder that just remembers the URL it was handed.
 *
 * <p>Lived inside the federation data source until federation was removed. It is hoisted rather
 * than deleted with it because opening a browser is what DEVICE SIGN-IN does, and that is the
 * plugin's live login path — the one thing in that file that was never about federation at all.</p>
 */
@FunctionalInterface
public interface BrowserOpener
{
	/** @return true when a browser was actually opened. */
	boolean open(String url);
}

package com.anvil;

/**
 * The "Announce combat achievements" dropdown: the lowest task tier posted to the clan, or OFF for no
 * posts at all (tier clears included). The tiers share {@link CombatAchievementTier}'s order and names,
 * so ordinals compare directly and a value saved under the old tier-typed setting still loads.
 * Bingo tile credit never looks at this.
 */
public enum CaAnnounceTier
{
	EASY("Easy"),
	MEDIUM("Medium"),
	HARD("Hard"),
	ELITE("Elite"),
	MASTER("Master"),
	GRANDMASTER("Grandmaster"),
	OFF("Off");

	private final String label;

	CaAnnounceTier(String label)
	{
		this.label = label;
	}

	/** Whether a task of {@code tier} is posted; always false when OFF. */
	boolean posts(CombatAchievementTier tier)
	{
		return this != OFF && tier.ordinal() >= ordinal();
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.anvil;

import java.util.List;

/**
 * One clan as the panel shows it — the JSON of {@code GET /api/clans/<slug>/card} ({@code clan-card}
 * capability). The Clan tab draws your own clan's; Lookup draws any listed clan's, and compare reads two.
 */
public final class ClanCard
{
	public String slug;
	public String name;
	public int members;
	public int activeThisWeek;
	/** EHP + EHB gained by the members in the last 7 days. */
	public double weekHours;
	public double totalEhp;
	public double totalEhb;
	public List<Gainer> topWeek;
	public List<Player> topPlayers;
	/** Null until a member has synced their log. */
	public Clog clog;
	public List<Highlight> highlights;
	public List<Competition> competitions;

	public static final class Gainer
	{
		public String rsn;
		public double hours;
	}

	public static final class Player
	{
		public String rsn;
		public long overallXp;
	}

	public static final class Clog
	{
		public int average;
		public int synced;
	}

	public static final class Highlight
	{
		public String rsn;
		public String label;
		public Integer itemId;
		public String kind;
		public String at;
	}

	public static final class Competition
	{
		public String type;
		public String metric;
		public String label;
	}

	/** {@code /api/clans/lookup} answer. */
	public static final class LookupResult
	{
		public List<Found> clans;
	}

	public static final class Found
	{
		public String slug;
		public String name;
	}
}

package com.anvil;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.util.Locale;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

import static com.anvil.PlayerCardView.header;
import static com.anvil.Ui.*;

/**
 * A {@link ClanCard}: who the clan is, how hard it played this week and who carried it, its strongest
 * accounts, what dropped lately and what's running. Under Events in the Clan tab (your clan) and in
 * Lookup (any listed clan) — the clan side of Anvil, next to the boards.
 */
final class ClanCardView
{
	private ClanCardView()
	{
	}

	/**
	 * @param onPlayer  open a member's player card (names are clickable); null = plain text
	 * @param onCompare "Compare with my clan"; null hides the button (it's your own clan)
	 */
	static JPanel render(ClanCard card, PlayerCardView.Icons icons, Consumer<String> onPlayer, Runnable onCompare)
	{
		PlayerCardView.Icons ic = icons == null ? PlayerCardView.Icons.NONE : icons;
		JPanel root = column();

		JPanel id = block();
		JPanel nameRow = row(6);
		nameRow.add(title(card.name), BorderLayout.CENTER);
		JLabel web = onClick(new JLabel(new GlyphIcon(GlyphIcon.Shape.EXTERNAL, 12, MUTED)), () ->
			net.runelite.client.util.LinkBrowser.browse(BingoApiClient.CANONICAL_SITE + "/c/"
				+ java.net.URLEncoder.encode(card.slug, java.nio.charset.StandardCharsets.UTF_8)));
		web.setToolTipText("Open the clan on the Anvil website");
		nameRow.add(web, BorderLayout.EAST);
		id.add(capH(nameRow));
		id.add(gap(2));
		id.add(small(String.format(Locale.ROOT, "%,d members · %,d active this week", card.members, card.activeThisWeek), MUTED));
		if (card.clog != null)
		{
			id.add(small(String.format(Locale.ROOT, "Avg log %,d slots · %,d synced", card.clog.average, card.clog.synced), MUTED));
		}
		if (card.competitions != null && !card.competitions.isEmpty())
		{
			StringBuilder sb = new StringBuilder("Running: ");
			for (int i = 0; i < card.competitions.size(); i++)
			{
				ClanCard.Competition c = card.competitions.get(i);
				sb.append(i > 0 ? " · " : "").append("boss".equals(c.type) ? "BOTW " : "skill".equals(c.type) ? "SOTW " : "").append(c.label);
			}
			id.add(gap(2));
			id.add(small(sb.toString(), ColorScheme.BRAND_ORANGE));
		}
		root.add(id);

		if (card.topWeek != null && !card.topWeek.isEmpty())
		{
			root.add(gap(6));
			JPanel week = block();
			week.add(header("This week", String.format(Locale.ROOT, "+%,.0fh gained", card.weekHours)));
			week.add(gap(4));
			int place = 1;
			for (ClanCard.Gainer g : card.topWeek)
			{
				week.add(nameLine(place++ + ".  " + g.rsn, String.format(Locale.ROOT, "+%.1fh", g.hours), g.rsn, onPlayer));
			}
			root.add(week);
		}

		if (card.topPlayers != null && !card.topPlayers.isEmpty())
		{
			root.add(gap(6));
			JPanel top = block();
			top.add(header("Top accounts", "by total XP"));
			top.add(gap(4));
			for (ClanCard.Player p : card.topPlayers)
			{
				top.add(nameLine(p.rsn, PlayerCardView.compact(p.overallXp) + " xp", p.rsn, onPlayer));
			}
			root.add(top);
		}

		if (card.highlights != null && !card.highlights.isEmpty())
		{
			root.add(gap(6));
			JPanel hl = block();
			hl.add(header("Lately in the clan", null));
			hl.add(gap(4));
			for (ClanCard.Highlight h : card.highlights)
			{
				JPanel line = row(6);
				JLabel icon = PlayerCardView.iconSlot(24, 22);
				if (h.itemId != null && ic.items != null)
				{
					ic.items.getImage(h.itemId).addTo(icon);
				}
				line.add(icon, BorderLayout.WEST);
				JPanel text = column();
				text.setOpaque(false);
				text.add(small(h.label, Color.WHITE));
				text.add(small(h.rsn + ("pet".equals(h.kind) ? " · pet" : ""), MUTED));
				line.add(text, BorderLayout.CENTER);
				line.add(small(PlayerCardView.ago(h.at), MUTED), BorderLayout.EAST);
				hl.add(capH(line));
				hl.add(gap(2));
			}
			root.add(hl);
		}

		if (onCompare != null)
		{
			root.add(gap(6));
			JButton compare = new JButton("Compare with my clan");
			compare.setFocusable(false);
			compare.setFont(SMALL);
			compare.addActionListener(e -> onCompare.run());
			JPanel row = row(0);
			row.add(compare, BorderLayout.CENTER);
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, compare.getPreferredSize().height));
			root.add(row);
		}
		return root;
	}

	/** "Name ......... value" — the name opens that player's card when {@code onPlayer} is given. */
	private static JPanel nameLine(String text, String value, String rsn, Consumer<String> onPlayer)
	{
		JPanel line = row(6);
		line.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
		line.add(small(text, Color.WHITE), BorderLayout.CENTER);
		line.add(small(value, ColorScheme.BRAND_ORANGE), BorderLayout.EAST);
		capH(line);
		if (onPlayer != null)
		{
			line.setToolTipText("Look up " + plainText(rsn));
			hoverable(line, ColorScheme.DARKER_GRAY_COLOR, () -> onPlayer.accept(rsn));
		}
		return line;
	}

	/** Two clans side by side: one line per measure, the leader's number in orange. */
	static JPanel compare(ClanCard a, ClanCard b)
	{
		JPanel block = block();
		block.add(CompareView.namesRow(a.name, b.name));
		block.add(gap(4));
		block.add(CompareView.row("Members", a.members, b.members, Long::toString));
		block.add(CompareView.row("Active this week", a.activeThisWeek, b.activeThisWeek, Long::toString));
		java.util.function.LongFunction<String> hours = n -> String.format(Locale.ROOT, "%,dh", n);
		block.add(CompareView.row("Total EHP", Math.round(a.totalEhp), Math.round(b.totalEhp), hours));
		block.add(CompareView.row("Total EHB", Math.round(a.totalEhb), Math.round(b.totalEhb), hours));
		block.add(CompareView.row("Avg log slots", a.clog == null ? -1 : a.clog.average, b.clog == null ? -1 : b.clog.average,
			n -> n < 0 ? "—" : String.format(Locale.ROOT, "%,d", n)));
		block.add(CompareView.row("Gained this week", Math.round(a.weekHours), Math.round(b.weekHours), hours));
		return block;
	}
}

package com.anvil;

import java.util.Locale;

/**
 * Turns repeated reads of the Clan Coffer coin stack into auditable balance transitions.
 *
 * <p>The widget gives us the amount, not who moved it. A nearby server-authored chat line can name
 * the local player, but it is used only for attribution: the balance delta remains the source of
 * truth and an unconfirmed movement is still reported anonymously.</p>
 */
final class ClanCofferTracker
{
	private static final long ACTOR_WINDOW_MS = 15_000L;

	enum Kind
	{
		SNAPSHOT("snapshot"),
		DEPOSIT("deposit"),
		WITHDRAWAL("withdrawal");

		final String wire;

		Kind(String wire)
		{
			this.wire = wire;
		}
	}

	static final class Observation
	{
		final Kind kind;
		final int beforeBalance;
		final int afterBalance;
		final boolean actorConfirmed;

		Observation(Kind kind, int beforeBalance, int afterBalance, boolean actorConfirmed)
		{
			this.kind = kind;
			this.beforeBalance = beforeBalance;
			this.afterBalance = afterBalance;
			this.actorConfirmed = actorConfirmed;
		}
	}

	private Integer lastBalance;
	private Kind recentSelfAction;
	private long recentSelfActionAt;

	void reset()
	{
		lastBalance = null;
		recentSelfAction = null;
		recentSelfActionAt = 0L;
	}

	/** Remember a server-authored coffer line only when it names this account (or says “you”). */
	void onChatLine(String line, String localRsn, long now)
	{
		Kind action = selfAction(line, localRsn);
		if (action != null)
		{
			recentSelfAction = action;
			recentSelfActionAt = now;
		}
	}

	Observation observe(int balance, long now)
	{
		if (balance < 0)
		{
			return null;
		}
		if (lastBalance == null)
		{
			lastBalance = balance;
			return new Observation(Kind.SNAPSHOT, balance, balance, false);
		}
		int before = lastBalance;
		if (before == balance)
		{
			return null;
		}

		Kind kind = balance > before ? Kind.DEPOSIT : Kind.WITHDRAWAL;
		boolean confirmed = recentSelfAction == kind
			&& now >= recentSelfActionAt
			&& now - recentSelfActionAt <= ACTOR_WINDOW_MS;
		lastBalance = balance;
		// One chat line may explain one physical transition, never a later unrelated one.
		recentSelfAction = null;
		recentSelfActionAt = 0L;
		return new Observation(kind, before, balance, confirmed);
	}

	static Kind selfAction(String line, String localRsn)
	{
		if (line == null)
		{
			return null;
		}
		String plain = line.replaceAll("<[^>]*>", "").trim();
		String lower = plain.toLowerCase(Locale.ROOT);
		if (!lower.contains("coffer"))
		{
			return null;
		}
		boolean namesSelf = lower.startsWith("you ") || lower.startsWith("you've ");
		String self = Rsn.normalize(localRsn);
		if (!namesSelf && !self.isEmpty())
		{
			String normalizedLine = Rsn.normalize(plain);
			namesSelf = normalizedLine.equals(self) || normalizedLine.startsWith(self + " ");
		}
		if (!namesSelf)
		{
			return null;
		}
		// "has/have deposited", "donated", "withdrew", "has/have withdrawn"…
		if (lower.contains("deposited") || lower.contains("donated"))
		{
			return Kind.DEPOSIT;
		}
		if (lower.contains("withdrew") || lower.contains("withdrawn"))
		{
			return Kind.WITHDRAWAL;
		}
		return null;
	}
}

package com.anvil;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.Transferable;
import lombok.extern.slf4j.Slf4j;

/**
 * Putting a path on the clipboard, which is as far as a hub plugin may go toward "open this folder".
 *
 * <p>RuneLite's LinkBrowser::open — the sanctioned way to hand a local path to the OS — is a
 * restricted API for plugin-hub releases, so the folder buttons can't launch a file manager. Copying
 * the path is the honest substitute: one paste into a file manager or a terminal, and nothing about
 * the plugin reaches outside its own directory.
 */
@Slf4j
final class Clipboards
{
	private Clipboards()
	{
	}

	/** True when the text made it onto the clipboard, so a caller can say so rather than assume. */
	static boolean copy(String value)
	{
		if (value == null || value.isEmpty())
		{
			return false;
		}
		return set(new StringSelection(value));
	}

	private static boolean set(Transferable contents)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(contents, null);
			return true;
		}
		catch (Exception e)
		{
			// A headless or locked-down desktop has no clipboard; the path still gets said out loud.
			log.debug("Anvil: clipboard copy skipped: {}", e.getMessage());
			return false;
		}
	}
}

package com.anvil;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Collects a WHOLE collection log, as the server transmits it.
 *
 * <p>The client normally holds one page — whichever the player last drew — which is why the page
 * reader ({@link ClogPageReader}) can only ever report what someone has clicked through. But opening
 * the log and toggling its Search makes the server transmit EVERY entry, one script fire per item.
 * That's the whole log in one go, with no paging and nothing for the player to do but open the
 * interface. (The technique is WikiSync's; RuneProfile uses it too.)
 *
 * <p>This class is the accumulator and the "have they stopped arriving yet" policy. It is
 * RuneLite-free on purpose: the awkward parts are the quiet period and the guards against half a
 * transmit being sent as if it were a log, and both are worth testing without a client.
 *
 * <p>Item ids only — no page names. The site owns the catalogue (src/data/clog.json) and maps ids to
 * pages on the way in, so a game update that shuffles pages is a dataset rebuild rather than a
 * plugin release.
 */
final class ClogFullSync
{
	/**
	 * Items land over several ticks; wait this long after the last one before calling it complete.
	 * Two ticks and change — long enough that a transmit arriving in bursts isn't cut in half, short
	 * enough that a player who pressed a button isn't left watching an ellipsis.
	 */
	static final long QUIET_MS = 1_200;

	/**
	 * A transmit that yields fewer items than this is treated as noise rather than a log. The point
	 * is not to validate someone's collection — a genuinely empty log is possible — but to refuse to
	 * REPLACE a stored log with the tail end of an interrupted transmit (they closed the interface
	 * mid-flight, or another plugin's own search toggle fired one item).
	 */
	static final int MIN_ITEMS = 5;

	/** itemId -> quantity, in arrival order so a batch reads like the log does. */
	private final Map<Integer, Integer> items = new LinkedHashMap<>();

	private long lastItemAt;
	private boolean receiving;
	/** Set when the player asked for this explicitly, so a no-change sync still gets sent + reported. */
	private boolean manual;

	/** A transmit is starting (the log was opened / the button was pressed). Clears anything stale. */
	void begin(boolean manualRequest)
	{
		items.clear();
		receiving = true;
		manual = manual || manualRequest;
		lastItemAt = 0;
	}

	/** One item, straight off the transmit script. Ignored unless a transmit is actually in flight. */
	void onItem(int itemId, int quantity, long now)
	{
		if (!receiving || itemId <= 0)
		{
			return;
		}
		items.put(itemId, Math.max(1, quantity));
		lastItemAt = now;
	}

	/**
	 * Has a complete-looking transmit settled? True once nothing has arrived for {@link #QUIET_MS}
	 * and enough items landed to be a log rather than a fragment.
	 */
	boolean isDue(long now)
	{
		return receiving
			&& lastItemAt > 0
			&& items.size() >= MIN_ITEMS
			&& now - lastItemAt >= QUIET_MS;
	}

	/** True when the player pressed the button, so the caller can report the result in chat. */
	boolean isManual()
	{
		return manual;
	}

	/** Everything received, as an unmodifiable snapshot. Does not clear — see {@link #onSent}. */
	Map<Integer, Integer> snapshot()
	{
		return Collections.unmodifiableMap(new LinkedHashMap<>(items));
	}

	int size()
	{
		return items.size();
	}

	/**
	 * A cheap fingerprint of what was received, so an unchanged log isn't pushed twice.
	 *
	 * <p>The transmit re-sends everything every time the log is opened, and most opens change
	 * nothing. Order-independent (the game's transmit order is not ours to rely on) and includes
	 * quantities, so a second of the same item still counts as a change.
	 */
	synchronized long fingerprint()
	{
		long hash = items.size();
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			// Mixed per entry then XORed in: adding an item changes it, and reordering doesn't.
			long h = e.getKey() * 0x9E3779B97F4A7C15L + e.getValue();
			hash ^= h ^ (h >>> 29);
		}
		return hash;
	}

	/** The push landed: drop the batch and stand down until the next transmit. */
	void onSent()
	{
		reset();
	}

	/**
	 * The push failed. Keeps the items so the next tick can retry, but stops the clock restarting —
	 * a site that is down must not cost the player their transmit.
	 */
	void onSendFailed(long now)
	{
		lastItemAt = now;
	}

	/** Account switch / logout: a half-received log belongs to nobody. */
	void reset()
	{
		items.clear();
		receiving = false;
		manual = false;
		lastItemAt = 0;
	}
}

package com.anvil;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One collection-log page as the game drew it: the entry name, every item the account has obtained
 * on it, and the counters the log prints under the title ("Abyssal Sire kills: 1,204").
 *
 * <p>Deliberately RuneLite-free so the accumulator and its tests never need a client. Reading the
 * widgets is {@link ClogPageReader}'s job; deciding what to send is {@link ClogSync}'s.
 *
 * <p><b>Only obtained items are carried.</b> The site already ships the full 1,712-item catalogue
 * (src/data/clog.json), so the missing half is derivable — sending it would double every payload to
 * say "still nothing here".
 */
final class ClogPage
{
	/** Entry title as the log prints it — "Abyssal Sire". The site maps it to its own page id. */
	final String name;
	/** Obtained item ids, in the order the log lists them. Parallel to {@link #quantities}. */
	final int[] itemIds;
	final int[] quantities;
	/** The log's own "Obtained: 5/9" pair — the site shows progress without owning the catalogue. */
	final int obtained;
	final int total;
	/** The counter lines under the title, label → value. Empty for pages that print none. */
	final Map<String, Integer> counts;
	/** 64-bit content hash — what makes "has this page changed?" a comparison, not a diff. */
	final long hash;

	ClogPage(String name, int[] itemIds, int[] quantities, int obtained, int total, Map<String, Integer> counts)
	{
		this.name = name;
		this.itemIds = itemIds;
		this.quantities = quantities;
		this.obtained = obtained;
		this.total = total;
		this.counts = counts == null || counts.isEmpty()
			? Collections.emptyMap()
			: Collections.unmodifiableMap(new LinkedHashMap<>(counts));
		this.hash = computeHash();
	}

	/**
	 * FNV-1a over the page's contents.
	 *
	 * <p>Hand-rolled rather than {@code Objects.hash} / a JSON round-trip because this runs on the
	 * client thread every time the log redraws — which is every keystroke while a player scrolls the
	 * log. No boxing, no allocation, no string building; a page is folded in a few hundred nanoseconds
	 * and the result is what stops us re-sending 125 identical pages.
	 */
	private long computeHash()
	{
		long h = 0xcbf29ce484222325L;
		h = fold(h, name == null ? 0 : name.hashCode());
		h = fold(h, obtained);
		h = fold(h, total);
		for (int i = 0; i < itemIds.length; i++)
		{
			h = fold(h, itemIds[i]);
			h = fold(h, quantities[i]);
		}
		for (Map.Entry<String, Integer> e : counts.entrySet())
		{
			h = fold(h, e.getKey().hashCode());
			h = fold(h, e.getValue());
		}
		return h;
	}

	private static long fold(long h, int value)
	{
		h ^= value;
		return h * 0x100000001b3L;
	}
}

package com.anvil;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;

/**
 * Reads the collection-log page the game is currently showing.
 *
 * <p>The client only ever holds ONE page — the log is drawn on demand, so an unopened page has no
 * items anywhere in memory. That's why a full sync means the player paging through their log once,
 * and why this is a read-what's-on-screen routine rather than a dump.
 *
 * <p><b>Self-verifying.</b> The header prints "Obtained: 5/9"; we count the items we believe are
 * obtained and only return a page when the two agree. A game update that changes how unobtained
 * items are drawn therefore makes this return null — the sync stalls and says so — instead of
 * quietly reporting that everybody lost half their collection log.
 *
 * <p>Runs on the client thread (its only caller is the COLLECTION_DRAW_LIST script hook), so it
 * allocates nothing beyond the page it returns and never blocks.
 */
final class ClogPageReader
{
	private ClogPageReader() {}

	/** "Obtained: 5/9" — the log's own progress line, and our correctness check. */
	private static final Pattern OBTAINED = Pattern.compile("obtained:\\s*(\\d+)\\s*/\\s*(\\d+)");
	/** "Abyssal Sire kills: 1,204" / "Chest openings: 87" — label and value, commas stripped. */
	private static final Pattern COUNT_LINE = Pattern.compile("^(.+?):\\s*([\\d,]+)$");
	/** Widget tags: the log wraps names in colour tags we don't want in the payload. */
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");

	/**
	 * The page on screen, or null when it isn't readable yet (mid-draw, empty, or the obtained
	 * count disagrees with what we read — see the class note).
	 */
	static ClogPage read(Client client)
	{
		Widget header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
		Widget items = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (header == null || items == null)
		{
			return null;
		}

		String name = null;
		int obtained = -1;
		int total = -1;
		// Allocated only if the page actually prints counters — most don't, and this runs on every
		// redraw of every page the player scrolls past.
		Map<String, Integer> counts = null;

		Widget[] lines = header.getStaticChildren();
		if (lines == null)
		{
			return null;
		}
		for (Widget line : lines)
		{
			if (line == null)
			{
				continue;
			}
			String text = strip(line.getText());
			if (text.isEmpty())
			{
				continue;
			}
			// First non-empty line is the entry title; the rest are progress and counters.
			if (name == null)
			{
				name = text;
				continue;
			}
			Matcher progress = OBTAINED.matcher(text.toLowerCase());
			if (progress.find())
			{
				obtained = parseInt(progress.group(1));
				total = parseInt(progress.group(2));
				continue;
			}
			Matcher count = COUNT_LINE.matcher(text);
			if (count.matches())
			{
				int value = parseInt(count.group(2).replace(",", ""));
				if (value >= 0)
				{
					if (counts == null)
					{
						counts = new LinkedHashMap<>(4);
					}
					counts.put(count.group(1).trim(), value);
				}
			}
		}

		if (name == null || name.isEmpty() || obtained < 0 || total <= 0)
		{
			return null;
		}

		Widget[] cells = items.getDynamicChildren();
		if (cells == null)
		{
			return null;
		}

		// Two passes so the arrays are exactly sized — a page is at most a few dozen items, and this
		// avoids both an ArrayList's boxing and a grow-and-copy on every redraw.
		int found = 0;
		for (Widget cell : cells)
		{
			if (isObtained(cell))
			{
				found++;
			}
		}
		// The log's own count is the authority. Disagreeing means we misread the page (or Jagex
		// changed the drawing); either way, committing it would corrupt a synced log.
		if (found != obtained)
		{
			return null;
		}

		int[] ids = new int[found];
		int[] quantities = new int[found];
		int i = 0;
		for (Widget cell : cells)
		{
			if (!isObtained(cell))
			{
				continue;
			}
			ids[i] = cell.getItemId();
			// A quantity of 0 on an obtained item means "one, uncounted" for the handful of log
			// entries that predate stack tracking; storing 0 would read as "you don't have it".
			quantities[i] = Math.max(1, cell.getItemQuantity());
			i++;
		}

		return new ClogPage(name, ids, quantities, obtained, total, counts);
	}

	/**
	 * Whether a cell is an item the account has.
	 *
	 * <p>The log draws unobtained items dimmed (non-zero opacity) with no quantity; obtained ones are
	 * fully opaque and carry their count. Either signal alone has an edge case, so both are accepted
	 * and the header's "Obtained: N" arbitrates — see {@link #read}.
	 */
	private static boolean isObtained(Widget cell)
	{
		if (cell == null || cell.getItemId() <= 0)
		{
			return false;
		}
		return cell.getOpacity() == 0 || cell.getItemQuantity() > 0;
	}

	private static String strip(String raw)
	{
		if (raw == null)
		{
			return "";
		}
		// The regex is the expensive part and most lines carry no tags at all — one scan for '<'
		// saves building a Matcher on every header line of every redraw.
		if (raw.indexOf('<') < 0)
		{
			return raw.trim();
		}
		return TAGS.matcher(raw).replaceAll("").trim();
	}

	private static int parseInt(String raw)
	{
		try
		{
			return Integer.parseInt(raw);
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Function;

/**
 * Decides what of the collection log is worth sending, and when.
 *
 * <p>The game redraws a log page on every scroll, filter and tab click, so the naive "push what's on
 * screen" would be hundreds of identical requests per session. This keeps a hash per page and only
 * queues one that actually changed, then batches the queue behind a quiet period.
 *
 * <p>The hashes of pages we've already sent are persisted (see {@link #serializeState}), so logging
 * back in and opening the log doesn't re-send a log that hasn't moved. That's the difference between
 * a sync that costs one request a week and one that costs a request a minute forever.
 *
 * <p>RuneLite-free on purpose: the flush policy is the part with edge cases, and this way it's
 * unit-testable without a client. The plugin owns the widget hook, the scheduler and the HTTP.
 */
final class ClogSync
{
	/** Wait this long after the last change before sending — a player paging through settles first. */
	static final long QUIET_MS = 2_500;
	/** Send at most this many pages per request; a full first sync becomes a handful of them. */
	static final int BATCH_PAGES = 25;
	/** Queue this many and go early — a bulk sync shouldn't sit waiting on the quiet timer. */
	private static final int EAGER_AT = BATCH_PAGES;

	/** Last hash we successfully sent, per page name. The persisted half of the state. */
	private final Map<String, Long> sent = new HashMap<>();
	/** Changed pages awaiting a push, newest write wins. Insertion-ordered so batches are stable. */
	private final Map<String, ClogPage> pending = new LinkedHashMap<>();

	private long lastChangeAt;
	private boolean stateLoaded;

	/**
	 * Offer the page currently on screen. Cheap and idempotent — the common case is a hash compare
	 * against what we already sent, and no allocation at all.
	 *
	 * @return true when the page was queued (i.e. it's new or changed)
	 */
	boolean offer(ClogPage page, long now)
	{
		if (page == null || page.name == null || page.name.isEmpty())
		{
			return false;
		}
		Long alreadySent = sent.get(page.name);
		if (alreadySent != null && alreadySent == page.hash)
		{
			return false;
		}
		ClogPage queued = pending.get(page.name);
		if (queued != null && queued.hash == page.hash)
		{
			return false;
		}
		pending.put(page.name, page);
		lastChangeAt = now;
		return true;
	}

	/** Whether a flush should run now: the queue has settled, or it's big enough to go early. */
	boolean isDue(long now)
	{
		if (pending.isEmpty())
		{
			return false;
		}
		return pending.size() >= EAGER_AT || now - lastChangeAt >= QUIET_MS;
	}

	/** Pages to send in the next request, oldest first. Does NOT clear them — see {@link #onSent}. */
	List<ClogPage> nextBatch()
	{
		List<ClogPage> batch = new ArrayList<>(Math.min(BATCH_PAGES, pending.size()));
		for (ClogPage page : pending.values())
		{
			batch.add(page);
			if (batch.size() >= BATCH_PAGES)
			{
				break;
			}
		}
		return batch;
	}

	/**
	 * Mark a batch delivered. Only called after the server has accepted it, so a failed push leaves
	 * the pages queued and the next flush retries them — no bookkeeping, no lost pages.
	 */
	void onSent(Collection<ClogPage> batch)
	{
		for (ClogPage page : batch)
		{
			ClogPage queued = pending.get(page.name);
			// Left queued if it changed again while the request was in flight.
			if (queued != null && queued.hash == page.hash)
			{
				pending.remove(page.name);
			}
			sent.put(page.name, page.hash);
		}
	}

	int pendingCount()
	{
		return pending.size();
	}

	/** How many distinct pages we've delivered — the numerator of the "68% synced" nudge. */
	int syncedPages()
	{
		return sent.size();
	}

	/** Forget everything. Called when the account changes — one player's log is not another's. */
	void reset()
	{
		sent.clear();
		pending.clear();
		lastChangeAt = 0;
		stateLoaded = false;
	}

	/**
	 * The sent-hash map as one config string: {@code <hex hash>|<page name>} per line.
	 *
	 * <p>Hash first, split on the first pipe: page names contain colons ("Chambers of Xeric:
	 * Challenge Mode") and spaces, so a name-first format would need escaping. A hex hash can't
	 * contain a pipe, which makes the parse total.
	 */
	String serializeState()
	{
		return writeLines(sent, Long::toHexString);
	}

	/** {@code <value>|<name>} per line — the shape this and {@link PersonalBests} persist. */
	static <V> String writeLines(Map<String, V> map, Function<V, String> value)
	{
		StringBuilder out = new StringBuilder(map.size() * 24);
		for (Map.Entry<String, V> e : map.entrySet())
		{
			if (e.getKey() == null || e.getKey().indexOf('\n') >= 0)
			{
				continue;
			}
			if (out.length() > 0)
			{
				out.append('\n');
			}
			out.append(value.apply(e.getValue())).append('|').append(e.getKey());
		}
		return out.toString();
	}

	/** Each well-formed {@link #writeLines} line as (value, name); a line whose value won't parse is skipped. */
	static void readLines(String raw, BiConsumer<String, String> line)
	{
		if (raw == null || raw.isEmpty())
		{
			return;
		}
		for (String l : raw.split("\n"))
		{
			int pipe = l.indexOf('|');
			if (pipe <= 0 || pipe == l.length() - 1)
			{
				continue;
			}
			try
			{
				line.accept(l.substring(0, pipe), l.substring(pipe + 1));
			}
			catch (NumberFormatException e)
			{
				// A truncated or hand-edited config line: drop it and let it re-sync.
			}
		}
	}

	/** Restore from {@link #serializeState}. Junk lines are skipped, never fatal. */
	void restoreState(String raw)
	{
		sent.clear();
		stateLoaded = true;
		readLines(raw, (hash, page) -> sent.put(page, Long.parseUnsignedLong(hash, 16)));
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;

/**
 * Pure (client-free) adapter that turns the plugin's tracked drops + stats into one list of task rows
 * for the Anvil side panel: progress, completion and board position per tile.
 *
 * Deliberately has no RuneLite dependencies so it is fully unit-testable.
 */
public final class ClogTaskModel
{
	private ClogTaskModel() {}

	public enum Status
	{
		IN_PROGRESS,
		NOT_STARTED,
		COMPLETED
	}

	/** A single task. Immutable but for {@link #position}; {@code points} is the tile's Leagues-style value. */
	public static final class TaskRow
	{
		public final int tileId;
		public final String label;
		public final int current;
		public final int goal;
		public final int points;
		public final Status status;
		// Board position — mirrors the site's tile order (difficulty sort, shuffle). Set after
		// construction; 0 on old servers.
		public int position;
		// The tile's description, for hover text. Set after construction; null when it has none.
		public String description;

		public TaskRow(int tileId, String label, int current, int goal, int points, boolean forceCompleted)
		{
			this.tileId = tileId;
			this.label = label == null ? "" : label;
			this.current = current;
			this.goal = goal;
			this.points = points;
			// A team-level completion (any member / manual) is authoritative even when this client's
			// own current < goal — e.g. an individual-mode tile a teammate finished first.
			this.status = forceCompleted ? Status.COMPLETED : statusOf(current, goal);
		}

		public boolean isCompleted()
		{
			return status == Status.COMPLETED;
		}
	}

	/**
	 * Derive completion status from progress. A goal of {@code <= 0} (an untargeted tile)
	 * counts as completed the moment there's any progress, otherwise not-started.
	 */
	public static Status statusOf(int current, int goal)
	{
		if (goal > 0)
		{
			if (current >= goal)
			{
				return Status.COMPLETED;
			}
			return current > 0 ? Status.IN_PROGRESS : Status.NOT_STARTED;
		}
		return current > 0 ? Status.COMPLETED : Status.NOT_STARTED;
	}

	/** Build the full task list from the plugin config (drops + stats). Null-safe. */
	public static List<TaskRow> build(PluginConfigResponse cfg)
	{
		List<TaskRow> rows = new ArrayList<>();
		if (cfg == null)
		{
			return rows;
		}

		Set<Integer> completed = new java.util.HashSet<>();
		each(cfg.completedTiles, c -> completed.add(c.tileId));

		each(cfg.trackedDrops, d ->
		{
			int current = d.currentAmount;
			int goal = d.requiredAmount;
			boolean done = completed.contains(d.tileId);
			// A per-item requirement list means "collect each of these" — a COLLECTION tile, which
			// completes when its SETS are satisfied, not when the summed submission count reaches
			// requiredAmount (the server stores that as a shortest-path total, often 1, so a 3-of-4
			// rings set read as 3/1 = done).
			if (d.itemRequirements != null && !d.itemRequirements.isEmpty())
			{
				int[] pg = collectionProgress(d.itemRequirements, d.groupMode, d.setsRequired);
				current = pg[0];
				goal = pg[1];
				done = done || pg[2] == 1;
			}
			add(rows, d, new TaskRow(d.tileId, d.label, current, goal, d.points, done));
		});
		each(cfg.trackedStats, s -> add(rows, s, new TaskRow(s.tileId, s.label, s.currentAmount,
			s.goalAmount, s.points, completed.contains(s.tileId))));
		// Kills, PvP kills, diaries and combat tasks all count completions toward requiredAmount.
		each(cfg.trackedKills, k -> add(rows, k, new TaskRow(k.tileId, k.label, k.currentAmount,
			k.requiredAmount, k.points, completed.contains(k.tileId))));
		each(cfg.trackedPvp, p -> add(rows, p, new TaskRow(p.tileId, p.label, p.currentAmount,
			p.requiredAmount, p.points, completed.contains(p.tileId))));
		each(cfg.trackedDiaries, d -> add(rows, d, new TaskRow(d.tileId, d.label, d.currentAmount,
			d.requiredAmount, d.points, completed.contains(d.tileId))));
		each(cfg.trackedCombatTasks, t -> add(rows, t, new TaskRow(t.tileId, t.label, t.currentAmount,
			t.requiredAmount, t.points, completed.contains(t.tileId))));
		// Timed tiles are pass/fail (no running count): the completed flag drives status; goal 1.
		each(cfg.trackedTimed, t ->
		{
			boolean done = t.completed || completed.contains(t.tileId);
			add(rows, t, new TaskRow(t.tileId, t.label, done ? 1 : 0, 1, t.points, done));
		});
		each(cfg.trackedLms, l -> add(rows, l, new TaskRow(l.tileId, l.label, l.currentAmount,
			Math.max(1, l.requiredAmount), l.points, completed.contains(l.tileId))));
		each(cfg.trackedValues, v ->
		{
			boolean done = v.completed || completed.contains(v.tileId);
			if (isTotalValue(v))
			{
				// A cumulative tile ("bank 50m between you") has real progress the server already
				// tracks. Bars are drawn from current/goal, so those carry the gp (clamped, since a
				// target can exceed an int).
				int goal = clampGp(v.thresholdGp);
				add(rows, v, new TaskRow(v.tileId, v.label, Math.min(clampGp(v.currentGp), goal), goal,
					v.points, done));
			}
			else
			{
				// Single-haul tiles are genuinely pass/fail — one qualifying drop or nothing.
				add(rows, v, new TaskRow(v.tileId, v.label, done ? 1 : 0, 1, v.points, done));
			}
		});
		// Gain tiles and deathless runs count like kills.
		each(cfg.trackedGains, g -> add(rows, g, new TaskRow(g.tileId, g.label, g.currentAmount,
			Math.max(1, g.requiredAmount), g.points, completed.contains(g.tileId))));
		each(cfg.trackedDeathless, d -> add(rows, d, new TaskRow(d.tileId, d.label, d.currentAmount,
			Math.max(1, d.requiredAmount), d.points, completed.contains(d.tileId))));
		return rows;
	}

	/** Every non-null entry of a possibly-null config list. */
	private static <T> void each(List<T> list, Consumer<T> f)
	{
		if (list != null)
		{
			for (T t : list)
			{
				if (t != null)
				{
					f.accept(t);
				}
			}
		}
	}

	/**
	 * True when a value tile accumulates toward its target rather than needing one qualifying haul.
	 * An older server sends no mode at all, which means single — the only behaviour it had.
	 */
	static boolean isTotalValue(PluginConfigResponse.TrackedValue v)
	{
		return v != null && "total".equalsIgnoreCase(v.mode);
	}

	/**
	 * Squeeze a gp amount into the int the progress bar is drawn from. A gp target is a long because
	 * a clan-wide one can pass 2.1b; the bar only needs the ratio, and both ends clamp together so a
	 * clamped tile still fills at the right rate rather than looking finished early.
	 */
	static int clampGp(long gp)
	{
		if (gp <= 0)
		{
			return 0;
		}
		return gp > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) gp;
	}

	/** Adds the row with its board position stamped — the within-status-group sort key. */
	private static void add(List<TaskRow> rows, PluginConfigResponse.TrackedTile tile, TaskRow row)
	{
		row.position = tile.position;
		row.description = tile.description;
		rows.add(row);
	}

	/**
	 * Set-aware collection progress, mirroring the site's lib/collectionSets (which owns the rule and
	 * decides completion server-side — this is the in-game read of the same tile).
	 *
	 * <p>Ungrouped requirements are ALWAYS required. Items sharing a {@code group} form one set, and a
	 * set counts as satisfied once {@code groupRequire} distinct items in it are obtained (0 = all of
	 * them, a full set). {@code groupMode} decides how the sets combine:
	 *
	 * <ul>
	 *   <li>{@code "any"} (default) — the sets are alternatives; satisfying ONE completes the tile.
	 *       Progress reports the set the player is CLOSEST to finishing, so a two-set tile shows real
	 *       progress toward one set instead of the inflated sum across every set.</li>
	 *   <li>{@code "all"} — every set must be satisfied. Progress sums what each set needs, so
	 *       "a unique from each of 4 bosses" reads 2/4 rather than pretending one boss finished it.</li>
	 * </ul>
	 *
	 * <p>An "any" tile needing {@code setsRequired} > 1 sets COUNTS them, the site's rule
	 * (lib/collectionSets setTimes): a set counts once per full batch of its pieces, across sets and
	 * within one, so 2 is "Ahrim's + Dharok's, or Ahrim's twice". Progress is in pieces: N times the
	 * smallest set, with the sets already done counted in full and the closest next one partly.
	 *
	 * <p>Returns {current, goal, done}. An older server sends no groupMode/groupRequire, which lands
	 * on exactly the previous behaviour: OR-ed full sets.
	 */
	static int[] collectionProgress(List<PluginConfigResponse.ItemRequirement> reqs, String groupMode, int setsRequired)
	{
		List<PluginConfigResponse.ItemRequirement> ungrouped = new ArrayList<>();
		LinkedHashMap<String, List<PluginConfigResponse.ItemRequirement>> groups = split(reqs, ungrouped);
		int ungroupedSat = satisfied(ungrouped);
		int ungroupedSize = ungrouped.size();
		boolean all = "all".equalsIgnoreCase(groupMode);
		if (setsRequired > 1 && !all && !groups.isEmpty())
		{
			return multiSetProgress(groups, ungroupedSat, ungroupedSize, setsRequired);
		}
		if (groups.isEmpty())
		{
			int goal = Math.max(1, ungroupedSize);
			return new int[]{ ungroupedSat, goal, ungroupedSat >= ungroupedSize && ungroupedSize > 0 ? 1 : 0 };
		}

		if (all)
		{
			// Every set must be satisfied: the tile's goal is the always-required items plus each set's
			// own requirement, and progress is what's been met toward that, capped per set so a fifth
			// Duke unique can't paper over a missing Leviathan one.
			int sat = ungroupedSat;
			int goal = ungroupedSize;
			boolean allSetsDone = true;
			for (List<PluginConfigResponse.ItemRequirement> grp : groups.values())
			{
				int need = requireCount(grp);
				int met = Math.min(satisfied(grp), need);
				sat += met;
				goal += need;
				if (met < need)
				{
					allSetsDone = false;
				}
			}
			return new int[]{ sat, Math.max(1, goal), allSetsDone && ungroupedSat >= ungroupedSize ? 1 : 0 };
		}

		// "any": each set, combined with the always-required items, is one alternative.
		int bestSat = 0;
		int bestGoal = 1;
		int bestRemaining = Integer.MAX_VALUE;
		for (List<PluginConfigResponse.ItemRequirement> grp : groups.values())
		{
			int need = requireCount(grp);
			int sat = ungroupedSat + Math.min(satisfied(grp), need);
			int size = ungroupedSize + need;
			if (size <= 0)
			{
				continue;
			}
			if (sat >= size)
			{
				return new int[]{ size, size, 1 }; // this set is satisfied — the tile is complete
			}
			int remaining = size - sat;
			if (remaining < bestRemaining || (remaining == bestRemaining && sat > bestSat))
			{
				bestRemaining = remaining;
				bestSat = sat;
				bestGoal = size;
			}
		}
		return new int[]{ bestSat, Math.max(1, bestGoal), 0 };
	}

	/**
	 * The requirements by set — case-insensitively, like the server's grouping, so "Duke" and "duke"
	 * are one set — with the ungrouped ones added to {@code ungrouped}.
	 */
	private static LinkedHashMap<String, List<PluginConfigResponse.ItemRequirement>> split(
		List<PluginConfigResponse.ItemRequirement> reqs, List<PluginConfigResponse.ItemRequirement> ungrouped)
	{
		LinkedHashMap<String, List<PluginConfigResponse.ItemRequirement>> groups = new LinkedHashMap<>();
		for (PluginConfigResponse.ItemRequirement r : reqs)
		{
			if (r == null)
			{
				continue;
			}
			String g = r.group == null ? "" : r.group.trim();
			if (g.isEmpty())
			{
				ungrouped.add(r);
			}
			else
			{
				groups.computeIfAbsent(g.toLowerCase(java.util.Locale.ROOT), k -> new ArrayList<>()).add(r);
			}
		}
		return groups;
	}

	/** {@link #collectionProgress} for N > 1 sets. */
	private static int[] multiSetProgress(LinkedHashMap<String, List<PluginConfigResponse.ItemRequirement>> groups,
		int ungroupedSat, int ungroupedSize, int n)
	{
		int setsDone = 0;
		int unit = Integer.MAX_VALUE;
		int bestPartial = 0;
		for (List<PluginConfigResponse.ItemRequirement> grp : groups.values())
		{
			int need = requireCount(grp);
			int times = setTimes(grp, need);
			setsDone += times;
			unit = Math.min(unit, need);
			// Pieces toward this set's NEXT copy.
			int partial = 0;
			for (PluginConfigResponse.ItemRequirement r : grp)
			{
				if (r.currentAmount >= (times + 1) * Math.max(1, r.requiredAmount))
				{
					partial++;
				}
			}
			bestPartial = Math.max(bestPartial, Math.min(partial, need - 1));
		}
		int goal = ungroupedSize + n * unit;
		int done = Math.min(setsDone, n);
		int current = ungroupedSat + done * unit + (done < n ? Math.min(bestPartial, unit - 1) : 0);
		boolean complete = setsDone >= n && ungroupedSat >= ungroupedSize;
		return new int[]{ complete ? goal : Math.min(current, goal - 1), Math.max(1, goal), complete ? 1 : 0 };
	}

	/** Times over a set is done: the largest k with {@code need} of its items at k × their amount. */
	static int setTimes(List<PluginConfigResponse.ItemRequirement> grp, int need)
	{
		List<Integer> perItem = new ArrayList<>();
		for (PluginConfigResponse.ItemRequirement r : grp)
		{
			perItem.add(r.currentAmount / Math.max(1, r.requiredAmount));
		}
		perItem.sort(java.util.Collections.reverseOrder());
		int idx = Math.min(need, perItem.size()) - 1;
		return idx < 0 ? 0 : perItem.get(idx);
	}

	/**
	 * The most of one item a tile can use — the site's lib/collectionSets itemCap. Normally its own
	 * amount; a grouped piece on an "any" tile needing N sets is useful N times over.
	 */
	static int itemCap(PluginConfigResponse.ItemRequirement req, String groupMode, int setsRequired)
	{
		int amount = Math.max(1, req.requiredAmount);
		boolean grouped = req.group != null && !req.group.trim().isEmpty();
		if (!grouped || "all".equalsIgnoreCase(groupMode))
		{
			return amount;
		}
		return amount * Math.max(1, setsRequired);
	}

	/** How many of these requirements the player has met. */
	private static int satisfied(List<PluginConfigResponse.ItemRequirement> reqs)
	{
		int n = 0;
		for (PluginConfigResponse.ItemRequirement r : reqs)
		{
			if (r.currentAmount >= Math.max(1, r.requiredAmount))
			{
				n++;
			}
		}
		return n;
	}

	/**
	 * How many distinct items a set needs. Rows of a set should agree; if they don't (hand-edited
	 * config) the strictest wins, clamped to the set's size so a stale "any 4 of" on a set that has
	 * since shrunk to 3 items stays satisfiable. Same resolution as the server's.
	 */
	private static int requireCount(List<PluginConfigResponse.ItemRequirement> grp)
	{
		int declared = 0;
		for (PluginConfigResponse.ItemRequirement r : grp)
		{
			if (r.groupRequire > declared)
			{
				declared = r.groupRequire;
			}
		}
		if (declared <= 0)
		{
			declared = grp.size();
		}
		return Math.min(Math.max(1, declared), grp.size());
	}

	/**
	 * The scored (non-optional) rows tallied for the board summary: their count, or the sum of their
	 * points, of every row or only the completed ones. Optional tiles are bonus, off the score.
	 */
	public static int tally(List<TaskRow> rows, Set<Integer> optionalTileIds, boolean completedOnly, boolean points)
	{
		int n = 0;
		for (TaskRow r : rows)
		{
			if ((!completedOnly || r.isCompleted()) && !optionalTileIds.contains(r.tileId))
			{
				n += points ? r.points : 1;
			}
		}
		return n;
	}
}

package com.anvil;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/**
 * A debounced push of ABSOLUTE counts — skill XP, boss kill counts, activity counters.
 *
 * <p>Values are queued per key and one request goes out once they stop moving, so a kill streak or
 * a training burst collapses into a single push of the newest numbers. Absolute values make a resend
 * harmless, which is what makes failure simple: the batch is folded back in (max-merged, so a newer
 * number queued meanwhile wins) and tried again — after a wait that doubles per failure up to
 * {@link #RETRY_CAP_MS}, so a site that is down isn't asked every 15 seconds. A permanent refusal
 * (a 4xx other than 401/408/429) drops the batch instead: resending it would never work. The network
 * send runs on the plugin's executor; nothing here touches the client thread.
 */
@Slf4j
final class CoalescedPush
{
	interface Sender
	{
		void send(Map<String, Integer> batch) throws IOException;
	}

	private final String what;
	private final long delayMs;
	private final Supplier<ScheduledExecutorService> executor;
	private final BooleanSupplier allowed;
	private final Sender sender;
	private final Runnable afterSend;
	/** What the site last accepted, when only a RISE is worth sending; null to send every value. */
	private final Map<String, Integer> sent;
	private final Map<String, Integer> pending = new HashMap<>();
	private ScheduledFuture<?> task;
	/** Failed sends since the last success; 0 = healthy. Drives the retry wait. */
	private int failures;
	/** Longest wait between retries while the site keeps failing. */
	static final long RETRY_CAP_MS = 300_000L;

	CoalescedPush(String what, long delayMs, boolean onlyRises, Supplier<ScheduledExecutorService> executor,
		BooleanSupplier allowed, Sender sender, Runnable afterSend)
	{
		this.what = what;
		this.delayMs = delayMs;
		this.sent = onlyRises ? new HashMap<>() : null;
		this.executor = executor;
		this.allowed = allowed;
		this.sender = sender;
		this.afterSend = afterSend;
	}

	void queue(String key, int value)
	{
		queue(java.util.Collections.singletonMap(key, value));
	}

	/** Buffer {@code values} and restart the settle timer — unless nothing in them is new. */
	synchronized void queue(Map<String, Integer> values)
	{
		ScheduledExecutorService ex = executor.get();
		if (ex == null || ex.isShutdown())
		{
			return;
		}
		boolean queued = false;
		for (Map.Entry<String, Integer> e : values.entrySet())
		{
			Integer last = sent == null ? null : sent.get(e.getKey());
			if (last == null || last < e.getValue())
			{
				pending.put(e.getKey(), e.getValue());
				queued = true;
			}
		}
		// While backing off, new values ride the retry that's already waiting rather than pulling it
		// forward to the settle delay — a training session would otherwise retry every 15s regardless.
		if (queued && !(failures > 0 && task != null && !task.isDone()))
		{
			schedule(ex, delayMs);
		}
	}

	/** What's waiting to go — for saving across a logout or restart. */
	synchronized Map<String, Integer> snapshot()
	{
		return new HashMap<>(pending);
	}

	/**
	 * Fold saved values back in. They're absolute, so the larger of saved and queued wins per key —
	 * the same merge a failed send uses.
	 */
	synchronized void restore(Map<String, Integer> values)
	{
		if (values == null || values.isEmpty())
		{
			return;
		}
		values.forEach((k, v) ->
		{
			if (k != null && v != null)
			{
				pending.merge(k, v, Integer::max);
			}
		});
		ScheduledExecutorService ex = executor.get();
		if (ex != null && !ex.isShutdown())
		{
			schedule(ex, delayMs);
		}
	}

	/** The site is reachable again: send what's waiting now instead of sitting out the backoff. */
	synchronized void kick()
	{
		if (failures == 0 || pending.isEmpty())
		{
			return;
		}
		failures = 0;
		ScheduledExecutorService ex = executor.get();
		if (ex != null && !ex.isShutdown())
		{
			schedule(ex, 0);
		}
	}

	/** Forget everything queued (and sent) — a new account, or the plugin stopping. */
	synchronized void reset()
	{
		pending.clear();
		failures = 0;
		if (sent != null)
		{
			sent.clear();
		}
		if (task != null)
		{
			task.cancel(false);
			task = null;
		}
	}

	private void schedule(ScheduledExecutorService ex, long waitMs)
	{
		if (task != null)
		{
			task.cancel(false);
		}
		task = ex.schedule(this::flush, waitMs, TimeUnit.MILLISECONDS);
	}

	/** The wait before the next retry after {@code failures} straight failures. First retry = the settle delay. */
	static long retryDelayMs(int failures, long settleMs, double jitter)
	{
		return RetryPolicy.backoffMs(failures, settleMs, Math.max(settleMs, RETRY_CAP_MS), jitter);
	}

	/** Send the buffer (no screenshot). Requeues on failure. */
	void flush()
	{
		Map<String, Integer> batch;
		synchronized (this)
		{
			if (pending.isEmpty())
			{
				return;
			}
			batch = new HashMap<>(pending);
			pending.clear();
		}
		if (!allowed.getAsBoolean())
		{
			return; // stopped being allowed between queue and flush — the hiscores side still has it
		}
		try
		{
			sender.send(batch);
		}
		catch (BingoApiClient.PermanentSubmissionException e)
		{
			// The site will never take this batch (a 4xx that isn't 401/408/429). Drop it rather than
			// resend it forever; newer values queued meanwhile still go on their own.
			log.warn("{} push refused ({} key(s)) — dropping: {}", what, batch.size(), e.getMessage());
			synchronized (this)
			{
				failures = 0;
			}
			return;
		}
		catch (IOException e)
		{
			synchronized (this)
			{
				failures++;
				batch.forEach((k, v) -> pending.merge(k, v, Integer::max));
				long wait = retryDelayMs(failures, delayMs, Math.random());
				log.warn("{} push failed ({} key(s)) — retrying in {}s: {}", what, batch.size(), wait / 1000, e.getMessage());
				ScheduledExecutorService ex = executor.get();
				if (ex != null && !ex.isShutdown())
				{
					schedule(ex, wait);
				}
			}
			return;
		}
		synchronized (this)
		{
			failures = 0;
			if (sent != null)
			{
				batch.forEach((k, v) -> sent.merge(k, v, Integer::max));
			}
		}
		afterSend.run(); // pull back the updated progress / any completion the push triggered
	}
}

package com.anvil;

import java.util.Locale;
import net.runelite.api.gameval.VarbitID;

/**
 * The six Combat Achievement tiers, with the point value awarded for a task at that tier and the
 * varbit holding the cumulative points needed to unlock the tier's rewards. Used to detect both
 * individual task completions (chat message gives the tier name) and tier unlocks (a task pushing
 * total points across a threshold).
 */
public enum CombatAchievementTier
{
	EASY(VarbitID.CA_THRESHOLD_EASY),
	MEDIUM(VarbitID.CA_THRESHOLD_MEDIUM),
	HARD(VarbitID.CA_THRESHOLD_HARD),
	ELITE(VarbitID.CA_THRESHOLD_ELITE),
	MASTER(VarbitID.CA_THRESHOLD_MASTER),
	GRANDMASTER(VarbitID.CA_THRESHOLD_GRANDMASTER);

	private final int thresholdVarbitId;

	CombatAchievementTier(int thresholdVarbitId)
	{
		this.thresholdVarbitId = thresholdVarbitId;
	}

	/** "Easy" … "Grandmaster". */
	public String getDisplayName()
	{
		return name().charAt(0) + name().substring(1).toLowerCase(Locale.ROOT);
	}

	public int getThresholdVarbitId()
	{
		return thresholdVarbitId;
	}

	@Override
	public String toString()
	{
		return getDisplayName();
	}

	/** Resolves the tier from the word used in the completion message ("easy", "elite", …). */
	public static CombatAchievementTier byName(String name)
	{
		if (name == null)
		{
			return null;
		}
		for (CombatAchievementTier t : values())
		{
			if (t.name().equalsIgnoreCase(name))
			{
				return t;
			}
		}
		return null;
	}
}

package com.anvil;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.LongFunction;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;

import static com.anvil.PlayerCardView.header;
import static com.anvil.Ui.*;

/**
 * Two players side by side — you and whoever you looked up. A line per headline number with the
 * leader's in orange, then where each of you is ahead: skills by the size of the gap, the bosses
 * either of you kills most, and the log pages where your counts differ.
 */
final class CompareView
{
	private CompareView()
	{
	}

	static JPanel players(PlayerCard me, PlayerCard them, PlayerCardView.Icons icons)
	{
		PlayerCardView.Icons ic = icons == null ? PlayerCardView.Icons.NONE : icons;
		JPanel root = column();

		JPanel head = block();
		head.add(namesRow("You", them.rsn));
		head.add(gap(4));
		head.add(row("Total level", me.totalLevel, them.totalLevel, n -> String.format(Locale.ROOT, "%,d", n)));
		head.add(row("Combat", nz(me.combatLevel), nz(them.combatLevel), Long::toString));
		head.add(row("Total XP", nz(me.overallXp), nz(them.overallXp), PlayerCardView::compact));
		head.add(row("EHP", Math.round(nzd(me.ehp)), Math.round(nzd(them.ehp)), n -> n + "h"));
		head.add(row("EHB", Math.round(nzd(me.ehb)), Math.round(nzd(them.ehb)), n -> n + "h"));
		head.add(row("Log slots", me.clog == null ? -1 : me.clog.obtained, them.clog == null ? -1 : them.clog.obtained,
			n -> n < 0 ? "—" : String.format(Locale.ROOT, "%,d", n)));
		root.add(head);

		List<SkillDiff> skills = skillDiffs(me, them);
		if (!skills.isEmpty())
		{
			root.add(gap(6));
			JPanel block = block();
			int ahead = 0;
			int behind = 0;
			for (SkillDiff d : skills)
			{
				if (d.mine > d.theirs)
				{
					ahead++;
				}
				else if (d.theirs > d.mine)
				{
					behind++;
				}
			}
			block.add(header("Skills", "you lead " + ahead + " · they lead " + behind));
			block.add(gap(4));
			JPanel grid = left(new JPanel(new GridLayout(0, 2, 6, 2)));
			grid.setOpaque(false);
			for (SkillDiff d : skills)
			{
				JLabel cell = small(d.mine + " / " + d.theirs,
					d.mine > d.theirs ? ColorScheme.PROGRESS_COMPLETE_COLOR : d.theirs > d.mine ? ColorScheme.PROGRESS_ERROR_COLOR : MUTED);
				cell.setIconTextGap(6);
				cell.setToolTipText(d.skill.getName() + " — you " + d.mine + ", them " + d.theirs);
				if (ic.skills != null)
				{
					cell.setIcon(new ImageIcon(ic.skills.getSkillImage(d.skill, true)));
				}
				grid.add(cell);
			}
			block.add(grid);
			root.add(block);
		}

		List<long[]> bossRows = new ArrayList<>();
		List<String> bossNames = new ArrayList<>();
		bossDiffs(me, them, bossNames, bossRows);
		if (!bossRows.isEmpty())
		{
			root.add(gap(6));
			JPanel block = block();
			block.add(header("Bosses", "you / them"));
			block.add(gap(4));
			for (int i = 0; i < bossRows.size(); i++)
			{
				block.add(iconRow(bossNames.get(i), bossRows.get(i)[0], bossRows.get(i)[1], ic));
			}
			root.add(block);
		}

		List<String[]> pages = pageDiffs(me, them);
		if (!pages.isEmpty())
		{
			root.add(gap(6));
			JPanel block = block();
			block.add(header("Collection log", "pages that differ"));
			block.add(gap(4));
			for (String[] p : pages)
			{
				block.add(row(p[0], Long.parseLong(p[1]), Long.parseLong(p[2]), Long::toString));
			}
			root.add(block);
		}
		return root;
	}

	// ---- Rows --------------------------------------------------------------------------------------

	static JPanel namesRow(String left, String right)
	{
		return threeUp(new JLabel(), small(left, Color.WHITE), small(right, Color.WHITE));
	}

	/** "Label    a    b" with the bigger of the two in orange. Negative = unknown, never leads. */
	static JPanel row(String label, long a, long b, LongFunction<String> fmt)
	{
		Color lead = ColorScheme.BRAND_ORANGE;
		return threeUp(small(label, MUTED), small(fmt.apply(a), a >= 0 && a > b ? lead : Color.WHITE),
			small(fmt.apply(b), b >= 0 && b > a ? lead : Color.WHITE));
	}

	/** Three equal columns, the two figures right-aligned. */
	private static JPanel threeUp(JLabel first, JLabel l, JLabel r)
	{
		JPanel row = left(new JPanel(new GridLayout(1, 3, 6, 0)));
		row.setOpaque(false);
		row.add(first);
		l.setHorizontalAlignment(SwingConstants.RIGHT);
		r.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(l);
		row.add(r);
		return capH(row);
	}

	private static JPanel iconRow(String name, long a, long b, PlayerCardView.Icons ic)
	{
		JPanel row = Ui.row(6);
		JLabel icon = PlayerCardView.iconSlot(22, 20);
		PlayerCardView.bossIcon(icon, name, ic);
		row.add(icon, BorderLayout.WEST);
		row.add(row(name, a, b, n -> String.format(Locale.ROOT, "%,d", n)), BorderLayout.CENTER);
		return capH(row);
	}

	// ---- Diffs (package-private for tests) ---------------------------------------------------------

	static final class SkillDiff
	{
		final Skill skill;
		final int mine;
		final int theirs;

		SkillDiff(Skill skill, int mine, int theirs)
		{
			this.skill = skill;
			this.mine = mine;
			this.theirs = theirs;
		}
	}

	/** Every skill either of you has, biggest level gap first. */
	static List<SkillDiff> skillDiffs(PlayerCard me, PlayerCard them)
	{
		Map<String, Integer> a = levels(me);
		Map<String, Integer> b = levels(them);
		List<SkillDiff> out = new ArrayList<>();
		if (a.isEmpty() && b.isEmpty())
		{
			return out;
		}
		for (Skill s : PlayerCardView.SKILL_GRID)
		{
			String k = s.name().toLowerCase(Locale.ROOT);
			out.add(new SkillDiff(s, a.getOrDefault(k, 1), b.getOrDefault(k, 1)));
		}
		out.sort((x, y) -> Math.abs(y.mine - y.theirs) - Math.abs(x.mine - x.theirs));
		return out;
	}

	private static Map<String, Integer> levels(PlayerCard c)
	{
		Map<String, Integer> m = new HashMap<>();
		if (c.skills != null)
		{
			for (PlayerCard.Skill s : c.skills)
			{
				m.put(s.key.toLowerCase(Locale.ROOT), s.level);
			}
		}
		return m;
	}

	/** The ten bosses either of you has killed most, with both counts. */
	static void bossDiffs(PlayerCard me, PlayerCard them, List<String> names, List<long[]> rows)
	{
		Map<String, long[]> by = new HashMap<>();
		Map<String, String> label = new HashMap<>();
		for (int side = 0; side < 2; side++)
		{
			PlayerCard c = side == 0 ? me : them;
			if (c.bosses == null)
			{
				continue;
			}
			for (PlayerCard.Boss b : c.bosses)
			{
				by.computeIfAbsent(b.key, k -> new long[2])[side] = b.kc;
				label.putIfAbsent(b.key, b.label);
			}
		}
		by.entrySet().stream()
			.sorted((x, y) -> Long.compare(Math.max(y.getValue()[0], y.getValue()[1]), Math.max(x.getValue()[0], x.getValue()[1])))
			.limit(10)
			.forEach(e ->
			{
				names.add(label.get(e.getKey()));
				rows.add(e.getValue());
			});
	}

	/** Log pages where your counts differ, biggest gap first, at most eight: {name, mine, theirs}. */
	static List<String[]> pageDiffs(PlayerCard me, PlayerCard them)
	{
		Map<String, int[]> by = new HashMap<>();
		for (int side = 0; side < 2; side++)
		{
			PlayerCard c = side == 0 ? me : them;
			if (c.clogPages == null)
			{
				continue;
			}
			for (PlayerCard.Page p : c.clogPages)
			{
				by.computeIfAbsent(p.name, k -> new int[2])[side] = p.obtained;
			}
		}
		List<String[]> out = new ArrayList<>();
		by.entrySet().stream()
			.filter(e -> e.getValue()[0] != e.getValue()[1])
			.sorted((x, y) -> Math.abs(y.getValue()[0] - y.getValue()[1]) - Math.abs(x.getValue()[0] - x.getValue()[1]))
			.limit(8)
			.forEach(e -> out.add(new String[]{e.getKey(), Integer.toString(e.getValue()[0]), Integer.toString(e.getValue()[1])}));
		return out;
	}

	private static long nz(Number n)
	{
		return n == null ? -1 : n.longValue();
	}

	private static double nzd(Double d)
	{
		return d == null ? 0 : d;
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Immutable UI view-model for the addressed clan in the sidebar ({@link AnvilSidebarPanel}), folding
 * the polled config + feed reads. RuneLite-free so
 * it's unit-testable and the panel binds to this shape, not an HTTP client; value-object style like
 * {@link ClogTaskModel.TaskRow}.
 */
public final class ConnectionView
{
	/**
	 * Milli-hours per hour. EHP/EHB weeklies travel as hours × 1000 (the site's EFFICIENCY_SCALE) so a
	 * week's gain survives the integer columns it's stored in — divide before showing one.
	 */
	static final double EFFICIENCY_SCALE = 1000.0;

	/** Compact count for display: {@code 1.2M} / {@code 340K} / {@code 850}. */
	static String formatCount(long n)
	{
		if (n >= 1_000_000)
		{
			double m = n / 1_000_000.0;
			return (m == Math.floor(m) ? String.valueOf((int) m) : String.format(java.util.Locale.ROOT, "%.1f", m)) + "M";
		}
		if (n >= 10_000)
		{
			return (n / 1000) + "K";
		}
		return String.valueOf(n);
	}

	/** Human clan/instance name — the label shown in the clan filter. */
	public final String clanName;

	/** Active event name, or {@code null} when there's no live event. */
	public final String eventName;

	/** A partial failure (the live feed), or {@code null} when reached cleanly — shown inline on the card. */
	public final String error;

	/** Tiles your team has completed on this board. */
	public final int tilesComplete;

	/** Total tiles on this board. */
	public final int tilesTotal;

	/** Tiles closest to completion, ordered nearest-first by the data source. Never {@code null}. */
	public final List<TileProgressView> nearestTiles;

	/** Newest-first team activity feed (the {@link AnvilActivityLog} snapshot). Never {@code null}. */
	public final List<ActivityEntry> recentActivity;

	/** Tiles being actively worked right now — yours and teammates', deduped by tile. Never {@code null}. */
	public final List<ActiveTask> activeNow;

	/** Site page to open for this board ({@code <baseUrl>/events/<id>}), or {@code null} when unknown. */
	public final String boardUrl;

	/**
	 * True when this board is scored by summed tile POINTS (Leagues — {@code scoringMode=points})
	 * rather than tile count. When set, {@link #tilesComplete}/{@link #tilesTotal} hold earned/total
	 * points and {@link #unitNoun()} reads "pts". Classic bingo + tile race stay count-based ("tiles").
	 */
	public final boolean pointsScored;

	/**
	 * Benign inline status for a board-less card ({@code tilesTotal == 0}) — e.g. the logged-out home's
	 * "Log in in-game to load your board." Unlike {@link #error} it never marks the clan filter with
	 * "(!)". {@code null} → the panel's generic "No active event yet." line.
	 */
	public final String statusNote;

	/**
	 * Reveal-policy boards (showdown / lucky draw / bounty) only: the one-line "still hidden" status
	 * rendered under the board summary — e.g. {@code "🙈 4 tiles hidden · next 19:00"} or
	 * {@code "🎯 4 bounties left · next on claim"}. {@code null} on classic boards (no line).
	 */
	public final String revealNote;

	/**
	 * Ladder events (DMM-All-Stars-style missions board): the live countdown target, the caller's rank,
	 * and the active missions with their face points + reveal times. {@code null} on every non-ladder
	 * board — the panel renders the normal summary + {@link #revealNote} instead. See {@link LadderMissions}
	 * for the per-second value/countdown math this feeds.
	 */
	public final Ladder ladder;

	/**
	 * Live weekly competitions on this clan (SOTW/BOTW) — events in their own right alongside the board,
	 * so a clan running only a weekly still has something to show. The panel lists them next to the board
	 * and drills into one on click. Never {@code null}.
	 */
	public final List<WeeklyView> weeklies;

	/**
	 * Other bingo events on this clan's schedule — starting soon, or live but not the caller's own
	 * board. Listed after the live stuff so members can see what's coming without leaving the game.
	 * Never {@code null}.
	 */
	public final List<ScheduledView> scheduled;

	/**
	 * Every tracked tile's progress on this board, by tile id — the same team numbers as
	 * {@link #nearestTiles}, uncapped, so a tile's detail view can show how far along it is. Never
	 * {@code null}; manual tiles are absent (the plugin has no count for them).
	 */
	public final Map<Integer, ClogTaskModel.TaskRow> tileProgress;

	public ConnectionView(String clanName, String eventName, String error,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles,
		List<ActivityEntry> recentActivity, List<ActiveTask> activeNow, String boardUrl, boolean pointsScored,
		String statusNote, String revealNote, Ladder ladder, List<WeeklyView> weeklies,
		List<ScheduledView> scheduled)
	{
		this(clanName, eventName, error, tilesComplete, tilesTotal, nearestTiles, recentActivity, activeNow,
			boardUrl, pointsScored, statusNote, revealNote, ladder, weeklies, scheduled, null);
	}

	public ConnectionView(String clanName, String eventName, String error,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles,
		List<ActivityEntry> recentActivity, List<ActiveTask> activeNow, String boardUrl, boolean pointsScored,
		String statusNote, String revealNote, Ladder ladder, List<WeeklyView> weeklies,
		List<ScheduledView> scheduled, List<ClogTaskModel.TaskRow> tileRows)
	{
		this.clanName = clanName == null || clanName.isEmpty() ? "(unnamed clan)" : clanName;
		this.eventName = eventName;
		this.error = error;
		this.tilesComplete = Math.max(0, tilesComplete);
		this.tilesTotal = Math.max(0, tilesTotal);
		this.nearestTiles = copyOrEmpty(nearestTiles);
		this.recentActivity = copyOrEmpty(recentActivity);
		this.activeNow = copyOrEmpty(activeNow);
		this.boardUrl = boardUrl;
		this.pointsScored = pointsScored;
		this.statusNote = statusNote;
		this.revealNote = revealNote;
		this.ladder = ladder;
		this.weeklies = copyOrEmpty(weeklies);
		this.scheduled = copyOrEmpty(scheduled);
		Map<Integer, ClogTaskModel.TaskRow> progress = new HashMap<>();
		if (tileRows != null)
		{
			for (ClogTaskModel.TaskRow r : tileRows)
			{
				progress.put(r.tileId, r);
			}
		}
		this.tileProgress = Collections.unmodifiableMap(progress);
	}

	private static <T> List<T> copyOrEmpty(List<T> src)
	{
		return src == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(src));
	}

	public boolean hasError()
	{
		return error != null && !error.isEmpty();
	}

	/** Board completion as 0..100, or 0 when the board has no tiles. Points-weighted for Leagues. */
	public int completionPercent()
	{
		return tilesTotal > 0 ? Math.min(100, (int) Math.round(tilesComplete * 100.0 / tilesTotal)) : 0;
	}

	/** The noun for {@link #tilesComplete}/{@link #tilesTotal}: "pts" for a points board, else "tiles". */
	public String unitNoun()
	{
		return pointsScored ? "pts" : "tiles";
	}

	/**
	 * One tile's progress ("nearest tiles" rows) — mirrors the {@code current}/{@code goal} pair used elsewhere
	 * ({@link ClogTaskModel.TaskRow}), so the future {@code /board} binding is a straight copy.
	 */
	public static final class TileProgressView
	{
		/** The board tile this row is, so clicking it can open that tile; -1 when unknown. */
		public final int tileId;
		public final String name;
		public final int current;
		public final int target;
		public final boolean complete;

		public TileProgressView(String name, int current, int target, boolean complete)
		{
			this(-1, name, current, target, complete);
		}

		public TileProgressView(int tileId, String name, int current, int target, boolean complete)
		{
			this.tileId = tileId;
			this.name = name == null ? "" : name;
			this.current = Math.max(0, current);
			this.target = Math.max(0, target);
			// A team-level completion is authoritative even if current < target (a teammate finished it).
			this.complete = complete || (target > 0 && this.current >= target);
		}

		/** Progress as 0..100. An untargeted tile (target ≤ 0) is 100 when complete, else 0. */
		public int percent()
		{
			if (target > 0)
			{
				return Math.min(100, (int) Math.round(current * 100.0 / target));
			}
			return complete ? 100 : 0;
		}
	}

	/**
	 * One tile someone's actively working ("Active now") — the tile's progress ({@link ClogTaskModel.TaskRow})
	 * plus who's on it ({@code "You"} for the local player, teammates by RSN, deduped).
	 */
	public static final class ActiveTask
	{
		public final ClogTaskModel.TaskRow tile;
		/** Distinct workers, "You" first when the local player is among them. Never null/empty. */
		public final List<String> workers;
		public final boolean includesSelf;
		/**
		 * KC / XP tiles: what each worker has gained on this tile over the event ({@code "You"} too), so
		 * the row shows who's actually landing kills. Empty for other tiles and on older sites.
		 */
		public final Map<String, Long> gains;

		public ActiveTask(ClogTaskModel.TaskRow tile, List<String> workers, boolean includesSelf)
		{
			this(tile, workers, includesSelf, null);
		}

		public ActiveTask(ClogTaskModel.TaskRow tile, List<String> workers, boolean includesSelf, Map<String, Long> gains)
		{
			this.tile = tile;
			this.workers = copyOrEmpty(workers);
			this.includesSelf = includesSelf;
			this.gains = gains == null ? Collections.emptyMap() : Collections.unmodifiableMap(new HashMap<>(gains));
		}

		/** "You", "Kayle", or "You + Kayle" / "You + 2 others" for the row's byline. */
		public String workersLabel()
		{
			if (workers.isEmpty())
			{
				return "";
			}
			if (!gains.isEmpty())
			{
				// "You 45 · Kurrozive 312 · +2" — numbers, so the row says who's landing the kills.
				StringBuilder b = new StringBuilder();
				int shown = Math.min(workers.size(), 3);
				for (int i = 0; i < shown; i++)
				{
					String w = workers.get(i);
					Long g = gains.get(w);
					b.append(i > 0 ? " · " : "").append(w);
					if (g != null && g > 0)
					{
						b.append(' ').append(formatCount(g));
					}
				}
				if (workers.size() > shown)
				{
					b.append(" · +").append(workers.size() - shown);
				}
				return b.toString();
			}
			if (workers.size() == 1)
			{
				return workers.get(0);
			}
			if (workers.size() == 2)
			{
				return workers.get(0) + " + " + workers.get(1);
			}
			return workers.get(0) + " + " + (workers.size() - 1) + " others";
		}
	}

	/**
	 * One live weekly competition (Skill / Boss of the Week) as the sidebar shows it: the comp itself,
	 * the caller's standing, and the head of the leaderboard. Every display string is derived here so
	 * the panel just renders — and so the shaping is unit-testable without Swing.
	 */
	public static final class WeeklyView
	{
		public final int id;
		public final String title;
		/** {@code "skill"} | {@code "boss"} — picks the kind label and the gain's unit. */
		public final String type;
		/** Raw metric key as the site stores it ({@code "mining"}, {@code "chambers_of_xeric"}). */
		public final String metric;
		/** What the site calls that metric, when it sends one. Read through {@link #metricLabel()}. */
		private final String sentLabel;
		public final String startDate;
		public final String endDate;
		/** True for a comp that hasn't started yet — it has no standings, just a start time. */
		public final boolean upcoming;
		/** Caller's rank, or 0 when they aren't on the board (not enrolled / no gain yet / unknown). */
		public final int yourRank;
		public final long yourGained;
		/** Ranked participants, or 0 when the standings couldn't be read. */
		public final int participants;
		/** Head of the leaderboard, rank order, capped by the source. Never {@code null}. */
		public final List<Standing> top;
		/** The comp's page on the Anvil site ({@code <baseUrl>/weekly/<id>}), or {@code null} when unknown. */
		public final String url;

		public WeeklyView(int id, String title, String type, String metric, String sentLabel, String startDate,
			String endDate, boolean upcoming, int yourRank, long yourGained, int participants,
			List<Standing> top, String url)
		{
			this.sentLabel = sentLabel;
			this.id = id;
			this.title = title == null || title.isEmpty() ? kindLabel(type) : title;
			this.type = type == null ? "" : type;
			this.metric = metric == null ? "" : metric;
			this.startDate = startDate;
			this.endDate = endDate;
			this.upcoming = upcoming;
			this.yourRank = Math.max(0, yourRank);
			this.yourGained = Math.max(0, yourGained);
			this.participants = Math.max(0, participants);
			this.top = copyOrEmpty(top);
			this.url = url;
		}

		/** True for an EHP/EHB comp — ranked by efficient hours, not one skill's XP or one boss's KC. */
		private boolean efficiency()
		{
			return "efficiency".equalsIgnoreCase(type);
		}

		/**
		 * "Skill of the Week" / "Boss of the Week" / "Efficiency of the Week" — the card's kind line and
		 * the list row's subtitle. The static form is for callers that hold only a raw type string (the
		 * login greeting), so they name a comp the same way this card does.
		 */
		public String kindLabel()
		{
			return kindLabel(type);
		}

		public static String kindLabel(String type)
		{
			if ("skill".equalsIgnoreCase(type))
			{
				return "Skill of the Week";
			}
			// Efficiency comps are a THIRD type, not a fallback: matching only "skill" and letting
			// everything else read as boss labelled every EHP/EHB week "Boss of the Week".
			return "efficiency".equalsIgnoreCase(type) ? "Efficiency of the Week" : "Boss of the Week";
		}

		/**
		 * The tracked metric, spelled for a person: the site's own name for it, falling back to what the
		 * key can be made to look like.
		 *
		 * <p>Prefer what was sent, always. Boss keys are hiscores keys, and no amount of splitting
		 * "phosanisNightmare" recovers the apostrophe in "Phosani's Nightmare" or turns
		 * "chambersOfXericChallengeMode" into the clan's "CoX: CM". The fallback exists for sites
		 * older than the field, not as an equal option.
		 */
		public String metricLabel()
		{
			if (sentLabel != null && !sentLabel.trim().isEmpty())
			{
				return sentLabel.trim();
			}
			// "ehp"/"ehb" are initialisms — humanise would title-case them to "Ehp".
			return efficiency() ? metric.toUpperCase(java.util.Locale.ROOT) : humanise(metric);
		}

		/** What a gain counts in: XP for a skill comp, kills for a boss one, hours for EHP/EHB. */
		public String unitNoun()
		{
			if (efficiency())
			{
				return "hrs";
			}
			return "skill".equalsIgnoreCase(type) ? "xp" : "kc";
		}

		/** A gain as the UI shows it — "1.2M xp", "184 kc", "12.40 hrs". */
		public String formatGain(long gained)
		{
			long safe = Math.max(0, gained);
			// Efficiency comps travel in MILLI-hours (the site's EFFICIENCY_SCALE): the weekly's
			// integer columns would round 12.4 EHB down to 12 and throw away most of a week's gain.
			// Rendered raw that arrives as "+12,400 kc".
			return (efficiency()
				? String.format(java.util.Locale.ROOT, "%.2f", safe / EFFICIENCY_SCALE)
				: formatCount(safe)) + " " + unitNoun();
		}

		/** Underscored/hyphenated metric keys → title case, keeping the small joining words lowercase. */
		static String humanise(String key)
		{
			if (key == null || key.isEmpty())
			{
				return "";
			}
			// Boss keys arrive camel-cased ("phosanisNightmare"), so a split on separators alone left
			// them as one word and title-case made it "PhosanisNightmare" — which is what the in-game
			// banner printed. A word boundary is also lower→upper (and letter→digit, for "theatreOfBlood2").
			String spaced = key.replace('_', ' ').replace('-', ' ')
				.replaceAll("(?<=[a-z0-9])(?=[A-Z])", " ")
				.replaceAll("(?<=[A-Za-z])(?=[0-9])", " ");
			String[] words = spaced.trim().split("\\s+");
			StringBuilder out = new StringBuilder();
			for (int i = 0; i < words.length; i++)
			{
				String w = words[i];
				if (w.isEmpty())
				{
					continue;
				}
				if (out.length() > 0)
				{
					out.append(' ');
				}
				// Case-insensitively, because the camel split hands these over capitalised ("Of").
				boolean small = i > 0 && ("of".equalsIgnoreCase(w) || "the".equalsIgnoreCase(w)
					|| "and".equalsIgnoreCase(w) || "at".equalsIgnoreCase(w));
				out.append(small ? w.toLowerCase(java.util.Locale.ROOT)
					: Character.toUpperCase(w.charAt(0)) + w.substring(1));
			}
			return out.toString();
		}
	}

	/**
	 * A bingo event on the clan's schedule that ISN'T the caller's own board — one starting soon, or a
	 * live one they aren't enrolled in. Read-only: there's no progress to show, so the card is the
	 * pitch (what, when, how big) plus a link to sign up on the site.
	 */
	public static final class ScheduledView
	{
		public final int id;
		public final String title;
		public final String startDate;
		public final String endDate;
		/** True when it's already running (the caller just isn't in it); false = still upcoming. */
		public final boolean live;
		/** Tiles configured, or 0 when the site didn't say. */
		public final int tileCount;
		/**
		 * The site's `boardSize`, whose MEANING depends on the format: N for a classic N×N grid, the
		 * tile COUNT for every list format (Leagues, tile race, ladder). See {@link #squareGrid()}.
		 */
		public final int boardSize;
		public final String format;
		public final String scoringMode;
		/** The event's page on the Anvil site, or {@code null} when the base URL is unknown. */
		public final String url;
		/**
		 * Where the LOGGED-IN CHARACTER stands: "entered", "pending", or null (not signed up, or a site
		 * that doesn't say). Per character — a person's main and alt get different answers.
		 */
		public final String yourEntry;

		public ScheduledView(int id, String title, String startDate, String endDate, boolean live,
			int tileCount, int boardSize, String format, String scoringMode, String url, String yourEntry)
		{
			this.yourEntry = yourEntry;
			this.id = id;
			this.title = title == null || title.isEmpty() ? "Bingo" : title;
			this.startDate = startDate;
			this.endDate = endDate;
			this.live = live;
			this.tileCount = Math.max(0, tileCount);
			this.boardSize = Math.max(0, boardSize);
			this.format = format;
			this.scoringMode = scoringMode;
			this.url = url;
		}

		/** "Bingo" / "Bingo (points)" / "Tile race" / "Ladder" — same wording as the in-game schedule. */
		public String kindLabel()
		{
			if (LadderMissions.isLadder(format))
			{
				return "Ladder";
			}
			if ("tilerace".equalsIgnoreCase(format))
			{
				return "Tile race";
			}
			return "points".equalsIgnoreCase(scoringMode) ? "Bingo (points)" : "Bingo";
		}

		/**
		 * Whether {@code boardSize} is a grid SIDE or a tile COUNT.
		 *
		 * <p>Only a classic bingo is square. Every other format — Leagues and its reveal-policy
		 * variants, tile race, ladder — is a task LIST whose boardSize is simply how many tiles it
		 * has, so treating it as a side length turns a 240-task Leagues board into a "240×240"
		 * claim about 57,600 tiles.
		 */
		private boolean squareGrid()
		{
			if (format != null && !format.isEmpty())
			{
				return "bingo".equalsIgnoreCase(format) && !"points".equalsIgnoreCase(scoringMode);
			}
			// A site too old to tell us. Believe the geometry instead: a square board's tile count is
			// its side squared, and anything that doesn't add up is a list.
			return tileCount > 0 && boardSize > 0 && boardSize * boardSize == tileCount;
		}

		/** "5×5 · 25 tiles" for a grid, "240 tiles" for a list, or "" when the site said nothing. */
		public String sizeLabel()
		{
			if (squareGrid())
			{
				// Deliberately NOT derived from boardSize² — a board that is still being authored has
				// fewer tiles than its grid has cells, and the honest thing is to say so.
				String tiles = tileCount > 0 ? tileCount + (tileCount == 1 ? " tile" : " tiles") : "";
				if (boardSize <= 0)
				{
					return tiles;
				}
				return tiles.isEmpty() ? boardSize + "×" + boardSize : boardSize + "×" + boardSize + " · " + tiles;
			}
			// A list: boardSize IS the tile count, so it stands in when the authored count is absent.
			int count = tileCount > 0 ? tileCount : boardSize;
			return count > 0 ? count + (count == 1 ? " tile" : " tiles") : "";
		}
	}

	/** One row of a weekly leaderboard, with the caller's own row flagged. */
	public static final class Standing
	{
		public final int rank;
		public final String rsn;
		public final long gained;
		public final boolean self;

		public Standing(int rank, String rsn, long gained, boolean self)
		{
			this.rank = Math.max(0, rank);
			this.rsn = rsn == null ? "" : rsn;
			this.gained = Math.max(0, gained);
			this.self = self;
		}
	}

	/**
	 * The ladder missions-board view-model for the sidebar card: the countdown target, the caller's
	 * rank (this month + all-time), and the currently-open missions. Display strings (live value,
	 * m:ss countdown) are computed at tick time from these raw values via {@link LadderMissions}.
	 */
	public static final class Ladder
	{
		/** ISO time of the next reveal — the per-second countdown target. Null when none is scheduled. */
		public final String nextRevealAtIso;
		public final int monthRank;      // caller's rank this month; 0 when unranked
		public final long monthPoints;   // caller's points this month
		public final int allTimeRank;    // caller's all-time rank; 0 when unranked
		/** The points ramp (may be null) — lets each mission show a live grow/decay value. */
		public final PluginConfigResponse.Decay decay;
		/** Currently-open missions (revealed, not yet claimed/expired), board order. Never null. */
		public final List<Mission> missions;
		/**
		 * True for a real ladder event, false for an ordinary bingo that merely carries missions.
		 *
		 * Both surface a mission strip — a bingo can drop hidden missions mid-event too, and those
		 * deserve the same countdown and live values rather than being left to show up as "New tile
		 * revealed" lines in the activity feed. Only a ladder REPLACES the board summary with this
		 * card and carries a personal rank; a bingo keeps its board summary and gets the strip
		 * underneath.
		 */
		public final boolean ladderFormat;

		public Ladder(String nextRevealAtIso, int monthRank, long monthPoints, int allTimeRank,
			PluginConfigResponse.Decay decay, List<Mission> missions, boolean ladderFormat)
		{
			this.nextRevealAtIso = nextRevealAtIso;
			this.monthRank = Math.max(0, monthRank);
			this.monthPoints = Math.max(0, monthPoints);
			this.allTimeRank = Math.max(0, allTimeRank);
			this.decay = decay;
			this.missions = copyOrEmpty(missions);
			this.ladderFormat = ladderFormat;
		}

		/** One open mission: its label, face value, and reveal time (for the live grow/decay value). */
		public static final class Mission
		{
			public final int tileId;
			public final String label;
			public final int face;
			public final String revealedAtIso;

			public Mission(int tileId, String label, int face, String revealedAtIso)
			{
				this.tileId = tileId;
				this.label = label == null ? "" : label;
				this.face = Math.max(0, face);
				this.revealedAtIso = revealedAtIso;
			}
		}
	}
}

package com.anvil;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * What killed us — as opposed to what we were killing.
 *
 * <p>The feed used to answer this with the last thing we landed a hit on, which is the only thing
 * the client volunteers and is wrong exactly when it matters. It reads fine at a boss, because the
 * boss you are hitting is the boss hitting you; it reads as nonsense the moment those differ, which
 * is why the clan feed filled up with "died to Abyssal portal", "died to Volatile earth" and, best
 * of all, "died to Jug". Those are things a player attacked. None of them killed anybody.
 *
 * <p>The game will not simply tell us. A hitsplat carries a type and an amount and no attacker
 * ({@link net.runelite.api.Hitsplat}), so "who dealt that damage" is not a question the API answers.
 * What it does answer is who is TARGETING us: an NPC or player acquiring us fires an interaction
 * change naming itself. So the killer is inferred from the things that had us in their sights when
 * we last took damage, which is a different guess from the old one and wrong in far fewer places.
 *
 * <p>When nothing was on us — a mechanic, a fall, poison after the fight — the answer is null and
 * the feed says only that someone died. That is a deliberate downgrade from the old behaviour: a
 * death with no killer is a smaller story than a death with the wrong one.
 *
 * <p>Pure and RuneLite-free so it is unit-tested directly (DeathAttributionTest). The plugin feeds
 * it names; it never holds an Actor, which would keep a dead NPC alive for as long as we did.
 */
final class DeathAttribution
{
	/**
	 * How long an attacker stays a candidate after we last took a hit. Long enough to cover the
	 * gap between a killing blow and the death animation, short enough that the thing that killed
	 * us half a minute ago in another fight is not still on the list.
	 */
	private static final long DAMAGE_WINDOW_MS = 15_000;

	/** Nothing sane has this many things attacking it; the cap is against a leak, not a crowd. */
	private static final int MAX_ATTACKERS = 24;

	/** Who has us targeted, and when they acquired us. Insertion-ordered so "most recent" is cheap. */
	private final Map<String, Long> attackers = new LinkedHashMap<>();

	/** When we last took damage from something other than ourselves. */
	private long lastDamageAt;

	/**
	 * Something acquired us as its target.
	 *
	 * <p>Re-acquiring refreshes the timestamp: an NPC that switches away and back is a better
	 * candidate than one that has been plinking at us since the start of the fight, because the
	 * thing that just turned to face you is the thing that just started hitting you.
	 */
	synchronized void targetedUs(String name, long nowMs)
	{
		if (name == null || name.isEmpty())
		{
			return;
		}
		attackers.remove(name); // re-insert so iteration order stays "oldest first"
		attackers.put(name, nowMs);
		while (attackers.size() > MAX_ATTACKERS)
		{
			attackers.remove(attackers.keySet().iterator().next());
		}
	}

	/** Something stopped targeting us — it is no longer a candidate for killing us. */
	synchronized void stoppedTargetingUs(String name)
	{
		if (name != null)
		{
			attackers.remove(name);
		}
	}

	/** We took a hit from something other than ourselves. Only the timing matters; see the class doc. */
	synchronized void tookDamage(long nowMs)
	{
		lastDamageAt = nowMs;
	}

	/** Forget everything. A new login, a new region, a fresh death — none of it carries over. */
	synchronized void clear()
	{
		attackers.clear();
		lastDamageAt = 0;
	}

	/**
	 * The killer, or null when nothing can honestly be named.
	 *
	 * <p>Two rules, in order:
	 *
	 * <ol>
	 *   <li>if one of the things targeting us is the thing we were fighting, it is that one — a
	 *       mutual fight is the least ambiguous case there is, and it is most deaths;
	 *   <li>otherwise the one that acquired us most recently, because in a room where several
	 *       things are on you the one that just turned to face you is the one that finished it.
	 * </ol>
	 *
	 * <p>Null when nothing had us targeted, or when the last damage we took is too old to connect
	 * to this death at all.
	 *
	 * @param weWereFighting the last thing we landed a hit on, used only to break a tie
	 */
	synchronized String killer(String weWereFighting, long nowMs)
	{
		if (lastDamageAt <= 0 || nowMs - lastDamageAt > DAMAGE_WINDOW_MS || attackers.isEmpty())
		{
			return null;
		}
		if (weWereFighting != null && !weWereFighting.isEmpty())
		{
			String fighting = weWereFighting.toLowerCase(Locale.ROOT);
			for (String name : attackers.keySet())
			{
				if (name.toLowerCase(Locale.ROOT).equals(fighting))
				{
					return name;
				}
			}
		}
		String newest = null;
		long newestAt = Long.MIN_VALUE;
		for (Map.Entry<String, Long> entry : attackers.entrySet())
		{
			if (entry.getValue() >= newestAt)
			{
				newestAt = entry.getValue();
				newest = entry.getKey();
			}
		}
		return newest;
	}

	/** How many things currently have us targeted — for the log line that explains an attribution. */
	synchronized int attackerCount()
	{
		return attackers.size();
	}
}

package com.anvil;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;

/**
 * The plugin's "Sign in with Discord" — the home-native device-code flow (site: /api/plugin/auth/*).
 * Start → open the home's /link-device page in the member's browser → poll until approved → hand the
 * account token to the caller to store. Asynchronous: every step runs on the scheduler (approval polls
 * paced by delayed rescheduling, never a sleeping thread) and BOTH callbacks arrive on that executor
 * thread — marshal to the EDT before touching Swing. {@code done} fires exactly once.
 *
 * <p><b>Security:</b> no local listener — completion is detected purely by polling the home. The
 * browser URL is pinned to the CONFIGURED home origin (the one host the member explicitly typed
 * into the plugin config) + the fixed {@code /link-device} path: same anti-phishing shape as the
 * federation broker pin, anchored to user intent instead of a hardcoded host, which is what lets
 * this work for hosted, self-hosted, and fully-standalone sites alike.</p>
 */
@Slf4j
public final class DeviceSignIn
{
	/** Fixed path of the approval page on the home site — the only page this flow will ever open. */
	static final String LINK_PATH = "/link-device";

	/** Fallback pacing/deadline when the server response omits them. */
	private static final int DEFAULT_INTERVAL_S = 5;
	private static final int DEFAULT_EXPIRES_S = 600;

	public enum Outcome
	{
		SIGNED_IN, DENIED, EXPIRED, UNAVAILABLE
	}

	/** Result: outcome + the account token when {@link Outcome#SIGNED_IN}. */
	public static final class Result
	{
		public final Outcome outcome;
		public final String token;

		Result(Outcome outcome, String token)
		{
			this.outcome = outcome;
			this.token = token;
		}
	}

	private final BingoApiClient apiClient;
	private final BrowserOpener browserOpener;
	private final PollScheduler scheduler;
	// Polling runs on RuneLite's shared executor, which outlives the plugin, so stopping it is ours to do.
	private volatile boolean cancelled;

	/** Production binding — real system browser + delayed steps on the shared client executor. */
	public DeviceSignIn(BingoApiClient apiClient, ScheduledExecutorService executor)
	{
		this(apiClient, DeviceSignIn::browse,
			(step, delayMs) -> executor.schedule(step, delayMs, TimeUnit.MILLISECONDS));
	}

	/** Test seam — injectable browser opener + scheduler so the flow runs offline and fast. */
	DeviceSignIn(BingoApiClient apiClient, BrowserOpener browserOpener,
		PollScheduler scheduler)
	{
		this.apiClient = apiClient;
		this.browserOpener = browserOpener;
		this.scheduler = scheduler;
	}

	/**
	 * Ask the desktop to open the sign-in page.
	 *
	 * <p>Returns whether we ASKED without throwing, which is all RuneLite lets us know:
	 * LinkBrowser.browse is void, so a browser that never appeared and one that opened fine are the
	 * same call from here. Everything downstream is written so that distinction doesn't matter — the
	 * address and the code go on screen either way.
	 */
	private static boolean browse(String url)
	{
		LinkBrowser.browse(url);
		return true;
	}

	/** Run the whole flow. {@code status} receives short human-readable progress lines for the UI;
	 * {@code done} the terminal {@link Result}. Both called on the executor thread. */
	public void run(Consumer<String> status, Consumer<Result> done)
	{
		// The first step runs on the executor too — authStart is network I/O, keep it off the EDT.
		schedule(() -> start(status, done), 0, status, done);
	}

	private void start(Consumer<String> status, Consumer<Result> done)
	{
		BingoApiClient.DeviceAuthStart start = apiClient.authStart();
		if (start == null || start.device_code == null || start.device_code.isEmpty())
		{
			fail(status, done, "Couldn't reach " + SetupNudge.SITE_HOST + " — check your connection and try again.", Outcome.UNAVAILABLE);
			return;
		}

		String url = start.verification_url_complete != null && !start.verification_url_complete.isEmpty()
			? start.verification_url_complete : start.verification_url;
		// Checked against the fixed site, not the client's address — that stays empty until there is a
		// token (BingoApiClient.configure), which is exactly the state sign-in runs in.
		if (!isConfiguredHomeUrl(BingoApiClient.CANONICAL_SITE, url))
		{
			// A response steering the browser anywhere but the member's own configured site is hostile.
			log.warn("refusing sign-in URL not on the configured home: {}", url);
			fail(status, done, "Sign-in blocked — the site returned a suspicious login page.", Outcome.UNAVAILABLE);
			return;
		}
		// The address is on screen whether or not the browser opened. We can't tell the difference
		// (see browse), and the failure mode of assuming success is a player staring at a code with
		// nowhere to type it — while the cost of saying both is one extra clause.
		if (!browserOpener.open(url))
		{
			status.accept("Couldn't open your browser — visit " + url + " and enter " + start.user_code + ".");
		}
		else
		{
			status.accept("Approve code " + start.user_code + " in your browser. If it didn't open: " + url);
		}

		long intervalMs = Math.max(1, start.interval > 0 ? start.interval : DEFAULT_INTERVAL_S) * 1000L;
		long deadline = System.currentTimeMillis()
			+ (start.expires_in > 0 ? start.expires_in : DEFAULT_EXPIRES_S) * 1000L;
		poll(status, done, start.device_code, intervalMs, deadline);
	}

	/** One scheduled approval poll; reschedules itself (server {@code slow_down} stretches the delay)
	 * until a terminal status or the deadline. */
	private void poll(Consumer<String> status, Consumer<Result> done, String deviceCode, long intervalMs, long deadline)
	{
		if (System.currentTimeMillis() >= deadline)
		{
			fail(status, done, "The code expired — try again.", Outcome.EXPIRED);
			return;
		}
		schedule(() ->
		{
			long nextIntervalMs = intervalMs;
			BingoApiClient.DeviceAuthPoll poll = apiClient.authPoll(deviceCode);
			if (poll != null && poll.status != null)
			{
				switch (poll.status)
				{
					case "complete":
						if (poll.token != null && !poll.token.isEmpty())
						{
							status.accept("Signed in.");
							done.accept(new Result(Outcome.SIGNED_IN, poll.token));
						}
						else
						{
							done.accept(new Result(Outcome.UNAVAILABLE, null));
						}
						return;
					case "denied":
						fail(status, done, "Sign-in denied on the site.", Outcome.DENIED);
						return;
					case "expired":
						fail(status, done, "The code expired — try again.", Outcome.EXPIRED);
						return;
					case "slow_down":
						nextIntervalMs = Math.max(intervalMs, Math.max(1, poll.interval) * 1000L);
						break;
					default: // pending (a null/blank poll is a transient blip — keep polling until the deadline)
						break;
				}
			}
			poll(status, done, deviceCode, nextIntervalMs, deadline);
		}, intervalMs, status, done);
	}

	/** Schedule a flow step; an escaped {@link RuntimeException} would otherwise vanish inside the
	 * executor, so surface it as the terminal failure. */
	private static void fail(Consumer<String> status, Consumer<Result> done, String message, Outcome outcome)
	{
		status.accept(message);
		done.accept(new Result(outcome, null));
	}

	/** Stop polling: any step not yet run is skipped and the callbacks never fire. */
	public void cancel()
	{
		cancelled = true;
	}

	private void schedule(Runnable step, long delayMs, Consumer<String> status, Consumer<Result> done)
	{
		scheduler.schedule(() ->
		{
			if (cancelled)
			{
				return;
			}
			try
			{
				step.run();
			}
			catch (RuntimeException e)
			{
				log.debug("sign-in flow failed", e);
				fail(status, done, "Sign-in failed — try again.", Outcome.UNAVAILABLE);
			}
		}, delayMs);
	}

	/**
	 * True only for an HTTPS/HTTP URL on the EXACT home origin (scheme + host + port all matching
	 * {@link BingoApiClient#CANONICAL_SITE}) with the fixed {@link #LINK_PATH} path. No credentials.
	 * HTTP is tolerated only when the home itself is HTTP (local dev builds).
	 */
	static boolean isConfiguredHomeUrl(String configuredApiUrl, String url)
	{
		if (configuredApiUrl == null || configuredApiUrl.isEmpty() || url == null || url.isEmpty())
		{
			return false;
		}
		try
		{
			URI home = new URI(configuredApiUrl);
			URI target = new URI(url);
			return target.getScheme() != null && target.getHost() != null && target.getUserInfo() == null
				&& target.getScheme().equalsIgnoreCase(home.getScheme())
				&& target.getHost().equalsIgnoreCase(home.getHost()) && target.getPort() == home.getPort()
				&& target.getPath() != null && target.getPath().startsWith(LINK_PATH);
		}
		catch (URISyntaxException e)
		{
			return false;
		}
	}
}

package com.anvil;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import net.runelite.client.util.Filepath;

/**
 * The few disk primitives the caches and the outbox share, all through RuneLite's {@link Filepath}.
 *
 * <p>Writes are atomic: the bytes go to a temp sibling first and are then renamed over the target, so
 * a client killed mid-write leaves the previous copy (or nothing), never half a JSON file. Every
 * method here blocks on disk — callers run them on the plugin executor, never the client thread.
 */
final class DiskFiles
{
	private DiskFiles()
	{
	}

	/** {@code dir}, created on demand; null when it can't be. */
	static Filepath ensureDir(Filepath dir)
	{
		if (dir == null)
		{
			return null;
		}
		try
		{
			if (!dir.exists())
			{
				dir.createDirectories();
			}
			return dir;
		}
		catch (IOException | RuntimeException e)
		{
			return null;
		}
	}

	static void writeAtomic(Filepath target, byte[] data) throws IOException
	{
		Filepath tmp = target.getParent().joinSegment(target.getFileName() + ".tmp");
		tmp.write(data);
		try
		{
			tmp.moveTo(target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (AtomicMoveNotSupportedException e)
		{
			tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	static void writeAtomic(Filepath target, String text) throws IOException
	{
		writeAtomic(target, text.getBytes(StandardCharsets.UTF_8));
	}

	/** The file's bytes, or null when it is missing or unreadable. */
	static byte[] read(Filepath file)
	{
		if (file == null || !file.isFile())
		{
			return null;
		}
		try (InputStream in = file.openInputStream())
		{
			return in.readAllBytes();
		}
		catch (IOException | RuntimeException e)
		{
			return null;
		}
	}

	static String readText(Filepath file)
	{
		byte[] b = read(file);
		return b == null ? null : new String(b, StandardCharsets.UTF_8);
	}

	static void deleteQuietly(Filepath file)
	{
		if (file == null)
		{
			return;
		}
		try
		{
			file.deleteIfExists();
		}
		catch (IOException | RuntimeException ignored)
		{
			// Best effort: a leftover file is pruned by age on the next load.
		}
	}

	/**
	 * A short, stable, filename-safe stand-in for something that must never appear on disk itself
	 * (an Account Token) or that shouldn't be readable from a directory listing (a character).
	 */
	static String fingerprint(String secret)
	{
		if (secret == null || secret.trim().isEmpty())
		{
			return "";
		}
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(secret.trim().getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder();
			for (int i = 0; i < 8; i++)
			{
				sb.append(String.format("%02x", digest[i]));
			}
			return sb.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;

/**
 * How a drop should be *talked about*: was it lucky, was it a long-overdue grind, or is it a rare
 * roll on something worthless?
 *
 * Rarity alone can't answer that. A 1/5000 roll on a player's second kill is a spoon; the same roll
 * at 20,000 kills is the opposite. So everything here is expressed against the kill count: with a
 * per-kill probability p, the share of players who would already hold the drop after kc kills is
 *
 *     P(at least one by now) = 1 - (1 - p)^kc
 *
 * A small share means you beat almost everyone to it (spooned); a large one means you were dry.
 *
 * Pure static logic with no RuneLite dependencies, so it's unit-tested directly (DropLuckTest).
 */
public final class DropLuck
{
	private DropLuck()
	{
	}

	/** Beat ~90% of players to it. */
	private static final double SPOONED_SHARE = 0.10;
	/** Ahead of the pack, but not absurd. */
	private static final double LUCKY_SHARE = 0.35;
	/** Most players already had it by this point — the grind was real. */
	private static final double DRY_SHARE = 0.85;

	/**
	 * A drop this rare that's worth less than this is a punchline, not a prize — the 1/10,000 roll
	 * that hands you a Dragon spear. Above it, it's simply a rare drop.
	 */
	public static final long TROLL_VALUE_CEILING = 250_000L;

	/**
	 * Awards you're GIVEN for finishing something, not rolled for: the cape you get for clearing the
	 * Inferno, the quiver for the Colosseum. Calling these "spooned" reads as an insult to the run,
	 * so the reaction lines are suppressed for them. Substring-matched, lowercased — the same style
	 * as the always-notify allowlist, so "Infernal cape (broken)" still matches.
	 */
	private static final List<String> EARNED_AWARDS = Arrays.asList(
		"infernal cape",
		"fire cape",
		"dizana's quiver",
		"champion's cape",
		"quest point cape",
		"music cape",
		"achievement diary cape",
		"max cape");

	public enum Verdict
	{
		/** Well ahead of the drop rate. */
		SPOONED,
		/** Ahead of the drop rate. */
		LUCKY,
		/** About when you'd expect it. */
		TYPICAL,
		/** Long past due. */
		DRY,
		/** No rate or no kill count — say nothing. */
		UNKNOWN
	}

	/** True when this item is handed out for completing content rather than rolled for. */
	public static boolean isEarnedAward(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}
		String n = itemName.toLowerCase(Locale.ROOT);
		for (String award : EARNED_AWARDS)
		{
			if (n.contains(award))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Share of players (0..1) who would already hold a drop of probability {@code p} after
	 * {@code kc} kills. Computed as 1-(1-p)^kc, via expm1/log1p so tiny rates don't lose precision.
	 */
	public static double obtainedShare(double p, int kc)
	{
		if (p <= 0 || kc <= 0)
		{
			return 0;
		}
		if (p >= 1)
		{
			return 1;
		}
		// 1 - exp(kc * ln(1-p)); log1p/expm1 keep this accurate for p in the 1e-5 range.
		return -Math.expm1(kc * Math.log1p(-p));
	}

	/** Where this drop sits against the grind. UNKNOWN when either input is missing. */
	public static Verdict classify(Double dropRate, Integer killCount)
	{
		if (dropRate == null || dropRate <= 0 || killCount == null || killCount <= 0)
		{
			return Verdict.UNKNOWN;
		}
		double share = obtainedShare(dropRate, killCount);
		if (share < SPOONED_SHARE)
		{
			return Verdict.SPOONED;
		}
		if (share < LUCKY_SHARE)
		{
			return Verdict.LUCKY;
		}
		if (share >= DRY_SHARE)
		{
			return Verdict.DRY;
		}
		return Verdict.TYPICAL;
	}

	/**
	 * A "troll": rare enough to trip the rarity gate, but worth almost nothing. Worth calling out as
	 * a joke rather than dressing up as treasure.
	 *
	 * @param dropRate     per-kill probability, or null when the drop qualified on value alone
	 * @param value        the drop's gp value
	 * @param rarityFloor  1-in-N the drop must beat to count as troll-rare (the clan's rarity floor)
	 */
	public static boolean isTrollDrop(Double dropRate, long value, int rarityFloor)
	{
		if (dropRate == null || dropRate <= 0 || rarityFloor <= 0)
		{
			return false;
		}
		if (value >= TROLL_VALUE_CEILING)
		{
			return false;
		}
		return MathUtils.lessThanOrEqual(dropRate, 1.0 / rarityFloor);
	}

	/**
	 * Whether to append a lucky-drop reaction line. Earned awards never qualify (see
	 * {@link #EARNED_AWARDS}); otherwise it's a genuine spoon against the kill count, or a drop
	 * valuable enough to be a moment regardless of how long it took.
	 */
	public static boolean deservesSpoonLine(String itemName, long value, Double dropRate, Integer killCount, long bigValue)
	{
		if (isEarnedAward(itemName))
		{
			return false;
		}
		if (classify(dropRate, killCount) == Verdict.SPOONED)
		{
			return true;
		}
		// No kill count to judge against (untracked NPC, or the clan hides KC): fall back to value.
		return value >= bigValue;
	}
}

package com.anvil;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * The reader for the server's {@code dropFacts}: which monster a pet is really from, and
 * whether an item was ever a roll at all. Both are the server's to know (a new boss is a dataset
 * regen there, a release here), so everything below degrades to the old behaviour on a null.
 *
 * <p>Pure and RuneLite-free, so it is unit-tested directly (DropSourceTest).
 */
final class DropSource
{
	private DropSource()
	{
	}

	/**
	 * True when {@code source} hands {@code itemName} over on every kill, per the server's facts.
	 *
	 * <p>Guaranteed drops are the one case where a reaction line actively misfires: an ornament kit
	 * the boss owes you is nobody's spoon, and saying someone drier deserved it reads as a bot that
	 * doesn't know the game. Unknown facts (an older site, an item nothing has an opinion about)
	 * answer false, which is exactly today's behaviour.
	 *
	 * <p>A {@code "*"} source in the list means "wherever it drops" — what a clan override without
	 * named sources stores, and the only sane reading of one.
	 */
	static boolean isGuaranteed(PluginConfigResponse.DropFacts facts, String itemName, String source)
	{
		if (facts == null || facts.guaranteed == null || itemName == null)
		{
			return false;
		}
		List<String> sources = facts.guaranteed.get(itemName.toLowerCase(Locale.ROOT).trim());
		if (sources == null || sources.isEmpty())
		{
			return false;
		}
		if (sources.contains("*"))
		{
			return true;
		}
		if (source == null)
		{
			return false;
		}
		String key = source.toLowerCase(Locale.ROOT).trim();
		return sources.contains(key);
	}

	/** The server's entry for a pet, or null when it has nothing to say about it. */
	static PluginConfigResponse.DropFacts.Pet petEntry(PluginConfigResponse.DropFacts facts, String petName)
	{
		if (facts == null || facts.pets == null || petName == null)
		{
			return null;
		}
		return facts.pets.get(petName.toLowerCase(Locale.ROOT).trim());
	}

	/**
	 * Which monster this pet actually came from.
	 *
	 * <p>A pet fires no loot event, so the only thing the client can offer is whatever loot it
	 * happened to see last — a minion, a stray kill, the chest rather than the raid. The pet's name
	 * is the reliable key, and the server holds the map from it. The rules, in order:
	 *
	 * <ol>
	 *   <li>if the loot the client saw IS one of the pet's real sources, that one — it is the most
	 *       specific answer available and disambiguates a pet with several (Vet'ion / Calvar'ion);
	 *   <li>if the pet has exactly one source, that one, whatever the client thought;
	 *   <li>otherwise the source the player has the most kills at, which is the likeliest of them;
	 *   <li>failing all of that, the pet's first listed source, and if there are none, null — a
	 *       skilling pet has no monster and a made-up one is worse than a shorter post.
	 * </ol>
	 *
	 * @param observed  the loot source the client saw around the drop; may be null
	 * @param killCount source name -> the player's kill count there, for the tie-break; may be null
	 */
	static String resolvePetSource(PluginConfigResponse.DropFacts facts, String petName, String observed,
								   Map<String, Integer> killCount)
	{
		PluginConfigResponse.DropFacts.Pet pet = petEntry(facts, petName);
		if (pet == null || pet.sources == null || pet.sources.isEmpty())
		{
			// Nothing known about this pet: an older site, or a pet the catalogue has not placed.
			// The observed source is then the best guess there is, which is where we started.
			return pet == null ? observed : null;
		}
		List<String> sources = pet.sources;
		if (observed != null && !observed.trim().isEmpty())
		{
			for (String candidate : sources)
			{
				if (candidate.equalsIgnoreCase(observed.trim()))
				{
					return candidate;
				}
			}
		}
		if (sources.size() == 1)
		{
			return sources.get(0);
		}
		String best = null;
		int bestKc = -1;
		Map<String, Integer> counts = killCount == null ? Collections.emptyMap() : killCount;
		for (String candidate : sources)
		{
			Integer kc = counts.get(candidate.toLowerCase(Locale.ROOT));
			int value = kc == null ? -1 : kc;
			if (value > bestKc)
			{
				bestKc = value;
				best = candidate;
			}
		}
		return best != null ? best : sources.get(0);
	}
}

package com.anvil;

import java.util.Locale;
import java.util.Map;
import java.util.function.Predicate;
import net.runelite.api.gameval.ItemID;

/**
 * Which item a "funny feeling" line was about.
 *
 * <p>A duplicate pet ("…would have been followed") and a duplicate champion's scroll ("…would have
 * received a Champion's scroll") name nothing: there is no item, no loot event and no collection-log
 * line. What the player was doing names it. A pet comes from what was just killed or looted, or from
 * the skill just trained; a champion's scroll comes from exactly one kind of monster.
 *
 * <p>Every answer here is a guess the site flags for staff, so ambiguity returns null rather than a
 * pick: a wrong credit costs a reviewer more than a manual proof does.
 */
final class DuplicateInference
{
	private DuplicateInference()
	{
	}

	/** The one pet {@code source} drops, or null when it drops none or several. */
	static String petForSource(PluginConfigResponse.DropFacts facts, String source)
	{
		String want = source == null ? "" : source.trim().toLowerCase(Locale.ROOT);
		return onlyPet(facts, want, pet -> pet.sources != null
			&& pet.sources.stream().anyMatch(s -> s != null && s.trim().toLowerCase(Locale.ROOT).equals(want)));
	}

	/** The one skilling pet {@code skill} gives, or null. */
	static String petForSkill(PluginConfigResponse.DropFacts facts, String skill)
	{
		String want = skill == null ? "" : skill.trim();
		return onlyPet(facts, want, pet -> "skill".equals(pet.kind) && want.equalsIgnoreCase(pet.skill));
	}

	/** The single pet matching {@code test}, or null when none or several do (or {@code want} is blank). */
	private static String onlyPet(PluginConfigResponse.DropFacts facts, String want, Predicate<PluginConfigResponse.DropFacts.Pet> test)
	{
		if (facts == null || facts.pets == null || want.isEmpty())
		{
			return null;
		}
		String found = null;
		for (Map.Entry<String, PluginConfigResponse.DropFacts.Pet> e : facts.pets.entrySet())
		{
			if (e.getValue() != null && test.test(e.getValue()))
			{
				if (found != null)
				{
					return null;
				}
				found = e.getKey();
			}
		}
		return found;
	}

	// Champion's scrolls by NPC name, checked in order: "x*" is a prefix (hobgoblin before goblin),
	// "*x" a suffix, anything else the whole name.
	private static final String[] CHAMPION_NPCS = {
		"hobgoblin*", "goblin*", "imp", "skeleton*", "zombie*", "ghoul", "earth warrior", "jogre", "lesser demon", "* giant",
	};
	private static final int[] CHAMPION_SCROLLS = {
		ItemID.CHAMPIONS_CHALLENGE_HOBGOBLIN, ItemID.CHAMPIONS_CHALLENGE_GOBLIN, ItemID.CHAMPIONS_CHALLENGE_IMP,
		ItemID.CHAMPIONS_CHALLENGE_SKELETON, ItemID.CHAMPIONS_CHALLENGE_ZOMBIE, ItemID.CHAMPIONS_CHALLENGE_GHOUL,
		ItemID.CHAMPIONS_CHALLENGE_EARTHWARRIOR, ItemID.CHAMPIONS_CHALLENGE_JOGRE, ItemID.CHAMPIONS_CHALLENGE_LESSERDEMON,
		ItemID.CHAMPIONS_CHALLENGE_GIANT,
	};

	/** The champion's scroll item id {@code npc} drops, or null. */
	static Integer championScrollFor(String npc)
	{
		String n = npc == null ? null : npc.trim().toLowerCase(Locale.ROOT);
		for (int i = 0; n != null && i < CHAMPION_NPCS.length; i++)
		{
			String k = CHAMPION_NPCS[i];
			if (k.endsWith("*") ? n.startsWith(k.substring(0, k.length() - 1))
				: k.startsWith("*") ? n.endsWith(k.substring(1)) : n.equals(k))
			{
				return CHAMPION_SCROLLS[i];
			}
		}
		return null;
	}
}

package com.anvil;

import java.util.List;

/**
 * One page of an event's roster — {@code GET /api/plugin/event/<id>/roster} (site capability
 * "event-roster"). The server does the ranking and the paging, so an event of 1,200 one-person teams
 * costs the same to open as two teams of five.
 *
 * <p>{@link #mode} says which of the shapes arrived:</p>
 * <ul>
 *   <li>{@code teams} — the teams ranked, with member counts; {@link #yourTeam} rides on every page.</li>
 *   <li>{@code players} — every team is one person (or the event ranks individuals), so the people
 *       are ranked instead; {@link #you} rides on every page.</li>
 *   <li>{@code members} — one team's members, captain first.</li>
 *   <li>{@code search} — players by name across every team.</li>
 * </ul>
 */
final class EventRoster
{
	String mode;
	int page;
	int pageSize;
	int total;
	int pages;

	List<Team> teams;
	Team yourTeam;
	/** Signed up but not on a team yet ({@code teams} mode). */
	int unplaced;

	List<Person> players;
	Person you;

	/** {@code members} mode: the team being listed. */
	Team team;
	/** {@code search} mode: what was searched for, as the server read it. */
	String query;

	static final class Team
	{
		int teamId;
		String name;
		String color;
		/** Null before the board is revealed — nothing to rank yet. */
		Integer rank;
		/** "12 tiles", "340 pts (+20 bonus)"; null before the reveal. */
		String score;
		int members;
		boolean yours;
	}

	static final class Person
	{
		String name;
		Integer teamId;
		String teamName;
		String teamColor;
		Integer rank;
		String score;
		boolean captain;
		boolean you;
	}

	boolean is(String m)
	{
		return m.equals(mode);
	}
}

package com.anvil;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import javax.swing.Icon;

/**
 * The sidebar's small symbols — chevrons, the external-link arrow, a tick, a cross, an ellipsis —
 * drawn as vector shapes instead of typed as characters.
 *
 * <p>Typed, they depended on the font: the RuneScape font has none of ‹ › ↗ ✓ ⋯, so each platform
 * substituted whatever its own fallback had. On macOS that was often nothing (an empty box or a
 * blank), and where a glyph did appear it sat on the text baseline, below the middle of the words
 * beside it. Drawn, they look the same everywhere, and Swing centres an icon against its label.
 *
 * <p>The colour follows the component's foreground (a hovered button's orange, a done tick's green)
 * unless one is fixed at construction.
 */
final class GlyphIcon implements Icon
{
	enum Shape
	{
		CHEVRON_LEFT, CHEVRON_RIGHT, EXTERNAL, CHECK, CLOSE, ELLIPSIS, GEAR
	}

	private final Shape shape;
	private final int size;
	private final Color color;

	GlyphIcon(Shape shape, int size)
	{
		this(shape, size, null);
	}

	GlyphIcon(Shape shape, int size, Color color)
	{
		this.shape = shape;
		this.size = size;
		this.color = color;
	}

	@Override
	public int getIconWidth()
	{
		return size;
	}

	@Override
	public int getIconHeight()
	{
		return size;
	}

	@Override
	public void paintIcon(Component c, Graphics graphics, int x, int y)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			Color ink = color != null ? color : (c != null ? c.getForeground() : Color.WHITE);
			if (c != null && !c.isEnabled())
			{
				ink = ink.darker();
			}
			g.setColor(ink);
			float s = size;
			g.setStroke(new BasicStroke(Math.max(1.4f, s / 7f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.translate(x, y);
			Path2D p = new Path2D.Float();
			switch (shape)
			{
				case CHEVRON_LEFT:
					g.draw(stroke(p, s, 0.62, 0.22, 0.34, 0.5, 0.62, 0.78));
					break;
				case CHEVRON_RIGHT:
					g.draw(stroke(p, s, 0.38, 0.22, 0.66, 0.5, 0.38, 0.78));
					break;
				case EXTERNAL:
					stroke(p, s, 0.28, 0.72, 0.72, 0.28);
					g.draw(stroke(p, s, 0.4, 0.28, 0.72, 0.28, 0.72, 0.6));
					break;
				case CHECK:
					g.draw(stroke(p, s, 0.2, 0.52, 0.42, 0.74, 0.8, 0.28));
					break;
				case CLOSE:
					stroke(p, s, 0.28, 0.28, 0.72, 0.72);
					g.draw(stroke(p, s, 0.72, 0.28, 0.28, 0.72));
					break;
				case ELLIPSIS:
					float d = Math.max(2f, s / 6f);
					for (int i = 0; i < 3; i++)
					{
						float cx = s * (0.25f + 0.25f * i);
						g.fill(new java.awt.geom.Ellipse2D.Float(cx - d / 2, s * 0.5f - d / 2, d, d));
					}
					break;
				case GEAR:
					// A ring with eight short teeth — the settings mark everyone reads without a label.
					float cx = s / 2f;
					float r = s * 0.24f;
					g.draw(new java.awt.geom.Ellipse2D.Float(cx - r, cx - r, r * 2, r * 2));
					for (int i = 0; i < 8; i++)
					{
						double a = Math.PI / 4 * i;
						p.moveTo(cx + Math.cos(a) * s * 0.33, cx + Math.sin(a) * s * 0.33);
						p.lineTo(cx + Math.cos(a) * s * 0.44, cx + Math.sin(a) * s * 0.44);
					}
					g.draw(p);
					break;
				default:
					break;
			}
		}
		finally
		{
			g.dispose();
		}
	}

	/** Adds one polyline to {@code p}: x,y pairs as fractions of the icon's size {@code s}. */
	private static Path2D stroke(Path2D p, float s, double... xy)
	{
		p.moveTo(s * xy[0], s * xy[1]);
		for (int i = 2; i < xy.length; i += 2)
		{
			p.lineTo(s * xy[i], s * xy[i + 1]);
		}
		return p;
	}
}

package com.anvil;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.IntConsumer;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import net.runelite.api.Skill;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.ProgressBar;

import static com.anvil.Ui.*;

/**
 * The You tab's goals: "99 Slayer", "500 Vorkath", "Barrows log complete".
 *
 * <p>Only the target is stored (site {@code player_goals}); progress is read from the same player
 * card the tab already shows, so a goal costs no polling and always agrees with the numbers above
 * it. A goal the card can't measure yet (no stats tracked, log not synced) says so instead of
 * showing a zero.</p>
 */
final class GoalsView
{
	private GoalsView()
	{
	}

	/** Where a goal stands: {@code current} of {@code target} in the goal's own unit. */
	static final class Progress
	{
		final long current;
		final long target;
		/** Null when the card has nothing to measure it with. */
		final String text;
		final boolean known;

		Progress(long current, long target, String text, boolean known)
		{
			this.current = current;
			this.target = target;
			this.text = text;
			this.known = known;
		}

		boolean done()
		{
			return known && current >= target;
		}
	}

	static JPanel render(List<BingoApiClient.PlayerGoal> goals, PlayerCard card, Runnable onAdd, IntConsumer onRemove,
		String error)
	{
		JPanel block = block();

		JPanel head = PlayerCardView.header("Goals", null);
		JLabel add = onClick(small("+ Add goal", ColorScheme.BRAND_ORANGE), onAdd);
		add.setToolTipText("A skill level, a boss kill count, or a whole log page");
		head.add(add, BorderLayout.EAST);
		block.add(capH(head));

		if (error != null && !error.isEmpty())
		{
			block.add(gap(4));
			block.add(small(error, ColorScheme.PROGRESS_ERROR_COLOR));
		}

		if (goals == null || goals.isEmpty())
		{
			block.add(gap(6));
			block.add(small("Nothing set yet — 99 a skill, a KC to hit, a log page to finish.", MUTED));
			return block;
		}

		for (BingoApiClient.PlayerGoal g : goals)
		{
			block.add(gap(8));
			block.add(row(g, progress(g, card), onRemove));
		}
		return block;
	}

	private static JPanel row(BingoApiClient.PlayerGoal g, Progress p, IntConsumer onRemove)
	{
		JPanel row = left(new JPanel(new BorderLayout(0, 3)));
		row.setOpaque(false);

		JPanel line = Ui.row(6);
		line.add(small(label(g), p.done() ? ColorScheme.PROGRESS_COMPLETE_COLOR : Color.WHITE), BorderLayout.CENTER);
		JPanel right = new JPanel(new GridLayout(1, 0, 6, 0));
		right.setOpaque(false);
		right.add(small(p.done() ? "Done" : p.text, p.done() ? ColorScheme.PROGRESS_COMPLETE_COLOR : MUTED));
		JLabel remove = onClick(new JLabel(new GlyphIcon(GlyphIcon.Shape.CLOSE, 8, MUTED)), () -> onRemove.accept(g.id));
		remove.setToolTipText("Remove this goal");
		line.add(right, BorderLayout.EAST);
		line.add(remove, BorderLayout.WEST);
		String due = p.done() ? null : dueText(g.dueOn, java.time.LocalDate.now(java.time.ZoneOffset.UTC));
		if (due != null)
		{
			JPanel top = new JPanel(new BorderLayout(0, 1));
			top.setOpaque(false);
			top.add(line, BorderLayout.NORTH);
			top.add(small(due, due.startsWith("overdue") ? ColorScheme.PROGRESS_ERROR_COLOR : MUTED), BorderLayout.SOUTH);
			row.add(top, BorderLayout.NORTH);
		}
		else
		{
			row.add(line, BorderLayout.NORTH);
		}

		if (p.known)
		{
			ProgressBar bar = new ProgressBar();
			bar.setMaximumValue((int) Math.min(Integer.MAX_VALUE, Math.max(1, p.target)));
			bar.setValue((int) Math.min(Integer.MAX_VALUE, Math.min(p.current, p.target)));
			bar.setLeftLabel("");
			bar.setRightLabel("");
			bar.setCenterLabel("");
			bar.setForeground(p.done() ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.BRAND_ORANGE);
			bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
			bar.setPreferredSize(new Dimension(0, 4));
			row.add(bar, BorderLayout.SOUTH);
		}
		return capH(row);
	}

	// ---- Progress (package-private for tests) -----------------------------------------------------

	/** "99 Slayer", "500 Vorkath", "Barrows Chests log". */
	static String label(BingoApiClient.PlayerGoal g)
	{
		switch (g.kind)
		{
			case "skill":
				return g.target + " " + titleCase(g.metric);
			case "boss":
				return String.format(Locale.ROOT, "%,d %s", g.target, humanise(g.metric));
			default:
				return g.metric + " log";
		}
	}

	static Progress progress(BingoApiClient.PlayerGoal g, PlayerCard card)
	{
		if ("skill".equals(g.kind))
		{
			PlayerCard.Skill s = card == null || card.skills == null ? null
				: card.skills.stream().filter(x -> g.metric.equalsIgnoreCase(x.key)).findFirst().orElse(null);
			if (s == null)
			{
				return new Progress(0, 1, "no stats yet", false);
			}
			long need = xpForLevel(g.target);
			int level = levelForXp(s.xp);
			return new Progress(s.xp, need, "Lv " + level + " / " + g.target, true);
		}
		if ("boss".equals(g.kind))
		{
			if (card == null || card.skills == null || card.skills.isEmpty())
			{
				return new Progress(0, g.target, "no stats yet", false);
			}
			int kc = card.bosses == null ? 0 : card.bosses.stream().filter(b -> g.metric.equalsIgnoreCase(b.key))
				.mapToInt(b -> b.kc).findFirst().orElse(0);
			return new Progress(kc, g.target, String.format(Locale.ROOT, "%,d / %,d", kc, g.target), true);
		}
		PlayerCard.Page page = card == null || card.clogPages == null ? null
			: card.clogPages.stream().filter(p -> g.metric.equalsIgnoreCase(p.name)).findFirst().orElse(null);
		if (page == null)
		{
			return new Progress(0, 1, "sync your log", false);
		}
		return new Progress(page.obtained, page.total, page.obtained + " / " + page.total, true);
	}

	/**
	 * "by 1 Dec · 50d left", "due today", "overdue by 3d" — calendar days, as the site counts them.
	 * Null when there's no deadline (or it can't be read).
	 */
	static String dueText(String dueOn, java.time.LocalDate today)
	{
		if (dueOn == null || dueOn.isEmpty())
		{
			return null;
		}
		java.time.LocalDate due;
		try
		{
			due = java.time.LocalDate.parse(dueOn);
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
		long days = java.time.temporal.ChronoUnit.DAYS.between(today, due);
		if (days < 0)
		{
			return "overdue by " + (-days) + "d";
		}
		if (days == 0)
		{
			return "due today";
		}
		String when = due.format(java.time.format.DateTimeFormatter.ofPattern(
			due.getYear() == today.getYear() ? "d MMM" : "d MMM yyyy", Locale.ENGLISH));
		return "by " + when + " · " + days + "d left";
	}

	/** The game's XP table: XP needed for {@code level}, 1–99. */
	static long xpForLevel(int level)
	{
		double points = 0;
		for (int l = 1; l < level; l++)
		{
			points += Math.floor(l + 300.0 * Math.pow(2.0, l / 7.0));
		}
		return (long) Math.floor(points / 4);
	}

	static int levelForXp(long xp)
	{
		for (int level = 99; level >= 1; level--)
		{
			if (xp >= xpForLevel(level))
			{
				return level;
			}
		}
		return 1;
	}

	/** "alchemicalHydra" → "Alchemical Hydra". */
	static String humanise(String key)
	{
		if (key == null || key.isEmpty())
		{
			return "";
		}
		String spaced = key.replaceAll("([a-z])([A-Z])", "$1 $2");
		return Character.toUpperCase(spaced.charAt(0)) + spaced.substring(1);
	}

	private static String titleCase(String s)
	{
		return s == null || s.isEmpty() ? "" : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	// ---- New-goal dialog ---------------------------------------------------------------------------

	/** What the member picked: kind, the name the site matches, and the target. */
	static final class NewGoal
	{
		final String kind;
		final String metric;
		final int target;
		/** YYYY-MM-DD, or null for no deadline. */
		final String dueOn;

		NewGoal(String kind, String metric, int target, String dueOn)
		{
			this.kind = kind;
			this.metric = metric;
			this.target = target;
			this.dueOn = dueOn;
		}
	}

	/** Ask for a goal. Null when cancelled. Log pages are offered only once the log is synced. */
	static NewGoal ask(Component parent, PlayerCard card)
	{
		List<String> kinds = new ArrayList<>();
		kinds.add("Skill level");
		kinds.add("Boss kills");
		List<String> pages = new ArrayList<>();
		if (card != null && card.clogPages != null)
		{
			card.clogPages.forEach(p -> pages.add(p.name));
		}
		if (!pages.isEmpty())
		{
			kinds.add("Log page");
		}

		List<String> skills = new ArrayList<>();
		for (Skill s : PlayerCardView.SKILL_GRID)
		{
			skills.add(s.getName());
		}
		List<String> bosses = new ArrayList<>();
		for (HiscoreSkill h : HiscoreSkill.values())
		{
			if (h.getType() == HiscoreSkillType.BOSS)
			{
				bosses.add(h.getName());
			}
		}
		bosses.sort(String.CASE_INSENSITIVE_ORDER);

		JComboBox<String> kind = new JComboBox<>(kinds.toArray(new String[0]));
		JComboBox<String> what = new JComboBox<>(skills.toArray(new String[0]));
		SpinnerNumberModel model = new SpinnerNumberModel(99, 2, 99, 1);
		JSpinner target = new JSpinner(model);
		JLabel targetLabel = new JLabel("Level");

		kind.addActionListener(e ->
		{
			String k = (String) kind.getSelectedItem();
			if ("Boss kills".equals(k))
			{
				what.setModel(new javax.swing.DefaultComboBoxModel<>(bosses.toArray(new String[0])));
				target.setModel(new SpinnerNumberModel(100, 1, 100_000, 50));
				targetLabel.setText("Kill count");
				target.setEnabled(true);
			}
			else if ("Log page".equals(k))
			{
				what.setModel(new javax.swing.DefaultComboBoxModel<>(pages.toArray(new String[0])));
				targetLabel.setText("Every slot");
				target.setEnabled(false);
			}
			else
			{
				what.setModel(new javax.swing.DefaultComboBoxModel<>(skills.toArray(new String[0])));
				target.setModel(new SpinnerNumberModel(99, 2, 99, 1));
				targetLabel.setText("Level");
				target.setEnabled(true);
			}
		});

		// A deadline is optional, so it's behind a tick: an always-on date field would set one by accident.
		javax.swing.JCheckBox hasDue = new javax.swing.JCheckBox("Set a deadline");
		java.util.Calendar inAMonth = java.util.Calendar.getInstance();
		inAMonth.add(java.util.Calendar.MONTH, 1);
		JSpinner due = new JSpinner(new javax.swing.SpinnerDateModel(inAMonth.getTime(), new java.util.Date(), null,
			java.util.Calendar.DAY_OF_MONTH));
		due.setEditor(new JSpinner.DateEditor(due, "d MMM yyyy"));
		due.setEnabled(false);
		hasDue.addActionListener(e -> due.setEnabled(hasDue.isSelected()));

		JPanel form = new JPanel(new GridLayout(0, 1, 0, 4));
		form.add(new JLabel("Goal"));
		form.add(kind);
		form.add(what);
		form.add(targetLabel);
		form.add(target);
		form.add(hasDue);
		form.add(due);

		int choice = JOptionPane.showConfirmDialog(parent, form, "New goal", JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.PLAIN_MESSAGE);
		if (choice != JOptionPane.OK_OPTION || what.getSelectedItem() == null)
		{
			return null;
		}
		String k = (String) kind.getSelectedItem();
		String wireKind = "Boss kills".equals(k) ? "boss" : "Log page".equals(k) ? "clog" : "skill";
		String metric = (String) what.getSelectedItem();
		if ("skill".equals(wireKind))
		{
			metric = metric.toLowerCase(Locale.ROOT);
		}
		int t = "clog".equals(wireKind) ? 0 : ((Number) target.getValue()).intValue();
		String dueOn = hasDue.isSelected()
			? new java.text.SimpleDateFormat("yyyy-MM-dd", Locale.ROOT).format((java.util.Date) due.getValue())
			: null;
		return new NewGoal(wireKind, metric, t, dueOn);
	}
}

package com.anvil;

import java.util.function.BooleanSupplier;

import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;

/**
 * An "Anvil" button in a game interface's title bar — the collection log's, beside WikiSync and
 * RuneProfile, and the clan window's, beside Wise Old Man's.
 *
 * <p>WHY BUTTONS AND NOT THE TAB WE DELETED. The in-game clog TAB went in 5d2e425 — four thousand
 * lines of hand-drawn widgets nobody read, sitting between the side panel (progress at a glance) and
 * the site (real search). These are not that: one control each, in the place the player already is,
 * doing what the sidebar already does, for somebody whose hands are in the game interface rather
 * than in RuneLite's.
 *
 * <p>DRAWN AS A BUTTON, NOT AS A WORD. The first version was a bare text widget, which read as a
 * stray label rather than something to click — its neighbours have a raised stone frame and a hover
 * state, and beside them a floating "Anvil" looks like a rendering fault. So this is the game's own
 * button: the V2 stone button's nine sprites (a backing, four corners, four edges) with the text
 * laid over the whole area carrying the listeners, swapping to the pressed-in set on hover. There is
 * essentially one right answer here and every plugin with a button in these bars has found it — the
 * sprites are the same ids whether a codebase spells them the legacy way (WORLD_MAP_BUTTON_*,
 * EQUIPMENT_BUTTON_*_HOVERED) or the generated way used here.
 *
 * <p>POSITIONED FROM THE RIGHT EDGE, not off a measured neighbour. Everything in these bars is
 * anchored right — the close button, then each plugin's button walking left — so an absolute-right
 * offset lands in the same slot at any window size, where arithmetic off another plugin's
 * coordinates moves the moment they move theirs.
 *
 * <p>SURVIVES A NEIGHBOUR REBUILDING THE BAR. WikiSync clears every dynamic child of this container
 * before adding its own, on the same script we draw on, so whether our button exists comes down to
 * who ran last — which is plugin load order, and nobody's to rely on. The answer is not to fight it:
 * we keep hold of what we made, notice when it is no longer attached, and build it again.
 */
final class HeaderButton
{
	/** Matches the native header buttons: small, and tall enough to hit comfortably. */
	private static final int WIDTH = 71;
	private static final int FALLBACK_HEIGHT = 20;
	/** The dimensions the nine-slice sprites are cut at. Stretching a corner is what looks wrong. */
	private static final int CORNER = 9;
	private static final int EDGE = 4;

	/** The stone button as it sits: raised, on the light backing. */
	private static final int[] SPRITES_IDLE = {
		SpriteID.TRADEBACKING,
		SpriteID.V2StoneButtonOut.A_TOP_LEFT,
		SpriteID.V2StoneButtonOut.A_TOP_RIGHT,
		SpriteID.V2StoneButtonOut.A_BOTTOM_LEFT,
		SpriteID.V2StoneButtonOut.A_BOTTOM_RIGHT,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_LEFT,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_TOP,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_RIGHT,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_BOTTOM,
	};

	/** The same button pressed in, on the dark backing — the game's own hover state for it. */
	private static final int[] SPRITES_HOVERED = {
		SpriteID.TRADEBACKING_DARK,
		SpriteID.V2StoneButtonIn.A_TOP_LEFT,
		SpriteID.V2StoneButtonIn.A_TOP_RIGHT,
		SpriteID.V2StoneButtonIn.A_BOTTOM_LEFT,
		SpriteID.V2StoneButtonIn.A_BOTTOM_RIGHT,
		SpriteID.V2StoneButtonIn.A_LEFT,
		SpriteID.V2StoneButtonIn.A_TOP,
		SpriteID.V2StoneButtonIn.A_RIGHT,
		SpriteID.V2StoneButtonIn.A_BOTTOM,
	};

	/** The frame's nine pieces, then the text on top. */
	private static final int PARTS = 10;
	private static final int TEXT = 9;

	private static final int TEXT_IDLE = 0xd6d6d6;
	private static final int TEXT_HOVERED = 0xffffff;

	/**
	 * The menu TARGET. The game builds an entry as "&lt;action&gt; &lt;name&gt;", which is why the
	 * action passed in is a verb alone — spelling it in both produced "Sync to Anvil Anvil".
	 */
	private static final String NAME = "Anvil";

	private final Client client;
	/** The container to draw in — the one the neighbouring buttons use, so we share its space. */
	private final int parentId;
	/** A native control in that bar, read for the row's height and vertical anchoring. */
	private final int anchorId;
	/** Distance from the bar's right edge to our left edge, in the slot left of our neighbours. */
	private final int rightOffset;
	/** Where to sit when the slot nearer the close button is empty. Equal to rightOffset when the
	 *  caller has no nearer slot to fall back to (the clan window, where we are already first). */
	private final int nearOffset;
	private final String label;
	/** The verb alone; the game appends {@link #NAME} to it. */
	private final String action;
	/** Whether syncing is possible right now — no site or no token means no button. */
	private final BooleanSupplier enabled;
	private final Runnable onClick;

	/** What we drew last time. Null until the first render, stale after a neighbour clears the bar. */
	private Widget[] parts;
	/** The slot those parts were drawn in, so a change of neighbours can be noticed and acted on. */
	private int drawnAt = Integer.MIN_VALUE;

	HeaderButton(Client client, int parentId, int anchorId, int rightOffset, String label, String action,
			BooleanSupplier enabled, Runnable onClick)
	{
		this(client, parentId, anchorId, rightOffset, rightOffset, label, action, enabled, onClick);
	}

	HeaderButton(Client client, int parentId, int anchorId, int rightOffset, int nearOffset, String label, String action,
				 BooleanSupplier enabled, Runnable onClick)
	{
		this.client = client;
		this.parentId = parentId;
		this.anchorId = anchorId;
		this.rightOffset = rightOffset;
		this.nearOffset = nearOffset;
		this.label = label;
		this.action = action;
		this.enabled = enabled;
		this.onClick = onClick;
	}

	/**
	 * Draw the button, or leave alone the one already there.
	 *
	 * <p>Safe to call on every draw of the interface. Must run on the client thread — and, because of
	 * the neighbour that clears this container, wants to run AFTER every other subscriber to the
	 * script has had its turn.
	 */
	void render()
	{
		Widget parent = client.getWidget(parentId);
		Widget anchor = client.getWidget(anchorId);
		if (parent == null || anchor == null || !enabled.getAsBoolean())
		{
			return;
		}
		final int x = slotFor(parent);
		if (stillAttached(parent))
		{
			if (drawnAt == x)
			{
				return; // ours, intact, in the right slot — drawing again would only make a second one
			}
			// THE NEIGHBOURS MOVED. Enabling WikiSync mid-session fills the slot we took while it was
			// away, and returning early here left the two buttons stacked on the same spot: ours was
			// still attached, so nothing ever reconsidered where it should be. Hide the old copy and
			// draw again at the slot that is free now.
			hideParts();
		}

		final int h = anchor.getOriginalHeight() > 0 ? anchor.getOriginalHeight() : FALLBACK_HEIGHT;
		final int y = anchor.getOriginalY();
		final int yMode = anchor.getYPositionMode();
		final int span = WIDTH - (CORNER * 2);
		final Widget[] made = new Widget[PARTS];

		// Background first so every edge draws over it, then the corners, then the edges between.
		made[0] = piece(parent, 0, x, y, WIDTH, h, yMode);
		made[1] = piece(parent, 1, x + WIDTH - CORNER, y, CORNER, CORNER, yMode);
		made[2] = piece(parent, 2, x, y, CORNER, CORNER, yMode);
		made[3] = piece(parent, 3, x + WIDTH - CORNER, y + h - CORNER, CORNER, CORNER, yMode);
		made[4] = piece(parent, 4, x, y + h - CORNER, CORNER, CORNER, yMode);
		made[5] = piece(parent, 5, x + WIDTH - CORNER, y + CORNER, CORNER, EDGE, yMode);
		made[7] = piece(parent, 7, x, y + CORNER, CORNER, EDGE, yMode);
		made[6] = piece(parent, 6, x + CORNER, y, span, CORNER, yMode);
		made[8] = piece(parent, 8, x + CORNER, y + h - CORNER, span, CORNER, yMode);

		// The text covers the whole button, so it is what the mouse actually meets: one layer owns
		// the click, the hover and the label, and the nine underneath are decoration.
		Widget text = child(parent, WidgetType.TEXT, x, y, WIDTH, h, yMode);
		text.setText(label);
		text.setTextColor(TEXT_IDLE);
		text.setFontId(FontID.PLAIN_11);
		text.setTextShadowed(true);
		text.setXTextAlignment(WidgetTextAlignment.CENTER);
		text.setYTextAlignment(WidgetTextAlignment.CENTER);
		text.setHasListener(true);
		text.setAction(0, action);
		text.setOnOpListener((JavaScriptCallback) e -> onClick.run());
		text.setOnMouseOverListener((JavaScriptCallback) e -> paint(made, SPRITES_HOVERED, TEXT_HOVERED));
		text.setOnMouseLeaveListener((JavaScriptCallback) e -> paint(made, SPRITES_IDLE, TEXT_IDLE));
		text.revalidate();
		made[TEXT] = text;

		parts = made;
		drawnAt = x;
		parent.revalidate();
	}

	/**
	 * Which slot to sit in — the far one when a neighbour holds the near one, the near one otherwise.
	 *
	 * The offsets stay FIXED; this only chooses between two of them. Deriving coordinates from
	 * another plugin's widget is what the class comment warns off, and this does not: it asks whether
	 * anything foreign is anchored in the near slot, which is a yes/no about occupancy rather than a
	 * position to copy.
	 *
	 * Without it the far offset was unconditional, so somebody with WikiSync disabled got a button
	 * floating a slot-width away from the close button with an empty gap between them — reserved for
	 * a plugin that was not running.
	 */
	private int slotFor(Widget parent)
	{
		if (nearOffset >= rightOffset)
		{
			return rightOffset;
		}
		Widget[] children = parent.getDynamicChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				if (child == null || NAME.equals(child.getName()))
				{
					continue; // ours, from a previous render we are about to replace
				}
				if (child.getXPositionMode() != WidgetPositionMode.ABSOLUTE_RIGHT)
				{
					continue;
				}
				final int childX = child.getOriginalX();
				if (childX >= nearOffset && childX < rightOffset)
				{
					return rightOffset; // somebody is in the near slot; take the one beyond it
				}
			}
		}
		return nearOffset;
	}

	/** One piece of the frame, by its index into the sprite sets. */
	private Widget piece(Widget parent, int index, int x, int y, int w, int h, int yMode)
	{
		Widget piece = child(parent, WidgetType.GRAPHIC, x, y, w, h, yMode);
		piece.setSpriteId(SPRITES_IDLE[index]);
		piece.revalidate();
		return piece;
	}

	/** One of our widgets, named as ours and placed from the parent's right edge. */
	private static Widget child(Widget parent, int type, int x, int y, int w, int h, int yMode)
	{
		Widget c = parent.createChild(-1, type);
		c.setName(NAME);
		c.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);
		c.setYPositionMode(yMode);
		c.setOriginalX(x);
		c.setOriginalY(y);
		c.setOriginalWidth(w);
		c.setOriginalHeight(h);
		return c;
	}

	/**
	 * Re-evaluate while the window is open: draw, move, or clear as the situation now stands.
	 *
	 * <p>Cheap enough for every tick. When the parent is gone there is nothing to do; when the button
	 * should not be there it is hidden once and then there is nothing to hide; when it is already
	 * right, render() returns on an identity scan.</p>
	 */
	void refresh()
	{
		Widget parent = client.getWidget(parentId);
		if (parent == null)
		{
			// The window is closed. Our widgets went with it, so forget them rather than hiding
			// objects that are no longer attached to anything.
			parts = null;
			drawnAt = Integer.MIN_VALUE;
			return;
		}
		if (!enabled.getAsBoolean())
		{
			if (parts != null)
			{
				hideParts();
			}
			return;
		}
		render();
	}

	/**
	 * Hide what we drew, and forget it.
	 *
	 * <p>Hidden rather than deleted because a dynamic child cannot be removed on its own — the only
	 * removal the API offers clears the whole container, which would take the neighbours with it.
	 * A hidden widget does not render and is collected when the interface is next rebuilt.</p>
	 */
	void hideParts()
	{
		if (parts != null)
		{
			for (Widget w : parts)
			{
				if (w != null)
				{
					w.setHidden(true);
				}
			}
		}
		parts = null;
		drawnAt = Integer.MIN_VALUE;
	}

	/** Swap the frame between its idle and hovered sprite sets. */
	private static void paint(Widget[] made, int[] sprites, int textColour)
	{
		for (int i = 0; i < TEXT; i++)
		{
			if (made[i] != null)
			{
				made[i].setSpriteId(sprites[i]);
			}
		}
		if (made[TEXT] != null)
		{
			made[TEXT].setTextColor(textColour);
		}
	}

	/**
	 * Is the button we last drew still a child of this bar?
	 *
	 * <p>Identity, not a name lookup. After a neighbour clears the container our widgets are still
	 * perfectly good objects — just no longer attached to anything — so the question is whether the
	 * bar still holds the one we made, which answers both "were we wiped" and "did the interface
	 * rebuild underneath us".
	 */
	private boolean stillAttached(Widget parent)
	{
		if (parts == null || parts[TEXT] == null)
		{
			return false;
		}
		Widget[] children = parent.getDynamicChildren();
		if (children == null)
		{
			return false;
		}
		for (Widget w : children)
		{
			if (w == parts[TEXT])
			{
				return true;
			}
		}
		return false;
	}
}

package com.anvil;

import java.time.LocalDateTime;
import java.time.ZoneOffset;

/**
 * Pure, RuneLite-free helpers for the in-game "missions board" of a ladder / rotating event: the live
 * grow-or-decay value of a mission, the per-second countdown to the next reveal, and their display
 * strings. Kept side-effect-free so the Swing sidebar renders
 * one implementation and it's unit-testable. No threads, no I/O — just clock math.
 */
final class LadderMissions
{
	private LadderMissions()
	{
	}

	/** True for the ladder format (individual-primary random-task leaderboard). Null/other → false. */
	static boolean isLadder(String format)
	{
		return "ladder".equalsIgnoreCase(format);
	}

	/**
	 * A mission's live value = face scaled by the decay ramp: {@code face * (1 - (1 - target) * frac)},
	 * where {@code target = targetPct/100} and {@code frac} is the elapsed fraction of the ramp window
	 * (0 at reveal → 1 after {@code hours}). {@code targetPct < 100} decays, {@code > 100} grows. Returns
	 * the plain face when there's no decay rule or the reveal time is unknown/unparseable.
	 */
	static long liveValue(long face, String revealedAtIso, PluginConfigResponse.Decay decay, long nowMs)
	{
		if (decay == null || decay.hours <= 0)
		{
			return face;
		}
		long revealedAt = parseUtcMillis(revealedAtIso);
		if (revealedAt < 0)
		{
			return face;
		}
		double target = decay.targetPct / 100.0;
		double frac = Math.min(1.0, Math.max(0.0, (nowMs - revealedAt) / (decay.hours * 3_600_000.0)));
		double value = face * (1.0 - (1.0 - target) * frac);
		return Math.round(Math.max(0.0, value));
	}

	/**
	 * "120 -> 90" (decay) / "120 -> 200" (grow) when the value has moved, else just "120". ASCII arrow:
	 * the OSRS chat + collection-log widget fonts don't carry Unicode arrows/emoji.
	 */
	static String valueLabel(long face, long current)
	{
		if (current == face)
		{
			return Long.toString(face);
		}
		return face + " -> " + current;
	}

	/**
	 * Per-second countdown to the next reveal: {@code "12:34"} (m:ss), {@code "1:02:03"} (h:mm:ss for
	 * long waits), {@code "now"} once due, or {@code null} when there's no scheduled reveal (e.g. a
	 * bounty board draws on claim, not a clock).
	 */
	static String countdown(String nextRevealAtIso, long nowMs)
	{
		if (nextRevealAtIso == null || nextRevealAtIso.isEmpty())
		{
			return null;
		}
		long at = parseUtcMillis(nextRevealAtIso);
		if (at < 0)
		{
			return null;
		}
		long secs = Math.max(0, (at - nowMs) / 1000);
		if (secs == 0)
		{
			return "now";
		}
		long h = secs / 3600;
		long m = (secs % 3600) / 60;
		long s = secs % 60;
		if (h > 0)
		{
			return h + ":" + two(m) + ":" + two(s);
		}
		return m + ":" + two(s);
	}

	private static String two(long v)
	{
		return v < 10 ? "0" + v : Long.toString(v);
	}

	/**
	 * Parse the server's UTC timestamp — either ISO ({@code 2026-07-29T12:00:00.000Z}) or the
	 * space-separated {@code yyyy-MM-dd HH:mm:ss} SQLite form — to epoch millis, or -1 if unparseable.
	 */
	static long parseUtcMillis(String ts)
	{
		if (ts == null || ts.isEmpty())
		{
			return -1;
		}
		String s = ts.trim().replace(' ', 'T');
		if (s.endsWith("Z"))
		{
			s = s.substring(0, s.length() - 1);
		}
		try
		{
			return LocalDateTime.parse(s).toInstant(ZoneOffset.UTC).toEpochMilli();
		}
		catch (RuntimeException e)
		{
			return -1;
		}
	}
}

package com.anvil;

/**
 * Which level-ups a destination wants posted (site capability {@code level-rules}): 99s, every
 * {@code skillStep} levels from {@code skillFrom}, every {@code totalStep} total from {@code totalFrom},
 * and maxing. The site sends one set for the clan's channel and one for the player's own webhooks; a
 * null set wants nothing. A site without the capability gets {@link #LEGACY_CLAN} for the clan — exactly the old
 * 99s-and-high-totals behaviour.
 */
public class LevelRules
{
	public boolean ninetyNines;
	public int skillStep;
	public int skillFrom;
	public int totalStep;
	public int totalFrom;
	public boolean maxTotal;

	public static class Sets
	{
		public LevelRules clan;
		public LevelRules personal;

		Sets()
		{
		}

		Sets(LevelRules clan, LevelRules personal)
		{
			this.clan = clan;
			this.personal = personal;
		}
	}

	static final LevelRules LEGACY_CLAN = new LevelRules(true, 0, 1, 100, 1800, true);

	LevelRules()
	{
	}

	LevelRules(boolean ninetyNines, int skillStep, int skillFrom, int totalStep, int totalFrom, boolean maxTotal)
	{
		this.ninetyNines = ninetyNines;
		this.skillStep = skillStep;
		this.skillFrom = skillFrom;
		this.totalStep = totalStep;
		this.totalFrom = totalFrom;
		this.maxTotal = maxTotal;
	}

	/**
	 * The sets this site asks for, with the clan's dropped when it has no channel for level posts
	 * (the player's own webhooks can still want one — the site routes it).
	 */
	static Sets resolve(PluginConfigResponse cfg, boolean clanChannel)
	{
		Sets s = cfg != null && cfg.levelRules != null && cfg.serverSupports("level-rules")
			? cfg.levelRules : new Sets(LEGACY_CLAN, null);
		return new Sets(clanChannel ? s.clan : null, s.personal);
	}

	boolean matchesSkill(int level)
	{
		return (level == 99 && ninetyNines)
			|| (skillStep > 0 && level >= skillFrom && (level - skillFrom) % skillStep == 0);
	}

	/** The highest level crossed ({@code prev < L <= now}) that either set wants, or 0. */
	static int skillMilestone(int prev, int now, Sets s)
	{
		for (int l = now; l > prev; l--)
		{
			if ((s.clan != null && s.clan.matchesSkill(l)) || (s.personal != null && s.personal.matchesSkill(l)))
			{
				return l;
			}
		}
		return 0;
	}

	/** The highest round total crossed ({@code prev < M <= now}) that either set wants, or 0. */
	static int totalMilestone(int prev, int now, Sets s)
	{
		return Math.max(totalMilestone(prev, now, s.clan), totalMilestone(prev, now, s.personal));
	}

	private static int totalMilestone(int prev, int now, LevelRules r)
	{
		if (r == null || r.totalStep <= 0)
		{
			return 0;
		}
		// The highest multiple reached; if that is under the floor, every lower one is too.
		int m = now / r.totalStep * r.totalStep;
		return m > prev && m >= r.totalFrom ? m : 0;
	}

	static boolean wantsMax(Sets s)
	{
		return (s.clan != null && s.clan.maxTotal) || (s.personal != null && s.personal.maxTotal);
	}
}

package com.anvil;

/**
 * Binomial-probability helpers for multi-roll drop rarity.
 *
 * Adapted from Dink (pajlads/DinkPlugin), BSD-2-Clause — see THIRD_PARTY_NOTICES.md. Trimmed to the
 * methods the rarity service needs and rewritten to avoid the Guava dependency.
 */
final class MathUtils {
    static final double EPSILON = 0.00001;

    // Precomputed factorials 0..9 — max rolls in npc_drops.json is 9.
    private static final int[] FACTORIALS;

    static {
        int n = 10;
        int[] facts = new int[n];
        facts[0] = 1;
        for (int i = 1; i < n; i++) {
            facts[i] = i * facts[i - 1];
        }
        FACTORIALS = facts;
    }

    private MathUtils() {
    }

    static boolean lessThanOrEqual(double a, double b) {
        return a < b || Math.abs(a - b) <= EPSILON;
    }

    static double binomialProbability(double p, int nTrials, int kSuccess) {
        // https://en.wikipedia.org/wiki/Binomial_distribution#Probability_mass_function
        return binomialCoefficient(nTrials, kSuccess) * Math.pow(p, kSuccess) * Math.pow(1 - p, nTrials - kSuccess);
    }

    private static int binomialCoefficient(int n, int k) {
        return FACTORIALS[n] / (FACTORIALS[k] * FACTORIALS[n - k]);
    }
}

package com.anvil;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

/**
 * What a clan notification says happened, for the site to turn into a Discord post.
 *
 * <p>The plugin decides WHETHER to post (toggles, channel flags, tier floors, dedup, rarity) and
 * reports what only the client knows; the site's lib/pluginEmbeds.ts owns how it reads (titles,
 * colours, links, wording, number formatting). Sent as {@code {channel, kind, facts}} to
 * /api/plugin/notify. The site has to advertise {@code site-embeds} BEFORE a plugin sending these
 * ships — there is no local fallback. Unset values are left out. Kinds and their facts:
 *
 * <ul>
 * <li>drop: items[{id,name,qty,value}] (several = one combined haul), source, sourceKind, kc,
 *     dropRate, guaranteed, troll, notable ("loot"|"unlock"), earned, spoon, note</li>
 * <li>pet: name, itemId, duplicate, source, skill, kc, dropRate</li>
 * <li>clogSlot: item, itemId, slots, slotsMax, source, kc</li>
 * <li>caTask: task, tier ("Easy".."Grandmaster"), totalPoints, nextThreshold</li>
 * <li>caTier: tier — diary: area, tier — quest: quest, difficulty ("Novice".."Grandmaster")</li>
 * <li>level: skill, level, at99, skills (level99 without level, to a site lacking level-rules) —
 *     totalLevel: total, milestone, maxed, current, max</li>
 * </ul>
 * Every kind also carries {@code rsn} when known.
 */
final class NotifyFacts
{
	final String kind;
	final JsonObject facts = new JsonObject();

	NotifyFacts(String kind, String rsn)
	{
		this.kind = kind;
		put("rsn", rsn);
	}

	NotifyFacts put(String key, String value)
	{
		if (value != null && !value.isEmpty())
		{
			facts.addProperty(key, value);
		}
		return this;
	}

	NotifyFacts put(String key, Number value)
	{
		if (value != null)
		{
			facts.addProperty(key, value);
		}
		return this;
	}

	NotifyFacts flag(String key, boolean value)
	{
		if (value)
		{
			facts.addProperty(key, true);
		}
		return this;
	}

	/** Adds one entry to the drop's {@code items}. */
	NotifyFacts item(int id, String name, int qty, long value)
	{
		JsonArray items = facts.getAsJsonArray("items");
		if (items == null)
		{
			items = new JsonArray();
			facts.add("items", items);
		}
		JsonObject it = new JsonObject();
		it.addProperty("id", id);
		it.addProperty("name", name);
		it.addProperty("qty", qty);
		it.addProperty("value", value);
		items.add(it);
		return this;
	}
}

package com.anvil;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Clan notifications (POST /api/plugin/notify) the site didn't take, kept and resent.
 *
 * <p>The happy path never comes here: a notification is sent straight away, exactly as before, and
 * only lands in the outbox when that attempt failed for a reason that may clear (no network, a 5xx,
 * 401/408/429). A permanent refusal is dropped where it happened. Each entry keeps the URL and the
 * identity headers (X-RSN, X-Account-Hash) it was first sent with, so a retry after a character switch
 * still speaks for the character the 99 or the pet belonged to.
 *
 * <p>On disk under {@code <plugin dir>/outbox/notify/} as {@code <id>.json} plus {@code <id>.png} when
 * there's a screenshot, so a client restart mid-outage loses nothing. Bounded: at most
 * {@link #MAX_ITEMS} entries, {@link #MAX_BYTES} of screenshots and {@link #MAX_AGE_MS} old — the
 * oldest go first; a notification a day late is news nobody wants.
 *
 * <p>Retries back off from {@link #FIRST_RETRY_MS} to {@link #MAX_RETRY_MS} with jitter, and one
 * failed send ends a pass: with the site down there is no point dialling it once per queued entry.
 * Sends run on the OkHttp pool, never the client thread; disk writes on the thread that enqueued
 * (an OkHttp callback) or that pool.
 */
@Slf4j
final class NotifyOutbox
{
	static final int MAX_ITEMS = 100;
	static final long MAX_AGE_MS = 24L * 60 * 60 * 1000;
	static final long MAX_BYTES = 20L * 1024 * 1024;
	static final long FIRST_RETRY_MS = 15_000L;
	static final long MAX_RETRY_MS = 300_000L;

	enum Result
	{
		SENT, PERMANENT, RETRY
	}

	interface Sender
	{
		Result send(Item item, byte[] png);
	}

	/** One queued notification. Serialized as-is; the PNG lives beside it. */
	static final class Item
	{
		String id;
		String url;
		String channel;
		/** The payload_json exactly as first sent. */
		String payload;
		String filename;
		String rsn;
		String accountHash;
		/** Fingerprint of the token it was sent with: another account's sign-in doesn't send it. */
		String account;
		int pngBytes;
		long createdAt;
		int attempts;
		long nextAttemptAt;
		/** The screenshot, held in memory only when there is no directory to write it to. */
		transient byte[] png;
	}

	private final Gson gson;
	private final Supplier<ScheduledExecutorService> scheduler;
	private final Supplier<ExecutorService> sendPool;
	private volatile Filepath dir;
	private volatile Sender sender;
	private final List<Item> items = new ArrayList<>();
	private ScheduledFuture<?> task;
	private boolean pumping;

	NotifyOutbox(Gson gson, Supplier<ScheduledExecutorService> scheduler, Supplier<ExecutorService> sendPool)
	{
		this.gson = gson;
		this.scheduler = scheduler;
		this.sendPool = sendPool;
	}

	void setDir(Filepath dir)
	{
		this.dir = dir;
	}

	void setSender(Sender sender)
	{
		this.sender = sender;
	}

	synchronized int size()
	{
		return items.size();
	}

	/** A fresh entry: first retry after {@link #FIRST_RETRY_MS} (jittered). */
	static Item newItem(long now)
	{
		Item it = new Item();
		it.id = now + "-" + UUID.randomUUID().toString().substring(0, 8);
		it.createdAt = now;
		it.attempts = 1;
		it.nextAttemptAt = now + RetryPolicy.backoffMs(1, FIRST_RETRY_MS, MAX_RETRY_MS, Math.random());
		return it;
	}

	/**
	 * The entries to evict, given the queue (oldest first): everything past {@code maxAge}, then the
	 * oldest until at most {@code maxItems} remain and their screenshots fit in {@code maxBytes}.
	 */
	static List<Item> overflow(List<Item> queue, long now, int maxItems, long maxAge, long maxBytes)
	{
		List<Item> evict = new ArrayList<>();
		List<Item> kept = new ArrayList<>();
		long bytes = 0;
		for (Item it : queue)
		{
			if (now - it.createdAt > maxAge)
			{
				evict.add(it);
			}
			else
			{
				kept.add(it);
				bytes += Math.max(0, it.pngBytes);
			}
		}
		int i = 0;
		while (i < kept.size() && (kept.size() - i > maxItems || bytes > maxBytes))
		{
			Item oldest = kept.get(i++);
			bytes -= Math.max(0, oldest.pngBytes);
			evict.add(oldest);
		}
		return evict;
	}

	/** Read what a previous session left. Blocking (disk); call off the client thread. */
	void load()
	{
		Filepath d = DiskFiles.ensureDir(dir);
		if (d == null)
		{
			return;
		}
		List<Item> found = new ArrayList<>();
		List<Filepath> pngs = new ArrayList<>();
		try (Stream<Filepath> walk = d.walk(1))
		{
			List<Filepath> files = walk.filter(Filepath::isFile).collect(Collectors.toList());
			for (Filepath f : files)
			{
				if (f.getFileName().endsWith(".png"))
				{
					pngs.add(f);
				}
				if (!f.getFileName().endsWith(".json"))
				{
					continue;
				}
				try
				{
					Item it = gson.fromJson(DiskFiles.readText(f), Item.class);
					if (it != null && it.id != null && it.url != null && it.payload != null && f.getFileName().equals(it.id + ".json"))
					{
						found.add(it);
					}
					else
					{
						DiskFiles.deleteQuietly(f);
					}
				}
				catch (JsonParseException e)
				{
					DiskFiles.deleteQuietly(f);
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Notification outbox unreadable: {}", e.getMessage());
			return;
		}
		// A screenshot whose entry never made it to disk is an orphan nothing will read.
		for (Filepath png : pngs)
		{
			String id = png.getFileName().substring(0, png.getFileName().length() - 4);
			if (found.stream().noneMatch(it -> it.id.equals(id)))
			{
				DiskFiles.deleteQuietly(png);
			}
		}
		if (found.isEmpty())
		{
			return;
		}
		synchronized (this)
		{
			for (Item it : found)
			{
				if (items.stream().noneMatch(x -> x.id.equals(it.id)))
				{
					items.add(it);
				}
			}
			items.sort(Comparator.comparingLong(x -> x.createdAt));
			prune(System.currentTimeMillis());
			log.info("Anvil: {} notification(s) waiting from last session", items.size());
			schedule(FIRST_RETRY_MS);
		}
	}

	/** Keep a notification that just failed to send. Blocking (disk); never on the client thread. */
	void enqueue(Item item, byte[] png)
	{
		Filepath d = DiskFiles.ensureDir(dir);
		item.pngBytes = png == null ? 0 : png.length;
		if (d != null)
		{
			try
			{
				if (png != null && png.length > 0)
				{
					DiskFiles.writeAtomic(d.joinSegment(item.id + ".png"), png);
				}
				DiskFiles.writeAtomic(d.joinSegment(item.id + ".json"), gson.toJson(item));
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Couldn't save notification for retry: {}", e.getMessage());
				item.png = png; // keep it for this session at least
			}
		}
		else
		{
			item.png = png;
		}
		synchronized (this)
		{
			items.add(item);
			prune(System.currentTimeMillis());
			if (task == null || task.isDone())
			{
				schedule(Math.max(0, item.nextAttemptAt - System.currentTimeMillis()));
			}
		}
	}

	/** The site is back: try everything now. */
	synchronized void kick()
	{
		if (items.isEmpty())
		{
			return;
		}
		for (Item it : items)
		{
			it.nextAttemptAt = 0;
		}
		schedule(0);
	}

	/** Signed out: nothing queued may go out under whoever signs in next. */
	void clear()
	{
		List<Item> all;
		synchronized (this)
		{
			all = new ArrayList<>(items);
			items.clear();
			cancel();
		}
		all.forEach(this::deleteFiles);
	}

	/** Plugin stopping: cancel the timer; the files stay for next time. */
	synchronized void stop()
	{
		cancel();
	}

	private void cancel()
	{
		if (task != null)
		{
			task.cancel(false);
			task = null;
		}
	}

	/** Call with the monitor held. */
	private void prune(long now)
	{
		List<Item> evict = overflow(items, now, MAX_ITEMS, MAX_AGE_MS, MAX_BYTES);
		if (evict.isEmpty())
		{
			return;
		}
		items.removeAll(evict);
		log.info("Anvil: dropped {} undelivered notification(s) (too old, or too many waiting)", evict.size());
		ExecutorService pool = sendPool.get();
		if (pool != null && !pool.isShutdown())
		{
			pool.submit(() -> evict.forEach(this::deleteFiles));
		}
	}

	/** Call with the monitor held. */
	private void schedule(long waitMs)
	{
		ScheduledExecutorService ex = scheduler.get();
		if (ex == null || ex.isShutdown())
		{
			return;
		}
		cancel();
		task = ex.schedule(this::handOff, Math.max(0, waitMs), TimeUnit.MILLISECONDS);
	}

	/** On the timer: run the pass on the HTTP pool, never the plugin's one thread. */
	private void handOff()
	{
		ExecutorService pool = sendPool.get();
		if (pool != null && !pool.isShutdown())
		{
			pool.submit(this::pump);
		}
	}

	/** One pass over what's due. Blocking HTTP; runs on the OkHttp pool. */
	void pump()
	{
		Sender s = sender;
		List<Item> due;
		synchronized (this)
		{
			if (pumping || s == null)
			{
				return;
			}
			pumping = true;
			long now = System.currentTimeMillis();
			prune(now);
			due = items.stream().filter(it -> it.nextAttemptAt <= now).collect(Collectors.toList());
		}
		try
		{
			for (int i = 0; i < due.size(); i++)
			{
				Item it = due.get(i);
				byte[] png = it.pngBytes > 0 ? screenshot(it) : null;
				if (it.pngBytes > 0 && png == null)
				{
					remove(it); // its screenshot is gone; nothing sensible left to send
					continue;
				}
				Result r = s.send(it, png);
				if (r != Result.RETRY)
				{
					if (r == Result.PERMANENT)
					{
						log.warn("Anvil: the site refused a queued '{}' notification — dropping it", it.channel);
					}
					remove(it);
					continue;
				}
				// Still down. Push this one back, and don't dial again for the rest — same wait for all.
				long now = System.currentTimeMillis();
				long next;
				synchronized (this)
				{
					it.attempts++;
					next = now + RetryPolicy.backoffMs(it.attempts, FIRST_RETRY_MS, MAX_RETRY_MS, Math.random());
					for (int j = i; j < due.size(); j++)
					{
						due.get(j).nextAttemptAt = Math.max(due.get(j).nextAttemptAt, next);
					}
				}
				rewrite(it);
				break;
			}
		}
		finally
		{
			synchronized (this)
			{
				pumping = false;
				long soonest = items.stream().mapToLong(it -> it.nextAttemptAt).min().orElse(-1);
				if (soonest >= 0)
				{
					schedule(soonest - System.currentTimeMillis());
				}
			}
		}
	}

	private byte[] screenshot(Item it)
	{
		if (it.png != null)
		{
			return it.png;
		}
		Filepath d = dir;
		return d == null ? null : DiskFiles.read(d.joinSegment(it.id + ".png"));
	}

	private void remove(Item it)
	{
		synchronized (this)
		{
			items.remove(it);
		}
		deleteFiles(it);
	}

	private void rewrite(Item it)
	{
		Filepath d = dir;
		if (d == null)
		{
			return;
		}
		try
		{
			DiskFiles.writeAtomic(d.joinSegment(it.id + ".json"), gson.toJson(it));
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Couldn't update queued notification: {}", e.getMessage());
		}
	}

	private void deleteFiles(Item it)
	{
		Filepath d = dir;
		if (d == null || it.id == null)
		{
			return;
		}
		try
		{
			DiskFiles.deleteQuietly(d.joinSegment(it.id + ".json"));
			DiskFiles.deleteQuietly(d.joinSegment(it.id + ".png"));
		}
		catch (RuntimeException ignored)
		{
			// joinSegment refusing a name read back from disk: nothing of ours to delete.
		}
	}
}

package com.anvil;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Progress this client has seen on a tile that the site hasn't confirmed yet — a kill, a drop, a KC
 * line, an XP drop — so the sidebar and the pinned tracker move the moment it happens instead of on
 * the next poll after the push lands.
 *
 * <p>A floor, not a replacement: every surface shows {@code max(site count, floor)}. It lives outside
 * the polled config, so a config refresh that lands before the push doesn't wind the count back. Each
 * floor goes away once the site reaches it, when the push failed ({@link #clear}), or after
 * {@link #TTL_MS} — a floor the site never reaches was wrong, and the site's number wins.
 */
final class OptimisticProgress
{
	static final long TTL_MS = 120_000;

	/** tileId → {floor, expiresAt}. */
	private final Map<Integer, long[]> floors = new ConcurrentHashMap<>();

	/** This client now has the tile at {@code current} (an absolute team count it just bumped to). */
	void raise(int tileId, long current, long now)
	{
		if (tileId <= 0 || current <= 0)
		{
			return;
		}
		floors.merge(tileId, new long[]{current, now + TTL_MS},
			(old, add) -> new long[]{Math.max(old[0], add[0]), add[1]});
	}

	/** This client gained {@code delta} on a tile the site last put at {@code siteCurrent}. */
	void add(int tileId, long siteCurrent, long delta, long now)
	{
		if (tileId <= 0 || delta <= 0)
		{
			return;
		}
		long[] f = live(tileId, siteCurrent, now);
		raise(tileId, Math.max(siteCurrent, f == null ? 0 : f[0]) + delta, now);
	}

	/** What to show for a tile the site puts at {@code siteCurrent}. */
	long apply(int tileId, long siteCurrent, long now)
	{
		long[] f = live(tileId, siteCurrent, now);
		return f == null ? siteCurrent : Math.max(siteCurrent, f[0]);
	}

	/** The push behind this tile's floor failed — back to what the site says. */
	void clear(int tileId)
	{
		floors.remove(tileId);
	}

	void reset()
	{
		floors.clear();
	}

	/** The tile's floor while it still means something; drops it once the site caught up or it expired. */
	private long[] live(int tileId, long siteCurrent, long now)
	{
		long[] f = floors.get(tileId);
		if (f == null)
		{
			return null;
		}
		if (siteCurrent >= f[0] || now > f[1])
		{
			floors.remove(tileId, f);
			return null;
		}
		return f;
	}
}

package com.anvil;

import com.google.gson.Gson;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.io.Writer;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

@Slf4j
@Singleton
public class PendingSubmissionStore
{
	// Garbage-collect pending submissions older than this. Prevents unbounded disk growth
	// when retries keep failing (e.g. site URL permanently wrong) and the user never clears.
	private static final long MAX_AGE_MS = 7L * 24 * 60 * 60 * 1000; // 7 days

	/**
	 * The plugin's own directory, handed over by AnvilPlugin — the only class allowed to ask for it.
	 *
	 * THE ROOT ITSELF, not a subfolder, and that is the migration's doing rather than a preference:
	 * `legacyDataDirectory` MOVES `.runelite/osrs-bingo-pending` to BE the plugin directory, so
	 * everything that folder held arrives at its root. Reading from anywhere else would mean not
	 * finding the very files the migration exists to carry across.
	 *
	 * Null until startUp resolves it, and null forever if that failed. Every method treats that as
	 * "no store": nothing queues, nothing loads, and the caller's own error path takes over — which
	 * is the same thing that happened when the disk was full.
	 */
	private volatile Filepath root;

	private final Gson gson;

	@Inject
	public PendingSubmissionStore(Gson gson)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
	}

	public static class PendingSubmission
	{
		public int eventId;
		public int tileId;
		public int teamId;
		public int playerId;
		public int amount;
		public String label;
		public String note;
		public String screenshotFile; // filename of PNG in pending dir
		public long timestamp;
		public Integer itemId; // specific item ID for per-item tracking (nullable)
		public Integer durationSeconds; // timed-tile clear time in seconds (nullable; non-null routes to submitTimed)
		public String capturedRsn; // character the drop was obtained on; only re-submitted while on it
		public String inferred; // the item was worked out, not seen (DuplicateInference); the site flags it for review
		// A proof the plugin can't auto-submit to a specific tile (pet drop, duplicate Champion's
		// scroll — the "would have received" line names no item), captured so the player has a ready
		// screenshot to attach when they submit by hand on the site. The retry loop skips these.
		public boolean manual;
	}

	public void setRoot(Filepath dir)
	{
		this.root = dir;
	}

	/** The directory, created on demand, or null when there is nowhere to write. */
	private Filepath dir()
	{
		Filepath d = root;
		if (d == null)
		{
			return null;
		}
		try
		{
			if (!d.exists())
			{
				d.createDirectories();
			}
			return d;
		}
		catch (IOException e)
		{
			log.warn("Anvil: cannot create the pending-submission directory: {}", e.getMessage());
			return null;
		}
	}

	public String save(PendingSubmission sub, byte[] pngBytes)
	{
		Filepath dir = dir();
		if (dir == null)
		{
			return null;
		}
		String id = sub.tileId + "-" + sub.timestamp;

		Filepath png = dir.joinSegment(id + ".png");
		try
		{
			png.write(pngBytes);
		}
		catch (IOException e)
		{
			log.error("Failed to save pending screenshot: {}", e.getMessage());
			return null;
		}

		sub.screenshotFile = id + ".png";
		try (Writer w = dir.joinSegment(id + ".json").openWriter())
		{
			gson.toJson(sub, w);
		}
		catch (IOException e)
		{
			log.error("Failed to save pending submission metadata: {}", e.getMessage());
			// The PNG without its metadata is an orphan nothing will ever read.
			try
			{
				png.deleteIfExists();
			}
			catch (IOException ignored)
			{
				// Already logged the real failure; a leftover file is the lesser problem.
			}
			return null;
		}

		log.info("Saved pending submission: {} (tile '{}')", id, sub.label);
		return id;
	}

	public List<PendingSubmission> loadAll()
	{
		List<PendingSubmission> result = new ArrayList<>();
		List<Filepath> jsonFiles = listJson();
		long now = System.currentTimeMillis();
		for (Filepath f : jsonFiles)
		{
			try (Reader r = f.openReader())
			{
				PendingSubmission sub = gson.fromJson(r, PendingSubmission.class);
				if (sub != null && sub.timestamp > 0 && (now - sub.timestamp) > MAX_AGE_MS)
				{
					log.info("Pruning expired pending submission '{}' ({} days old)",
						sub.label, (now - sub.timestamp) / (24 * 60 * 60 * 1000));
					remove(sub);
					continue;
				}
				result.add(sub);
			}
			catch (Exception e)
			{
				log.warn("Failed to read pending submission {}: {}", f.getFileName(), e.getMessage());
			}
		}
		return result;
	}

	/**
	 * The queued metadata files, one per waiting submission.
	 *
	 * Depth 1 rather than a full walk: the migration drops these at the root of the plugin directory
	 * alongside `sounds/`, and descending would read a banner clip's neighbours looking
	 * for JSON.
	 */
	private List<Filepath> listJson()
	{
		Filepath dir = dir();
		if (dir == null)
		{
			return new ArrayList<>();
		}
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk.filter(f -> f.isFile() && f.getFileName().endsWith(".json")).collect(Collectors.toList());
		}
		catch (IOException e)
		{
			log.warn("Failed to list pending submissions: {}", e.getMessage());
			return new ArrayList<>();
		}
	}

	public byte[] readScreenshot(PendingSubmission sub)
	{
		Filepath dir = dir();
		if (dir == null || sub.screenshotFile == null)
		{
			return null;
		}
		// joinSegment, not join: it refuses a separator, so a screenshotFile read back out of a JSON
		// file cannot walk anywhere with "../" in it.
		try (InputStream in = dir.joinSegment(sub.screenshotFile).openInputStream())
		{
			return in.readAllBytes();
		}
		catch (IOException | RuntimeException e)
		{
			log.error("Failed to read pending screenshot {}: {}", sub.screenshotFile, e.getMessage());
			return null;
		}
	}

	public void remove(PendingSubmission sub)
	{
		Filepath dir = dir();
		if (dir == null || sub.screenshotFile == null)
		{
			return;
		}
		String baseName = sub.screenshotFile.replace(".png", "");
		try
		{
			dir.joinSegment(baseName + ".png").deleteIfExists();
			dir.joinSegment(baseName + ".json").deleteIfExists();
			log.info("Removed pending submission: {} (tile '{}')", baseName, sub.label);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Failed to remove pending submission {}: {}", baseName, e.getMessage());
		}
	}

}

package com.anvil;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pulls a personal best out of a completion message.
 *
 * <p>Two shapes, and the difference matters — reading the wrong number would record a slow run as
 * somebody's best:
 * <pre>
 *   "Duration: 2:58.03 (new personal best)"          → the PB is the duration, 2:58.03
 *   "Challenge duration: 10:24. Personal best: 7:59." → the PB is 7:59, NOT this run's 10:24
 * </pre>
 *
 * <p>Times are returned in <b>centiseconds</b>. The game prints hundredths and a leaderboard that
 * rounded to whole seconds would tie runs the game itself separates.
 *
 * <p>The activity is deliberately NOT parsed here: the plugin already extracts it from the adjacent
 * "Your X kill count is: N" line for kill crediting, so PB capture reuses that instead of running a
 * second regex over every line of chat. RuneLite-free, so the fragile part is unit-tested.
 */
final class PersonalBestParser
{
	private PersonalBestParser() {}

	/** An [h:]mm:ss[.cc] token. The game never prints a bare seconds count for a PB. */
	private static final Pattern TIME = Pattern.compile("(\\d{1,3}):(\\d{2})(?::(\\d{2}))?(?:\\.(\\d{1,2}))?");
	/** "personal best: 7:59" — the explicit form, where this run was NOT the best. */
	private static final Pattern EXPLICIT = Pattern.compile("personal best:\\s*");

	/**
	 * The personal best this line reports, in centiseconds, or null when it reports none.
	 */
	static Integer parseCentis(String message)
	{
		if (message == null)
		{
			return null;
		}
		String lower = message.toLowerCase();
		int marker = lower.indexOf("personal best");
		if (marker < 0)
		{
			return null;
		}

		// "Personal best: <time>" — read the time AFTER the label, and only that one.
		Matcher explicit = EXPLICIT.matcher(lower);
		if (explicit.find(marker))
		{
			Matcher time = TIME.matcher(lower);
			if (time.find(explicit.end()))
			{
				return toCentis(time);
			}
			return null;
		}

		// "(new personal best)" — this run IS the best, so the line's own duration is the number.
		Matcher time = TIME.matcher(lower);
		if (time.find())
		{
			return toCentis(time);
		}
		return null;
	}

	private static Integer toCentis(Matcher m)
	{
		try
		{
			int a = Integer.parseInt(m.group(1));
			int b = Integer.parseInt(m.group(2));
			// Three parts means h:mm:ss; two means mm:ss.
			int seconds = m.group(3) != null
				? a * 3600 + b * 60 + Integer.parseInt(m.group(3))
				: a * 60 + b;
			int centis = seconds * 100;
			String fraction = m.group(4);
			if (fraction != null)
			{
				// ".3" is three tenths — pad to hundredths rather than reading it as three.
				centis += fraction.length() == 1
					? Integer.parseInt(fraction) * 10
					: Integer.parseInt(fraction);
			}
			return centis > 0 ? centis : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/**
 * The account's best times, kept locally and pushed to the clan site.
 *
 * <p>Two ways in, because neither alone is enough:
 * <ul>
 *   <li><b>Live</b> — the completion messages the plugin already reads for timed tiles also carry
 *       "(new personal best)" / "Personal best: 7:59". Free: no extra chat parsing, and no waiting.</li>
 *   <li><b>Seed</b> — RuneLite's own chat-commands plugin has been recording these into its config
 *       for years. Importing that once turns a blank profile into a complete one on first login,
 *       which is what makes this feel like a sync rather than a slow accrual. The plugin reads it;
 *       this class only receives the numbers ({@link #seed}).</li>
 * </ul>
 *
 * <p>Times are centiseconds — the game separates runs by hundredths and so should a leaderboard.
 *
 * <p>The activity is supplied by the caller from the "Your X kill count is: N" line it already
 * parses, so a PB costs no additional regex on the chat hot path. Correlation works in both
 * directions because the game is inconsistent about ordering: the Inferno prints the duration
 * before the kill count, most bosses print it after.
 *
 * <p>RuneLite-free, so the correlation and flush rules are unit-testable without a client.
 */
final class PersonalBests
{
	/** How long a kill-count line and a duration line can be apart and still be the same kill. */
	static final long CORRELATION_MS = 6_000;
	/** Settle time before a push — a raid prints several lines at once. */
	static final long QUIET_MS = 3_000;

	/** Best known time per activity, keyed lowercase. Lower is better; that's the whole model. */
	private final Map<String, Integer> best = new HashMap<>();
	/** What the server already has, so an unchanged PB is never re-sent. */
	private final Map<String, Integer> sent = new HashMap<>();
	/** Activities whose best has moved since the last successful push. */
	private final Set<String> dirty = new LinkedHashSet<>();

	/** The most recent activity name from a kill-count line, and when we saw it. */
	private String recentActivity;
	private long recentActivityAt;
	/** A PB that arrived before its activity did (Inferno ordering), awaiting a name. */
	private int orphanCentis;
	private long orphanAt;

	private long lastChangeAt;

	/** The activity a kill-count line just named. Cheap: two field writes, no parsing. */
	void onActivitySeen(String activity, long now)
	{
		if (activity == null || activity.isEmpty())
		{
			return;
		}
		recentActivity = activity.toLowerCase();
		recentActivityAt = now;
		// A duration that arrived first now has its name.
		if (orphanCentis > 0 && now - orphanAt <= CORRELATION_MS)
		{
			record(recentActivity, orphanCentis, now);
			orphanCentis = 0;
		}
	}

	/**
	 * Offer a chat line. Returns true when it produced a new best.
	 *
	 * <p>Lines with no personal best in them cost one {@code indexOf} — this runs on every line of
	 * chat, so the negative path is the one that has to be free.
	 */
	boolean onChatLine(String message, long now)
	{
		Integer centis = PersonalBestParser.parseCentis(message);
		if (centis == null)
		{
			return false;
		}
		if (recentActivity != null && now - recentActivityAt <= CORRELATION_MS)
		{
			return record(recentActivity, centis, now);
		}
		// No name yet — hold it for the kill-count line that's about to arrive.
		orphanCentis = centis;
		orphanAt = now;
		return false;
	}

	/**
	 * Import times recorded by another source (RuneLite's chat-commands store).
	 *
	 * @return how many were adopted as new bests
	 */
	int seed(Map<String, Integer> centisByActivity, long now)
	{
		if (centisByActivity == null || centisByActivity.isEmpty())
		{
			return 0;
		}
		int adopted = 0;
		for (Map.Entry<String, Integer> e : centisByActivity.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null)
			{
				continue;
			}
			if (record(e.getKey().toLowerCase(), e.getValue(), now))
			{
				adopted++;
			}
		}
		return adopted;
	}

	/** Keep the fastest. A PB only ever goes down, so a slower number is noise, not an update. */
	private boolean record(String activity, int centis, long now)
	{
		if (activity == null || activity.isEmpty() || centis <= 0)
		{
			return false;
		}
		Integer current = best.get(activity);
		if (current != null && current <= centis)
		{
			return false;
		}
		best.put(activity, centis);
		dirty.add(activity);
		lastChangeAt = now;
		return true;
	}

	boolean isDue(long now)
	{
		return !dirty.isEmpty() && now - lastChangeAt >= QUIET_MS;
	}

	/** The pending bests, activity → centiseconds. */
	Map<String, Integer> nextBatch()
	{
		Map<String, Integer> batch = new LinkedHashMap<>(dirty.size());
		for (String activity : dirty)
		{
			Integer centis = best.get(activity);
			if (centis != null)
			{
				batch.put(activity, centis);
			}
		}
		return batch;
	}

	/**
	 * Mark a batch delivered. Anything that improved again mid-flight stays dirty, so the better
	 * time is sent next round rather than being silently dropped.
	 */
	void onSent(Map<String, Integer> batch)
	{
		for (Map.Entry<String, Integer> e : batch.entrySet())
		{
			sent.put(e.getKey(), e.getValue());
			Integer current = best.get(e.getKey());
			if (current != null && current.equals(e.getValue()))
			{
				dirty.remove(e.getKey());
			}
		}
	}

	int knownCount()
	{
		return best.size();
	}

	int pendingCount()
	{
		return dirty.size();
	}

	/** Forget everything — the next account's bests are not this one's. */
	void reset()
	{
		best.clear();
		sent.clear();
		dirty.clear();
		recentActivity = null;
		orphanCentis = 0;
		lastChangeAt = 0;
	}

	/**
	 * The delivered bests as one config string: {@code <centis>|<activity>} per line.
	 *
	 * <p>Value first for the same reason as the collection log's state: activity names contain
	 * colons and spaces, an integer can't contain a pipe, so the parse needs no escaping.
	 */
	String serializeState()
	{
		return ClogSync.writeLines(sent, String::valueOf);
	}

	/**
	 * Restore delivered state. These count as known bests too — otherwise every login would re-push
	 * the whole set to tell the server what it already stored.
	 */
	void restoreState(String raw)
	{
		// A truncated or hand-edited line is dropped; the next kill re-establishes it.
		ClogSync.readLines(raw, (value, activity) ->
		{
			int centis = Integer.parseInt(value);
			if (centis > 0)
			{
				sent.put(activity, centis);
				best.merge(activity, centis, Math::min);
			}
		});
	}
}

package com.anvil;

import java.util.List;

/**
 * One character as the side panel's Lookup and You tabs show it — the JSON of
 * {@code GET /api/players/<rsn>/card} (the {@code player-card} capability).
 *
 * <p>What's notable about the account and nothing that's zero: the site already left out empty boss
 * rows and log groups, so the panel draws whatever arrives.</p>
 */
public final class PlayerCard
{
	public String rsn;
	public String accountType;
	public Clan clan;
	public int totalLevel;
	public Integer combatLevel;
	public Long overallXp;
	public Double ehp;
	public Double ehb;
	/** Null until they've synced their collection log. */
	public Clog clog;
	public List<Latest> latest;
	public List<Boss> topBosses;
	// The in-panel profile behind the summary. Absent from an older site; treat null as empty.
	public List<Skill> skills;
	public List<Boss> bosses;
	public List<Activity> activities;
	public List<Page> clogPages;
	/** Uploaded personal bests: one entry per boss and mode, its best time first, team sizes behind it. */
	public List<PbEntry> times;
	/**
	 * "hiscores" when the name has no Anvil account and the site built this card from the official
	 * hiscores instead ({@code player-card-hiscores}); null (an Anvil profile) on any other card and on
	 * older sites.
	 */
	public String source;
	/** When the site read the hiscores for a {@code source: "hiscores"} card (ISO); null otherwise. */
	public String fetchedAt;

	/** Built from the official hiscores, not an Anvil profile: no log, no feed, no profile page. */
	public boolean fromHiscores()
	{
		return "hiscores".equalsIgnoreCase(source);
	}

	public static final class PbEntry
	{
		/** "Chambers of Xeric: Challenge Mode", "Duke Sucellus (Awakened)", "Vorkath". */
		public String name;
		/** The boss alone — what the icon is found by. */
		public String base;
		public String mode;
		public String best;
		/** Team sizes, Solo first; empty when there's only the one time. */
		public List<PbVariant> variants;
	}

	public static final class PbVariant
	{
		/** "Solo", "2", "11-15", or "" when the time has no team size. */
		public String team;
		public String time;
		public String activity;
	}

	public static final class Skill
	{
		public String key;
		public int level;
		public long xp;
	}

	public static final class Activity
	{
		public String key;
		public String label;
		public String shortLabel;
		/** "clues", "minigames" or "collection". */
		public String group;
		public int score;
	}

	public static final class Page
	{
		public String name;
		public String group;
		public int obtained;
		public int total;
		/** An item to draw the page by — its first slot. Null on an older site. */
		public Integer iconItemId;
	}

	public static final class Clan
	{
		public String slug;
		public String name;
	}

	public static final class Clog
	{
		public int obtained;
		public int total;
		public List<Group> groups;
	}

	public static final class Group
	{
		public String name;
		public int obtained;
		public int total;
	}

	public static final class Latest
	{
		/** "item" or "milestone". */
		public String kind;
		public String label;
		public Integer itemId;
		public String at;
	}

	public static final class Boss
	{
		public String key;
		/** The game's name, matched to RuneLite's hiscore sprites. */
		public String label;
		public int kc;
		/** The log page its kills fill (a raid's modes share one); null when it has none. */
		public String clogPage;
	}
}

