/**
 * "Anvil" on a player's right-click menu: opens their character page, {@code /p/<rsn>}.
 *
 * <p>Two places a name can be clicked, wired the two ways RuneLite allows. A player standing in the
 * world gets a player-menu item (MenuManager owns those slots, shared with every other plugin). A name
 * in a list — friends, ignore, chat channel, clan panels, the chatbox, private messages — gets an
 * entry slotted next to the game's own options, the same placement the hiscores "Lookup" uses, so it
 * sits where a person already looks for "who is this".</p>
 *
 * <p>Where it lands: the side panel's Lookup tab when the site serves player cards, the browser when
 * it doesn't (an older site, or signed out).</p>
 *
 * <p>Your own card is the side panel's You tab, not this: the game offers no player menu on
 * yourself.</p>
 *
 * <p>The URL is built here and nowhere else. It always points at {@link BingoApiClient#CANONICAL_SITE}
 * — character pages are not clan-scoped, a character belongs to its player wherever they play.</p>
 */
@Singleton
final class ProfileLookup
{
	static final String OPTION = "Anvil";

	/** List options our entry goes AFTER (below) / BEFORE (above), matching the hiscores plugin. */
	private static final Set<String> AFTER_OPTIONS = Set.of("Message", "Add ignore", "Remove friend", "Delete", "Kick", "Reply");
	private static final Set<String> BEFORE_OPTIONS = Set.of("Add friend", "Remove ignore");

	private final Client client;
	private final MenuManager menuManager;
	private final AnvilConfig config;
	private final EventBus eventBus;

	private boolean playerItemShown;
	/** Opens a name in the side panel's Lookup tab; false when it can't (no card support), and we browse. */
	private volatile Predicate<String> panelOpener;

	@Inject
	ProfileLookup(Client client, MenuManager menuManager, AnvilConfig config, EventBus eventBus)
	{
		this.client = client;
		this.menuManager = menuManager;
		this.config = config;
		this.eventBus = eventBus;
	}

	/** The character page for {@code rsn}, or null when there is no name to look up. */
	static String profileUrl(String rsn)
	{
		if (rsn == null)
		{
			return null;
		}
		// The game pads names with U+00A0; the site folds case and spacing itself, so only the
		// padding has to go. Path-encoded, not form-encoded: '+' in a path is a literal plus.
		String name = rsn.replace(' ', ' ').trim();
		if (name.isEmpty())
		{
			return null;
		}
		return BingoApiClient.CANONICAL_SITE + "/p/" + URLEncoder.encode(name, StandardCharsets.UTF_8).replace("+", "%20");
	}

	/** The card API for {@code rsn} ({@code player-card} capability), or null when there is no name. */
	static String apiCardUrl(String rsn)
	{
		String page = profileUrl(rsn);
		return page == null ? null
			: BingoApiClient.CANONICAL_SITE + "/api/players/" + page.substring(page.lastIndexOf('/') + 1) + "/card";
	}

	/** Open {@code rsn}'s character page in the system browser. False when there was no name. */
	static boolean open(String rsn)
	{
		String url = profileUrl(rsn);
		if (url == null)
		{
			return false;
		}
		LinkBrowser.browse(url);
		return true;
	}

	/** The name lists (friends, ignores, chat channels, clans, raid party, private chat) that get the entry. */
	private static final Set<Integer> NAME_LISTS = Set.of(InterfaceID.FRIENDS, InterfaceID.IGNORE, InterfaceID.CHATCHANNEL_CURRENT,
		InterfaceID.CLANS_SIDEPANEL, InterfaceID.CLANS_GUEST_SIDEPANEL, InterfaceID.RAIDS_SIDEPANEL, InterfaceID.PM_CHAT);

	/**
	 * Which side of a list option our entry goes on: +1 after it, -1 before it, 0 not a list entry we
	 * add to. The chatbox's "Kick" is a clan-chat moderation entry, not a name menu, so it is skipped
	 * there — the same carve-out the hiscores plugin makes.
	 */
	static int listPlacement(int groupId, String option)
	{
		boolean nameList = NAME_LISTS.contains(groupId) || (groupId == InterfaceID.CHATBOX && !"Kick".equals(option));
		if (!nameList || option == null)
		{
			return 0;
		}
		if (AFTER_OPTIONS.contains(option))
		{
			return 1;
		}
		return BEFORE_OPTIONS.contains(option) ? -1 : 0;
	}

	/** Whether the per-surface setting lets the entry onto names in this interface. */
	private boolean surfaceOn(int groupId)
	{
		switch (groupId)
		{
			case InterfaceID.CHATBOX:
			case InterfaceID.PM_CHAT:
				return config.lookupChat();
			case InterfaceID.CLANS_SIDEPANEL:
			case InterfaceID.CLANS_GUEST_SIDEPANEL:
				return config.lookupClan();
			case InterfaceID.CHATCHANNEL_CURRENT:
				return config.lookupFriendsChat();
			default:
				return config.lookupLists();
		}
	}

	/**
	 * The menu index for our entry. {@code -1} goes on top of the option just added, which in the
	 * chat makes it the top row — the left-click on a name. Chat names always take {@code -2}, under
	 * that option, so a click on a name never opens a lookup.
	 */
	static int menuIndex(int groupId, int placement)
	{
		boolean chat = groupId == InterfaceID.CHATBOX || groupId == InterfaceID.PM_CHAT;
		return placement > 0 || chat ? -2 : -1;
	}

	static boolean sameTarget(String a, String b)
	{
		return Text.removeTags(a == null ? "" : a).equals(Text.removeTags(b == null ? "" : b));
	}

	void startUp()
	{
		eventBus.register(this);
		syncPlayerItem();
	}

	void shutDown()
	{
		eventBus.unregister(this);
		if (playerItemShown)
		{
			menuManager.removePlayerMenuItem(OPTION);
			playerItemShown = false;
		}
	}

	void setPanelOpener(Predicate<String> opener)
	{
		this.panelOpener = opener;
	}

	/** The panel's Lookup tab when it can show cards, the browser when it can't. */
	private void lookUp(String rsn)
	{
		Predicate<String> opener = panelOpener;
		if (opener != null && rsn != null && opener.test(rsn))
		{
			return;
		}
		open(rsn);
	}

	/** Add or remove the in-world player item to match the settings. Called on start and config change. */
	void syncPlayerItem()
	{
		boolean want = config.profileLookupMenu() && config.lookupPlayers();
		if (want == playerItemShown)
		{
			return;
		}
		if (want)
		{
			menuManager.addPlayerMenuItem(OPTION);
		}
		else
		{
			menuManager.removePlayerMenuItem(OPTION);
		}
		playerItemShown = want;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.profileLookupMenu())
		{
			return;
		}
		int groupId = WidgetUtil.componentToInterface(event.getActionParam1());
		int placement = listPlacement(groupId, event.getOption());
		if (placement == 0 || !surfaceOn(groupId))
		{
			return;
		}
		// One per name. A name's menu often carries two of the options we sit beside ("Add friend" and
		// "Add ignore" on a stranger in chat), and each used to add its own "Anvil".
		for (net.runelite.api.MenuEntry existing : client.getMenu().getMenuEntries())
		{
			if (OPTION.equals(existing.getOption()) && sameTarget(existing.getTarget(), event.getTarget()))
			{
				return;
			}
		}
		client.getMenu().createMenuEntry(menuIndex(groupId, placement))
			.setOption(OPTION)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.setIdentifier(event.getIdentifier())
			.onClick(e -> lookUp(Text.removeTags(e.getTarget())));
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getMenuAction() != MenuAction.RUNELITE_PLAYER || !OPTION.equals(event.getMenuOption()))
		{
			return;
		}
		Player player = event.getMenuEntry().getPlayer();
		if (player != null)
		{
			lookUp(player.getName());
		}
	}
}

package com.anvil;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Unsent KC / XP / activity counts and highlight-feed moments, saved per CHARACTER across a logout or a
 * client restart and handed back when that character logs in again.
 *
 * <p>Per character because every one of these is sent as whoever is logged in (X-RSN): restoring one
 * character's kill counts into another's session would credit the wrong account. The file is
 * {@code <plugin dir>/outbox/pushes-<fingerprint>.json}, the fingerprint a truncated SHA-256 of the
 * account hash (or the name when the hash isn't known), and reading it deletes it. Anything older
 * than {@link #MAX_AGE_MS} is ignored — the hiscores have caught up by then, and a day-old moment is
 * old news. All methods block on disk: executor only.
 */
@Slf4j
final class PushStash
{
	static final long MAX_AGE_MS = 24L * 60 * 60 * 1000;

	/** One character's waiting pushes. Plain fields only: it round-trips through Gson as-is. */
	static final class Data
	{
		long savedAt;
		Map<String, Integer> kc = new HashMap<>();
		Map<String, Integer> xp = new HashMap<>();
		Map<String, Integer> activity = new HashMap<>();
		List<SavedMoment> moments = new ArrayList<>();

		boolean isEmpty()
		{
			return empty(kc) && empty(xp) && empty(activity) && (moments == null || moments.isEmpty());
		}

		private static boolean empty(Map<?, ?> m)
		{
			return m == null || m.isEmpty();
		}
	}

	/** {@link AnvilMoments.Moment} as stored — a plain DTO, so nothing final needs reconstructing. */
	static final class SavedMoment
	{
		String kind;
		Integer itemId;
		String itemName;
		int quantity;
		Long valueGp;
		String source;
		String sourceKind;
		Integer kc;
		String taskName;
		String tier;
		long at;
		String key;

		static SavedMoment of(AnvilMoments.Moment m)
		{
			SavedMoment s = new SavedMoment();
			s.kind = m.kind;
			s.itemId = m.itemId;
			s.itemName = m.itemName;
			s.quantity = m.quantity;
			s.valueGp = m.valueGp;
			s.source = m.source;
			s.sourceKind = m.sourceKind;
			s.kc = m.kc;
			s.taskName = m.taskName;
			s.tier = m.tier;
			s.at = m.at;
			s.key = m.key;
			return s;
		}

		AnvilMoments.Moment toMoment()
		{
			return new AnvilMoments.Moment(kind, itemId, itemName, quantity, valueGp, source, sourceKind, kc,
				taskName, tier, at, key);
		}
	}

	private final Gson gson;
	private volatile Filepath dir;

	PushStash(Gson gson)
	{
		this.gson = gson;
	}

	void setDir(Filepath dir)
	{
		this.dir = dir;
	}

	/** The file stem for a character: by account hash when known, else by name. Null when neither is. */
	static String keyFor(String rsn, String accountHash)
	{
		if (accountHash != null && !accountHash.isEmpty())
		{
			return DiskFiles.fingerprint("h:" + accountHash);
		}
		if (rsn != null && !rsn.trim().isEmpty())
		{
			return DiskFiles.fingerprint("r:" + rsn.trim().toLowerCase(Locale.ROOT));
		}
		return null;
	}

	/** Merge two stashes — counts are absolute, so the larger wins; moments by key, newer wins. */
	static Data merge(Data older, Data newer)
	{
		if (older == null)
		{
			return newer;
		}
		Data out = new Data();
		out.savedAt = Math.max(older.savedAt, newer.savedAt);
		mergeMax(out.kc, older.kc, newer.kc);
		mergeMax(out.xp, older.xp, newer.xp);
		mergeMax(out.activity, older.activity, newer.activity);
		Map<String, SavedMoment> byKey = new java.util.LinkedHashMap<>();
		for (List<SavedMoment> list : java.util.Arrays.asList(older.moments, newer.moments))
		{
			if (list != null)
			{
				for (SavedMoment m : list)
				{
					if (m != null && m.key != null)
					{
						byKey.put(m.key, m);
					}
				}
			}
		}
		out.moments = new ArrayList<>(byKey.values());
		return out;
	}

	private static void mergeMax(Map<String, Integer> into, Map<String, Integer> a, Map<String, Integer> b)
	{
		for (Map<String, Integer> m : java.util.Arrays.asList(a, b))
		{
			if (m != null)
			{
				m.forEach((k, v) ->
				{
					if (k != null && v != null)
					{
						into.merge(k, v, Integer::max);
					}
				});
			}
		}
	}

	private Filepath file(String key)
	{
		Filepath d = DiskFiles.ensureDir(dir);
		return d == null || key == null ? null : d.joinSegment("pushes-" + key + ".json");
	}

	/** Save {@code data} for the character {@code key}, folded into anything already saved. */
	void save(String key, Data data)
	{
		Filepath f = file(key);
		if (f == null || data == null || data.isEmpty())
		{
			return;
		}
		Data merged = merge(read(f), data);
		try
		{
			DiskFiles.writeAtomic(f, gson.toJson(merged));
			log.debug("Saved unsent pushes for later");
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Couldn't save unsent pushes: {}", e.getMessage());
		}
	}

	/** What was saved for {@code key} (deleting it), or null when nothing fresh was. */
	Data take(String key, long now)
	{
		Filepath f = file(key);
		Data d = read(f);
		DiskFiles.deleteQuietly(f);
		return d == null || now - d.savedAt > MAX_AGE_MS ? null : d;
	}

	/** Signed out: drop every character's saved pushes. */
	void clearAll()
	{
		Filepath d = DiskFiles.ensureDir(dir);
		if (d == null)
		{
			return;
		}
		try (Stream<Filepath> walk = d.walk(1))
		{
			walk.filter(f -> f.isFile() && f.getFileName().startsWith("pushes-")).collect(Collectors.toList())
				.forEach(DiskFiles::deleteQuietly);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Couldn't clear saved pushes: {}", e.getMessage());
		}
	}

	private Data read(Filepath f)
	{
		String text = DiskFiles.readText(f);
		if (text == null)
		{
			return null;
		}
		try
		{
			return gson.fromJson(text, Data.class);
		}
		catch (JsonParseException e)
		{
			return null;
		}
	}
}

package com.anvil;

/**
 * The lowest quest difficulty posted to the clan achievements channel, or OFF for none. A quest's
 * difficulty comes from {@code questTiers} in anvil_text.json; a quest missing there (the wiki's
 * "Special" ones, such as most of Recipe for Disaster) posts only on ALL. ALL keeps its old name
 * so a saved "All quests" setting still loads; MASTER and GRANDMASTER likewise.
 */
public enum QuestAnnounceTier
{
	ALL("All"),
	INTERMEDIATE("Intermediate"),
	EXPERIENCED("Experienced"),
	MASTER("Master"),
	GRANDMASTER("Grandmaster"),
	OFF("Off");

	private final String label;

	QuestAnnounceTier(String label)
	{
		this.label = label;
	}

	/**
	 * Whether a quest of {@code difficulty} ("NOVICE" … "GRANDMASTER", or null when unknown) is
	 * posted. Unknown counts as the lowest tier.
	 */
	boolean posts(String difficulty)
	{
		if (this == OFF)
		{
			return false;
		}
		int rank = 0;
		if (difficulty != null)
		{
			switch (difficulty)
			{
				case "INTERMEDIATE": rank = 1; break;
				case "EXPERIENCED": rank = 2; break;
				case "MASTER": rank = 3; break;
				case "GRANDMASTER": rank = 4; break;
				default: rank = 0;
			}
		}
		return rank >= ordinal();
	}

	@Override
	public String toString()
	{
		return label;
	}
}

