package com.anvil;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * The last good {@code /api/plugin/config} and active {@code /api/plugin/board} answers, kept on disk
 * per signed-in account so the next launch can draw the side panel straight away and open with a
 * conditional GET instead of a full download.
 *
 * <p>DISPLAY ONLY. What comes back from here is never handed to tracking — an event can end, a team
 * can change and a token can be revoked between sessions — so the plugin shows it until the site's
 * first live answer and then forgets it (see AnvilPlugin#sidebarConfig).
 *
 * <p>Files live in {@code <plugin dir>/cache/}, named {@code <kind>-<fingerprint>.json}, where the
 * fingerprint is a truncated SHA-256 of the Account Token: the token itself never touches disk. Not
 * at the plugin directory's root, where PendingSubmissionStore reads every JSON file as a proof.
 */
@Slf4j
final class ResponseDiskCache
{
	static final String CONFIG = "config";
	static final String BOARD = "board";
	/** A board bigger than this isn't worth the disk; the next launch just downloads it. */
	private static final int MAX_BODY_CHARS = 2_000_000;

	/** One saved answer. */
	static final class Entry
	{
		String url;
		String etag;
		String body;
		/** The character the request was made as (X-RSN, else the launcher hint), or null. */
		String rsn;
		long savedAt;
	}

	private final Gson gson;
	private volatile Filepath dir;
	/** Fingerprint of the token in use, "" when signed out. */
	private volatile String account = "";
	/** kind → etag (or body hash) last written, so an unchanged 30s poll doesn't rewrite the file. */
	private final Map<String, String> written = new ConcurrentHashMap<>();

	ResponseDiskCache(Gson gson)
	{
		this.gson = gson;
	}

	void setDir(Filepath dir)
	{
		this.dir = dir;
	}

	/**
	 * Point at the account behind {@code token}. Returns the fingerprint whose files should now be
	 * deleted (signing out, or a different account signing in), else null. Memory only — the caller
	 * deletes off the client thread.
	 */
	String switchAccount(String token)
	{
		String next = DiskFiles.fingerprint(token);
		String prev = account;
		if (next.equals(prev))
		{
			return null;
		}
		account = next;
		written.clear();
		return prev.isEmpty() ? null : prev;
	}

	String account()
	{
		return account;
	}

	private Filepath file(String kind, String acct)
	{
		Filepath d = DiskFiles.ensureDir(dir);
		return d == null || acct == null || acct.isEmpty() ? null : d.joinSegment(kind + "-" + acct + ".json");
	}

	/** The saved answer of {@code kind} for the current account, or null. Blocking. */
	Entry load(String kind)
	{
		Filepath f = file(kind, account);
		String text = DiskFiles.readText(f);
		if (text == null)
		{
			return null;
		}
		try
		{
			Entry e = gson.fromJson(text, Entry.class);
			if (e == null || e.body == null || e.url == null)
			{
				return null;
			}
			written.put(kind, e.etag != null ? e.etag : Integer.toString(e.body.hashCode()));
			return e;
		}
		catch (JsonParseException e)
		{
			log.debug("Saved {} unreadable, ignoring: {}", kind, e.getMessage());
			DiskFiles.deleteQuietly(f);
			return null;
		}
	}

	/** Save a fresh 200 body. Blocking; called from the HTTP worker that fetched it, never the client thread. */
	void store(String kind, String url, String etag, String body, String rsn)
	{
		if (body == null || body.length() > MAX_BODY_CHARS)
		{
			return;
		}
		String acct = account;
		String marker = etag != null ? etag : Integer.toString(body.hashCode());
		if (marker.equals(written.get(kind)))
		{
			return;
		}
		Filepath f = file(kind, acct);
		if (f == null)
		{
			return;
		}
		Entry e = new Entry();
		e.url = url;
		e.etag = etag;
		e.body = body;
		e.rsn = rsn;
		e.savedAt = System.currentTimeMillis();
		try
		{
			DiskFiles.writeAtomic(f, gson.toJson(e));
			written.put(kind, marker);
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Couldn't save {}: {}", kind, ex.getMessage());
		}
	}

	/** Delete every saved answer for {@code acct}. Blocking. */
	void clear(String acct)
	{
		if (acct == null || acct.isEmpty())
		{
			return;
		}
		DiskFiles.deleteQuietly(file(CONFIG, acct));
		DiskFiles.deleteQuietly(file(BOARD, acct));
	}
}

package com.anvil;

/**
 * The two questions every retry path asks, answered once: is this refusal worth trying again, and how
 * long to wait before doing so.
 */
final class RetryPolicy
{
	private RetryPolicy()
	{
	}

	/**
	 * A refusal that will never succeed however often it is resent: a 4xx, except 401 (the token may
	 * refresh, and a push fired in the second after login, before X-RSN is stamped, is refused with one
	 * that the next attempt clears), 408 (timed out) and 429 (slow down). 5xx and network failures
	 * are transient; anything below 400 is not a refusal at all.
	 */
	static boolean isPermanent(int code)
	{
		return code >= 400 && code < 500 && code != 401 && code != 408 && code != 429;
	}

	/**
	 * The wait before attempt {@code failures + 1}: {@code firstMs} doubling per failure, capped at
	 * {@code capMs}, spread ±20% by {@code jitter} (a uniform draw in [0, 1)) so a clan's clients that
	 * all lost the site at the same moment don't all come back at the same moment. Never above the cap.
	 */
	static long backoffMs(int failures, long firstMs, long capMs, double jitter)
	{
		if (failures <= 0)
		{
			return 0;
		}
		long base = firstMs;
		for (int i = 1; i < failures && base < capMs; i++)
		{
			base *= 2;
		}
		base = Math.min(base, capMs);
		double j = Math.max(0, Math.min(1, jitter));
		return Math.min(capMs, Math.round(base * (0.8 + 0.4 * j)));
	}
}

package com.anvil;

import java.util.Locale;

/**
 * One way to fold an OSRS name into a comparison key — the SAME way the site does it.
 *
 * <p>Every use of this is the same shape: take a name the client read out of the game, take a name
 * the server sent, and decide whether they are the same account. That only works if both sides fold
 * identically. There were three of these in the plugin, agreeing with each other about half the
 * time and with the server never.</p>
 *
 * <p><b>The rule</b> is the server's ({@code Anvil.Site src/lib/auth.ts normalizeRsn}):
 * lower-case, and collapse every run of whitespace <em>or underscore</em> to one space.</p>
 *
 * <p><b>Underscores are the part that was missing.</b> OSRS treats space and underscore as the same
 * character in a name: the game renders "GIM Nisbro", while logins, hiscores lookups and
 * hand-entered roster rows carry "GIM_nisbro". The server folds them together deliberately —
 * without it a roster sync reports one member left and another joined for the same person. The
 * plugin did not, so any name holding an underscore on the site failed to match the account playing
 * it: no bounty credit, no drop attribution, no "that's you" in a standings list.</p>
 *
 * <p><b>Two places where Java quietly disagrees with JavaScript</b>, both of which this has to bridge
 * because the server is the JavaScript one:</p>
 * <ul>
 *   <li>{@code String.trim()} in Java strips only characters up to U+0020, so it leaves a
 *       non-breaking space where JS strips it. OSRS names are full of U+00A0 — that is how the game
 *       encodes their spaces so a name never wraps a line. Folded to a plain space first.</li>
 *   <li>Java's {@code \\s} does not match U+00A0 either; JS's does. Spelled out in the class.</li>
 * </ul>
 *
 * <p>{@link Locale#ROOT} rather than the default locale, and that is not pedantry: a Turkish client
 * lower-cases 'I' to 'ı', so "IRON MIKE" would fold to something the server has never seen and that
 * player would silently stop matching their own roster row.</p>
 */
public final class Rsn
{
	private Rsn()
	{
	}

	/** Whitespace-or-underscore runs. U+00A0 is named explicitly — Java's {@code \s} omits it. */
	private static final java.util.regex.Pattern FOLD =
		java.util.regex.Pattern.compile("[\\s\\u00a0_]+");

	/**
	 * The comparison key for a name, or "" when there is no name.
	 *
	 * <p>Never null, because every caller compares the result and a null check at each of them is a
	 * check somebody eventually forgets. An empty key never matches a real one — callers guard on
	 * {@code !me.isEmpty()} before comparing, so an unknown local name matches nobody rather than
	 * everybody.</p>
	 */
	public static String normalize(String rsn)
	{
		if (rsn == null)
		{
			return "";
		}
		// U+00A0 → space BEFORE trimming, so a name padded with them trims like it does on the server.
		String plain = rsn.replace('\u00A0', ' ').trim().toLowerCase(Locale.ROOT);
		return FOLD.matcher(plain).replaceAll(" ").trim();
	}

	/** Do these two names denote the same account? Empty never matches, including empty itself. */
	public static boolean same(String a, String b)
	{
		String left = normalize(a);
		return !left.isEmpty() && left.equals(normalize(b));
	}
}

package com.anvil;

/**
 * What the plugin says in chat about its own setup, and how often.
 *
 * <p>THE STATE THAT SAID NOTHING. Somebody who installed Anvil and never opened the side panel used
 * to get complete silence forever: the plugin's whole surface is a panel they have no reason to
 * click, and nothing in the game ever mentioned that there was a step left. There is one setting to
 * have now — the Account Token, which Sign in fills in — so the only question is "signed in yet?".</p>
 *
 * <p>That mattered less when Anvil was something your clan admin set up for you and handed you a
 * token for. It is now a per-person account that works with no clan at all, so a fresh install is
 * the normal way in rather than a clan's leftover, and the thing it needs to know is where to go.</p>
 *
 * <p>NUDGE, NOT NAG. The first-run line is capped — {@link #FIRST_RUN_NUDGES} logins, counted in
 * config so the cap survives a restart — because somebody who has decided not to connect has
 * answered the question, and a message that repeats forever is how a plugin gets uninstalled.</p>
 *
 * <p>Pure, and RuneLite-free, so the decision can be tested without a client: the plugin supplies
 * the token and the count, and gets back what to print.</p>
 */
public final class SetupNudge
{
	/** How many logins a never-configured install is told where to go before it stops asking. */
	static final int FIRST_RUN_NUDGES = 3;

	/** The site, as it reads in a chat line — one source of truth with the address the plugin uses. */
	static final String SITE_HOST = BingoApiClient.CANONICAL_SITE.replaceFirst("^https?://", "");

	public enum Kind
	{
		/** Connected, or done asking. Say nothing. */
		NONE,
		/** Not signed in — the fresh install. */
		FIRST_RUN,
	}

	/**
	 * @param firstRunShown how many times the first-run line has already been printed on this install
	 */
	public static Kind decide(String token, int firstRunShown)
	{
		if (token != null && !token.trim().isEmpty())
		{
			return Kind.NONE;
		}
		return firstRunShown < FIRST_RUN_NUDGES ? Kind.FIRST_RUN : Kind.NONE;
	}

	/**
	 * The chat lines for a decision, in order. Empty for {@link Kind#NONE}.
	 *
	 * <p>The first-run pair is two lines on purpose: the first is the instruction — one button, in a
	 * panel they are being told exists — and the second is the reason anyone would press it, which
	 * for a person with no clan is the part that is not obvious. Neither line is a request to go
	 * anywhere but the one site this plugin talks to.</p>
	 */
	public static String[] lines(Kind kind)
	{
		switch (kind)
		{
			case FIRST_RUN:
				return new String[]{
					"Not connected yet — open the Anvil panel (the anvil icon on the right) and press \"Sign in with Discord\".",
					"A free account on " + SITE_HOST + " tracks your collection log, personal bests and records. No clan needed — and starting one is free.",
				};
			default:
				return new String[0];
		}
	}

	private SetupNudge()
	{
	}
}

package com.anvil;

/**
 * The Guice key the always-on progress sidebar ({@link AnvilSidebarPanel}) is wired through, bound to
 * {@link AnvilSidebarDataSource} — a view over the config the plugin already polls, and the only
 * implementation. It holds the row types the plugin and the panel share.
 */
public interface SidebarDataSource
{
	// ── The logged-in character: whose it's tracked as, and the way out ──────────────────────────
	//
	// The Account Token names whoever set this RuneLite up, not whoever is playing. Every character
	// links to it by default (the one-click path); siblings and visitors use this row to say "not
	// mine", and to claim back a character that's linked to somebody else.

	/** One line about the logged-in character. */
	final class AccountRow
	{
		public enum State
		{
			/** Linked to (or linking to) the signed-in Anvil account. Offers Not my account. */
			TRACKING,
			/** Marked Not my account on this computer; nothing is sent. Offers Track it again. */
			PAUSED,
			/** Claimed by another Anvil account; nothing tracks for this token. Offers It's mine. */
			OTHER,
		}

		public enum Action
		{
			NOT_MINE,
			TRACK_AGAIN,
			DISPUTE,
		}

		public final String rsn;
		public final State state;

		public AccountRow(String rsn, State state)
		{
			this.rsn = rsn;
			this.state = state;
		}
	}

	/**
	 * What the panel may DO for the addressed clan.
	 *
	 * <p>A roster sync scrapes the clan channel you are standing in, so it needs an admin with that
	 * channel readable. A profile sync goes to the site the plugin is authenticated against.
	 */
	class PanelActions
	{
		public static final PanelActions NONE = new PanelActions(false, false, null);

		/** Show "Sync clan roster": admin, at home, with a readable clan channel. */
		public final boolean canSyncRoster;
		/** Show "Sync profile": the site takes profile data and it's the one we're signed in to. */
		public final boolean canSyncProfile;
		/** Why the roster button is absent, when the reason is worth saying. Null when it isn't. */
		public final String rosterNote;

		public PanelActions(boolean canSyncRoster, boolean canSyncProfile, String rosterNote)
		{
			this.canSyncRoster = canSyncRoster;
			this.canSyncProfile = canSyncProfile;
			this.rosterNote = rosterNote;
		}
	}
}

package com.anvil;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.plaf.basic.BasicScrollBarUI;
import net.runelite.client.ui.ColorScheme;

/**
 * A thin, flat scrollbar for the side panel: no arrow buttons, a rounded thumb that lightens under
 * the mouse, and a track the colour of the panel. The default bar is 17px of a 225px-wide panel,
 * which on a small client is a lot of width spent on chrome.
 */
final class SlimScrollBarUI extends BasicScrollBarUI
{
	static final int WIDTH = 7;

	private static final Color THUMB = ColorScheme.MEDIUM_GRAY_COLOR;
	private static final Color THUMB_HOVER = ColorScheme.LIGHT_GRAY_COLOR;

	/** Restyle every scroll pane directly under {@code root} (the PluginPanel's wrapper). */
	static void applyTo(Container root)
	{
		if (root == null)
		{
			return;
		}
		for (Component c : root.getComponents())
		{
			if (c instanceof JScrollPane)
			{
				style(((JScrollPane) c).getVerticalScrollBar());
			}
		}
	}

	static void style(JScrollBar bar)
	{
		bar.setUI(new SlimScrollBarUI());
		bar.setPreferredSize(new Dimension(WIDTH, 0));
		bar.setOpaque(true);
		bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bar.setBorder(null);
		bar.setUnitIncrement(16);
	}

	@Override
	protected JButton createDecreaseButton(int orientation)
	{
		return zeroButton();
	}

	@Override
	protected JButton createIncreaseButton(int orientation)
	{
		return zeroButton();
	}

	private static JButton zeroButton()
	{
		JButton b = new JButton();
		Dimension none = new Dimension(0, 0);
		b.setPreferredSize(none);
		b.setMinimumSize(none);
		b.setMaximumSize(none);
		return b;
	}

	@Override
	protected void paintTrack(Graphics g, JComponent c, Rectangle r)
	{
		g.setColor(ColorScheme.DARK_GRAY_COLOR);
		g.fillRect(r.x, r.y, r.width, r.height);
	}

	@Override
	protected void paintThumb(Graphics g, JComponent c, Rectangle r)
	{
		if (r.isEmpty() || !scrollbar.isEnabled())
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(isThumbRollover() || isDragging ? THUMB_HOVER : THUMB);
		int inset = 1;
		g2.fillRoundRect(r.x + inset, r.y + inset, r.width - inset * 2, r.height - inset * 2, WIDTH, WIDTH);
		g2.dispose();
	}

	@Override
	protected Dimension getMinimumThumbSize()
	{
		return new Dimension(WIDTH, 24);
	}
}

package com.anvil;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The starting shot, on screen from the whistle until it's filed: where to stand and the same live
 * checks the sidebar card shows, then a short "you're tracked" before it gets out of the way. Shares
 * its toggle with the arrow to the spot (config startSpotGuide).
 */
class StartProofOverlay extends OverlayPanel
{
	/** How long "you're tracked" stays up once the shot is filed. */
	private static final long DONE_SHOWN_MS = 10_000;
	private static final Color ORANGE = new Color(255, 152, 31);

	private final AnvilPlugin plugin;
	private final AnvilConfig config;

	@Inject
	StartProofOverlay(AnvilPlugin plugin, AnvilConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.startSpotGuide())
		{
			return null;
		}
		if (plugin.needsStartProof())
		{
			PluginConfigResponse cfg = plugin.getPluginConfig();
			PluginConfigResponse.StartProof proof = cfg == null ? null : cfg.startProof;
			if (proof == null)
			{
				return null;
			}
			title("Starting shot needed", ORANGE);
			if (proof.location != null)
			{
				line("Go to", proof.location, Color.WHITE);
			}
			for (StartProofRules.Check c : plugin.startProofChecks(proof))
			{
				panelComponent.getChildren().add(LineComponent.builder().left(c.text).leftColor(
					c.state == StartProofRules.Check.State.OK ? Color.GREEN
						: c.state == StartProofRules.Check.State.BAD ? Color.RED : Color.LIGHT_GRAY).build());
			}
			if (plugin.startProofSending())
			{
				line("Checking tracking", "sending…", Color.YELLOW);
			}
			else
			{
				line(plugin.autoStartShotEnabled() ? "Taken automatically once all green" : "Press Take starting shot in the Anvil panel",
					"", Color.LIGHT_GRAY);
			}
			return super.render(graphics);
		}
		long filedAt = plugin.startProofFiledAt();
		if (filedAt > 0 && System.currentTimeMillis() - filedAt < DONE_SHOWN_MS)
		{
			title("You're tracked", Color.GREEN);
			line("Starting shot filed — drops and tiles count now", "", Color.WHITE);
			return super.render(graphics);
		}
		return null;
	}

	private void title(String text, Color color)
	{
		panelComponent.getChildren().add(TitleComponent.builder().text(text).color(color).build());
	}

	private void line(String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(left).right(right).rightColor(rightColor).build());
	}
}

package com.anvil;

/**
 * The client-side half of the STARTING SHOT rule (site lib/startProof).
 *
 * <p>Two things the site can ask for beyond the screenshot itself, both of which only this client can
 * answer, and both of which are far more useful checked BEFORE the frame is grabbed than filed and
 * argued about afterwards:
 *
 * <ul>
 *   <li><b>Where you are.</b> A drawn spot the host pinned on the map comes down as coordinates, so
 *       "go to Edgeville bank" stops being an instruction nobody can verify.</li>
 *   <li><b>How old this session is.</b> Hiscores only flush on LOGOUT, so a player who has been
 *       logged in since before the event started has a stale start baseline — every gain they made
 *       beforehand lands in the event's first sweep. Making them log out and back in right before
 *       the shot is what actually stops that, and the screenshot is just the receipt.</li>
 * </ul>
 *
 * <p>Pure and static so it unit-tests without a client: the plugin supplies the numbers.
 */
final class StartProofRules
{
	/** {@code sessionLoginAtMs} when we never saw the login — a plugin enabled mid-session. */
	static final long UNKNOWN_LOGIN = 0L;

	private StartProofRules()
	{
	}

	/**
	 * Squares from the drawn spot, the way OSRS measures "within N squares" — the longer axis, not
	 * the diagonal. -1 when there is nothing to measure (no pin, or no position to compare).
	 */
	static int distance(PluginConfigResponse.StartProof proof, Integer x, Integer y)
	{
		if (proof == null || proof.spot == null || x == null || y == null)
		{
			return -1;
		}
		return Math.max(Math.abs(x - proof.spot.x), Math.abs(y - proof.spot.y));
	}

	/**
	 * Why this shot can't be filed yet, as a sentence for chat — or null when it can.
	 *
	 * <p>Every check fails OPEN: an older site sends no spot and no window, an unpinned location has
	 * no coordinates, and a client that can't read its own position skips the distance test. The
	 * rule only ever blocks on something we positively know is wrong.
	 */
	static String blockReason(
		PluginConfigResponse.StartProof proof,
		long sessionLoginAtMs,
		long nowMs,
		Integer x,
		Integer y)
	{
		if (proof == null)
		{
			return null;
		}

		if (proof.maxSessionMinutes > 0)
		{
			if (sessionLoginAtMs == UNKNOWN_LOGIN)
			{
				// The plugin was switched on (or the client reconnected) mid-session, so we can't
				// vouch for the logout that flushed the hiscores. One relog settles it.
				return "Log out and back in before your starting shot — that's what saves your hiscores"
					+ " so your starting totals are right.";
			}
			long minutes = Math.max(0, (nowMs - sessionLoginAtMs) / 60_000L);
			if (minutes > proof.maxSessionMinutes)
			{
				return "You've been logged in for " + describeMinutes(minutes) + " — log out and back in,"
					+ " then take your starting shot within " + proof.maxSessionMinutes + " min."
					+ " Hiscores only save on logout, so this is what sets your starting totals.";
			}
		}

		int away = distance(proof, x, y);
		if (away >= 0 && away > proof.spot.radius)
		{
			return "You're " + away + " squares from " + (proof.location != null ? proof.location : "the start spot")
				+ " — go there, then take your starting shot.";
		}

		return null;
	}

	/**
	 * May the plugin take the shot by itself right now? Stricter than {@link #blockReason}, which fails
	 * open: a manual click on an unpinned spot is the player vouching they're there, but nobody is
	 * vouching for an automatic one — so it needs a pin, a known position inside it, and (when the
	 * host asks) a known, fresh session. {@code stillTicks} is how long the player has stood on this
	 * square; a moment's pause keeps the frame from catching them mid-run or mid-teleport.
	 */
	static boolean autoReady(PluginConfigResponse.StartProof proof, long sessionLoginAtMs, long nowMs,
		Integer x, Integer y, int stillTicks)
	{
		if (proof == null || proof.spot == null || x == null || y == null || stillTicks < AUTO_STILL_TICKS)
		{
			return false;
		}
		return blockReason(proof, sessionLoginAtMs, nowMs, x, y) == null;
	}

	/** Ticks (0.6s each) standing on one square before an automatic shot. */
	static final int AUTO_STILL_TICKS = 3;

	/** One live requirement on the starting-shot card: met, not met, or not knowable yet. */
	static final class Check
	{
		enum State
		{
			OK, BAD, UNKNOWN
		}

		final State state;
		final String text;

		Check(State state, String text)
		{
			this.state = state;
			this.text = text;
		}
	}

	/**
	 * The session-age requirement as the card shows it, or null when the host isn't asking. Same
	 * thresholds as {@link #blockReason}, so the card going green means the button won't refuse.
	 */
	static Check sessionCheck(PluginConfigResponse.StartProof proof, long sessionLoginAtMs, long nowMs)
	{
		if (proof == null || proof.maxSessionMinutes <= 0)
		{
			return null;
		}
		if (sessionLoginAtMs == UNKNOWN_LOGIN)
		{
			return new Check(Check.State.BAD, "Log out and back in (then under " + proof.maxSessionMinutes + " min)");
		}
		long minutes = Math.max(0, (nowMs - sessionLoginAtMs) / 60_000L);
		if (minutes > proof.maxSessionMinutes)
		{
			return new Check(Check.State.BAD, "Session " + describeMinutes(minutes) + ": relog (under "
				+ proof.maxSessionMinutes + " min)");
		}
		return new Check(Check.State.OK, "Fresh session: " + describeMinutes(minutes) + " of " + proof.maxSessionMinutes + " min");
	}

	/** The position requirement as the card shows it, or null when the spot has no pin to measure from. */
	static Check positionCheck(PluginConfigResponse.StartProof proof, Integer x, Integer y)
	{
		if (proof == null || proof.spot == null)
		{
			return null;
		}
		int away = distance(proof, x, y);
		if (away < 0)
		{
			return new Check(Check.State.UNKNOWN, "Position unknown until you're logged in");
		}
		if (away > proof.spot.radius)
		{
			return new Check(Check.State.BAD, away + " squares away (within " + proof.spot.radius + ")");
		}
		return new Check(Check.State.OK, "At the spot");
	}

	/**
	 * How long is left before the site stops asking for a shot, as a sentence fragment — or null
	 * when there is no deadline to quote (an older site that doesn't send one, or an unreadable
	 * stamp). The window closing is not a failure state: the ask simply expires, so this reads as a
	 * countdown rather than a threat.
	 */
	static String describeWindow(PluginConfigResponse.StartProof proof, long nowMs)
	{
		if (proof == null || proof.windowEndsAt == null || proof.windowEndsAt.isEmpty())
		{
			return null;
		}
		long endsMs;
		try
		{
			endsMs = java.time.Instant.parse(proof.windowEndsAt).toEpochMilli();
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
		long minutes = (endsMs - nowMs) / 60_000L;
		return minutes <= 0 ? null : describeMinutes(minutes);
	}

	/** "12 min" / "2h 05m" — a session age a player reads at a glance. */
	static String describeMinutes(long minutes)
	{
		if (minutes < 60)
		{
			return minutes + " min";
		}
		return (minutes / 60) + "h " + String.format("%02dm", minutes % 60);
	}
}

package com.anvil;

import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;

/**
 * Points the way to the starting shot's drawn spot while one is owed: the game's own hint arrow (over
 * the tile up close, on the minimap edge from afar) and a world-map pin that clamps to the map's edge
 * and jumps there on click. {@link #route} asks the Shortest Path plugin, when installed, for the
 * whole route; without it the message simply goes unheard.
 */
@Singleton
class StartSpotMarker
{
	private static final BufferedImage PIN = ImageUtil.resizeImage(
		ImageUtil.loadImageResource(StartSpotMarker.class, "/com/anvil/sidebar_icon.png"), 20, 20);

	private final Client client;
	private final WorldMapPointManager mapPoints;
	private final EventBus eventBus;

	private WorldPoint shown;
	private WorldMapPoint mapPoint;

	@Inject
	StartSpotMarker(Client client, WorldMapPointManager mapPoints, EventBus eventBus)
	{
		this.client = client;
		this.mapPoints = mapPoints;
		this.eventBus = eventBus;
	}

	/** The spot to mark, or null for none. Spots are drawn on the surface, so the plane is 0. */
	static WorldPoint target(PluginConfigResponse.StartProof proof)
	{
		return proof == null || proof.spot == null ? null : new WorldPoint(proof.spot.x, proof.spot.y, 0);
	}

	/**
	 * Client thread, every tick. Sets the arrow and pin once when the target appears or moves and takes
	 * them down when it goes, so a quest's own hint arrow is only ever replaced while a shot is owed.
	 */
	void update(WorldPoint target, String label)
	{
		if (Objects.equals(target, shown))
		{
			return;
		}
		clear();
		if (target == null)
		{
			return;
		}
		client.setHintArrow(target);
		mapPoint = WorldMapPoint.builder()
			.worldPoint(target)
			.image(PIN)
			.name("Anvil starting shot")
			.tooltip("Anvil starting shot" + (label != null ? ": " + label : ""))
			.snapToEdge(true)
			.jumpOnClick(true)
			.build();
		mapPoints.add(mapPoint);
		shown = target;
	}

	/** Client thread. Takes down our arrow (never someone else's) and our pin. */
	void clear()
	{
		if (shown != null && client.hasHintArrow() && shown.equals(client.getHintArrowPoint()))
		{
			client.clearHintArrow();
		}
		if (mapPoint != null)
		{
			mapPoints.remove(mapPoint);
			mapPoint = null;
		}
		shown = null;
	}

	/** Ask Shortest Path for a route to {@code target}. Client thread. */
	void route(WorldPoint target)
	{
		if (target != null)
		{
			eventBus.post(new PluginMessage("shortestpath", "path", Collections.singletonMap("target", target)));
		}
	}
}

package com.anvil;

/**
 * How long to wait before trying a failed push again.
 *
 * <p>The profile syncs run off a fixed 30s tick, so a push that keeps failing is a request every 30
 * seconds for as long as the player stays logged in — against a site that has already said no. That
 * is rude to a clan's server and pointless for the player: the two cases are "your site is down"
 * (which wants patience) and "your site doesn't accept this" (which wants stopping altogether).
 *
 * <p>This covers the first: doubling waits from 30s to a 10-minute ceiling, reset by any success.
 * The second is the caller's job — a permanent failure drops the batch instead of backing off.
 */
final class SyncBackoff
{
	static final long FIRST_MS = 30_000L;
	static final long MAX_MS = 600_000L;

	private final long firstMs;
	private final long maxMs;
	private long nextAttemptAt;
	private long waitMs;

	SyncBackoff()
	{
		this(FIRST_MS, MAX_MS);
	}

	SyncBackoff(long firstMs, long maxMs)
	{
		this.firstMs = firstMs;
		this.maxMs = maxMs;
	}

	/** Is a push allowed right now? True until something fails. */
	boolean ready(long now)
	{
		return now >= nextAttemptAt;
	}

	/** A push worked — back to normal cadence. */
	void onSuccess()
	{
		nextAttemptAt = 0;
		waitMs = 0;
	}

	/** A push failed for a reason that might clear on its own. Waits twice as long each time. */
	void onFailure(long now)
	{
		waitMs = waitMs == 0 ? firstMs : Math.min(maxMs, waitMs * 2);
		nextAttemptAt = now + waitMs;
	}

	/** Has anything failed since the last success? */
	boolean backingOff()
	{
		return waitMs != 0;
	}

	/** Seconds until the next attempt, for a log line that explains the silence. */
	long secondsUntilReady(long now)
	{
		return Math.max(0, (nextAttemptAt - now + 999) / 1000);
	}

	void reset()
	{
		onSuccess();
	}
}

package com.anvil;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.Executor;
import java.util.function.Consumer;
import java.util.function.IntSupplier;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;

import static com.anvil.PlayerCardView.header;
import static com.anvil.Ui.*;

/**
 * An event's Teams page: who is on which team, a page at a time ({@link EventRoster}).
 *
 * <p>Stateful on purpose, unlike the card views: the search field has to keep its caret and focus
 * while results arrive, so the panel mounts ONE of these per open page and leaves it alone, and only
 * the results area under the field is ever rebuilt. Every fetch runs on the interactive executor;
 * an answer that arrives after a newer request was made is dropped.</p>
 */
final class TeamsView extends JPanel
{
	interface Source
	{
		EventRoster fetch(int eventId, int teamId, String query, int page);
	}

	private static final Color YOU = ColorScheme.BRAND_ORANGE;
	private static final int SEARCH_DELAY_MS = 350;

	private final Source source;
	private final Executor executor;
	/** Resolves the event id off the EDT when the caller did not have it (the active board). */
	private final IntSupplier eventIdLookup;
	/** Opens a name in the Lookup tab; null when this site has no player cards. */
	private final Consumer<String> lookup;

	private int eventId;
	private int teamId;
	private int page = 1;
	/** The overview page to return to from a team. */
	private int overviewPage = 1;
	private String query = "";

	private EventRoster data;
	private boolean loading;
	private boolean failed;
	private int generation;
	private boolean settingSearch;

	private final JTextField search = new JTextField();
	private final JPanel results = new JPanel();
	private final Timer debounce;

	TeamsView(Source source, Executor executor, int eventId, IntSupplier eventIdLookup, Consumer<String> lookup)
	{
		this.source = source;
		this.executor = executor;
		this.eventId = eventId;
		this.eventIdLookup = eventIdLookup;
		this.lookup = lookup;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setAlignmentX(LEFT_ALIGNMENT);

		styleSearch(search);
		search.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		search.setToolTipText("Find a player on any team");
		JLabel hint = small("Search players", MUTED);
		JPanel searchRow = left(new JPanel(new BorderLayout(0, 2)));
		searchRow.setOpaque(false);
		searchRow.add(hint, BorderLayout.NORTH);
		searchRow.add(search, BorderLayout.CENTER);
		add(capH(searchRow));
		add(gap(8));

		debounce = new Timer(SEARCH_DELAY_MS, e ->
		{
			query = search.getText().trim();
			page = 1;
			load();
		});
		debounce.setRepeats(false);
		onEdit(search, () ->
		{
			if (!settingSearch)
			{
				debounce.restart();
			}
		});
		search.addActionListener(e ->
		{
			debounce.stop();
			query = search.getText().trim();
			page = 1;
			load();
		});

		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		results.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(left(results));

		load();
	}

	/** Leaving the page: nothing that arrives later may touch it. */
	void dispose()
	{
		debounce.stop();
		generation++;
	}

	// ---- Fetching ---------------------------------------------------------------------------------

	private void load()
	{
		final int mine = ++generation;
		final int wantTeam = teamId;
		final String wantQuery = query;
		final int wantPage = page;
		final int knownEvent = eventId;
		loading = true;
		renderResults();
		executor.execute(() ->
		{
			int id = knownEvent > 0 ? knownEvent : eventIdLookup.getAsInt();
			EventRoster r = id > 0 ? source.fetch(id, wantTeam, wantQuery, wantPage) : null;
			SwingUtilities.invokeLater(() ->
			{
				if (mine != generation)
				{
					return;
				}
				eventId = id;
				loading = false;
				failed = r == null;
				if (r != null)
				{
					data = r;
					page = Math.max(1, r.page);
				}
				renderResults();
			});
		});
	}

	private void openTeam(int id)
	{
		if (!query.isEmpty())
		{
			setSearch("");
		}
		else
		{
			overviewPage = page;
		}
		teamId = id;
		page = 1;
		load();
	}

	private void backToTeams()
	{
		teamId = 0;
		page = overviewPage;
		load();
	}

	private void goToPage(int p)
	{
		page = p;
		load();
	}

	private void setSearch(String text)
	{
		settingSearch = true;
		try
		{
			search.setText(text);
		}
		finally
		{
			settingSearch = false;
		}
		debounce.stop();
		query = text;
	}

	// ---- Rendering --------------------------------------------------------------------------------

	private void renderResults()
	{
		results.removeAll();
		if (data == null)
		{
			if (loading)
			{
				results.add(small("Loading teams…", MUTED));
			}
			else
			{
				results.add(small("Couldn't load the teams.", ColorScheme.PROGRESS_ERROR_COLOR));
				results.add(gap(6));
				results.add(AnvilSidebarPanel.fullWidthButton("Try again", "Load the teams again", this::load));
			}
			finish();
			return;
		}
		if (loading || failed)
		{
			results.add(small(loading ? "Updating…" : "Couldn't refresh — showing the last answer.",
				failed ? ColorScheme.PROGRESS_ERROR_COLOR : MUTED));
			results.add(gap(4));
		}

		if (data.is("members"))
		{
			renderMembers();
		}
		else if (data.is("search"))
		{
			renderSearch();
		}
		else if (data.is("players"))
		{
			renderPlayers();
		}
		else
		{
			renderTeams();
		}
		renderPager();
		finish();
	}

	private void finish()
	{
		results.revalidate();
		results.repaint();
	}

	private void renderTeams()
	{
		List<EventRoster.Team> teams = data.teams;
		if (teams == null || teams.isEmpty())
		{
			results.add(small(data.unplaced > 0 ? "Teams haven't been set yet." : "No teams yet.", MUTED));
			if (data.unplaced > 0)
			{
				results.add(small(count(data.unplaced, "player") + " signed up.", MUTED));
			}
			return;
		}
		EventRoster.Team yours = data.yourTeam;
		if (yours != null && teams.stream().noneMatch(t -> t.teamId == yours.teamId))
		{
			results.add(header("Your team", null));
			results.add(gap(3));
			results.add(teamRow(yours));
			results.add(gap(8));
		}
		results.add(header(count(data.total, "team"), data.unplaced > 0 ? data.unplaced + " not placed" : null));
		results.add(gap(3));
		for (EventRoster.Team t : teams)
		{
			results.add(teamRow(t));
			results.add(gap(2));
		}
	}

	private void renderPlayers()
	{
		List<EventRoster.Person> people = data.players;
		if (people == null || people.isEmpty())
		{
			results.add(small("Nobody has signed up yet.", MUTED));
			return;
		}
		EventRoster.Person you = data.you;
		if (you != null && people.stream().noneMatch(p -> p.you))
		{
			results.add(header("You", null));
			results.add(gap(3));
			results.add(personRow(you, true, false));
			results.add(gap(8));
		}
		results.add(header(count(data.total, "player"), null));
		results.add(gap(3));
		for (EventRoster.Person p : people)
		{
			results.add(personRow(p, true, false));
			results.add(gap(2));
		}
	}

	private void renderMembers()
	{
		EventRoster.Team t = data.team;
		JLabel back = small("‹ All teams", ColorScheme.LIGHT_GRAY_COLOR);
		hoverable(back, ColorScheme.DARK_GRAY_COLOR, this::backToTeams);
		results.add(back);
		results.add(gap(6));
		if (t != null)
		{
			JPanel card = block();
			JPanel title = row(6);
			title.add(swatch(t.color, 10), BorderLayout.WEST);
			title.add(title(t.name), BorderLayout.CENTER);
			card.add(capH(title));
			card.add(gap(3));
			card.add(small(teamLine(t), MUTED));
			results.add(capH(card));
			results.add(gap(8));
		}
		if (data.players == null || data.players.isEmpty())
		{
			results.add(small("Nobody on this team yet.", MUTED));
			return;
		}
		results.add(header("Members", null));
		results.add(gap(3));
		for (EventRoster.Person p : data.players)
		{
			results.add(personRow(p, false, false));
			results.add(gap(2));
		}
	}

	private void renderSearch()
	{
		List<EventRoster.Person> hits = data.players;
		if (hits == null || hits.isEmpty())
		{
			results.add(small("No players match \"" + data.query + "\".", MUTED));
			return;
		}
		results.add(header(count(data.total, "match", "matches"), null));
		results.add(gap(3));
		for (EventRoster.Person p : hits)
		{
			results.add(personRow(p, false, true));
			results.add(gap(2));
		}
	}

	private void renderPager()
	{
		if (data.pages <= 1)
		{
			return;
		}
		results.add(gap(6));
		JButton prev = AnvilSidebarPanel.flatButton("‹ Prev", "The previous page", () -> goToPage(data.page - 1));
		JButton next = AnvilSidebarPanel.flatButton("Next ›", "The next page", () -> goToPage(data.page + 1));
		prev.setEnabled(data.page > 1 && !loading);
		next.setEnabled(data.page < data.pages && !loading);
		JLabel where = small(data.page + " / " + data.pages, MUTED);
		where.setHorizontalAlignment(SwingConstants.CENTER);
		JPanel row = row(6);
		row.add(prev, BorderLayout.WEST);
		row.add(where, BorderLayout.CENTER);
		row.add(next, BorderLayout.EAST);
		results.add(capH(row));
	}

	// ---- Rows -------------------------------------------------------------------------------------

	private JPanel teamRow(EventRoster.Team t)
	{
		JPanel row = row(6);
		row.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		row.add(swatch(t.color, 8), BorderLayout.WEST);
		row.add(twoLines(small(t.name, t.yours ? YOU : Color.WHITE), small(teamLine(t), MUTED)), BorderLayout.CENTER);

		JLabel arrow = new JLabel("›");
		arrow.setForeground(MUTED);
		row.add(arrow, BorderLayout.EAST);
		row.setToolTipText(plainText(t.name) + " — see who's on it");
		hoverable(capH(row), ColorScheme.DARKER_GRAY_COLOR, () -> openTeam(t.teamId));
		return row;
	}

	/**
	 * A person: rank (when ranked), name, and a second line — their score in a ranking, their team in
	 * a search. Clicking the person looks them up; a search result's team line opens that team.
	 * Without player cards there is no Lookup, so a search result opens its team as before.
	 */
	private JPanel personRow(EventRoster.Person p, boolean ranked, boolean showTeam)
	{
		JPanel row = row(6);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

		if (ranked)
		{
			JLabel rank = small(p.rank == null ? "–" : "#" + p.rank, p.rank != null && p.rank <= 3 ? ColorScheme.BRAND_ORANGE : MUTED);
			rank.setPreferredSize(new Dimension(34, rank.getPreferredSize().height));
			row.add(rank, BorderLayout.WEST);
		}

		JPanel text = twoLines(small(p.name, p.you ? YOU : Color.WHITE), null);
		String second = showTeam
			? (p.teamName != null ? p.teamName : "Not on a team yet")
			: ranked ? p.score : null;
		boolean canLookUp = lookup != null && p.name != null && !p.name.isEmpty();
		if (second != null)
		{
			JLabel line = small(second, MUTED);
			if (showTeam && p.teamColor != null)
			{
				line.setIcon(swatchIcon(p.teamColor, 6));
				line.setIconTextGap(4);
			}
			if (showTeam && p.teamId != null && canLookUp)
			{
				// The row looks the person up, so their team gets its own way in.
				line.setText(plainText(second + " ›"));
				line.setToolTipText("Open " + plainText(p.teamName));
				onClick(line, () -> openTeam(p.teamId));
			}
			text.add(line, BorderLayout.SOUTH);
		}
		row.add(text, BorderLayout.CENTER);

		String tag = p.captain && p.you ? "Captain · you" : p.captain ? "Captain" : p.you ? "You" : null;
		if (tag != null)
		{
			row.add(small(tag, p.captain ? ColorScheme.BRAND_ORANGE : YOU), BorderLayout.EAST);
		}
		capH(row);
		if (canLookUp)
		{
			row.setToolTipText("Look up " + plainText(p.name));
			hoverable(row, ColorScheme.DARKER_GRAY_COLOR, () -> lookup.accept(p.name));
		}
		else if (showTeam && p.teamId != null)
		{
			row.setToolTipText("Open " + plainText(p.teamName));
			hoverable(row, ColorScheme.DARKER_GRAY_COLOR, () -> openTeam(p.teamId));
		}
		else
		{
			row.setOpaque(true);
			row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		}
		return row;
	}

	// ---- Bits -------------------------------------------------------------------------------------

	/** A name over its second line ({@code below} may be null, to be added later). */
	private static JPanel twoLines(JLabel top, JLabel below)
	{
		JPanel text = new JPanel(new BorderLayout());
		text.setOpaque(false);
		text.add(top, BorderLayout.NORTH);
		if (below != null)
		{
			text.add(below, BorderLayout.SOUTH);
		}
		return text;
	}

	/** "#2 · 12 tiles · 8 members" — what is known; the rank and score wait for the reveal. */
	static String teamLine(EventRoster.Team t)
	{
		StringBuilder s = new StringBuilder();
		if (t.rank != null)
		{
			s.append('#').append(t.rank).append(" · ");
		}
		if (t.score != null)
		{
			s.append(t.score).append(" · ");
		}
		return s.append(count(t.members, "member")).toString();
	}

	static String count(int n, String one)
	{
		return count(n, one, one + "s");
	}

	static String count(int n, String one, String many)
	{
		return String.format(Locale.ROOT, "%,d %s", n, n == 1 ? one : many);
	}

	/** A team's colour; the server stores "#rrggbb", and anything else reads as grey. */
	static Color teamColor(String hex)
	{
		if (hex != null && hex.matches("#[0-9a-fA-F]{6}"))
		{
			return new Color(Integer.parseInt(hex.substring(1), 16));
		}
		return MUTED;
	}

	private static Component swatch(String hex, int size)
	{
		Color c = teamColor(hex);
		JComponent dot = new JComponent()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				g.setColor(c);
				int y = (getHeight() - size) / 2;
				g.fillRect(0, Math.max(0, y), size, size);
			}
		};
		dot.setPreferredSize(new Dimension(size, size));
		return dot;
	}

	static javax.swing.Icon swatchIcon(String hex, int size)
	{
		Color c = teamColor(hex);
		return new javax.swing.Icon()
		{
			@Override
			public void paintIcon(Component comp, Graphics g, int x, int y)
			{
				g.setColor(c);
				g.fillRect(x, y, size, size);
			}

			@Override
			public int getIconWidth()
			{
				return size;
			}

			@Override
			public int getIconHeight()
			{
				return size;
			}
		};
	}
}

package com.anvil;

import com.google.gson.Gson;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.OptionalDouble;

/**
 * Pickpocket drop rarity, backed by the bundled thieving.json (plus a couple of hard-coded shards
 * the wiki doesn't express cleanly).
 * Adapted from Dink (pajlads/DinkPlugin), BSD-2-Clause — see THIRD_PARTY_NOTICES.md.
 */
@Singleton
public class ThievingService extends AbstractRarityService {

    @Inject
    ThievingService(Gson gson, ItemManager itemManager) {
        super("/thieving.json", 32, gson, itemManager);
    }

    @Override
    public OptionalDouble getRarity(String sourceName, int itemId, int quantity) {
        if (itemId == ItemID.BLOOD_SHARD) {
            // https://oldschool.runescape.wiki/w/Blood_shard#Item_sources
            return OptionalDouble.of(1.0 / 5000);
        }

        if (itemId == ItemID.PRIF_TELEPORT_SEED) {
            // https://oldschool.runescape.wiki/w/Enhanced_crystal_teleport_seed#Item_sources
            return OptionalDouble.of(1.0 / 1024);
        }

        return super.getRarity(sourceName, itemId, quantity);
    }
}

package com.anvil;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Tiles pinned from the sidebar as in-game widgets ("Track on screen"): one movable, resizable
 * overlay per tile showing every team's progress and each team's top contributors, read from
 * {@code GET /api/plugin/event/<id>/tile/<tileId>/progress} (site capability "tile-tracker").
 *
 * <p>Fetched only while something is pinned: on the plugin's 30s config tick, and a few seconds after
 * this account progresses a pinned tile, so your own kill shows without waiting a full poll. Pins
 * belong to one event. They can go up before it starts (the widget counts down, then goes live on the
 * first poll after the whistle) and are forgotten once the site says it's over.
 *
 * <p>A pin your team finishes shows "Done" for a moment and then takes itself down. A done tile can't be
 * pinned — the sidebar offers no button for it.
 */
@Singleton
public class TileTracker
{
	static final int MAX_PINS = 3;
	private static final String CFG_PINS = "trackedTiles";
	private static final Color GOLD = new Color(255, 215, 0);
	private static final int OTHER_TEAMS_SHOWN = 4;
	/** How long a just-finished pin keeps showing "Done" before it unpins (hidden on the next fetch after). */
	private static final long DONE_LINGER_MS = 10_000;

	private final OverlayManager overlayManager;
	private final ConfigManager configManager;
	private final BingoApiClient apiClient;

	/** tileId → its widget, in pin order. Guarded by {@code this}. */
	private final Map<Integer, Widget> pins = new LinkedHashMap<>();
	private int eventId;
	/**
	 * (tileId, site count) → what to show for your team: the plugin's own newer count when it has one,
	 * so a pinned tile moves on your kill. Identity until the plugin sets it.
	 */
	private volatile java.util.function.ToLongBiFunction<Integer, Long> shownProgress = (id, site) -> site;
	/**
	 * One panel holding every pin (the default) or a movable widget per pin. One panel can't end up
	 * with pins on top of each other, and is one thing to place; separate ones can be put anywhere.
	 */
	private boolean onePanel = true;
	private final Combined combined = new Combined();
	/**
	 * The pins as the frame draw sees them: replaced whole on every change, read without a lock.
	 * The shared panel renders on the client thread every frame, which must never wait on a lock.
	 */
	private volatile List<Widget> drawn = new ArrayList<>();

	@Inject
	TileTracker(OverlayManager overlayManager, ConfigManager configManager, BingoApiClient apiClient)
	{
		this.overlayManager = overlayManager;
		this.configManager = configManager;
		this.apiClient = apiClient;
	}

	void setShownProgress(java.util.function.ToLongBiFunction<Integer, Long> shown)
	{
		shownProgress = shown;
	}

	/** Switch between one panel and a widget per pin, moving whatever is pinned across. */
	synchronized void setOnePanel(boolean one)
	{
		if (one == onePanel)
		{
			return;
		}
		hideAll();
		onePanel = one;
		showAll();
	}

	private void hideAll()
	{
		overlayManager.remove(combined);
		for (Widget w : pins.values())
		{
			overlayManager.remove(w);
		}
	}

	private void showAll()
	{
		if (pins.isEmpty())
		{
			return;
		}
		if (onePanel)
		{
			overlayManager.add(combined);
		}
		else
		{
			for (Widget w : pins.values())
			{
				overlayManager.add(w);
			}
		}
	}

	private Widget removePin(int tileId)
	{
		Widget w = pins.remove(tileId);
		drawn = new ArrayList<>(pins.values());
		return w;
	}

	/** Take one pin's widget down, and the shared panel with the last one. */
	private void hide(Widget w)
	{
		overlayManager.remove(w);
		if (pins.isEmpty())
		{
			overlayManager.remove(combined);
		}
	}

	/** Restore the pins saved for the event in config ("eventId:tileId,tileId"). */
	synchronized void startUp()
	{
		String saved = configManager.getConfiguration("osrsbingo", CFG_PINS);
		if (saved == null || !saved.contains(":"))
		{
			return;
		}
		try
		{
			String[] parts = saved.split(":", 2);
			eventId = Integer.parseInt(parts[0]);
			for (String id : parts[1].split(","))
			{
				if (!id.isEmpty() && pins.size() < MAX_PINS)
				{
					add(Integer.parseInt(id));
				}
			}
		}
		catch (NumberFormatException e)
		{
			unpinAll();
		}
	}

	synchronized void shutDown()
	{
		hideAll();
		pins.clear();
		drawn = new ArrayList<>();
	}

	synchronized boolean isPinned(int eventId, int tileId)
	{
		return this.eventId == eventId && pins.containsKey(tileId);
	}

	synchronized boolean isFull(int eventId)
	{
		return this.eventId == eventId && pins.size() >= MAX_PINS;
	}

	/**
	 * Pin ({@code on}) or unpin — an explicit state, not a flip, so a button drawn before the pin took
	 * itself down (a finished tile) can't put it back up when clicked.
	 */
	synchronized void set(int eventId, int tileId, boolean on)
	{
		if (isPinned(eventId, tileId) != on)
		{
			toggle(eventId, tileId);
		}
	}

	/** Pin or unpin; pinning a tile from another event drops the old event's pins. */
	synchronized void toggle(int eventId, int tileId)
	{
		if (isPinned(eventId, tileId))
		{
			hide(removePin(tileId));
		}
		else
		{
			if (this.eventId != eventId)
			{
				unpinAll();
				this.eventId = eventId;
			}
			if (pins.size() >= MAX_PINS)
			{
				return;
			}
			// A done tile can't be pinned (the sidebar offers no button), so a pin that turns out done
			// on its first fetch was finished in between — it comes down like any other.
			add(tileId).keepWhenDone = false;
		}
		save();
	}

	/** The 30s tick: refetch every pin. Blocking; call off the client thread. */
	void poll()
	{
		List<Integer> ids;
		synchronized (this)
		{
			ids = new ArrayList<>(pins.keySet());
		}
		for (int id : ids)
		{
			refresh(id);
		}
	}

	/** Refetch one pinned tile (no-op when it isn't pinned). Blocking. */
	void refresh(int tileId)
	{
		Widget w;
		int event;
		synchronized (this)
		{
			w = pins.get(tileId);
			event = eventId;
		}
		if (w == null)
		{
			return;
		}
		Progress p = apiClient.fetchTileProgress(event, tileId);
		if (p != null && p.phase != null && p.phase.contains("ended"))
		{
			synchronized (this)
			{
				if (eventId == event)
				{
					unpinAll();
					save();
				}
			}
		}
		else if (p != null)
		{
			w.progress = p;
			if (finishedAndShown(w, p, System.currentTimeMillis()))
			{
				unpinDone(event, tileId, w);
			}
		}
	}

	/**
	 * Note this fetch on the widget and say whether it should now come down: the viewer's team has
	 * finished the tile, the pin isn't one made on an already-done tile, and "Done" has been up for
	 * {@link #DONE_LINGER_MS}.
	 */
	static boolean finishedAndShown(Widget w, Progress p, long now)
	{
		boolean done = ownTeamDone(p);
		if (w.keepWhenDone == null)
		{
			w.keepWhenDone = done;
		}
		if (!done || w.keepWhenDone)
		{
			return false;
		}
		if (w.doneSinceMs == 0)
		{
			w.doneSinceMs = now;
			return false;
		}
		return now - w.doneSinceMs >= DONE_LINGER_MS;
	}

	private static boolean ownTeamDone(Progress p)
	{
		if (p.teams == null || "upcoming".equals(p.phase))
		{
			return false;
		}
		for (Team t : p.teams)
		{
			if (t.mine)
			{
				return t.complete;
			}
		}
		return false;
	}

	private synchronized void unpinDone(int event, int tileId, Widget w)
	{
		if (eventId == event && pins.get(tileId) == w)
		{
			hide(removePin(tileId));
			save();
		}
	}

	/** The tiles pinned for this event, in pin order. */
	synchronized List<Integer> pinned(int eventId)
	{
		return this.eventId == eventId ? new ArrayList<>(pins.keySet()) : new ArrayList<>();
	}

	/** Take every pin for this event down. */
	synchronized void clear(int eventId)
	{
		if (this.eventId == eventId && !pins.isEmpty())
		{
			unpinAll();
			save();
		}
	}

	/** Asked from the client thread on every credited kill, so read off the snapshot, lock-free. */
	boolean tracks(int tileId)
	{
		for (Widget w : drawn)
		{
			if (w.tileId == tileId)
			{
				return true;
			}
		}
		return false;
	}

	private Widget add(int tileId)
	{
		int slot = 0;
		while (slotTaken(slot))
		{
			slot++;
		}
		Widget w = new Widget(slot, tileId, (id, site) -> shownProgress.applyAsLong(id, site));
		pins.put(tileId, w);
		drawn = new ArrayList<>(pins.values());
		if (onePanel)
		{
			overlayManager.remove(combined); // re-added, so it is never in twice
			overlayManager.add(combined);
		}
		else
		{
			overlayManager.add(w);
		}
		return w;
	}

	private boolean slotTaken(int slot)
	{
		return pins.values().stream().anyMatch(w -> w.slot == slot);
	}

	private void unpinAll()
	{
		shutDown();
		eventId = 0;
	}

	private void save()
	{
		if (pins.isEmpty())
		{
			configManager.unsetConfiguration("osrsbingo", CFG_PINS);
			return;
		}
		StringBuilder sb = new StringBuilder().append(eventId).append(':');
		for (int id : pins.keySet())
		{
			sb.append(id).append(',');
		}
		configManager.setConfiguration("osrsbingo", CFG_PINS, sb.substring(0, sb.length() - 1));
	}

	/** Every pin in one movable panel, in pin order, a blank line between them — name and bar each. */
	class Combined extends OverlayPanel
	{
		Combined()
		{
			setPosition(OverlayPosition.TOP_LEFT);
			setResizable(true);
			setMovable(true);
		}

		@Override
		public String getName()
		{
			return "AnvilTileTrackerPanel";
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			List<Widget> shown = drawn; // no lock on the frame path
			for (int i = 0; i < shown.size(); i++)
			{
				if (i > 0)
				{
					panelComponent.getChildren().add(LineComponent.builder().build());
				}
				shown.get(i).drawInto(panelComponent, true);
			}
			return shown.isEmpty() ? null : super.render(graphics);
		}
	}

	/** The site's answer (lib/tileTracker): the viewer's team first, then the rest by progress. */
	static class Progress
	{
		/** lib/eventTime's phase: "upcoming", "active", "ended" or "force-ended". */
		String phase;
		String startsAt;
		int tileId;
		String label;
		int points;
		int goal;
		String statType;
		List<Team> teams;
	}

	static class Team
	{
		int teamId;
		String name;
		String color;
		long current;
		boolean complete;
		boolean mine;
		List<Member> members;
	}

	static class Member
	{
		String name;
		long amount;
		boolean mine;
	}

	/**
	 * One pinned tile. Alt-drag moves it and drags its edge to resize, like any overlay; each slot has
	 * its own name so RuneLite remembers where every one was put.
	 */
	static class Widget extends OverlayPanel
	{
		final int slot;
		final int tileId;
		private final java.util.function.ToLongBiFunction<Integer, Long> shown;
		volatile Progress progress;
		/**
		 * Stay up after the team finishes? Pins restored from config start false, so a tile finished
		 * while the client was closed still comes down; a fresh pin is decided by its first fetch.
		 */
		Boolean keepWhenDone = false;
		/** When this pin was first seen done, or 0. */
		long doneSinceMs;

		Widget(int slot)
		{
			this(slot, 0, (id, site) -> site);
		}

		Widget(int slot, int tileId, java.util.function.ToLongBiFunction<Integer, Long> shown)
		{
			this.slot = slot;
			this.tileId = tileId;
			this.shown = shown;
			setPosition(OverlayPosition.TOP_LEFT);
			setResizable(true);
			setMovable(true);
		}

		@Override
		public String getName()
		{
			return "AnvilTileTracker" + slot;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			drawInto(panelComponent, false);
			return super.render(graphics);
		}

		/**
		 * This pin's lines, into its own widget or the shared panel. {@code compact} (the shared panel)
		 * is the tile's name and your team's bar only — three pins with every member and rival team
		 * each made a panel taller than the game view.
		 */
		void drawInto(PanelComponent panelComponent, boolean compact)
		{
			Progress p = progress;
			if (p == null || p.teams == null)
			{
				panelComponent.getChildren().add(TitleComponent.builder().text("Anvil: loading tile…").color(GOLD).build());
				return;
			}
			panelComponent.getChildren().add(TitleComponent.builder().text(p.label).color(GOLD).build());
			if ("upcoming".equals(p.phase))
			{
				// Nothing counts before the start, so there is no progress to draw yet — only when.
				panelComponent.getChildren().add(LineComponent.builder().left("Goal").right(fmt(p.goal)).build());
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Starts in").right(countdown(p.startsAt)).rightColor(Color.YELLOW).build());
				return;
			}
			int others = 0;
			for (Team t : p.teams)
			{
				if (t.mine)
				{
					renderOwnTeam(panelComponent, p, t, compact);
				}
				else if (!compact && others++ < OTHER_TEAMS_SHOWN)
				{
					panelComponent.getChildren().add(LineComponent.builder()
						.left(t.name)
						.leftColor(teamColor(t.color))
						.right(t.complete ? "Done" : fmt(t.current) + "/" + fmt(p.goal))
						.rightColor(t.complete ? Color.GREEN : Color.WHITE)
						.build());
				}
			}
		}

		private void renderOwnTeam(PanelComponent panelComponent, Progress p, Team t, boolean compact)
		{
			// Your own kill counts here the moment it happens; the fetch after the push confirms it.
			long current = t.complete ? t.current : shown.applyAsLong(tileId, t.current);
			long ahead = current - t.current;
			ProgressBarComponent bar = new ProgressBarComponent();
			bar.setMaximum(Math.max(1, p.goal));
			bar.setValue(t.complete ? p.goal : Math.min(current, p.goal));
			bar.setForegroundColor(t.complete ? new Color(0, 160, 0) : teamColor(t.color).darker());
			bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.FULL);
			panelComponent.getChildren().add(bar);
			if (compact || t.members == null)
			{
				return;
			}
			for (Member m : t.members)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(m.mine ? "You" : m.name)
					.leftColor(m.mine ? GOLD : Color.LIGHT_GRAY)
					.right(fmt(m.mine ? m.amount + Math.max(0, ahead) : m.amount))
					.build());
			}
		}

		private static Color teamColor(String hex)
		{
			try
			{
				return hex != null && hex.startsWith("#") ? Color.decode(hex) : Color.WHITE;
			}
			catch (NumberFormatException e)
			{
				return Color.WHITE;
			}
		}

		private static String countdown(String iso)
		{
			try
			{
				long s = Math.max(0, java.time.Duration.between(java.time.Instant.now(), java.time.Instant.parse(iso)).getSeconds());
				return s >= 3600 ? (s / 3600) + "h " + (s % 3600 / 60) + "m" : s >= 60 ? (s / 60) + "m " + (s % 60) + "s" : s + "s";
			}
			catch (RuntimeException e)
			{
				return "soon";
			}
		}

		private static String fmt(long n)
		{
			return n >= 10_000_000 ? (n / 1_000_000) + "M" : n >= 100_000 ? (n / 1_000) + "K" : String.format("%,d", n);
		}
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure, side-effect-free parsing for timed-clear tiles. Kept out of the plugin so the fragile,
 * game-version-specific bits (the exact completion strings) are unit-testable against real chat
 * messages without standing up RuneLite.
 *
 * Two responsibilities:
 *   1. {@link #parseDurationSeconds} — pull a clear time out of a "...duration: mm:ss(.ff)" /
 *      "...completion time: mm:ss" message (raids, gauntlet, colosseum, inferno, ToB/ToA).
 *   2. {@link #messageMatchesActivity} — decide whether a chat line identifies a given tile's
 *      activity, via a signature table. The identifying line is usually NOT the duration line
 *      (it's the adjacent "Your X kill/completion count is:" line), which is why the plugin
 *      correlates the two across a short window.
 *
 * Real message formats this was built against (verify/extend as Jagex changes them):
 *   Inferno      "Duration: 2:58.03 (new personal best)"  +  "Your TzKal-Zuk kill count is: 1."
 *   TzHaar-Ket-Rak "Challenge duration: 8:54.00"  +  "Your completion count for TzHaar-Ket-Rak's ... is: 1."
 *   Nightmare    "Team size: Solo Fight duration: 24:35"  +  "Your Nightmare kill count is: 11."
 *   Colosseum    "Wave 12 completed! Wave duration: 33:32.40"  +  "Your Sol Heredit kill count is: 100."
 *   CoX          "...your raid is complete! Duration: 15:39"  +  "Your completed Chambers of Xeric count is: 306."
 *   Boss timers  "Fight duration: 1:36 (new personal best)"  +  "Your <boss> kill count is: N." — the
 *                generic pair for every boss with an in-game kill timer (GWD, Zulrah, Vorkath, Hydra,
 *                Grotesque Guardians, Muspah, the DT2 four, Scurrius, Araxxor, Yama, etc.); the
 *                identity line names the boss, so the activity-name fallback covers them.
 *   Gauntlet     "Challenge duration: 10:24. Personal best: 7:59."  +  "Your Gauntlet completion count is: 45."
 *   Barracuda Trials (Sailing)
 *                "You have completed the Gwenith Glide and achieved the Marlin rank."
 *                + "Time: 6:04.20 (new personal best)."  +  "Your Gwenith Glide completion count is: 49"
 *                — no signature entry needed: both flanking lines name the trial, so the
 *                activity-name fallback matches tiles like "gwenith glide" / "tempor tantrum".
 */
final class TimedClearParser
{
	private TimedClearParser() {}

	// A duration keyword followed (within a few non-digits) by an [h:]mm:ss token. Fractional
	// ".ff" tails are intentionally left out of the capture group. Minutes go to three digits:
	// slow Inferno/Zuk clears print raw minutes past 99 ("Duration: 172:18. Personal best:
	// 134:52") rather than rolling into h:mm:ss. Keyword family, mirroring the formats
	// RuneLite's chat-commands PB tracker knows:
	//   duration        — "Fight/Wave/Challenge/Corrupted challenge duration:", raid "Duration:"
	//   completion time — ToB/ToA "total completion time:"
	//   time:           — Barracuda Trials "Time: 6:04.20", Sepulchre "Floor 5 time:"/"Overall
	//                     time:". Colon fused so countdown lines ("Time remaining: 5:00") don't
	//                     parse as a clear.
	//   subdued in      — Tempoross "Subdued in 6:32"
	// ToA's per-room / per-challenge sub-times also match "duration"/"time:" but are filtered
	// out before this (see RAID_SUBTIME) — they're not the raid clear time.
	private static final Pattern DURATION = Pattern.compile(
			"(?:duration|completion time|time:|subdued in)[^0-9]{0,16}((?:\\d{1,2}:)?\\d{1,3}:\\d{2})");

	// ToA reports several *sub*-times before the raid total, each carrying its own duration:
	//   "Challenge complete: The Wardens. Duration: 7:05"     — one room
	//   "Challenge time: 10:23"                                — one challenge
	//   "Tombs of Amascut: Expert Mode challenge completion time: 30:16" — rooms only, no overhead
	// None of these is the raid clear time — a "clear the raid under X" tile must use the
	// "… total completion time:" line (or CoX's "raid is complete! Duration:"). Crediting a room
	// duration was letting a 34:50 raid pass a 25-minute tile off its 7:05 final room. These are
	// the only "challenge …"/"… completion time" phrasings we reject; "Challenge duration:"
	// (Gauntlet / Corrupted Gauntlet / TzHaar-Ket-Rak) and "total completion time" are kept.
	private static final Pattern RAID_SUBTIME = Pattern.compile(
			"challenge complete|challenge time:|challenge completion time");

	// Lowercased activity (as configured on the tile) -> substrings that, if present in a nearby
	// chat line, identify that activity. The identifying line is typically the boss/raid
	// kill/completion-count message, which names the boss rather than the activity (e.g. Inferno
	// -> "tzkal-zuk", Colosseum -> "sol heredit"). Default signature is the activity name itself.
	private static final Map<String, List<String>> SIGNATURES = new HashMap<>();

	// {"activity|alias…", signature…}
	private static final String[][] SIGNATURE_TABLE = {
		{"inferno", "tzkal-zuk", "inferno"},
		{"fight caves", "tztok-jad", "fight cave"},
		// Raid-mode shorthands, so a mode tile matches however the admin phrased it. Colons and
		// spacing are already folded away by norm(), so we only enumerate the abbreviations here;
		// each pins the EXACT game count-line substring. A CM/HM/Expert tile must carry the full
		// mode text so a *base*-mode clear (whose line omits it) can't wrongly complete it — while a
		// base-raid tile keeps matching every harder mode (the mode line contains the base name).
		{"chambers of xeric|cox", "chambers of xeric"},
		{"cox cm|cox challenge mode|chambers of xeric cm", "chambers of xeric challenge mode"},
		{"theatre of blood|tob", "theatre of blood"},
		{"tob hm|tob hard mode|theatre of blood hm", "theatre of blood hard mode"},
		{"tombs of amascut|toa", "tombs of amascut"},
		{"toa em|toa expert|toa expert mode|tombs of amascut em", "tombs of amascut expert mode"},
		{"fortis colosseum|colosseum", "sol heredit", "colosseum"},
		{"the nightmare|nightmare", "nightmare"},
		{"phosani's nightmare", "phosani's nightmare"},
		{"tzhaar-ket-rak", "tzhaar-ket-rak"},
		// The completion line reads "Your Gauntlet completion count is: N" — it never contains
		// "the gauntlet", so a self-signature could never match. "your gauntlet completion" is
		// also Corrupted-safe: CG's line reads "your corrupted gauntlet completion count".
		{"the gauntlet", "your gauntlet completion", "the gauntlet"},
		{"corrupted gauntlet", "corrupted gauntlet"},
		// Bosses whose kill-count line drops the article ("Your Leviathan kill count is: N"),
		// so a tile named with "The …" would miss on the plain-substring fallback.
		{"the leviathan", "leviathan"},
		{"the whisperer", "whisperer"},
		{"the hueycoatl", "hueycoatl"},
		{"the royal titans", "royal titans"},
		// "nex" is too short for the contains-fallback — "next" in any nearby line would
		// false-match. Pin it to the real kill-count line.
		{"nex", "your nex kill count"},
		// Sailing Barracuda Trials: no chat line ever says "barracuda", so a generic
		// any-trial tile needs the three course names. Tiles naming a specific course
		// ("Gwenith Glide") ride the plain fallback — both flanking lines name it.
		{"barracuda trials|barracuda trial", "tempor tantrum", "jubbly jive", "gwenith glide"},
		// Hallowed Sepulchre full runs: no chat line says "sepulchre" either — the exit
		// message is "Overall time: 26:39.20", which both carries the time and identifies
		// the run. Floor tiles ("Floor 5") ride the fallback against "Floor 5 time: ...".
		{"hallowed sepulchre|sepulchre", "overall time"}
	};

	static
	{
		for (String[] row : SIGNATURE_TABLE)
		{
			for (String activity : row[0].split("\\|"))
			{
				SIGNATURES.put(activity, Arrays.asList(row).subList(1, row.length));
			}
		}
	}

	/** Returns the clear time in whole seconds, or null if the message carries no duration. */
	static Integer parseDurationSeconds(String message)
	{
		if (message == null)
		{
			return null;
		}
		String lower = message.toLowerCase();
		// A ToA per-room / per-challenge sub-time — never the raid clear time. Ignore it so a
		// slow raid can't pass a timed tile off a fast final room (see RAID_SUBTIME).
		if (RAID_SUBTIME.matcher(lower).find())
		{
			return null;
		}
		Matcher m = DURATION.matcher(lower);
		if (!m.find())
		{
			return null;
		}
		String[] p = m.group(1).split(":");
		try
		{
			int s = p.length == 3
					? Integer.parseInt(p[0]) * 3600 + Integer.parseInt(p[1]) * 60 + Integer.parseInt(p[2])
					: Integer.parseInt(p[0]) * 60 + Integer.parseInt(p[1]);
			return s > 0 ? s : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	static List<String> signaturesFor(String activity)
	{
		String a = norm(activity);
		List<String> s = SIGNATURES.get(a);
		if (s != null)
		{
			return s;
		}
		return a.isEmpty() ? Collections.emptyList() : Collections.singletonList(a);
	}

	/**
	 * Folds the punctuation/spacing admins add inconsistently so an activity string still matches the
	 * game's count line. Colons especially: the game writes CoX Challenge Mode with NO colon, yet
	 * "Chambers of Xeric: Challenge Mode" is the natural way to type it, and ToB/ToA modes DO carry a
	 * colon — dropping it on BOTH sides of the compare makes colons irrelevant either way.
	 */
	static String norm(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.toLowerCase(java.util.Locale.ROOT).replace(':', ' ').replaceAll("\\s+", " ").trim();
	}

	/** True when {@code message} contains any of the activity's identifying signatures. */
	static boolean messageMatchesActivity(String message, String activity)
	{
		if (message == null)
		{
			return false;
		}
		String nmsg = norm(message);
		for (String sig : signaturesFor(activity))
		{
			if (nmsg.contains(norm(sig)))
			{
				return true;
			}
		}
		return false;
	}

	static String formatClock(int totalSeconds)
	{
		int mm = totalSeconds / 60;
		int ss = totalSeconds % 60;
		return mm + ":" + (ss < 10 ? "0" + ss : String.valueOf(ss));
	}

	// ── Barracuda Trials (Sailing) rank tiles ──────────────────────────────────────────────────────
	// Each course awards a rank by time, but the three ranks are SEPARATE challenges (different routes,
	// each with its own PB) — so a rank tile must match the EXACT rank the game reports, never a time
	// cap (a Shark run is not just a slow Marlin run). The completion line names both:
	//   "You have completed the Gwenith Glide and achieved the Marlin rank."
	private static final String[] TRIAL_COURSES = { "tempor tantrum", "jubbly jive", "gwenith glide" };
	private static final String[] TRIAL_RANKS = { "swordfish", "shark", "marlin" };
	private static final Pattern TRIAL_COMPLETION = Pattern.compile("completed the (.+?) and achieved the (\\w+) rank");

	/** {course, rank} from a Barracuda Trials completion line, or null if this line isn't one. */
	static String[] parseTrialCompletion(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = TRIAL_COMPLETION.matcher(message.toLowerCase());
		if (!m.find())
		{
			return null;
		}
		String course = norm(m.group(1));
		String rank = m.group(2);
		for (String c : TRIAL_COURSES)
		{
			if (course.endsWith(c))
			{
				for (String r : TRIAL_RANKS)
				{
					if (rank.equals(r))
					{
						return new String[]{ c, r };
					}
				}
			}
		}
		return null;
	}

	/** {course, rank} a tile's activity targets (e.g. "Gwenith Glide — Marlin"), or null if it's not a rank tile. */
	static String[] trialTileTarget(String activity)
	{
		String a = norm(activity);
		if (a.isEmpty())
		{
			return null;
		}
		for (String r : TRIAL_RANKS)
		{
			if (a.endsWith(" " + r))
			{
				String course = a.substring(0, a.length() - r.length()).replaceAll("[^a-z]+$", "");
				for (String c : TRIAL_COURSES)
				{
					if (course.equals(c) || course.endsWith(c))
					{
						return new String[]{ c, r };
					}
				}
			}
		}
		return null;
	}
}

package com.anvil;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JProgressBar;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The side panel's shared Swing pieces — the labels, rows, cards and click wiring every view builds
 * the same way, so the sidebar and the card views can't drift apart in how they look.
 */
final class Ui
{
	// FontManager hands out the same static instances every call, so holding them changes nothing.
	static final Font SMALL = FontManager.getRunescapeSmallFont();
	static final Font REGULAR = FontManager.getRunescapeFont();
	static final Font BOLD = FontManager.getRunescapeBoldFont();

	/** Secondary text: counts, hints, the quieter half of a row. */
	static final Color MUTED = new Color(0x98_98_98);

	private Ui()
	{
	}

	/**
	 * Neutralize a site-supplied string for Swing. A {@link JLabel}/{@link javax.swing.JToolTip} renders as
	 * HTML when its text begins (ignoring leading whitespace, case-insensitive) with {@code <html}, so an
	 * untrusted clan/tile/activity name could inject markup. Such strings get their markup chars escaped so they
	 * render only as literal text; ordinary strings pass through. An explicit sanitize rather than reliance on
	 * {@code html.disable}; every server-supplied field the panel renders routes through here.
	 *
	 * <p>Use {@link #esc} instead when the string is being placed INSIDE markup we are building: there the
	 * leading-{@code <html} test does not apply and every occurrence has to be escaped.</p>
	 */
	static String plainText(String s)
	{
		if (s == null)
		{
			return "";
		}
		int i = 0;
		while (i < s.length() && Character.isWhitespace(s.charAt(i)))
		{
			i++;
		}
		return s.regionMatches(true, i, "<html", 0, 5) ? esc(s) : s;
	}

	/** Escape markup characters for text placed inside HTML we build ourselves. */
	static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** {@code html} wrapped to {@code widthPt} so a long line breaks instead of clipping at the panel's edge. */
	static String wrapHtml(String html, int widthPt)
	{
		return "<html><body style='width:" + widthPt + "pt'>" + html + "</body></html>";
	}

	/** A label in {@code font} and {@code color}, its text sanitized ({@link #plainText}). */
	static JLabel label(String text, Font font, Color color)
	{
		JLabel l = new JLabel(plainText(text));
		l.setFont(font);
		l.setForeground(color);
		return l;
	}

	static JLabel small(String text, Color color)
	{
		return label(text, SMALL, color);
	}

	static JLabel title(String text)
	{
		return label(text, BOLD, Color.WHITE);
	}

	/**
	 * Cap a component's height at what it wants right now, so a vertical BoxLayout stops stretching it.
	 * Call once it's filled — the cap is the preferred height at the time of the call.
	 */
	static <T extends JComponent> T capH(T c)
	{
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		return c;
	}

	static <T extends JComponent> T left(T c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		return c;
	}

	/** A hand cursor and a click that runs {@code action}. */
	static <T extends JComponent> T onClick(T c, Runnable action)
	{
		c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		c.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				action.run();
			}
		});
		return c;
	}

	/** Lights up under the mouse and does {@code onClick} — so a row or tile says it can be opened. */
	static void hoverable(JComponent c, Color base, Runnable onClick)
	{
		c.setOpaque(true);
		c.setBackground(base);
		onClick(c, onClick).addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				c.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				c.setBackground(base);
			}
		});
	}

	/** A left-aligned vertical stack on the panel background. */
	static JPanel column()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return left(p);
	}

	/** A {@link #column} as a card: the darker surface with an 8px inset. */
	static JPanel block()
	{
		JPanel p = column();
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		return p;
	}

	/** A transparent, left-aligned BorderLayout row with {@code hgap} between its parts. */
	static JPanel row(int hgap)
	{
		JPanel p = new JPanel(new BorderLayout(hgap, 0));
		p.setOpaque(false);
		return left(p);
	}

	static Component gap(int h)
	{
		return Box.createVerticalStrut(h);
	}

	/** The search fields' look: white text and caret on the darker surface, an orange selection. */
	static void styleSearch(javax.swing.JTextField f)
	{
		f.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		f.setForeground(Color.WHITE);
		f.setCaretColor(Color.WHITE);
		f.setSelectionColor(ColorScheme.BRAND_ORANGE);
		f.setSelectedTextColor(Color.BLACK);
		f.setFont(REGULAR);
	}

	/** Runs {@code changed} on every edit of the field's text. */
	static void onEdit(javax.swing.text.JTextComponent f, Runnable changed)
	{
		f.getDocument().addDocumentListener(new javax.swing.event.DocumentListener()
		{
			@Override
			public void insertUpdate(javax.swing.event.DocumentEvent e)
			{
				changed.run();
			}

			@Override
			public void removeUpdate(javax.swing.event.DocumentEvent e)
			{
				changed.run();
			}

			@Override
			public void changedUpdate(javax.swing.event.DocumentEvent e)
			{
				changed.run();
			}
		});
	}

	/** The panel's flat 0–100 progress bar: no text, no border, {@code h} px tall. */
	static JProgressBar bar(int percent, Color fg, Color bg, int h)
	{
		JProgressBar bar = new JProgressBar(0, 100);
		bar.setValue(percent);
		bar.setStringPainted(false);
		bar.setBorderPainted(false);
		bar.setForeground(fg);
		bar.setBackground(bg);
		bar.setPreferredSize(new Dimension(0, h));
		return bar;
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Where an account sits in a boss's vestige rotation.
 *
 * <p>The DT2 bosses don't hand out their vestige at random: rolls of the unique table go
 * non-vestige, non-vestige, VESTIGE. So counting uniques since the last vestige tells a player
 * something they can act on — "that's roll 2, the next unique is the vestige" — which is worth far
 * more than another "you got a Virtus mask" line. The roll tables themselves (which items count,
 * which one is the vestige, how long the cycle is) come from the server, so a game change is an
 * edit there rather than a plugin release.
 *
 * <p>Honesty about what we can know: the cycle is account state on Jagex's side, and this plugin
 * only sees drops it was running for. A count is therefore ESTIMATED until a vestige is actually
 * observed — after that the cycle is anchored and the count is EXACT. The estimate is still worth
 * showing (it's right whenever the player has been running the plugin), it just says so.
 *
 * <p>RuneLite-free so it can be unit-tested; {@link AnvilPlugin} owns persistence.
 */
final class VestigeRolls
{
	/** One boss's cycle state. */
	static final class State
	{
		/** Rolls seen since the last vestige — 0 means "a vestige is 3 rolls away". */
		final int rolls;
		/** True once a vestige has been observed, which anchors the cycle. */
		final boolean exact;

		State(int rolls, boolean exact)
		{
			this.rolls = rolls;
			this.exact = exact;
		}
	}

	/** What a drop did to the cycle, and what to say about it. */
	static final class Result
	{
		final State state;
		/** True when this drop WAS the vestige. */
		final boolean vestige;
		/** True when the next unique from this boss is guaranteed to be the vestige. */
		final boolean vestigeNext;
		/** One line for chat and the drop post, or null when there's nothing worth saying. */
		final String line;

		Result(State state, boolean vestige, boolean vestigeNext, String line)
		{
			this.state = state;
			this.vestige = vestige;
			this.vestigeNext = vestigeNext;
			this.line = line;
		}
	}

	private final Map<String, State> byBoss = new HashMap<>();

	static String key(String boss)
	{
		return boss == null ? "" : boss.trim().toLowerCase(Locale.ROOT);
	}

	State get(String boss)
	{
		return byBoss.getOrDefault(key(boss), new State(0, false));
	}

	void put(String boss, State state)
	{
		byBoss.put(key(boss), state);
	}

	/**
	 * Fold one unique-table drop into the boss's cycle. Returns null when the item isn't part of
	 * this boss's roll table (nothing to count) or the table is unusable.
	 */
	Result record(PluginConfigResponse.RollTable table, int itemId)
	{
		if (table == null || table.rollItemIds == null || !table.rollItemIds.contains(itemId))
		{
			return null;
		}
		int cycle = Math.max(2, table.rollsPerVestige);
		State was = get(table.boss);
		Result r = advance(was, itemId == table.vestigeItemId, cycle, table.vestigeName);
		put(table.boss, r.state);
		return r;
	}

	/**
	 * The rule, in one place: a vestige resets the cycle and anchors it; anything else advances it.
	 * A non-vestige arriving where the vestige was due means our count was off (drops taken while
	 * the plugin wasn't watching) — start the cycle over from this drop and stop claiming exact.
	 */
	static Result advance(State was, boolean isVestige, int rollsPerVestige, String vestigeName)
	{
		String vestige = vestigeName == null || vestigeName.isEmpty() ? "vestige" : vestigeName;
		if (isVestige)
		{
			return new Result(new State(0, true), true, false,
				vestige + "! The cycle resets — the next one is " + rollsPerVestige + " rolls away.");
		}

		int next = was.rolls + 1;
		if (next >= rollsPerVestige)
		{
			// We thought the vestige was due and it wasn't: the count was wrong, not the game.
			return new Result(new State(1, false), false, false,
				"Roll 1 of " + rollsPerVestige + " (estimated — the count was off, re-anchoring)");
		}

		boolean vestigeNext = next == rollsPerVestige - 1;
		String line = "Roll " + next + " of " + rollsPerVestige
			+ (vestigeNext ? " — the next unique is the " + vestige + "!" : "")
			+ (was.exact ? "" : " (estimated)");
		return new Result(new State(next, was.exact), false, vestigeNext, line);
	}

	/** Serialised as "boss=rolls:exact;…" for the RuneLite config, so the cycle survives a restart. */
	String serialise()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<String, State> e : byBoss.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(e.getKey()).append('=').append(e.getValue().rolls).append(':').append(e.getValue().exact ? 1 : 0);
		}
		return sb.toString();
	}

	static VestigeRolls parse(String raw)
	{
		VestigeRolls out = new VestigeRolls();
		if (raw == null || raw.trim().isEmpty())
		{
			return out;
		}
		for (String part : raw.split(";"))
		{
			String[] kv = part.split("=", 2);
			if (kv.length != 2)
			{
				continue;
			}
			String[] v = kv[1].split(":", 2);
			try
			{
				int rolls = Integer.parseInt(v[0].trim());
				boolean exact = v.length > 1 && "1".equals(v[1].trim());
				out.byBoss.put(key(kv[0]), new State(Math.max(0, rolls), exact));
			}
			catch (NumberFormatException ignored)
			{
				// A corrupted entry just loses that boss's count — it re-estimates from the next drop.
			}
		}
		return out;
	}
}

