	/** A client that serves a canned leaderboard offline and counts the reads (for the throttle test). */
	private static final class StubWeeklyClient extends BingoApiClient
	{
		final List<Integer> reads = new ArrayList<>();
		final WeeklyLeaderboard board;

		StubWeeklyClient(WeeklyLeaderboard board)
		{
			super(new Gson(), new OkHttpClient());
			this.board = board;
		}

		@Override
		public WeeklyLeaderboard fetchWeeklyLeaderboard(Integer competitionId)
		{
			reads.add(competitionId);
			return board;
		}
	}

	private static BingoApiClient.LeaderboardEntry entry(int rank, String rsn, long gained)
	{
		BingoApiClient.LeaderboardEntry e = new BingoApiClient.LeaderboardEntry();
		e.rank = rank;
		e.rsn = rsn;
		e.gained = gained;
		return e;
	}

	/** A 12-deep board with the caller sitting at #12, below the sidebar's top-10 cut. */
	private static BingoApiClient.WeeklyLeaderboard deepBoard()
	{
		BingoApiClient.WeeklyLeaderboard lb = new BingoApiClient.WeeklyLeaderboard();
		lb.total = 30;
		lb.entries = new ArrayList<>();
		for (int i = 1; i <= 11; i++)
		{
			lb.entries.add(entry(i, "Player " + i, 1_000_000L - i));
		}
		// OSRS display names carry non-breaking spaces — the "you" match must see through that.
		lb.entries.add(entry(12, "Ahmed Two", 4200));
		lb.competition = new BingoApiClient.WeeklyComp();
		return lb;
	}

	@Test
	public void standingsFoldInTheCallersRowEvenBelowTheCut() throws Exception
	{
		PluginConfigResponse cfg = withSchedule(new PluginConfigResponse(),
			weekly(7, "Mining Madness", "skill", "mining", "active"));
		StubWeeklyClient client = new StubWeeklyClient(deepBoard());
		AnvilSidebarDataSource ds = new AnvilSidebarDataSource(() -> cfg, client,
			java.util.Collections::emptyMap, () -> "ahmed two");

		ConnectionView.WeeklyView w = ds.fetch(false).weeklies.get(0);
		assertEquals(12, w.yourRank);
		assertEquals(4200, w.yourGained);
		assertEquals(30, w.participants);
		// Top 10 + the caller's own out-of-view row, and only that row is flagged as theirs.
		assertEquals(11, w.top.size());
		assertEquals(12, w.top.get(10).rank);
		assertTrue(w.top.get(10).self);
		assertFalse(w.top.get(0).self);
	}

	@Test
	public void standingsAreThrottledAcrossPollsButRefreshForcesARead() throws Exception
	{
		PluginConfigResponse cfg = withSchedule(new PluginConfigResponse(),
			weekly(7, "Mining Madness", "skill", "mining", "active"));
		StubWeeklyClient client = new StubWeeklyClient(deepBoard());
		AnvilSidebarDataSource ds = new AnvilSidebarDataSource(() -> cfg, client,
			java.util.Collections::emptyMap, () -> null);

		ds.fetch(false);   // first read
		ds.fetch(false);   // 15 s poll — must reuse the cached board
		ds.fetch(false);
		assertEquals(1, client.reads.size());

		ds.fetch(true); // the member clicked Refresh — read now
		assertEquals(2, client.reads.size());
		// The cached standings survive the throttled polls, so the card never goes blank between reads.
		assertEquals(30, ds.fetch(false).weeklies.get(0).participants);
		assertEquals(2, client.reads.size());
	}

	@Test
	public void anUpcomingWeeklyIsAnnouncedButNeverRead() throws Exception
	{
		PluginConfigResponse cfg = withSchedule(eventConfig(),
			weekly(9, "Next week's comp", "skill", "fishing", "upcoming"));
		StubWeeklyClient client = new StubWeeklyClient(deepBoard());
		AnvilSidebarDataSource ds = new AnvilSidebarDataSource(() -> cfg, client,
			java.util.Collections::emptyMap, () -> "ahmed two");

		ConnectionView.WeeklyView w = ds.fetch(false).weeklies.get(0);
		assertTrue(w.upcoming);
		// Nothing has happened in it yet, so there's no leaderboard worth a request.
		assertTrue(client.reads.isEmpty());
		assertTrue(w.top.isEmpty());
		assertEquals(0, w.yourRank);
	}

	@Test
	public void noWeekliesAtAllYieldsNoWeeklyEvents() throws Exception
	{
		assertTrue(newSource(AnvilSidebarDataSourceTest::eventConfig)
			.fetch(false).weeklies.isEmpty());
	}

	@Test
	public void otherAndUpcomingBingosRideAlongWithoutYourOwn() throws Exception
	{
		PluginConfigResponse cfg = eventConfig();   // the caller's own event is id 5
		cfg.schedule = new BingoApiClient.ScheduleResponse();
		cfg.schedule.bingos = new ArrayList<>(Arrays.asList(
			bingo(9, "Autumn Bingo", "upcoming", "2026-09-01T00:00:00Z"),
			bingo(5, "Summer Bingo", "active", "2026-07-01T00:00:00Z"),   // the caller's own board
			bingo(6, "Someone else's", "active", "2026-07-20T00:00:00Z")));

		List<ConnectionView.ScheduledView> scheduled = newSource(() -> cfg).fetch(false).scheduled;
		// Own event dropped (the board card IS that event); live first, then soonest upcoming.
		assertEquals(2, scheduled.size());
		assertEquals(6, scheduled.get(0).id);
		assertTrue(scheduled.get(0).live);
		assertEquals(9, scheduled.get(1).id);
		assertFalse(scheduled.get(1).live);
	}

	@Test
	public void eventEndingResetsToEmpty() throws Exception
	{
		PluginConfigResponse cfg = eventConfig();
		final PluginConfigResponse[] holder = { cfg };
		AnvilSidebarDataSource ds = newSource(() -> holder[0]);

		assertNotNull(ds.fetch(false));
		holder[0] = new PluginConfigResponse();      // event ended
		// Post-event the home still renders — as the board-less stub card, not an empty sidebar.
		ConnectionView after = ds.fetch(false);
		assertEquals(0, after.tilesTotal);
		assertTrue(after.nearestTiles.isEmpty());
	}
}

package com.anvil;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/** The shared request helpers in BingoApiClient, driven through a canned-response interceptor. */
public class ApiClientHttpTest
{
	private final List<Request> seen = new ArrayList<>();
	private final List<String> bodies = new ArrayList<>();
	private int code = 200;
	private String reply = "{}";
	private String etag;

	private BingoApiClient client()
	{
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			Request r = chain.request();
			seen.add(r);
			Buffer b = new Buffer();
			if (r.body() != null)
			{
				r.body().writeTo(b);
			}
			bodies.add(b.readUtf8());
			Response.Builder rb = new Response.Builder().request(r).protocol(Protocol.HTTP_1_1).code(code).message("x")
				.body(ResponseBody.create(MediaType.parse("application/json"), reply));
			if (etag != null)
			{
				rb.header("ETag", etag);
			}
			return rb.build();
		}).build();
		BingoApiClient c = new BingoApiClient(new Gson(), http);
		c.configure("tok");
		return c;
	}

	@Test
	public void conditionalGetReusesTheCachedBodyOn304() throws IOException
	{
		BingoApiClient c = client();
		etag = "\"v1\"";
		reply = "{\"clanName\":\"Foo\"}";
		PluginConfigResponse first = c.fetchConfig();
		assertEquals("Foo", first.clanName);
		assertNull(seen.get(0).header("If-None-Match"));
		code = 304;
		assertSame(first, c.fetchConfig());
		assertEquals("\"v1\"", seen.get(1).header("If-None-Match"));
	}

	@Test
	public void configFetch404IsTheNoClanState()
	{
		BingoApiClient c = client();
		code = 404;
		try
		{
			c.fetchConfig();
			fail();
		}
		catch (IOException e)
		{
			assertEquals("Config fetch failed: HTTP 404", e.getMessage());
		}
		assertTrue(c.signedInWithoutClan());
		code = 500;
		assertNull(c.fetchBoard());
	}

	@Test
	public void statPushesShareOneShapeAndPlainErrors() throws IOException
	{
		BingoApiClient c = client();
		Map<String, Integer> kc = new LinkedHashMap<>();
		kc.put("Zulrah", 5);
		kc.put(null, 1);
		c.submitStatKc(kc);
		assertEquals("{\"stats\":[{\"name\":\"Zulrah\",\"kc\":5}]}", bodies.get(0));
		c.submitStatXp(Collections.singletonMap("mining", 10));
		assertEquals("{\"skills\":[{\"name\":\"mining\",\"xp\":10}]}", bodies.get(1));
		// A 4xx the site will always refuse is permanent, so CoalescedPush drops the batch instead of
		// resending it forever; a 401 (fired before X-RSN was stamped at login) stays retryable.
		code = 400;
		reply = "";
		try
		{
			c.submitStatActivities(Collections.singletonMap("cluesElite", 3));
			fail();
		}
		catch (BingoApiClient.PermanentSubmissionException e)
		{
			assertEquals("Activity push failed: HTTP 400 — no body", e.getMessage());
		}
		code = 401;
		try
		{
			c.submitStatXp(Collections.singletonMap("mining", 11));
			fail();
		}
		catch (BingoApiClient.PermanentSubmissionException e)
		{
			fail("a 401 at login clears once X-RSN is stamped");
		}
		catch (IOException e)
		{
			assertEquals("Skill XP push failed: HTTP 401 — no body", e.getMessage());
		}
	}

	@Test
	public void submissionsAreClassified()
	{
		BingoApiClient c = client();
		code = 409;
		reply = "{\"error\":\"done\"}";
		try
		{
			c.submitTimed(1, 2, 3, 60, "u", "n", 4);
			fail();
		}
		catch (BingoApiClient.PermanentSubmissionException e)
		{
			assertEquals("Timed submission failed: HTTP 409 — {\"error\":\"done\"}", e.getMessage());
		}
		catch (IOException e)
		{
			fail("4xx is permanent");
		}
		assertTrue(bodies.get(0).contains("\"durationSeconds\":60"));
		assertTrue(bodies.get(0).contains("\"amount\":1"));
	}

	@Test
	public void wholeLogPushSpeaksToPeople() throws IOException
	{
		BingoApiClient c = client();
		reply = "{\"added\":2}";
		Map<Integer, Integer> items = new LinkedHashMap<>();
		items.put(4151, 1);
		assertEquals(2, c.submitClogItems(items).added);
		assertEquals("{\"items\":[{\"id\":4151,\"q\":1}]}", bodies.get(0));
		code = 429;
		reply = "{\"error\":\"Slow down\",\"retryAfterMs\":49445}";
		try
		{
			c.submitClogItems(items);
			fail();
		}
		catch (BingoApiClient.RateLimitedException e)
		{
			assertEquals("Slow down", e.getMessage());
			assertEquals(49445, e.retryAfterMs);
		}
		code = 200;
		reply = "not json";
		assertEquals(0, c.submitClogItems(items).added);
	}

	@Test
	public void publicReadsCarryOnlyTheToken()
	{
		BingoApiClient c = client();
		c.setCurrentRsn("Zezima");
		reply = "{\"clans\":[]}";
		assertFalse(c.lookupClans("foo") == null);
		assertNull("lookups are anonymous", seen.get(0).header("Authorization"));
		code = 404;
		assertTrue(c.fetchPlayerCard("Zezima").notFound);
		code = 503;
		BingoApiClient.PlayerCardResult busy = c.fetchPlayerCard("Zezima");
		assertTrue("hiscores budget busy, not 'not found'", busy.busy);
		assertFalse(busy.notFound);
		code = 404;
		assertEquals("Bearer tok", seen.get(1).header("Authorization"));
		assertNull(seen.get(1).header("X-RSN"));
	}

	@Test
	public void progressPushKeepsItsWireShape() throws IOException
	{
		BingoApiClient c = client();
		Map<String, Integer> progress = new LinkedHashMap<>();
		progress.put("questPoints", 300);
		progress.put(AccountProgress.ACCOUNT_TYPE_KEY, 1);
		Map<Integer, Integer> varps = new LinkedHashMap<>();
		varps.put(3116, 7);
		c.submitProgress(progress, "quest", Collections.singletonList(new AccountProgress.Item(5, "Cook's Assistant", 2)), varps, 40);
		assertEquals("{\"progress\":[{\"key\":\"questPoints\",\"value\":300}],\"accountType\":1,"
			+ "\"items\":[{\"category\":\"quest\",\"items\":[{\"id\":5,\"name\":\"Cook's Assistant\",\"state\":2}]}],"
			+ "\"caVarps\":{\"3116\":7},\"caPoints\":40}", bodies.get(0));
	}
}

