package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * Chat styling comes off before anything is parsed — in BOTH the forms the game uses.
 *
 * <p>The angle-bracket form (RuneLite's {@code <col=…>}) was always stripped. The other is Jagex's
 * older {@code @tag@} colour codes, which now include named ones sitting inline with the text: a
 * Combat Achievement line arrives as "…combat task: {@code @ach_comp@}Phantom Muspah Speed-Chaser."
 * That code rode along into the task name, so the tile matcher looked for a task nothing is called,
 * the Discord title read "@ach_comp@Phantom Muspah Speed-Chaser", and the wiki link it builds
 * pointed at a page that does not exist.
 */
public class ChatTagStripTest
{
	@Test
	public void stripsBothStylingForms()
	{
		assertEquals("Whack-a-Mole", AnvilPlugin.stripChatTags("<col=ff0000>Whack-a-Mole</col>"));
		assertEquals("Whack-a-Mole", AnvilPlugin.stripChatTags("@red@Whack-a-Mole@whi@"));
		assertEquals("Whack-a-Mole", AnvilPlugin.stripChatTags("@ach_comp@<col=ff0000>Whack-a-Mole</col>"));
		assertEquals("", AnvilPlugin.stripChatTags(null));
	}

	@Test
	public void leavesOrdinaryTextAlone()
	{
		// One @ is not a code — it takes a closing one, close behind, to be styling.
		assertEquals("me@home", AnvilPlugin.stripChatTags("me@home"));
		assertEquals("Phantom Muspah Speed-Chaser", AnvilPlugin.stripChatTags("Phantom Muspah Speed-Chaser"));
	}

	@Test
	public void aCombatTaskLineParsesToTheTaskNameAlone()
	{
		// The exact shape observed in game (the post that started this said
		// "⚔️ @ach_comp@Phantom Muspah Speed-Chaser").
		String plain = AnvilPlugin.stripChatTags(
			"Congratulations, you've completed a Master combat task: @ach_comp@Phantom Muspah Speed-Chaser.");
		Matcher m = AnvilPlugin.CA_TASK_PATTERN.matcher(plain);
		assertEquals(true, m.find());
		assertEquals("Master", m.group(1));
		assertEquals("Phantom Muspah Speed-Chaser",
			AnvilPlugin.CA_TASK_POINTS.matcher(m.group(2).trim()).replaceAll("").trim());
	}

	@Test
	public void aStyledRecompletionStillLosesItsPointsSuffix()
	{
		String plain = AnvilPlugin.stripChatTags(
			"Congratulations, you've completed an Elite combat task: @ach_comp@Whack-a-Mole (5 points).");
		Matcher m = AnvilPlugin.CA_TASK_PATTERN.matcher(plain);
		assertEquals(true, m.find());
		assertEquals("Whack-a-Mole",
			AnvilPlugin.CA_TASK_POINTS.matcher(m.group(2).trim()).replaceAll("").trim());
	}
}

package com.anvil;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * WHICH CLAN a request is for, once the Site URL stops naming one.
 *
 * The member types one address and one Anvil answers on it for every clan, so on the canonical form
 * the URL says nothing about which clan is meant and the server picks from the token. That works,
 * and it is invisible: a member drafted onto two live boards had no way to see which one their drops
 * were filing into, and no way to change it.
 *
 * So there are two slugs and they are not the same thing. The one the MEMBER picked wins outright.
 * The one the SERVER last said it answered for is adopted for everything else — which is what makes
 * a submission, a starting shot and its upload land in the right clan on an address that names none,
 * since those routes resolve a clan from the address rather than from the token.
 *
 * The config poll is the exception that makes Auto work: on Auto it stays unaddressed, so every poll
 * is a fresh question and a member whose live board moves to their other clan follows it.
 */
public class ClanAddressingTest
{
	private BingoApiClient client;

	@Before
	public void setUp()
	{
		client = new BingoApiClient(new Gson(), new OkHttpClient());
		client.configure("tok");
	}

	// ---- Auto: nothing chosen, nothing heard yet ---------------------------------------------------

	@Test
	public void withNothingKnownEveryUrlIsTheBareRoot()
	{
		assertEquals("https://anvilosrs.com/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		assertEquals("https://anvilosrs.com/api/plugin/config", client.configUrl("/api/plugin/config"));
		assertEquals("", client.getActiveClan());
	}

	@Test
	public void theServerSAnswerIsAdoptedForEverythingButTheNextQuestion()
	{
		client.setResolvedClan("theafkspot");

		// Everything the plugin DOES is now addressed…
		assertEquals("https://anvilosrs.com/c/theafkspot/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		assertEquals("https://anvilosrs.com/c/theafkspot/api/events/12/submissions",
			client.clanUrl("/api/events/12/submissions"));
		assertEquals("https://anvilosrs.com/c/theafkspot/api/upload", client.clanUrl("/api/upload"));

		// …but the poll that ASKS stays open, so the site can still change its mind.
		assertEquals("https://anvilosrs.com/api/plugin/config", client.configUrl("/api/plugin/config"));
		assertEquals("theafkspot", client.getActiveClan());
	}

	@Test
	public void onAutoTheSiteCanMoveUsToAnotherClan()
	{
		client.setResolvedClan("theafkspot");
		client.setResolvedClan("vanguard"); // a new board went live over there
		assertEquals("https://anvilosrs.com/c/vanguard/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
	}

	// ---- An explicit pick outranks the server ------------------------------------------------------

	@Test
	public void aMemberSPickBeatsWhateverTheServerResolved()
	{
		client.setResolvedClan("theafkspot");
		client.setChosenClan("vanguard");

		assertEquals("https://anvilosrs.com/c/vanguard/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		// And the poll is addressed too — they asked for this clan, so stop re-asking.
		assertEquals("https://anvilosrs.com/c/vanguard/api/plugin/config", client.configUrl("/api/plugin/config"));
		assertEquals("vanguard", client.getActiveClan());
	}

	@Test
	public void choosingAutoAgainHandsTheDecisionBack()
	{
		client.setResolvedClan("theafkspot");
		client.setChosenClan("vanguard");
		client.setChosenClan(""); // the Auto row

		assertEquals("https://anvilosrs.com/c/theafkspot/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		assertEquals("https://anvilosrs.com/api/plugin/config", client.configUrl("/api/plugin/config"));
	}

	// ---- The slug is validated, because it goes straight into a URL --------------------------------

	@Test
	public void anythingThatIsNotASlugNamesNoClan()
	{
		for (String bad : new String[]{
			null, "", "   ",
			"a",                                // too short for the site's own pattern
			"Not A Slug",                       // spaces
			"THEAFKSPOT/../../evil",            // traversal
			"theafkspot/api/plugin/config",     // a path, not a slug
			"the_afk_spot",                     // underscore is not in the alphabet
			"..",
			"a".repeat(33),                     // past the 32-char cap
		})
		{
			client.setChosenClan(bad);
			client.setResolvedClan(bad);
			assertEquals("rejected: " + bad,
				"https://anvilosrs.com/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		}
	}

	@Test
	public void aSlugIsLowercasedAndTrimmedRatherThanRefused()
	{
		client.setChosenClan("  TheAfkSpot  ");
		assertEquals("https://anvilosrs.com/c/theafkspot/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
	}

	// ---- Signing in is about a person, so it never carries a clan ----------------------------------

	@Test
	public void deviceSignInIsNeverAddressed()
	{
		client.setChosenClan("vanguard");
		client.setResolvedClan("theafkspot");

		// The member has no clan yet at this point — that is the whole reason they are signing in — and
		// the site's device-auth pair is a platform route that a clan prefix would only redirect out of.
		assertEquals("https://anvilosrs.com/api/plugin/auth/start", BingoApiClient.authUrl("/api/plugin/auth/start"));
		assertEquals("https://anvilosrs.com/api/plugin/auth/poll", BingoApiClient.authUrl("/api/plugin/auth/poll"));
	}

	@Test
	public void anUnconfiguredClientBuildsNothingSurprising()
	{
		BingoApiClient blank = new BingoApiClient(new Gson(), new OkHttpClient());
		blank.setResolvedClan("theafkspot");
		// No base URL: the caller checks isConfigured() before ever calling out, and the builder must
		// not throw on the way to that check.
		assertEquals("null/c/theafkspot/api/plugin/stats", blank.clanUrl("/api/plugin/stats"));
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.*;

public class ClanCofferTrackerTest
{
	@Test
	public void startsWithAZeroEffectSnapshotThenReportsMovement()
	{
		ClanCofferTracker t = new ClanCofferTracker();
		ClanCofferTracker.Observation first = t.observe(12_000_000, 1_000L);
		assertEquals(ClanCofferTracker.Kind.SNAPSHOT, first.kind);
		assertEquals(first.beforeBalance, first.afterBalance);
		assertNull(t.observe(12_000_000, 2_000L));

		ClanCofferTracker.Observation deposit = t.observe(17_000_000, 3_000L);
		assertEquals(ClanCofferTracker.Kind.DEPOSIT, deposit.kind);
		assertEquals(12_000_000, deposit.beforeBalance);
		assertEquals(17_000_000, deposit.afterBalance);
		assertFalse(deposit.actorConfirmed);
	}

	@Test
	public void matchingSelfChatAttributesOnlyTheNearbyMovement()
	{
		ClanCofferTracker t = new ClanCofferTracker();
		t.observe(10_000_000, 0L);
		t.onChatLine("You have deposited 5,000,000 coins into the Clan Coffer.", "Drenvox mdps", 1_000L);
		assertTrue(t.observe(15_000_000, 2_000L).actorConfirmed);
		assertFalse(t.observe(16_000_000, 3_000L).actorConfirmed);
	}

	@Test
	public void clanDonationWordAndPrefixedSenderAreRecognised()
	{
		ClanCofferTracker t = new ClanCofferTracker();
		t.observe(1, 0L);
		t.onChatLine("Drenvox mdps has donated to the clan coffer.", "Drenvox_mdps", 1_000L);
		assertTrue(t.observe(2, 2_000L).actorConfirmed);
	}

	@Test
	public void otherPlayersAndStaleOrWrongDirectionMessagesNeverAttribute()
	{
		ClanCofferTracker t = new ClanCofferTracker();
		t.observe(10_000_000, 0L);
		t.onChatLine("Other Person has withdrawn 1,000,000 coins from the Clan Coffer.", "Drenvox mdps", 1_000L);
		assertFalse(t.observe(9_000_000, 2_000L).actorConfirmed);

		t.onChatLine("Drenvox mdps has deposited coins into the Clan Coffer.", "Drenvox_mdps", 3_000L);
		assertFalse(t.observe(8_000_000, 4_000L).actorConfirmed);

		t.onChatLine("You have withdrawn coins from the Clan Coffer.", "Drenvox mdps", 5_000L);
		assertFalse(t.observe(7_000_000, 21_000L).actorConfirmed);
	}

	@Test
	public void resetMakesAReopenABaselineAgain()
	{
		ClanCofferTracker t = new ClanCofferTracker();
		t.observe(4, 0L);
		t.reset();
		assertEquals(ClanCofferTracker.Kind.SNAPSHOT, t.observe(9, 1L).kind);
	}
}

package com.anvil;

import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * Whole-log collection sync ({@link ClogFullSync}) — the accumulator behind the "Sync profile"
 * button. The rules that matter are all about NOT sending a fragment: a partial transmit replaces a
 * stored log, so "have the items stopped arriving" and "is this even a log" are the whole job.
 */
public class ClogFullSyncTest
{
	private static ClogFullSync receiving(int items, long at)
	{
		ClogFullSync sync = new ClogFullSync();
		sync.begin(false);
		for (int i = 1; i <= items; i++)
		{
			sync.onItem(1000 + i, 1, at);
		}
		return sync;
	}

	@Test
	public void itemsArriveAndSettleAfterTheQuietPeriod()
	{
		ClogFullSync sync = receiving(10, 1_000);
		assertEquals(10, sync.size());
		// Still arriving.
		assertFalse(sync.isDue(1_000));
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS - 1));
		assertTrue(sync.isDue(1_000 + ClogFullSync.QUIET_MS));
	}

	@Test
	public void aLateItemRestartsTheClock()
	{
		ClogFullSync sync = receiving(10, 1_000);
		sync.onItem(9999, 1, 2_500);
		assertFalse("the transmit is still going", sync.isDue(2_500 + ClogFullSync.QUIET_MS - 1));
		assertTrue(sync.isDue(2_500 + ClogFullSync.QUIET_MS));
		assertEquals(11, sync.size());
	}

	@Test
	public void aFragmentIsNeverSent()
	{
		// One stray item — another plugin's search toggle, or an interface closed mid-transmit.
		// Sending this would replace a full stored log with a single row.
		ClogFullSync sync = receiving(ClogFullSync.MIN_ITEMS - 1, 1_000);
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS * 10));
	}

	@Test
	public void nothingIsCollectedUntilATransmitStarts()
	{
		ClogFullSync sync = new ClogFullSync();
		sync.onItem(4151, 1, 1_000); // an item fired while we weren't asking
		assertEquals(0, sync.size());
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS));
	}

	@Test
	public void quantityIsKeptAndNeverBelowOne()
	{
		ClogFullSync sync = new ClogFullSync();
		sync.begin(false);
		sync.onItem(4151, 3, 1_000);
		sync.onItem(11802, 0, 1_000); // the game reports some slots without a count
		Map<Integer, Integer> snapshot = sync.snapshot();
		assertEquals(Integer.valueOf(3), snapshot.get(4151));
		assertEquals(Integer.valueOf(1), snapshot.get(11802));
	}

	@Test
	public void aSecondTransmitReplacesTheFirst()
	{
		ClogFullSync sync = receiving(10, 1_000);
		// Opening the log again re-transmits everything; the old batch must not linger and inflate it.
		sync.begin(false);
		assertEquals(0, sync.size());
		sync.onItem(4151, 1, 5_000);
		assertEquals(1, sync.size());
	}

	@Test
	public void aFailedPushKeepsTheItemsForTheNextTick()
	{
		ClogFullSync sync = receiving(10, 1_000);
		assertTrue(sync.isDue(1_000 + ClogFullSync.QUIET_MS));

		sync.onSendFailed(4_000);
		assertEquals("a site being down mustn't cost the transmit", 10, sync.size());
		assertFalse(sync.isDue(4_000));
		assertTrue(sync.isDue(4_000 + ClogFullSync.QUIET_MS));

		sync.onSent();
		assertEquals(0, sync.size());
		assertFalse(sync.isDue(9_000));
	}

	@Test
	public void aManualRequestSurvivesUntilItIsSent()
	{
		ClogFullSync sync = new ClogFullSync();
		sync.begin(true);
		assertTrue(sync.isManual());
		// Pressing the button, then opening the log (which begins its own transmit), still reports.
		sync.begin(false);
		assertTrue(sync.isManual());
		sync.onSent();
		assertFalse(sync.isManual());
	}

	@Test
	public void theFingerprintIgnoresOrderButNotContent()
	{
		ClogFullSync a = new ClogFullSync();
		a.begin(false);
		a.onItem(4151, 1, 1_000);
		a.onItem(11802, 2, 1_000);

		ClogFullSync b = new ClogFullSync();
		b.begin(false);
		b.onItem(11802, 2, 5_000);
		b.onItem(4151, 1, 5_000);
		assertEquals("the same log in any order is the same log", a.fingerprint(), b.fingerprint());

		// A new item, or another of one you had, is a different log — both must push.
		ClogFullSync more = new ClogFullSync();
		more.begin(false);
		more.onItem(4151, 1, 1_000);
		more.onItem(11802, 2, 1_000);
		more.onItem(20997, 1, 1_000);
		assertNotEquals(a.fingerprint(), more.fingerprint());

		ClogFullSync dupe = new ClogFullSync();
		dupe.begin(false);
		dupe.onItem(4151, 1, 1_000);
		dupe.onItem(11802, 3, 1_000);
		assertNotEquals(a.fingerprint(), dupe.fingerprint());
	}

	@Test
	public void switchingAccountsDropsAHalfReceivedLog()
	{
		ClogFullSync sync = receiving(10, 1_000);
		sync.reset();
		assertEquals(0, sync.size());
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS));
		// And a stray item after the reset isn't collected either.
		sync.onItem(4151, 1, 2_000);
		assertEquals(0, sync.size());
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Which thing a collection-log unlock says it came from.
 *
 * <p>The source used to be "whatever loot event happened most recently", which is right for a drop
 * announced the instant it lands and wrong for anything that arrives on its own schedule. A clue
 * reward is the clean example: kill a Saradomin wizard, open the casket that kill eventually led to,
 * and the unlock for Enchanted top was stamped <em>Saradomin wizard</em> — the last thing the player
 * hit rather than the thing the item fell out of.</p>
 *
 * <p>Nothing failed. The post went out, read plausibly, and named the wrong monster.</p>
 */
public class ClogSourceTest
{
	private static final long WINDOW = 60_000;

	private static Map<String, AnvilPlugin.RecentItem> seen(Object... triples)
	{
		Map<String, AnvilPlugin.RecentItem> m = new HashMap<>();
		for (int i = 0; i < triples.length; i += 3)
		{
			String name = (String) triples[i];
			long at = ((Number) triples[i + 1]).longValue();
			String source = (String) triples[i + 2];
			m.put(name.toLowerCase(), new AnvilPlugin.RecentItem(1, at, source));
		}
		return m;
	}

	@Test
	public void anItemIsCreditedToWhatItFellOutOf()
	{
		// Both happened inside the window; the casket is not the most recent, and is still correct.
		Map<String, AnvilPlugin.RecentItem> m = seen(
			"Enchanted top", 1_000L, "Clue Scroll (Medium)",
			"Grimy guam leaf", 5_000L, "Saradomin wizard");

		assertEquals("Clue Scroll (Medium)", AnvilPlugin.sourceOf(m, "Enchanted top", 5_000L, WINDOW));
		assertEquals("Saradomin wizard", AnvilPlugin.sourceOf(m, "Grimy guam leaf", 5_000L, WINDOW));
	}

	@Test
	public void nameLookupIgnoresCase()
	{
		Map<String, AnvilPlugin.RecentItem> m = seen("Enchanted top", 0L, "Clue Scroll (Medium)");
		assertEquals("Clue Scroll (Medium)", AnvilPlugin.sourceOf(m, "ENCHANTED TOP", 0L, WINDOW));
	}

	/** Past the window it is not this unlock's loot, and guessing is what caused the bug. */
	@Test
	public void anItemFromTooLongAgoNamesNothing()
	{
		Map<String, AnvilPlugin.RecentItem> m = seen("Enchanted top", 0L, "Clue Scroll (Medium)");
		assertNull(AnvilPlugin.sourceOf(m, "Enchanted top", WINDOW + 1, WINDOW));
	}

	@Test
	public void anUnlockWithNoLootBehindItNamesNothing()
	{
		// A skilling pet or a quest reward: the caller falls back to the recent-loot source, which is
		// the only signal there is when no loot event carried the item.
		assertNull(AnvilPlugin.sourceOf(seen(), "Rocky", 0L, WINDOW));
		assertNull(AnvilPlugin.sourceOf(seen("Rocky", 0L, ""), "Rocky", 0L, WINDOW));
		assertNull(AnvilPlugin.sourceOf(seen("Rocky", 0L, "Thieving"), null, 0L, WINDOW));
	}
}

package com.anvil;

import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The collection-log flush policy: what gets queued, what gets skipped, and what survives a restart.
 *
 * <p>The behaviour worth defending is the skipping. The game redraws a log page on every scroll and
 * tab click, so a sync that pushed what it saw would be hundreds of identical requests a session.
 */
public class ClogSyncTest
{
	private static ClogPage page(String name, int obtained, int... itemIds)
	{
		int[] quantities = new int[itemIds.length];
		java.util.Arrays.fill(quantities, 1);
		return new ClogPage(name, itemIds, quantities, obtained, 9, Collections.emptyMap());
	}

	@Test
	public void anUnchangedPageIsNeverQueuedTwice()
	{
		ClogSync sync = new ClogSync();
		assertTrue(sync.offer(page("Abyssal Sire", 2, 4151, 7979), 0));
		// The same page redrawn — scrolling, clicking away and back — is not news.
		assertFalse(sync.offer(page("Abyssal Sire", 2, 4151, 7979), 10));
		assertEquals(1, sync.pendingCount());
	}

	@Test
	public void aNewItemOnAPageRequeuesIt()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Abyssal Sire", 2, 4151, 7979), 0);
		sync.onSent(sync.nextBatch());
		assertEquals(0, sync.pendingCount());
		// Third item drops: same page, different contents, must go again.
		assertTrue(sync.offer(page("Abyssal Sire", 3, 4151, 7979, 13262), 100));
		assertEquals(1, sync.pendingCount());
	}

	@Test
	public void quantityChangesCount()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Abyssal Sire", 1, 4151), 0);
		sync.onSent(sync.nextBatch());
		int[] ids = {4151};
		int[] quantities = {2}; // second whip
		assertTrue(sync.offer(new ClogPage("Abyssal Sire", ids, quantities, 1, 9, Collections.emptyMap()), 100));
	}

	@Test
	public void flushWaitsForQuietThenGoes()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Zulrah", 1, 12345), 1_000);
		assertFalse("still browsing", sync.isDue(1_000 + ClogSync.QUIET_MS - 1));
		assertTrue("settled", sync.isDue(1_000 + ClogSync.QUIET_MS));
	}

	@Test
	public void aBigQueueGoesWithoutWaiting()
	{
		ClogSync sync = new ClogSync();
		for (int i = 0; i < ClogSync.BATCH_PAGES; i++)
		{
			sync.offer(page("Page " + i, 1, 100 + i), 0);
		}
		// A player paging through their whole log shouldn't sit behind the quiet timer.
		assertTrue(sync.isDue(1));
		assertEquals(ClogSync.BATCH_PAGES, sync.nextBatch().size());
	}

	@Test
	public void batchesAreCappedAndDrainAcrossPushes()
	{
		ClogSync sync = new ClogSync();
		for (int i = 0; i < ClogSync.BATCH_PAGES + 7; i++)
		{
			sync.offer(page("Page " + i, 1, 100 + i), 0);
		}
		List<ClogPage> first = sync.nextBatch();
		assertEquals(ClogSync.BATCH_PAGES, first.size());
		sync.onSent(first);
		assertEquals(7, sync.pendingCount());
	}

	@Test
	public void aFailedPushLeavesPagesQueued()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Vorkath", 1, 22106), 0);
		List<ClogPage> batch = sync.nextBatch();
		// onSent is only called on success, so a failure is simply not calling it.
		assertEquals(1, sync.pendingCount());
		sync.onSent(batch);
		assertEquals(0, sync.pendingCount());
	}

	@Test
	public void aPageThatChangesMidFlightStaysQueued()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Vorkath", 1, 22106), 0);
		List<ClogPage> inFlight = sync.nextBatch();
		// The drop lands while the request is on the wire.
		sync.offer(page("Vorkath", 2, 22106, 22109), 10);
		sync.onSent(inFlight);
		assertEquals("the newer version must still go", 1, sync.pendingCount());
	}

	@Test
	public void stateSurvivesARestartSoNothingIsResent()
	{
		ClogSync sync = new ClogSync();
		// A colon in the name is the case a naive "name:hash" format would corrupt.
		sync.offer(page("Chambers of Xeric: Challenge Mode", 1, 20851), 0);
		sync.onSent(sync.nextBatch());
		String state = sync.serializeState();

		ClogSync restarted = new ClogSync();
		restarted.restoreState(state);
		assertEquals(1, restarted.syncedPages());
		assertFalse("already synced before the restart",
			restarted.offer(page("Chambers of Xeric: Challenge Mode", 1, 20851), 100));
	}

	@Test
	public void malformedStateIsSkippedNotFatal()
	{
		ClogSync sync = new ClogSync();
		sync.restoreState("garbage\n|\nzzzz|Zulrah\n1a2b|Vorkath");
		assertEquals("only the valid line survives", 1, sync.syncedPages());
	}

	@Test
	public void resetForgetsTheAccount()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Zulrah", 1, 12345), 0);
		sync.onSent(sync.nextBatch());
		sync.reset();
		assertEquals(0, sync.syncedPages());
		// The next account's identical page is new information, not a duplicate.
		assertTrue(sync.offer(page("Zulrah", 1, 12345), 100));
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ClogTaskModelTest
{
	private static PluginConfigResponse.TrackedDrop drop(int id, String label, int cur, int req, Integer... items)
	{
		PluginConfigResponse.TrackedDrop d = new PluginConfigResponse.TrackedDrop();
		d.tileId = id;
		d.label = label;
		d.currentAmount = cur;
		d.requiredAmount = req;
		d.itemIds = new ArrayList<>();
		for (Integer it : items)
		{
			d.itemIds.add(it);
		}
		return d;
	}

	private static PluginConfigResponse.TrackedStat stat(int id, String label, int cur, int goal)
	{
		PluginConfigResponse.TrackedStat s = new PluginConfigResponse.TrackedStat();
		s.tileId = id;
		s.label = label;
		s.currentAmount = cur;
		s.goalAmount = goal;
		return s;
	}

	@Test
	public void statusDerivation()
	{
		assertEquals(ClogTaskModel.Status.NOT_STARTED, ClogTaskModel.statusOf(0, 5));
		assertEquals(ClogTaskModel.Status.IN_PROGRESS, ClogTaskModel.statusOf(2, 5));
		assertEquals(ClogTaskModel.Status.COMPLETED, ClogTaskModel.statusOf(5, 5));
		assertEquals(ClogTaskModel.Status.COMPLETED, ClogTaskModel.statusOf(7, 5));
		// Untargeted tile (goal <= 0): any progress completes it.
		assertEquals(ClogTaskModel.Status.NOT_STARTED, ClogTaskModel.statusOf(0, 0));
		assertEquals(ClogTaskModel.Status.COMPLETED, ClogTaskModel.statusOf(1, 0));
	}

	@Test
	public void buildIsNullSafe()
	{
		assertTrue(ClogTaskModel.build(null).isEmpty());
		assertTrue(ClogTaskModel.build(new PluginConfigResponse()).isEmpty());
	}

	@Test
	public void buildReadsEveryTrackedKind()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.trackedDrops = new ArrayList<>();
		cfg.trackedDrops.add(drop(1, "Zulrah unique", 3, 5, 12921, 12922));
		// Per-item requirement list → progress off the sets, not the summed count.
		PluginConfigResponse.TrackedDrop coll = drop(2, "Void set", 0, 1, 11665);
		coll.itemRequirements = new ArrayList<>();
		coll.itemRequirements.add(req("Void top", 1, null, 0));
		coll.itemRequirements.add(req("Void legs", 0, null, 0));
		cfg.trackedDrops.add(coll);
		cfg.trackedStats = new ArrayList<>();
		cfg.trackedStats.add(stat(3, "Mining XP", 100, 100));
		cfg.trackedKills = new ArrayList<>();
		PluginConfigResponse.TrackedKill kill = new PluginConfigResponse.TrackedKill();
		kill.tileId = 4;
		kill.requiredAmount = 10;
		kill.currentAmount = 4;
		kill.points = 7;
		cfg.trackedKills.add(kill);
		cfg.trackedTimed = new ArrayList<>();
		PluginConfigResponse.TrackedTimed timed = new PluginConfigResponse.TrackedTimed();
		timed.tileId = 5;
		timed.completed = true;
		timed.points = 3;
		cfg.trackedTimed.add(timed);
		cfg.trackedValues = new ArrayList<>();
		cfg.trackedValues.add(value("total", 50_000_000L, 12_500_000L));
		cfg.trackedValues.get(0).tileId = 6;

		List<ClogTaskModel.TaskRow> rows = ClogTaskModel.build(cfg);
		assertEquals(6, rows.size());
		assertEquals(ClogTaskModel.Status.IN_PROGRESS, rowOf(rows, 1).status);
		assertEquals(1, rowOf(rows, 2).current);
		assertEquals(2, rowOf(rows, 2).goal);
		assertTrue(rowOf(rows, 3).isCompleted());
		assertEquals(ClogTaskModel.Status.IN_PROGRESS, rowOf(rows, 4).status);
		// The timed tile carries its completed flag through.
		assertTrue(rowOf(rows, 5).isCompleted());
		// A cumulative value tile carries its gp as current/goal.
		assertEquals(12_500_000, rowOf(rows, 6).current);
		assertEquals(50_000_000, rowOf(rows, 6).goal);

		java.util.Set<Integer> none = java.util.Collections.emptySet();
		assertEquals(2, ClogTaskModel.tally(rows, none, true, false));
		assertEquals(10, ClogTaskModel.tally(rows, none, false, true));
		assertEquals(3, ClogTaskModel.tally(rows, none, true, true));
		assertEquals(1, ClogTaskModel.tally(rows, java.util.Collections.singleton(3), true, false));
		assertEquals(5, ClogTaskModel.tally(rows, java.util.Collections.singleton(3), false, false));
	}

	private static ClogTaskModel.TaskRow rowOf(List<ClogTaskModel.TaskRow> rows, int tileId)
	{
		for (ClogTaskModel.TaskRow r : rows)
		{
			if (r.tileId == tileId)
			{
				return r;
			}
		}
		throw new AssertionError("no row " + tileId);
	}

	// ---- Collection set modes (mirrors the site's lib/collectionSets) ------------------------------

	private static PluginConfigResponse.ItemRequirement req(String name, int have, String group, int groupRequire)
	{
		PluginConfigResponse.ItemRequirement r = new PluginConfigResponse.ItemRequirement();
		r.name = name;
		r.requiredAmount = 1;
		r.currentAmount = have;
		r.group = group;
		r.groupRequire = groupRequire;
		return r;
	}

	@Test
	public void flatCollectionNeedsEveryItem()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("Bandos chestplate", 1, null, 0));
		reqs.add(req("Bandos tassets", 0, null, 0));
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, null, 1));
		reqs.get(1).currentAmount = 1;
		assertArrayEquals(new int[]{ 2, 2, 1 }, ClogTaskModel.collectionProgress(reqs, null, 1));
	}

	@Test
	public void anyModeReportsTheClosestSetAndCompletesOnOne()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("Dharok's helm", 1, "Dharok", 0));
		reqs.add(req("Dharok's greataxe", 0, "Dharok", 0));
		reqs.add(req("Guthan's helm", 0, "Guthan", 0));
		reqs.add(req("Guthan's warspear", 0, "Guthan", 0));
		// Closest set, not the sum across sets.
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, "any", 1));
		reqs.get(1).currentAmount = 1;
		assertArrayEquals(new int[]{ 2, 2, 1 }, ClogTaskModel.collectionProgress(reqs, "any", 1));
	}

	@Test
	public void allModeNeedsEverySetAndOneSourceCannotFinishIt()
	{
		// One unique from each of three bosses.
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		for (String boss : new String[]{ "Duke", "Leviathan", "Whisperer" })
		{
			reqs.add(req(boss + " a", 0, boss, 1));
			reqs.add(req(boss + " b", 0, boss, 1));
		}
		assertArrayEquals(new int[]{ 0, 3, 0 }, ClogTaskModel.collectionProgress(reqs, "all", 1));

		// Both Duke uniques is still ONE source — capped at what that set needs.
		reqs.get(0).currentAmount = 1;
		reqs.get(1).currentAmount = 1;
		assertArrayEquals(new int[]{ 1, 3, 0 }, ClogTaskModel.collectionProgress(reqs, "all", 1));

		// The same board under the old OR-ed reading would have read as complete.
		assertEquals(1, ClogTaskModel.collectionProgress(reqs, "any", 1)[2]);

		reqs.get(2).currentAmount = 1; // Leviathan
		reqs.get(4).currentAmount = 1; // Whisperer
		assertArrayEquals(new int[]{ 3, 3, 1 }, ClogTaskModel.collectionProgress(reqs, "all", 1));
	}

	@Test
	public void partialSetsNeedOnlyTheirRequireCount()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		for (int i = 0; i < 6; i++)
		{
			reqs.add(req("Megarare " + i, i < 2 ? 1 : 0, "Rares", 3));
		}
		assertArrayEquals(new int[]{ 2, 3, 0 }, ClogTaskModel.collectionProgress(reqs, "any", 1));
		reqs.get(2).currentAmount = 1;
		assertArrayEquals(new int[]{ 3, 3, 1 }, ClogTaskModel.collectionProgress(reqs, "any", 1));
	}

	@Test
	public void ungroupedItemsStayRequiredAlongsideTheSets()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("Scythe of vitur", 0, null, 0));
		reqs.add(req("Duke unique", 1, "Duke", 1));
		// The set is satisfied, the always-required item isn't.
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, "all", 1));
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, "any", 1));
	}

	@Test
	public void anOlderServerSendingNoModeKeepsTheLegacyReading()
	{
		// No groupMode and no groupRequire — OR-ed full sets, exactly as before set modes existed.
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("Ahrim's hood", 1, "Ahrim", 0));
		reqs.add(req("Ahrim's staff", 1, "Ahrim", 0));
		reqs.add(req("Karil's coif", 0, "Karil", 0));
		assertArrayEquals(new int[]{ 2, 2, 1 }, ClogTaskModel.collectionProgress(reqs, null, 1));
	}

	@Test
	public void setNamesGroupCaseInsensitively()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("a", 1, "Duke", 1));
		reqs.add(req("b", 0, "duke", 1));
		reqs.add(req("c", 0, "Leviathan", 1));
		// Two sets, not three — and Duke's is already satisfied.
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, "all", 1));
	}

	@Test
	public void aStaleRequireLargerThanItsSetStaysSatisfiable()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("a", 1, "Set", 4));
		reqs.add(req("b", 1, "Set", 4));
		assertArrayEquals(new int[]{ 2, 2, 1 }, ClogTaskModel.collectionProgress(reqs, "all", 1));
	}

	// ── Cumulative value tiles ──────────────────────────────────────────────────────────────────

	private static PluginConfigResponse.TrackedValue value(String mode, long threshold, long current)
	{
		PluginConfigResponse.TrackedValue v = new PluginConfigResponse.TrackedValue();
		v.tileId = 1;
		v.label = "Bank it";
		v.mode = mode;
		v.thresholdGp = threshold;
		v.currentGp = current;
		return v;
	}

	@Test
	public void onlyTotalModeCountsAsCumulative()
	{
		assertTrue(ClogTaskModel.isTotalValue(value("total", 1, 0)));
		assertTrue(ClogTaskModel.isTotalValue(value("TOTAL", 1, 0)));
		assertFalse(ClogTaskModel.isTotalValue(value("single", 1, 0)));
		// An older server sends no mode at all, which has only ever meant single-haul.
		assertFalse(ClogTaskModel.isTotalValue(value(null, 1, 0)));
	}

	@Test
	public void multipleSetsCountAcrossSetsAndWithinOne()
	{
		java.util.List<PluginConfigResponse.ItemRequirement> reqs = new java.util.ArrayList<>();
		for (String set : new String[]{"Ahrim", "Dharok"})
		{
			for (int p = 0; p < 2; p++)
			{
				PluginConfigResponse.ItemRequirement r = new PluginConfigResponse.ItemRequirement();
				r.itemId = reqs.size() + 1;
				r.requiredAmount = 1;
				r.group = set;
				reqs.add(r);
			}
		}
		reqs.get(0).currentAmount = 1;
		reqs.get(1).currentAmount = 1;
		assertArrayEquals(new int[]{ 2, 4, 0 }, ClogTaskModel.collectionProgress(reqs, "any", 2));
		reqs.get(2).currentAmount = 1;
		assertArrayEquals(new int[]{ 3, 4, 0 }, ClogTaskModel.collectionProgress(reqs, "any", 2));
		reqs.get(3).currentAmount = 1;
		assertArrayEquals(new int[]{ 4, 4, 1 }, ClogTaskModel.collectionProgress(reqs, "any", 2));
		reqs.get(2).currentAmount = 0;
		reqs.get(3).currentAmount = 0;
		reqs.get(0).currentAmount = 2;
		reqs.get(1).currentAmount = 2;
		assertArrayEquals("one set twice", new int[]{ 4, 4, 1 }, ClogTaskModel.collectionProgress(reqs, "any", 2));
		assertEquals(2, ClogTaskModel.itemCap(reqs.get(0), "any", 2));
		assertEquals(1, ClogTaskModel.itemCap(reqs.get(0), "all", 2));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The clan broadcast for a new collection-log slot.
 *
 * <p>WHY IT IS PARSED AT ALL: the personal line — "New item added to your collection log: X" — only
 * prints when the player has the in-game collection-log notification switched on. With it off the
 * plugin saw nothing: no achievements post, no tile credit, no kill-count stamp, while the clan chat
 * announced the unlock to everyone else. The broadcast depends on the CLAN's settings instead, so
 * between the two most unlocks are seen by one line or the other.
 *
 * <p>It is only ever acted on for the local player. A clanmate's unlock belongs to their client —
 * acting on it here would post their slot from somebody else's account.
 */
public class ClogUnlockLineTest
{
	private static Matcher match(String line)
	{
		return AnvilPlugin.CLAN_CLOG_BROADCAST_PATTERN.matcher(line);
	}

	@Test
	public void readsTheNameAndTheItem()
	{
		Matcher m = match("hyperi0n received a new collection log item: Lost bag (356/1717)");
		assertTrue(m.matches());
		assertEquals("hyperi0n", m.group(1));
		assertEquals("Lost bag", m.group(2));
	}

	/** The progress tail is a clan setting, so it may simply not be there. */
	@Test
	public void theCountIsOptional()
	{
		Matcher m = match("Nisbro received a new collection log item: Twisted bow");
		assertTrue(m.matches());
		assertEquals("Twisted bow", m.group(2));
	}

	@Test
	public void keepsBracketsThatBelongToTheItem()
	{
		Matcher m = match("Zezima received a new collection log item: Ancient page 1 (part 2) (99/1717)");
		assertTrue(m.matches());
		assertEquals("Ancient page 1 (part 2)", m.group(2));
	}

	@Test
	public void toleratesATrailingStop()
	{
		Matcher m = match("Zezima received a new collection log item: Dizana's quiver (uncharged).");
		assertTrue(m.matches());
		assertEquals("Dizana's quiver (uncharged)", m.group(2));
	}

	/**
	 * The drop broadcast is a different line about a different thing, and the two must not be
	 * confused: crediting a drop as a clog slot would post it to the wrong channel.
	 */
	@Test
	public void doesNotSwallowTheDropBroadcast()
	{
		assertFalse(match("Nisbro received a drop: Elder venator fang (50,000,000 coins) from Maggot King.").matches());
	}

	/** Whose unlock it is decides whether we act, and RSN comparison is the site's rule. */
	@Test
	public void theNameIsComparedTheWayTheSiteCompares()
	{
		Matcher m = match("Hyperi0n  received a new collection log item: Lost bag (356/1717)");
		assertTrue(m.matches());
		assertTrue(Rsn.same(m.group(1), "hyperi0n"));
		assertFalse(Rsn.same(m.group(1), "someone else"));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the Combat Achievement completion chat-line parsing. CA bingo tiles credit off this
 * line (including recompletions fired by the in-game "Repeat completion" setting, which append a
 * " (N points)" suffix) — if Jagex changes the string a test here goes red and tells you CA tile
 * auto-detect broke (manual site submission is the fallback).
 */
public class CombatTaskLineTest
{
	/** Runs a line through the same parse the plugin does: match, then strip the points suffix. */
	private static String[] parse(String line)
	{
		Matcher m = AnvilPlugin.CA_TASK_PATTERN.matcher(line);
		if (!m.find())
		{
			return null;
		}
		String task = AnvilPlugin.CA_TASK_POINTS.matcher(m.group(2).trim()).replaceAll("").trim();
		return new String[]{m.group(1), task};
	}

	@Test
	public void parsesFirstCompletion()
	{
		String[] r = parse("Congratulations, you've completed an Elite combat task: Whack-a-Mole.");
		assertEquals("Elite", r[0]);
		assertEquals("Whack-a-Mole", r[1]);
	}

	@Test
	public void parsesRepeatCompletionWithPointsSuffix()
	{
		// The in-game "Repeat completion" setting re-fires the line with a points suffix.
		String[] r = parse("Congratulations, you've completed a Master combat task: Nylocas, On the Rocks (5 points).");
		assertEquals("Master", r[0]);
		assertEquals("Nylocas, On the Rocks", r[1]);
	}

	@Test
	public void parsesSinglePointSuffixAndAArticle()
	{
		String[] r = parse("Congratulations, you've completed an Easy combat task: Noxious Foe (1 point).");
		assertEquals("Easy", r[0]);
		assertEquals("Noxious Foe", r[1]);
	}

	@Test
	public void tierResolvesForEveryGroupOneValue()
	{
		String[] r = parse("Congratulations, you've completed a Grandmaster combat task: The Worst Ranged Weapon.");
		assertEquals(CombatAchievementTier.GRANDMASTER, CombatAchievementTier.byName(r[0]));
	}

	@Test
	public void ignoresUnrelatedCongratulationsLines()
	{
		assertFalse(AnvilPlugin.CA_TASK_PATTERN.matcher(
			"Congratulations, you've just advanced your Mining level. You are now level 99.").find());
	}

	@Test
	public void keepsParenthesesThatAreNotAPointsSuffix()
	{
		// Task names can legitimately end in a parenthesised qualifier — only "(N points)" strips.
		String[] r = parse("Congratulations, you've completed an Elite combat task: Chambers of Xeric: CM (Solo) Speed-Chaser.");
		assertEquals("Chambers of Xeric: CM (Solo) Speed-Chaser", r[1]);
	}

	@Test
	public void matcherRequiresTierWord()
	{
		assertTrue(AnvilPlugin.CA_TASK_PATTERN.matcher(
			"Congratulations, you've completed a Hard combat task: Whack-a-Mole.").find());
		assertFalse(AnvilPlugin.CA_TASK_PATTERN.matcher(
			"you've completed a combat task").find());
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Skill;
import org.junit.Test;

public class CompareViewTest
{
	private static PlayerCard card(String rsn, int slayer, int agility, int vorkath, int zulrahPage)
	{
		PlayerCard c = new PlayerCard();
		c.rsn = rsn;
		PlayerCard.Skill s = new PlayerCard.Skill();
		s.key = "slayer";
		s.level = slayer;
		PlayerCard.Skill a = new PlayerCard.Skill();
		a.key = "agility";
		a.level = agility;
		c.skills = Arrays.asList(s, a);
		PlayerCard.Boss b = new PlayerCard.Boss();
		b.key = "vorkath";
		b.label = "Vorkath";
		b.kc = vorkath;
		c.bosses = new ArrayList<>(List.of(b));
		PlayerCard.Page p = new PlayerCard.Page();
		p.name = "Zulrah";
		p.obtained = zulrahPage;
		p.total = 6;
		c.clogPages = List.of(p);
		return c;
	}

	@Test
	public void skillsSortByTheBiggestGap()
	{
		List<CompareView.SkillDiff> d = CompareView.skillDiffs(card("me", 99, 70, 0, 0), card("them", 98, 90, 0, 0));
		assertEquals(Skill.AGILITY, d.get(0).skill);
		assertEquals(70, d.get(0).mine);
		assertEquals(90, d.get(0).theirs);
		assertEquals(24, d.size());
	}

	@Test
	public void bossesAndPagesCarryBothSides()
	{
		List<String> names = new ArrayList<>();
		List<long[]> rows = new ArrayList<>();
		CompareView.bossDiffs(card("me", 1, 1, 800, 2), card("them", 1, 1, 50, 6), names, rows);
		assertEquals("Vorkath", names.get(0));
		assertEquals(800, rows.get(0)[0]);
		assertEquals(50, rows.get(0)[1]);
		List<String[]> pages = CompareView.pageDiffs(card("me", 1, 1, 0, 2), card("them", 1, 1, 0, 6));
		assertEquals("Zulrah", pages.get(0)[0]);
		assertTrue(CompareView.pageDiffs(card("a", 1, 1, 0, 3), card("b", 1, 1, 0, 3)).isEmpty());
	}

	@Test
	public void clueTiersMapToTheirLogPage()
	{
		assertEquals("Hard Treasure Trails", PlayerCardView.cluePage("cluesHard"));
		assertEquals("Beginner Treasure Trails", PlayerCardView.cluePage("cluesBeginner"));
		assertNull(PlayerCardView.cluePage("cluesAll"));
		assertNull(PlayerCardView.cluePage("lastManStanding"));
	}

	@Test
	public void clanCardParsesAndRenders()
	{
		String json = "{\"slug\":\"the-afk-spot\",\"name\":\"The AFK Spot\",\"members\":166,\"activeThisWeek\":40,"
			+ "\"totalEhp\":12000.5,\"totalEhb\":9000,\"topWeek\":[{\"rsn\":\"Bob\",\"hours\":12.5}],"
			+ "\"topPlayers\":[{\"rsn\":\"<html>x\",\"overallXp\":400000000}],\"clog\":{\"average\":600,\"synced\":30},"
			+ "\"highlights\":[{\"rsn\":\"Bob\",\"label\":\"Pet snakeling\",\"itemId\":12921,\"kind\":\"pet\",\"at\":\"2026-10-12T10:00:00Z\"}],"
			+ "\"competitions\":[{\"type\":\"skill\",\"metric\":\"slayer\",\"label\":\"Slayer\"}]}";
		ClanCard c = new Gson().fromJson(json, ClanCard.class);
		assertEquals(166, c.members);
		assertEquals("Bob", c.topWeek.get(0).rsn);
		// Renders with every block present (no icons in tests) and compares with itself.
		ClanCardView.render(c, PlayerCardView.Icons.NONE, name -> { }, () -> { });
		ClanCardView.compare(c, c);
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * What killed us, as opposed to what we were killing.
 *
 * <p>The feed used to name the last thing we landed a hit on, which produced "died to Abyssal
 * portal", "died to Volatile earth" and "died to Jug" — three things a player attacked and none
 * that killed anybody. A hitsplat carries no attacker, so the inference runs off who had us
 * TARGETED when we last took damage.
 */
public class DeathAttributionTest
{
	private static final long T = 1_000_000L;

	@Test
	public void namesTheThingAttackingUsRatherThanTheThingWeAttacked()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("The Whisperer", T);
		d.tookDamage(T + 100);
		// We spent the fight hitting a mechanic. It did not kill us.
		assertEquals("The Whisperer", d.killer("Volatile earth", T + 200));
	}

	@Test
	public void aMutualFightWinsOverAnythingElseOnUs()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Tekton", T);
		d.targetedUs("Abyssal portal", T + 50); // more recent, but not who we were fighting
		d.tookDamage(T + 100);
		assertEquals("Tekton", d.killer("Tekton", T + 200));
	}

	@Test
	public void otherwiseTheThingThatJustTurnedOnUs()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Guardian", T);
		d.targetedUs("Vasa Nistirio", T + 500);
		d.tookDamage(T + 600);
		// We were hitting neither; the newest acquisition is the one that finished it.
		assertEquals("Vasa Nistirio", d.killer("Muttadile", T + 700));
	}

	@Test
	public void reAcquiringUsRefreshesTheClaim()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Nylocas Ischyros", T);
		d.targetedUs("Nylocas Toxobolos", T + 100);
		d.targetedUs("Nylocas Ischyros", T + 900); // switched back onto us
		d.tookDamage(T + 950);
		assertEquals("Nylocas Ischyros", d.killer(null, T + 1_000));
	}

	@Test
	public void somethingThatStoppedAttackingUsIsNotASuspect()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Zulrah", T);
		d.tookDamage(T + 100);
		d.stoppedTargetingUs("Zulrah");
		assertNull(d.killer("Zulrah", T + 200));
	}

	@Test
	public void nothingOnUsIsAnsweredWithNothing()
	{
		// A mechanic, a fall, poison after the fight. Naming what we were hitting is exactly the bug.
		DeathAttribution d = new DeathAttribution();
		d.tookDamage(T);
		assertNull(d.killer("Jug", T + 100));
	}

	@Test
	public void damageTooOldToBeThisDeathNamesNobody()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Vorkath", T);
		d.tookDamage(T);
		assertNull(d.killer("Vorkath", T + 60_000));
	}

	@Test
	public void neverHavingTakenDamageNamesNobody()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Vorkath", T);
		assertNull(d.killer("Vorkath", T + 100));
	}

	@Test
	public void clearingEndsEveryClaim()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Vorkath", T);
		d.tookDamage(T);
		d.clear();
		assertEquals(0, d.attackerCount());
		assertNull(d.killer("Vorkath", T + 100));
	}

	@Test
	public void theAttackerListCannotGrowWithoutBound()
	{
		DeathAttribution d = new DeathAttribution();
		for (int i = 0; i < 200; i++)
		{
			d.targetedUs("Attacker " + i, T + i);
		}
		// Capped, and it is the OLDEST that get dropped — the newest arrivals are the suspects.
		assertEquals(24, d.attackerCount());
		d.tookDamage(T + 500);
		assertEquals("Attacker 199", d.killer(null, T + 600));
	}

	@Test
	public void blankNamesAreIgnoredRatherThanStored()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs(null, T);
		d.targetedUs("", T);
		d.tookDamage(T);
		assertEquals(0, d.attackerCount());
		assertNull(d.killer(null, T + 100));
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static com.anvil.DeviceSignIn.isConfiguredHomeUrl;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The sign-in browser pin: only the CONFIGURED home origin + /link-device may ever open (§8 shape,
 * anchored to the member-typed Site URL instead of a hardcoded host). */
public class DeviceSignInTest
{
	private static final String HOME = "https://clan.anvilosrs.com";

	@Test
	public void acceptsOwnLinkDevicePage()
	{
		assertTrue(isConfiguredHomeUrl(HOME, HOME + "/link-device"));
		assertTrue(isConfiguredHomeUrl(HOME, HOME + "/link-device?code=ABCD-EFGH"));
	}

	@Test
	public void refusesForeignHosts()
	{
		assertFalse(isConfiguredHomeUrl(HOME, "https://evil.com/link-device"));
		assertFalse(isConfiguredHomeUrl(HOME, "https://clan.anvilosrs.com.evil.com/link-device"));
	}

	@Test
	public void refusesLookalikeAuthorityTricks()
	{
		assertFalse(isConfiguredHomeUrl(HOME, "https://clan.anvilosrs.com@evil.com/link-device"));
		assertFalse(isConfiguredHomeUrl(HOME, "https://clan.anvilosrs.com:8443/link-device")); // port mismatch
	}

	@Test
	public void refusesOtherPathsOnOwnHost()
	{
		assertFalse(isConfiguredHomeUrl(HOME, HOME + "/"));
		assertFalse(isConfiguredHomeUrl(HOME, HOME + "/profile"));
	}

	@Test
	public void refusesSchemeDowngrade()
	{
		// A https home never opens a http page; a deliberate http dev home may open its own http page.
		assertFalse(isConfiguredHomeUrl(HOME, "http://clan.anvilosrs.com/link-device"));
		assertTrue(isConfiguredHomeUrl("http://localhost:3000", "http://localhost:3000/link-device"));
	}

	@Test
	public void refusesGarbage()
	{
		assertFalse(isConfiguredHomeUrl(HOME, null));
		assertFalse(isConfiguredHomeUrl(HOME, ""));
		assertFalse(isConfiguredHomeUrl(HOME, "javascript:alert(1)"));
		assertFalse(isConfiguredHomeUrl(null, HOME + "/link-device"));
	}

	@Test
	public void cancelledFlowRunsNoFurtherSteps()
	{
		// The flow polls on RuneLite's shared executor, which outlives the plugin; a cancel at
		// shutdown must leave every queued step a no-op (no request, no callback).
		List<Runnable> queued = new ArrayList<>();
		List<Object> callbacks = new ArrayList<>();
		DeviceSignIn flow = new DeviceSignIn(null, url -> true, (step, delayMs) -> queued.add(step));
		flow.run(callbacks::add, callbacks::add);
		flow.cancel();
		for (Runnable step : new ArrayList<>(queued))
		{
			step.run();
		}
		assertEquals(1, queued.size());
		assertTrue(callbacks.isEmpty());
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Luck / troll classification for drop posts — the difference between "spooned" and "finally".
 */
public class DropLuckTest
{
	private static final long BIG_VALUE = 50_000_000L;

	@Test
	public void obtainedShareFollowsTheDropRate()
	{
		// At exactly 1/rate kills, ~63% of players have it (1 - 1/e).
		assertEquals(0.632, DropLuck.obtainedShare(1.0 / 512, 512), 0.005);
		// A single kill at 1/512 is just the drop rate.
		assertEquals(1.0 / 512, DropLuck.obtainedShare(1.0 / 512, 1), 1e-9);
		// Missing inputs never blow up.
		assertEquals(0.0, DropLuck.obtainedShare(0, 100), 1e-9);
		assertEquals(0.0, DropLuck.obtainedShare(1.0 / 512, 0), 1e-9);
	}

	@Test
	public void earlyDropsAreSpoonedAndLongGrindsAreDry()
	{
		// 1/512 on the 20th kill: only ~4% of players are there yet.
		assertEquals(DropLuck.Verdict.SPOONED, DropLuck.classify(1.0 / 512, 20));
		// ~200 kills in: ahead of the pack, not miraculous.
		assertEquals(DropLuck.Verdict.LUCKY, DropLuck.classify(1.0 / 512, 200));
		// Around the drop rate: unremarkable.
		assertEquals(DropLuck.Verdict.TYPICAL, DropLuck.classify(1.0 / 512, 500));
		// Triple the rate: almost everyone had it by now.
		assertEquals(DropLuck.Verdict.DRY, DropLuck.classify(1.0 / 512, 1500));
	}

	@Test
	public void classifyNeedsBothARateAndAKillCount()
	{
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(null, 500));
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(1.0 / 512, null));
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(1.0 / 512, 0));
	}

	@Test
	public void trollsAreRareRollsOnWorthlessItems()
	{
		// A 1/10,000 roll on a ~35k item — the joke drop.
		assertTrue(DropLuck.isTrollDrop(1.0 / 10_000, 35_000, 10_000));
		// Same rarity, real money: just a rare drop.
		assertFalse(DropLuck.isTrollDrop(1.0 / 10_000, 5_000_000, 10_000));
		// Cheap but not rare enough to be funny — this is the herb spam we don't want.
		assertFalse(DropLuck.isTrollDrop(1.0 / 2_000, 5_000, 10_000));
		// Qualified on value alone (no rate known).
		assertFalse(DropLuck.isTrollDrop(null, 5_000, 10_000));
	}

	@Test
	public void earnedAwardsAreNeverCalledSpooned()
	{
		assertTrue(DropLuck.isEarnedAward("Infernal cape"));
		assertTrue(DropLuck.isEarnedAward("Dizana's quiver"));
		assertTrue(DropLuck.isEarnedAward("Fire cape"));
		assertFalse(DropLuck.isEarnedAward("Twisted bow"));

		// Even a 1-KC Inferno clear gets no "spooned" line — it was earned, not rolled.
		assertFalse(DropLuck.deservesSpoonLine("Infernal cape", 0, 1.0 / 1, 1, BIG_VALUE));
		// A genuine early roll does.
		assertTrue(DropLuck.deservesSpoonLine("Twisted bow", 1_000_000_000L, 1.0 / 512, 20, BIG_VALUE));
		// A dry grind doesn't get called lucky just because the item is worth a lot... unless it's
		// worth *so* much that the drop is a moment on its own.
		assertTrue(DropLuck.deservesSpoonLine("Twisted bow", 1_000_000_000L, 1.0 / 512, 1500, BIG_VALUE));
		assertFalse(DropLuck.deservesSpoonLine("Dragon spear", 35_000, 1.0 / 512, 1500, BIG_VALUE));
		// No rate/KC to judge by: value decides.
		assertFalse(DropLuck.deservesSpoonLine("Rune platebody", 38_000, null, null, BIG_VALUE));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the drop-attribution chat-line parsing against the REAL in-game message. This line is
 * the ONLY loot signal for drops that bypass both loot events (Maggot King's spill-out uniques),
 * so if Jagex changes the string a test here goes red and tells you drop auto-detect broke for
 * those bosses (manual site submission is the fallback).
 */
public class DropNotificationLineTest
{
	@Test
	public void parsesMaggotKingSpillLine()
	{
		// Exact line observed in game, following "Some loot spills out alongside the Maggot
		// King's guts. Yuck."
		Matcher m = AnvilPlugin.DROP_NOTIFICATION_PATTERN.matcher(
			"Nisbro received a drop: Elder venator fang (Maggot King)");
		assertTrue(m.matches());
		assertEquals("Nisbro", m.group(1));
		assertNull(m.group(2));
		assertEquals("Elder venator fang", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void parsesQuantityPrefixAndTrailingPeriod()
	{
		Matcher m = AnvilPlugin.DROP_NOTIFICATION_PATTERN.matcher(
			"Nisbro received a drop: 1,500 x Cannonball (Maggot King).");
		assertTrue(m.matches());
		assertEquals("1,500", m.group(2));
		assertEquals("Cannonball", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void keepsParenthesesInsideItemNames()
	{
		// Greedy item group: only the LAST parenthetical is the source.
		Matcher m = AnvilPlugin.DROP_NOTIFICATION_PATTERN.matcher(
			"Nisbro received a drop: Rune platebody (g) (Maggot King)");
		assertTrue(m.matches());
		assertEquals("Rune platebody (g)", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void ignoresClanBroadcastVariant()
	{
		// The CLAN_MESSAGE broadcast carries a value and a "from <source>" suffix. The personal
		// pattern must not match it — the broadcast has its own pattern (below) whose handler is
		// recipient-checked, and a personal-pattern match would mis-parse the source group.
		assertFalse(AnvilPlugin.DROP_NOTIFICATION_PATTERN.matcher(
			"Nisbro received a drop: Elder venator fang (50,000,000 coins) from Maggot King.").matches());
	}

	@Test
	public void parsesClanBroadcastVariant()
	{
		// Exact clan broadcast observed in game alongside (and independently of) the personal
		// line — the fallback signal when a member's in-game loot notifications are off.
		Matcher m = AnvilPlugin.CLAN_DROP_BROADCAST_PATTERN.matcher(
			"Nisbro received a drop: Elder venator fang (50,000,000 coins) from Maggot King.");
		assertTrue(m.matches());
		assertEquals("Nisbro", m.group(1));
		assertNull(m.group(2));
		assertEquals("Elder venator fang", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void clanBroadcastKeepsParenthesesInsideItemNames()
	{
		Matcher m = AnvilPlugin.CLAN_DROP_BROADCAST_PATTERN.matcher(
			"Nisbro received a drop: Rune platebody (g) (39,000 coins) from Maggot King.");
		assertTrue(m.matches());
		assertEquals("Rune platebody (g)", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void clanBroadcastDoesNotMatchPersonalLine()
	{
		// The personal line has no "(N coins) from" tail — each pattern matches only its own
		// variant so one chat line can never be parsed twice by both handlers.
		assertFalse(AnvilPlugin.CLAN_DROP_BROADCAST_PATTERN.matcher(
			"Nisbro received a drop: Elder venator fang (Maggot King)").matches());
	}

	@Test
	public void aChestsItemLinesAreReadWithoutASource()
	{
		Matcher plain = AnvilPlugin.DROP_LINE_PLAIN.matcher("Drenvox received a drop: Dagon'hai robe bottom");
		assertTrue(plain.matches());
		assertEquals("Drenvox", plain.group(1));
		assertEquals("Dagon'hai robe bottom", plain.group(3));

		Matcher stack = AnvilPlugin.DROP_LINE_PLAIN.matcher("Drenvox received a drop: 581 x Iron ore");
		assertTrue(stack.matches());
		assertEquals("581", stack.group(2));
		assertEquals("Iron ore", stack.group(3));

		Matcher valuable = AnvilPlugin.VALUABLE_DROP_LINE.matcher("Valuable drop: Dagon'hai robe bottom (573,719 coins)");
		assertTrue(valuable.matches());
		assertEquals("Dagon'hai robe bottom", valuable.group(2));

		Matcher untradeable = AnvilPlugin.VALUABLE_DROP_LINE.matcher("Untradeable drop: Dagon'hai hat");
		assertTrue(untradeable.matches());
		assertEquals("Dagon'hai hat", untradeable.group(2));
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Naming a drop's source, and reading the server's facts about it.
 */
public class DropSourceTest
{
	private static PluginConfigResponse.DropFacts facts()
	{
		PluginConfigResponse.DropFacts f = new PluginConfigResponse.DropFacts();
		f.pets = new HashMap<>();
		f.guaranteed = new HashMap<>();
		return f;
	}

	private static PluginConfigResponse.DropFacts.Pet pet(String kind, String... sources)
	{
		PluginConfigResponse.DropFacts.Pet p = new PluginConfigResponse.DropFacts.Pet();
		p.kind = kind;
		p.sources = Arrays.asList(sources);
		return p;
	}

	// ---- guaranteed drops -------------------------------------------------------------------

	@Test
	public void aGuaranteedDropIsRecognisedFromTheSourceThatOwesIt()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.guaranteed.put("ancient blood ornament kit", Arrays.asList("duke sucellus", "vardorvis"));
		assertTrue(DropSource.isGuaranteed(f, "Ancient blood ornament kit", "Duke Sucellus"));
		assertTrue(DropSource.isGuaranteed(f, "ANCIENT BLOOD ORNAMENT KIT", "vardorvis"));
		// Same item, a source that does not owe it: still a real roll.
		assertFalse(DropSource.isGuaranteed(f, "Ancient blood ornament kit", "The Whisperer"));
	}

	@Test
	public void aStarSourceMeansWhereverItDrops()
	{
		// What a clan override that named no sources stores.
		PluginConfigResponse.DropFacts f = facts();
		f.guaranteed.put("some kit", Collections.singletonList("*"));
		assertTrue(DropSource.isGuaranteed(f, "Some kit", "Anything"));
		assertTrue(DropSource.isGuaranteed(f, "Some kit", null));
	}

	@Test
	public void anOlderSiteKnowsNothingAndChangesNothing()
	{
		assertFalse(DropSource.isGuaranteed(null, "Ancient blood ornament kit", "Duke Sucellus"));
		assertFalse(DropSource.isGuaranteed(facts(), "Ancient blood ornament kit", "Duke Sucellus"));
		assertFalse(DropSource.isGuaranteed(facts(), null, "Duke Sucellus"));
	}

	// ---- pets -------------------------------------------------------------------------------

	@Test
	public void aPetComesFromItsOwnBossNotFromWhateverDroppedLootLast()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("baby mole", pet("npc", "Giant Mole"));
		// The client had just seen loot from something else entirely — a stray kill on the way out.
		assertEquals("Giant Mole", DropSource.resolvePetSource(f, "Baby mole", "Hill Giant", null));
		// And with nothing observed at all, which is the skilling-adjacent case.
		assertEquals("Giant Mole", DropSource.resolvePetSource(f, "Baby mole", null, null));
	}

	@Test
	public void whatTheClientSawWinsWhenItIsOneOfTheRealSources()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("vet'ion jr.", pet("npc", "Calvar'ion", "Vet'ion"));
		assertEquals("Vet'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", "vet'ion", null));
		assertEquals("Calvar'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", "Calvar'ion", null));
	}

	@Test
	public void severalSourcesAndNoSightingFallBackToWhereTheyActuallyGrind()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("vet'ion jr.", pet("npc", "Calvar'ion", "Vet'ion"));
		Map<String, Integer> kc = new HashMap<>();
		kc.put("calvar'ion", 12);
		kc.put("vet'ion", 940);
		assertEquals("Vet'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", null, kc));
		// No kills recorded anywhere: the first listed source beats naming nothing.
		assertEquals("Calvar'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", null, null));
	}

	@Test
	public void aSkillingPetHasNoMonsterAndDoesNotBorrowOne()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("beaver", pet("skill"));
		// Whatever loot the client saw, a Beaver did not come from it.
		assertNull(DropSource.resolvePetSource(f, "Beaver", "Hill Giant", null));
	}

	@Test
	public void anUnknownPetKeepsWhateverTheClientSaw()
	{
		// A pet released after the site's last dataset regen: the old guess is still the best there
		// is, so nothing gets worse while the server catches up.
		assertEquals("New Boss", DropSource.resolvePetSource(facts(), "Newpet", "New Boss", null));
		assertEquals("New Boss", DropSource.resolvePetSource(null, "Newpet", "New Boss", null));
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/** Naming the duplicates the game won't name — and refusing to guess when it can't be sure. */
public class DuplicateInferenceTest
{
	private static PluginConfigResponse.DropFacts.Pet pet(String kind, String skill, String... sources)
	{
		PluginConfigResponse.DropFacts.Pet p = new PluginConfigResponse.DropFacts.Pet();
		p.kind = kind;
		p.skill = skill;
		p.sources = Arrays.asList(sources);
		return p;
	}

	private static PluginConfigResponse.DropFacts facts()
	{
		PluginConfigResponse.DropFacts f = new PluginConfigResponse.DropFacts();
		f.pets = new HashMap<>();
		f.pets.put("vorki", pet("npc", null, "Vorkath"));
		f.pets.put("olmlet", pet("event", null, "Chambers of Xeric", "Chambers of Xeric Challenge Mode"));
		f.pets.put("rock golem", pet("skill", "Mining"));
		f.pets.put("heron", pet("skill", "Fishing"));
		// Two pets from one source: no single answer.
		f.pets.put("pet a", pet("npc", null, "Shared Boss"));
		f.pets.put("pet b", pet("npc", null, "Shared Boss"));
		return f;
	}

	@Test
	public void aBossNamesItsPet()
	{
		assertEquals("vorki", DuplicateInference.petForSource(facts(), "vorkath"));
		assertEquals("olmlet", DuplicateInference.petForSource(facts(), "Chambers of Xeric Challenge Mode"));
	}

	@Test
	public void aSkillNamesItsPet()
	{
		assertEquals("rock golem", DuplicateInference.petForSkill(facts(), "Mining"));
		assertNull(DuplicateInference.petForSkill(facts(), "Cooking"));
	}

	@Test
	public void ambiguityIsNotAnAnswer()
	{
		assertNull(DuplicateInference.petForSource(facts(), "Shared Boss"));
		assertNull(DuplicateInference.petForSource(facts(), "Goblin"));
		assertNull(DuplicateInference.petForSource(null, "Vorkath"));
		PluginConfigResponse.DropFacts empty = new PluginConfigResponse.DropFacts();
		empty.pets = Collections.emptyMap();
		assertNull(DuplicateInference.petForSkill(empty, "Mining"));
	}

	@Test
	public void championScrollsComeFromOneMonsterEach()
	{
		assertEquals(Integer.valueOf(ItemID.CHAMPIONS_CHALLENGE_GOBLIN), DuplicateInference.championScrollFor("Goblin"));
		assertEquals(Integer.valueOf(ItemID.CHAMPIONS_CHALLENGE_HOBGOBLIN), DuplicateInference.championScrollFor("Hobgoblin"));
		assertEquals(Integer.valueOf(ItemID.CHAMPIONS_CHALLENGE_GIANT), DuplicateInference.championScrollFor("Hill Giant"));
		assertEquals(Integer.valueOf(ItemID.CHAMPIONS_CHALLENGE_LESSERDEMON), DuplicateInference.championScrollFor("Lesser demon"));
		assertNull(DuplicateInference.championScrollFor("Greater demon"));
		assertNull(DuplicateInference.championScrollFor(null));
	}
}

package com.anvil;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The client setting a live board silently depends on.
 *
 * <p>A switch the member is not looking at turns their event off, and the board gives them no way to
 * tell. The in-game loot-drop line is what corpse-boss loot credits off, and the reminder to enable
 * it used to be gated on clan rare-drop POSTS being on, which has nothing to do with whether the
 * board needs it.</p>
 *
 * <p>There used to be a second one here: "Auto Submit Drops" governed every tile kind and the stat
 * pushes, not just drops, so one flick of it played a whole bingo for nothing — and the nudge was
 * the apology for a switch that should not have existed. The setting is gone, and submitting is
 * simply what the plugin does, so the nudge went with it.</p>
 *
 * <p>Asked only while an event is actually running: a plugin that lectures about settings for
 * something that is not happening is noise, and noise is what gets a nudge ignored.</p>
 */
public class EventNudgeTest
{
	private static PluginConfigResponse live()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.event = new PluginConfigResponse.EventInfo();
		cfg.event.name = "July Bingo";
		cfg.event.startDate = "2020-01-01T00:00:00.000Z";
		return cfg;
	}

	private static PluginConfigResponse notStarted()
	{
		PluginConfigResponse cfg = live();
		cfg.event.startDate = "2099-01-01T00:00:00.000Z";
		return cfg;
	}

	@Test
	public void aBoardWithDropTilesNeedsTheInGameDropLine()
	{
		PluginConfigResponse cfg = live();
		cfg.trackedDrops = Collections.singletonList(new PluginConfigResponse.TrackedDrop());
		assertTrue(AnvilPlugin.eventNeedsDropLines(cfg));
	}

	@Test
	public void soDoesOneWithValueTiles()
	{
		// Same signal, same reason: a haul from a corpse boss reaches neither tile kind without it.
		PluginConfigResponse cfg = live();
		cfg.trackedValues = Collections.singletonList(new PluginConfigResponse.TrackedValue());
		assertTrue(AnvilPlugin.eventNeedsDropLines(cfg));
	}

	@Test
	public void aBoardWithNeitherIsLeftAlone()
	{
		assertFalse("a KC-only board never reads that line", AnvilPlugin.eventNeedsDropLines(live()));
		assertFalse(AnvilPlugin.eventNeedsDropLines(null));

		PluginConfigResponse upcoming = notStarted();
		upcoming.trackedDrops = Collections.singletonList(new PluginConfigResponse.TrackedDrop());
		assertFalse("not until it starts", AnvilPlugin.eventNeedsDropLines(upcoming));
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import org.junit.Test;

public class GoalsViewTest
{
	private static BingoApiClient.PlayerGoal goal(String kind, String metric, int target)
	{
