package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the Jagex kill-count chat-line parsing that drives real-time boss-KC pushes, KC-line
 * kill crediting, and the KC shown on rare-drop posts. The captured boss name must exactly match
 * the server's trackedKcNames watch-list (after shared normalization), so counter words that vary
 * by activity ("completion", "chest", "success", …) and the "subdued"/"completed" prefixes must
 * never leak into it — the Gauntlet's "completion count" wording did exactly that and silently
 * killed its real-time tracking.
 */
public class KillCountLineTest
{
	/** Runs a line through the plugin's KC parse: [bossName, count], or null when it doesn't match. */
	private static String[] parse(String line)
	{
		Matcher m = AnvilPlugin.KILL_COUNT_PATTERN.matcher(line);
		if (!m.find())
		{
			return null;
		}
		return new String[]{m.group(1).trim(), m.group(2)};
	}

	@Test
	public void parsesPlainKillCount()
	{
		String[] r = parse("Your Leviathan kill count is: 42.");
		assertEquals("Leviathan", r[0]);
		assertEquals("42", r[1]);
	}

	@Test
	public void parsesRaidCompletedVariant()
	{
		String[] r = parse("Your completed Chambers of Xeric count is: 125.");
		assertEquals("Chambers of Xeric", r[0]);
		assertEquals("125", r[1]);
	}

	@Test
	public void parsesRaidModeVariantWithColon()
	{
		String[] r = parse("Your completed Tombs of Amascut: Expert Mode count is: 8.");
		assertEquals("Tombs of Amascut: Expert Mode", r[0]);
		assertEquals("8", r[1]);
	}

	@Test
	public void completionCounterWordStaysOutOfName()
	{
		String[] r = parse("Your Gauntlet completion count is: 15.");
		assertEquals("Gauntlet", r[0]);
		assertEquals("15", r[1]);
	}

	@Test
	public void corruptedGauntletCompletionVariant()
	{
		String[] r = parse("Your Corrupted Gauntlet completion count is: 3.");
		assertEquals("Corrupted Gauntlet", r[0]);
		assertEquals("3", r[1]);
	}

	@Test
	public void subduedPrefixStaysOutOfName()
	{
		String[] r = parse("Your subdued Wintertodt count is: 200.");
		assertEquals("Wintertodt", r[0]);
		assertEquals("200", r[1]);
	}

	@Test
	public void chestCounterWordStaysOutOfName()
	{
		String[] r = parse("Your Barrows chest count is: 310.");
		assertEquals("Barrows", r[0]);
		assertEquals("310", r[1]);
	}

	@Test
	public void successCounterWordStaysOutOfName()
	{
		String[] r = parse("Your Zalcano success count is: 61.");
		assertEquals("Zalcano", r[0]);
		assertEquals("61", r[1]);
	}

	@Test
	public void parsesThousandsSeparators()
	{
		String[] r = parse("Your Zulrah kill count is: 1,250.");
		assertEquals("Zulrah", r[0]);
		assertEquals("1,250", r[1]);
	}

	/**
	 * Agility-lap tiles are kill tiles whose targets are course names, so the whole kind rests on
	 * the "lap" counter word staying out of the captured name. A course whose name reaches the
	 * index as "Ardougne Rooftop lap" matches nothing and the tile counts zero for a whole event.
	 */
	@Test
	public void lapCounterWordStaysOutOfCourseName()
	{
		String[] r = parse("Your Gnome Stronghold Agility lap count is: 1.");
		assertEquals("Gnome Stronghold Agility", r[0]);
		assertEquals("1", r[1]);
	}

	@Test
	public void parsesRooftopLapCountWithApostropheAndThousands()
	{
		String[] r = parse("Your Seers' Village Rooftop lap count is: 1,234.");
		assertEquals("Seers' Village Rooftop", r[0]);
		assertEquals("1,234", r[1]);
	}

	/** The Colossal Wyrm courses parenthesise their tier — the brackets are part of the name. */
	@Test
	public void parsesParenthesisedCourseTier()
	{
		String[] r = parse("Your Colossal Wyrm Agility Course (Advanced) lap count is: 5.");
		assertEquals("Colossal Wyrm Agility Course (Advanced)", r[0]);
		assertEquals("5", r[1]);
	}

	@Test
	public void ignoresUnrelatedChat()
	{
		assertNull(parse("Your heart is racing."));
	}

	@Test
	public void parsesDoomDeepDelves()
	{
		// Doom has no kill-count line; its hiscores count is deep delves completed.
		Matcher m = AnvilPlugin.DEEP_DELVES_PATTERN.matcher("Deep delves completed: 1,893");
		assertTrue(m.find());
		assertEquals("1,893", m.group(1));
		assertFalse(AnvilPlugin.DEEP_DELVES_PATTERN.matcher("Delve level: 8+ (9) duration: 1:38. Personal best: 0:56").find());
		assertNull(parse("Deep delves completed: 893"));
	}

	@Test
	public void recognisesPickpocketLines()
	{
		// A pocket is not a kill: these lines mark the tick whose ServerNpcLoot is pickpocket loot.
		assertTrue(AnvilPlugin.PICKPOCKET_PATTERN.matcher("You pick the man's pocket.").matches());
		assertTrue(AnvilPlugin.PICKPOCKET_PATTERN.matcher("You pick the Elf's pocket.").matches());
		assertTrue(AnvilPlugin.PICKPOCKET_PATTERN.matcher("You pick the vyre's pocket.").matches());
		assertFalse(AnvilPlugin.PICKPOCKET_PATTERN.matcher("You fail to pick the man's pocket.").matches());
		assertFalse(AnvilPlugin.PICKPOCKET_PATTERN.matcher("Your Gargoyle kill count is: 154").matches());
	}
}

package com.anvil;

import java.time.Instant;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The ladder missions board's pure math ({@link LadderMissions}): the grow/decay ramp mirrors the
 * server's completionAward formula ({@code face * (1 - (1 - targetPct/100) * frac)}), and the
 * per-second countdown. Kept in lockstep with Anvil.Site/src/lib/eventRules.ts.
 */
public class LadderMissionsTest
{
	private static PluginConfigResponse.Decay decay(int targetPct, int hours)
	{
		PluginConfigResponse.Decay d = new PluginConfigResponse.Decay();
		d.targetPct = targetPct;
		d.hours = hours;
		return d;
	}

	private static String isoAgo(long ms)
	{
		return Instant.ofEpochMilli(System.currentTimeMillis() - ms).toString();
	}

	@Test
	public void faceWhenNoDecayOrNoRevealTime()
	{
		long now = System.currentTimeMillis();
		assertEquals(100, LadderMissions.liveValue(100, isoAgo(0), null, now));
		assertEquals(100, LadderMissions.liveValue(100, null, decay(50, 24), now));
		assertEquals(100, LadderMissions.liveValue(100, "not-a-time", decay(50, 24), now));
	}

	@Test
	public void decaysLinearlyToTargetOverTheWindow()
	{
		long now = System.currentTimeMillis();
		// 200-pt mission, decays to 50% over 24h. At reveal → 200; half-way (12h) → 150; full → 100; past → 100.
		PluginConfigResponse.Decay d = decay(50, 24);
		assertEquals(200, LadderMissions.liveValue(200, isoAgo(0), d, now));
		assertEquals(150, LadderMissions.liveValue(200, isoAgo(12L * 3_600_000), d, now));
		assertEquals(100, LadderMissions.liveValue(200, isoAgo(24L * 3_600_000), d, now));
		assertEquals(100, LadderMissions.liveValue(200, isoAgo(48L * 3_600_000), d, now)); // clamps at the floor
	}

	@Test
	public void growsToTargetAboveFace()
	{
		long now = System.currentTimeMillis();
		// 100-pt mission that GROWS to 200% over 10h. Half-way → 150; full → 200; capped after.
		PluginConfigResponse.Decay d = decay(200, 10);
		assertEquals(150, LadderMissions.liveValue(100, isoAgo(5L * 3_600_000), d, now));
		assertEquals(200, LadderMissions.liveValue(100, isoAgo(10L * 3_600_000), d, now));
		assertEquals(200, LadderMissions.liveValue(100, isoAgo(20L * 3_600_000), d, now));
	}

	@Test
	public void valueLabelShowsMovementOnly()
	{
		assertEquals("120", LadderMissions.valueLabel(120, 120));
		assertEquals("120 -> 90", LadderMissions.valueLabel(120, 90));
		assertEquals("120 -> 200", LadderMissions.valueLabel(120, 200));
	}

	@Test
	public void countdownFormatsMinuteSecondAndDue()
	{
		long now = System.currentTimeMillis();
		assertEquals("12:34", LadderMissions.countdown(Instant.ofEpochMilli(now + (12 * 60 + 34) * 1000L).toString(), now));
		assertEquals("0:09", LadderMissions.countdown(Instant.ofEpochMilli(now + 9_000L).toString(), now));
		assertEquals("1:02:03", LadderMissions.countdown(Instant.ofEpochMilli(now + (3600 + 2 * 60 + 3) * 1000L).toString(), now));
		assertEquals("now", LadderMissions.countdown(Instant.ofEpochMilli(now - 1000L).toString(), now));
		assertNull(LadderMissions.countdown(null, now));
		assertNull(LadderMissions.countdown("", now));
	}

	@Test
	public void isLadderMatchesOnlyLadder()
	{
		assertTrue(LadderMissions.isLadder("ladder"));
		assertTrue(LadderMissions.isLadder("Ladder"));
		assertTrue(!LadderMissions.isLadder("bingo"));
		assertTrue(!LadderMissions.isLadder(null));
	}
}

package com.anvil;

import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class LevelRulesTest
{
	private static LevelRules rules(boolean nn, int skillStep, int skillFrom, int totalStep, int totalFrom, boolean max)
	{
		return new LevelRules(nn, skillStep, skillFrom, totalStep, totalFrom, max);
	}

	private static LevelRules.Sets sets(LevelRules clan, LevelRules personal)
	{
		return new LevelRules.Sets(clan, personal);
	}

	private static PluginConfigResponse site(LevelRules.Sets levelRules, String... caps)
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.server = new PluginConfigResponse.ServerInfo();
		cfg.server.capabilities = java.util.Arrays.asList(caps);
		cfg.levelRules = levelRules;
		return cfg;
	}

	@Test
	public void skillStepsCountFromTheFromLevel()
	{
		LevelRules r = rules(false, 10, 50, 0, 0, false);
		assertTrue(r.matchesSkill(50));
		assertTrue(r.matchesSkill(70));
		assertFalse(r.matchesSkill(40));
		assertFalse(r.matchesSkill(75));
		assertFalse(r.matchesSkill(99));
		assertTrue(rules(true, 0, 1, 0, 0, false).matchesSkill(99));
		assertFalse(rules(true, 0, 1, 0, 0, false).matchesSkill(98));
	}

	@Test
	public void aMultiLevelJumpPostsTheHighestMatchingLevel()
	{
		LevelRules.Sets s = sets(rules(false, 5, 1, 0, 0, false), null);
		assertEquals(56, LevelRules.skillMilestone(54, 59, s));
		assertEquals(0, LevelRules.skillMilestone(56, 60, s)); // 56 itself is not crossed
		// Either set can supply the match: the personal 10s beat the clan's 99s-only here.
		s = sets(LevelRules.LEGACY_CLAN, rules(false, 10, 10, 0, 0, false));
		assertEquals(70, LevelRules.skillMilestone(68, 72, s));
		assertEquals(99, LevelRules.skillMilestone(95, 99, s));
		assertEquals(0, LevelRules.skillMilestone(71, 79, s));
	}

	@Test
	public void totalMilestonesAcrossAJump()
	{
		LevelRules.Sets s = sets(rules(false, 0, 1, 100, 1800, false), rules(false, 0, 1, 50, 1500, false));
		assertEquals(1850, LevelRules.totalMilestone(1795, 1860, s)); // personal 1850 beats clan 1800
		assertEquals(1800, LevelRules.totalMilestone(1795, 1849, s));
		assertEquals(0, LevelRules.totalMilestone(1801, 1849, s));
		assertEquals(0, LevelRules.totalMilestone(1440, 1499, s));
		assertEquals(1500, LevelRules.totalMilestone(1440, 1520, sets(null, rules(false, 0, 1, 50, 1500, false))));
		// The legacy floor: 1700 is under it, 1800 is not.
		LevelRules.Sets legacy = sets(LevelRules.LEGACY_CLAN, null);
		assertEquals(0, LevelRules.totalMilestone(1699, 1701, legacy));
		assertEquals(1800, LevelRules.totalMilestone(1799, 1800, legacy));
	}

	@Test
	public void maxAndNullDestinations()
	{
		assertTrue(LevelRules.wantsMax(sets(null, rules(false, 0, 1, 0, 0, true))));
		assertFalse(LevelRules.wantsMax(sets(rules(true, 0, 1, 100, 1800, false), null)));
		LevelRules.Sets none = sets(null, null);
		assertFalse(LevelRules.wantsMax(none));
		assertEquals(0, LevelRules.skillMilestone(98, 99, none));
		assertEquals(0, LevelRules.totalMilestone(1799, 1900, none));
	}

	@Test
	public void sitesWithoutLevelRulesGetTodaysBehaviour()
	{
		LevelRules.Sets s = LevelRules.resolve(site(null), true);
		assertSame(LevelRules.LEGACY_CLAN, s.clan);
		assertNull(s.personal);
		assertSame(LevelRules.LEGACY_CLAN, LevelRules.resolve(null, true).clan);
		// Rules sent without the capability are ignored like any other unadvertised surface.
		assertSame(LevelRules.LEGACY_CLAN,
			LevelRules.resolve(site(sets(null, null)), true).clan);
		// No clan channel: the clan side wants nothing, the player's own webhooks still can.
		LevelRules mine = rules(true, 0, 1, 0, 0, false);
		s = LevelRules.resolve(site(sets(LevelRules.LEGACY_CLAN, mine), "level-rules"), false);
		assertNull(s.clan);
		assertSame(mine, s.personal);
		// With the capability a null set means that destination wants nothing.
		assertNull(LevelRules.resolve(site(sets(null, mine), "level-rules"), true).clan);
		assertNull(LevelRules.resolve(null, false).clan);
	}

	@Test
	public void theWireShapeParses()
	{
		PluginConfigResponse cfg = new Gson().fromJson("{\"server\":{\"capabilities\":[\"level-rules\"]},"
			+ "\"levelRules\":{\"clan\":{\"ninetyNines\":true,\"skillStep\":10,\"skillFrom\":70,\"totalStep\":250,"
			+ "\"totalFrom\":1500,\"maxTotal\":false},\"personal\":null}}", PluginConfigResponse.class);
		LevelRules.Sets s = LevelRules.resolve(cfg, true);
		assertEquals(90, LevelRules.skillMilestone(85, 92, s));
		assertEquals(1750, LevelRules.totalMilestone(1700, 1760, s));
		assertFalse(LevelRules.wantsMax(s));
		assertNull(s.personal);
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.regex.Matcher;
import org.junit.Test;

/**
 * The level-up line, as the game prints it.
 *
 * <p>The pattern used to look for "you just advanced". The game says "you've just advanced", and has
 * for as long as it has said anything, so the chat fallback matched nothing from the day it was
 * written. It survived because the test next to it asserted the same invented sentence — written
 * from the same memory as the pattern, so the two agreed with each other and neither agreed with
 * RuneScape.</p>
 *
 * <p>Every string below is the real thing.</p>
 */
public class LevelUpLineTest
{
	private static Matcher match(String line)
	{
		Matcher m = AnvilPlugin.LEVEL_UP_PATTERN.matcher(line);
		assertTrue("should match: " + line, m.find());
		return m;
	}

	@Test
	public void readsTheLineTheGameActuallyPrints()
	{
		Matcher m = match("Congratulations, you've just advanced your Cooking level. You are now level 99.");
		assertEquals("Cooking", m.group(1));
		assertEquals("99", m.group(2));
	}

	@Test
	public void readsTheSkillsThatTakeAnArticleInsteadOfYour()
	{
		assertEquals("Agility",
			match("Congratulations, you've just advanced an Agility level. You are now level 70.").group(1));
	}

	/** Some clients render the apostrophe as a typographic one; the sentence is the same sentence. */
	@Test
	public void acceptsACurlyApostrophe()
	{
		assertEquals("Fishing",
			match("Congratulations, you’ve just advanced your Fishing level. You are now level 99.").group(1));
	}

	@Test
	public void stillReadsTheFormWithoutTheContraction()
	{
		assertEquals("Mining",
			match("Congratulations, you just advanced your Mining level. You are now level 99.").group(1));
	}

	@Test
	public void doesNotMatchAnUnrelatedCongratulation()
	{
		assertFalse(AnvilPlugin.LEVEL_UP_PATTERN
			.matcher("Congratulations, you've completed a combat task: Peach Conjurer.").find());
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.game.ItemStack;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Chest loot that lands in the looting bag: only what the bag GAINED counts, and only against a known bag. */
public class LootingBagGainsTest
{
	@Test
	public void countsOnlyIncreases()
	{
		Map<Integer, Integer> before = new HashMap<>();
		before.put(1, 5);
		before.put(2, 1);
		Map<Integer, Integer> after = new HashMap<>();
		after.put(1, 8);
		after.put(3, 2);
		List<ItemStack> gained = AnvilPlugin.lootingBagGains(before, after);
		assertEquals(2, gained.size());
		for (ItemStack s : gained)
		{
			assertEquals(s.getId() == 1 ? 3 : 2, s.getQuantity());
		}
	}

	@Test
	public void anUnknownBagCreditsNothing()
	{
		Map<Integer, Integer> after = new HashMap<>();
		after.put(1, 100);
		assertTrue(AnvilPlugin.lootingBagGains(null, after).isEmpty());
	}

	@Test
	public void matchesBothChestLines()
	{
		assertTrue(AnvilPlugin.LARRAN_OPENED.matcher("You have opened Larran's big chest 12 times.").matches());
		assertTrue(AnvilPlugin.LARRAN_OPENED.matcher("You have opened Larran's small chest 1 time.").matches());
	}

	@Test
	public void emptyingStorageIsAMoveNotAGather()
	{
		assertTrue(AnvilPlugin.isStorageMove("Empty"));
		assertTrue(AnvilPlugin.isStorageMove("Withdraw-All"));
		assertTrue(AnvilPlugin.isStorageMove("Remove"));
		org.junit.Assert.assertFalse(AnvilPlugin.isStorageMove("Fill"));
		org.junit.Assert.assertFalse(AnvilPlugin.isStorageMove("Net"));
	}
}

package com.anvil;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * Which notifications a clan's channel setup lets through.
 *
 * <p>Pets, levels, quests, diaries and collection-log slots were each announced under the name of a
 * channel they shared. They have their own names now, which puts every clan in one of two states:
 * either the site knows the new names and answered for them, or it predates the split and said
 * nothing. Only the first is a preference. The second must keep behaving as it always did, because a
 * clan that never asked for a change should not lose its 99 posts to one.</p>
 */
public class NotifyChannelTest
{
	private static PluginConfigResponse.NotifyChannels legacySite()
	{
		PluginConfigResponse.NotifyChannels n = new PluginConfigResponse.NotifyChannels();
		n.rareDrops = true;
		n.combatAchievements = true;
		return n; // pets/levels/quests/diaries/collectionLog absent, as an older site leaves them
	}

	@Test
	public void aSiteThatPredatesTheSplitKeepsPostingWhereItDid()
	{
		PluginConfigResponse.NotifyChannels n = legacySite();
		assertTrue(AnvilPlugin.channelEnabled(n, "levels"));
		assertTrue(AnvilPlugin.channelEnabled(n, "quests"));
		assertTrue(AnvilPlugin.channelEnabled(n, "diaries"));
		assertTrue(AnvilPlugin.channelEnabled(n, "collectionLog"));
		assertTrue(AnvilPlugin.channelEnabled(n, "pets"));
	}

	@Test
	public void inheritanceFollowsTheChannelEachOneUsedToShare()
	{
		PluginConfigResponse.NotifyChannels n = new PluginConfigResponse.NotifyChannels();
		n.rareDrops = true; // drops on, CAs off
		assertTrue("pets rode with drops", AnvilPlugin.channelEnabled(n, "pets"));
		assertFalse("levels rode with CAs", AnvilPlugin.channelEnabled(n, "levels"));
	}

	@Test
	public void anExplicitAnswerBeatsTheChannelItSplitFrom()
	{
		PluginConfigResponse.NotifyChannels n = legacySite();
		n.levels = false; // clan pointed levels nowhere, though CAs still have a home
		assertFalse(AnvilPlugin.channelEnabled(n, "levels"));
		assertTrue(AnvilPlugin.channelEnabled(n, "combatAchievements"));

		PluginConfigResponse.NotifyChannels off = new PluginConfigResponse.NotifyChannels();
		off.levels = true; // levels split out; the channel it came from is unset
		assertTrue(AnvilPlugin.channelEnabled(off, "levels"));
	}

	/**
	 * The old default arm answered `rareDrops` for anything it didn't recognise, so every channel
	 * added after it would have silently ridden the drop flag — on for clans that never configured it
	 * and off for clans that had.
	 */
	@Test
	public void anUnknownChannelIsOffRatherThanTreatedAsDrops()
	{
		PluginConfigResponse.NotifyChannels n = new PluginConfigResponse.NotifyChannels();
		n.rareDrops = true;
		assertFalse(AnvilPlugin.channelEnabled(n, "somethingLater"));
	}

	@Test
	public void noConfigAtAllPostsNothing()
	{
		assertFalse(AnvilPlugin.channelEnabled(null, "levels"));
	}

	@Test
	public void aPetPostUsesTheLiveServerDecisionInsteadOfTheCachedChannelFlag()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.notify = new PluginConfigResponse.NotifyChannels();
		cfg.notify.pets = false; // stale/no clan hook; a personal destination may still exist

		assertTrue(AnvilPlugin.petAnnouncementEnabled(true, true, cfg));
		assertFalse(AnvilPlugin.petAnnouncementEnabled(false, true, cfg));
		assertFalse(AnvilPlugin.petAnnouncementEnabled(true, false, cfg));
		assertFalse(AnvilPlugin.petAnnouncementEnabled(true, true, null));
	}
}

package com.anvil;

import com.google.gson.Gson;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The facts a notification carries are the whole contract with the site's lib/pluginEmbeds.ts, so
 * their exact JSON is pinned here; the site's tests pin what it builds from them.
 */
public class NotifyFactsTest
{
	@Test
	public void dropFactsLeaveOutWhatIsUnknown()
	{
		NotifyFacts f = new NotifyFacts("drop", "Zezima").put("source", "Vorkath").put("sourceKind", "npc")
			.put("kc", 54).item(22111, "Dragonbone necklace", 1, 12_345_678L).put("dropRate", 1.0 / 1000)
			.flag("guaranteed", false).flag("troll", false).flag("spoon", true).put("note", (String) null);
		assertEquals("{\"rsn\":\"Zezima\",\"source\":\"Vorkath\",\"sourceKind\":\"npc\",\"kc\":54,"
			+ "\"items\":[{\"id\":22111,\"name\":\"Dragonbone necklace\",\"qty\":1,\"value\":12345678}],"
			+ "\"dropRate\":0.001,\"spoon\":true}", f.facts.toString());
	}

	@Test
	public void aHaulCarriesEveryItemAndNoRsnWhenThereIsNone()
	{
		NotifyFacts f = new NotifyFacts("drop", null).put("source", (String) null).put("kc", (Integer) null)
			.item(1, "Item A", 1, 1_000_000L).item(2, "Item B", 4, 2_000_000L);
		assertEquals("{\"items\":[{\"id\":1,\"name\":\"Item A\",\"qty\":1,\"value\":1000000},"
			+ "{\"id\":2,\"name\":\"Item B\",\"qty\":4,\"value\":2000000}]}", f.facts.toString());
	}

	@Test
	public void achievementFacts()
	{
		assertEquals("{\"rsn\":\"Zezima\",\"task\":\"Into the Den of Giants\",\"tier\":\"Hard\",\"totalPoints\":216,"
				+ "\"nextThreshold\":726}",
			new NotifyFacts("caTask", "Zezima").put("task", "Into the Den of Giants")
				.put("tier", CombatAchievementTier.HARD.getDisplayName()).put("totalPoints", 216)
				.put("nextThreshold", 726).facts.toString());
		assertEquals("{\"rsn\":\"Zezima\",\"quest\":\"Dragon Slayer II\",\"difficulty\":\"Grandmaster\"}",
			new NotifyFacts("quest", "Zezima").put("quest", "Dragon Slayer II").put("difficulty", "Grandmaster")
				.facts.toString());
		assertEquals("{\"rsn\":\"Zezima\",\"total\":1800,\"milestone\":1800,\"current\":1803,\"max\":2277}",
			new NotifyFacts("totalLevel", "Zezima").put("total", 1800).flag("maxed", false).put("milestone", 1800)
				.put("current", 1803).put("max", 2277).facts.toString());
		// Maxed: no milestone, no distance.
		assertEquals("{\"rsn\":\"Zezima\",\"total\":2277,\"maxed\":true}",
			new NotifyFacts("totalLevel", "Zezima").put("total", 2277).flag("maxed", true)
				.put("milestone", (Integer) null).facts.toString());
	}

	@Test
	public void theRequestSendsKindAndFactsNotAnEmbed() throws Exception
	{
		assertEquals("{\"channel\":\"levels\",\"kind\":\"level\",\"facts\":{\"rsn\":\"Zezima\",\"skill\":\"Slayer\","
				+ "\"level\":90,\"at99\":12,\"skills\":23}}",
			send(new NotifyFacts("level", "Zezima").put("skill", "Slayer").put("level", 90).put("at99", 12)
				.put("skills", 23), null));
		// An older site's kind, without the level.
		assertEquals("{\"channel\":\"levels\",\"kind\":\"level99\",\"facts\":{\"rsn\":\"Zezima\",\"skill\":\"Slayer\","
				+ "\"at99\":12,\"skills\":23}}",
			send(new NotifyFacts("level99", "Zezima").put("skill", "Slayer").put("level", (Integer) null).put("at99", 12)
				.put("skills", 23), null));

		// With a screenshot it's multipart: the same JSON as payload_json, plus the named file.
		String body = send(new NotifyFacts("caTier", null).put("tier", "Elite"), new byte[]{1, 2, 3});
		assertTrue(body.contains("{\"channel\":\"levels\",\"kind\":\"caTier\",\"facts\":{\"tier\":\"Elite\"}}"));
		assertTrue(body.contains("filename=\"anvil-shot.png\""));
		assertFalse(body.contains("\"embed\""));
	}

	private static String send(NotifyFacts f, byte[] png) throws InterruptedException
	{
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<String> body = new AtomicReference<>();
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			Request r = chain.request();
			Buffer b = new Buffer();
			r.body().writeTo(b);
			body.set(b.readUtf8());
			done.countDown();
			return new Response.Builder().request(r).protocol(Protocol.HTTP_1_1).code(200).message("x")
				.body(ResponseBody.create(MediaType.parse("application/json"), "{\"ok\":true}")).build();
		}).build();
		BingoApiClient c = new BingoApiClient(new Gson(), http);
		c.configure("tok");
		c.postNotification("levels", null, f, png, "anvil-shot.png");
		assertTrue(done.await(5, TimeUnit.SECONDS));
		return body.get();
	}
}

