/**
 * Verifies quest-scroll name extraction against the REAL scroll texts RuneLite's
 * ScreenshotPlugin tests use — the scroll phrasing varies per quest, and these
 * fixtures pin the variants (plain, quoted, RFD subquests, partial/II phrasings).
 */
public class QuestScrollParseTest
{
	@Test
	public void parsesScrollVariants()
	{
		assertEquals("The Corsair Curse", AnvilPlugin.parseQuestScroll("You have completed The Corsair Curse!"));
		assertEquals("One Small Favour", AnvilPlugin.parseQuestScroll("'One Small Favour' completed!"));
		assertEquals("Rag and Bone Man II", AnvilPlugin.parseQuestScroll("You have completely completed Rag and Bone Man!"));
		assertEquals("Recipe for Disaster - Culinaromancer", AnvilPlugin.parseQuestScroll("Congratulations! You have defeated the Culinaromancer!"));
		assertEquals("Recipe for Disaster - Another Cook's Quest", AnvilPlugin.parseQuestScroll("You have completed Another Cook's Quest!"));
		assertEquals("Doric's Quest", AnvilPlugin.parseQuestScroll("You have completed Doric's Quest!"));
		assertEquals("Dragon Slayer II", AnvilPlugin.parseQuestScroll("You have completed Dragon Slayer II!"));
	}

	@Test
	public void hazeelPartialIsFlagged()
	{
		// The Hazeel Cult "kind of completed" scroll isn't a completion — the caller drops it.
		String parsed = AnvilPlugin.parseQuestScroll("You have... kind of... completed the Hazeel Cult Quest!");
		assertTrue(parsed != null && parsed.contains("partial completion"));
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Which kill-count line belongs to a drop.
 *
 * THE BUG THIS FIXES. RuneLite reports raid loot under the BASE name — its event says "Tombs of
 * Amascut" whichever mode you ran — while the game's kill-count line names the mode: "Your completed
 * Tombs of Amascut: Expert Mode count is: 220". The plugin keyed its counts on the chat name and
 * looked them up by the loot name, so the two never met, and the lookup answered with whatever the
 * NORMAL-mode count happened to be. A Masori mask off an Expert raid at 220 posted to Discord as
 * "KC 54".
 */
public class RaidKillCountTest
{
	@Test
	public void aModeCreditsItsBaseRaid()
	{
		assertTrue(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut", "Tombs of Amascut: Expert Mode"));
		assertTrue(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut", "Tombs of Amascut: Entry Mode"));
		// CoX Challenge Mode carries no colon in the game's line — punctuation is normalised away, so
		// the two spellings behave the same.
		assertTrue(AnvilPlugin.kcLineBelongsTo("Chambers of Xeric", "Chambers of Xeric Challenge Mode"));
		assertTrue(AnvilPlugin.kcLineBelongsTo("Theatre of Blood", "Theatre of Blood: Hard Mode"));
	}

	@Test
	public void theSameActivityStillMatchesItself()
	{
		assertTrue(AnvilPlugin.kcLineBelongsTo("Zulrah", "Zulrah"));
		assertTrue(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut", "Tombs of Amascut"));
	}

	@Test
	public void aLongerUNRELATEDNameIsNotAMode()
	{
		// The boundary is what stops a short name swallowing a longer one once punctuation is gone.
		// A mode adds WORDS; it never merely extends one.
		assertFalse(AnvilPlugin.kcLineBelongsTo("Kree", "Kree'Arra"));
		assertFalse(AnvilPlugin.kcLineBelongsTo("Cerb", "Cerberus"));
	}

	@Test
	public void adifferentActivityNeverMatches()
	{
		assertFalse(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut", "Chambers of Xeric"));
		assertFalse(AnvilPlugin.kcLineBelongsTo("Zulrah", "Vorkath"));
	}

	@Test
	public void theBaseDoesNotCreditFromAMoreSpecificSource()
	{
		// Direction matters. A drop from the mode should not be answered by the base raid's line —
		// only the other way round, which is the direction RuneLite's naming actually produces.
		assertFalse(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut: Expert Mode", "Tombs of Amascut"));
	}

	@Test
	public void nothingMatchesNothing()
	{
		assertFalse(AnvilPlugin.kcLineBelongsTo(null, "Zulrah"));
		assertFalse(AnvilPlugin.kcLineBelongsTo("Zulrah", null));
		assertFalse(AnvilPlugin.kcLineBelongsTo("", "Zulrah"));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Reveal-policy plumbing (showdown / lucky draw / bounty events): the {@code "reveal"} activity
 * kind and the sidebar's "still hidden" one-liner ({@link AnvilSidebarDataSource#revealNote}).
 */
public class RevealModeTest
{
	@Test
	public void revealKindParsesFromWireAndOldKindsStillMap()
	{
		assertEquals(ActivityEntry.Kind.REVEAL, ActivityEntry.Kind.fromWire("reveal"));
		assertEquals(ActivityEntry.Kind.REVEAL, ActivityEntry.Kind.fromWire(" Reveal "));
		assertEquals(ActivityEntry.Kind.COMPLETE, ActivityEntry.Kind.fromWire("complete"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("progress"));
		// Forward-compat contract: anything unknown stays a harmless progress row.
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("mystery"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire(null));
	}

	@Test
	public void revealSummaryLeadsWithTheTile()
	{
		ActivityEntry e = new ActivityEntry("r42", "2026-07-24T18:00:00Z", null, 42, "500 Zulrah KC",
			ActivityEntry.Kind.REVEAL, 0, false);
		assertEquals("New tile revealed: 500 Zulrah KC", e.summary());
	}

	private static PluginConfigResponse.EventInfo event(String policy, int hidden, String nextAt)
	{
		PluginConfigResponse.EventInfo ev = new PluginConfigResponse.EventInfo();
		ev.revealPolicy = policy;
		ev.hiddenTileCount = hidden;
		ev.nextRevealAt = nextAt;
		return ev;
	}

	@Test
	public void revealNoteIsNullForClassicBoardsAndWhenNothingIsHidden()
	{
		assertNull(AnvilSidebarDataSource.revealNote(null));
		assertNull(AnvilSidebarDataSource.revealNote(event(null, 5, null)));
		assertNull(AnvilSidebarDataSource.revealNote(event("interval", 0, null)));
	}

	@Test
	public void revealNoteCountsTilesAndBounties()
	{
		String interval = AnvilSidebarDataSource.revealNote(
			event("interval", 4, java.time.Instant.now().plusSeconds(42 * 60 + 30).toString()));
		assertTrue(interval, interval.startsWith("4 tiles hidden"));
		assertTrue(interval, interval.contains("next in 42m"));

		String scheduledNoClock = AnvilSidebarDataSource.revealNote(event("scheduled", 1, null));
		assertEquals("1 tile hidden", scheduledNoClock);

		String bounty = AnvilSidebarDataSource.revealNote(event("bounty", 3, null));
		assertEquals("3 bounties left · next on claim", bounty);

		String lastBounty = AnvilSidebarDataSource.revealNote(event("bounty", 1, null));
		assertEquals("1 bounty left · next on claim", lastBounty);
	}

	@Test
	public void revealNoteHandlesImminentAndFarReveals()
	{
		String imminent = AnvilSidebarDataSource.revealNote(
			event("interval", 2, java.time.Instant.now().plusSeconds(10).toString()));
		assertTrue(imminent, imminent.endsWith("next any minute"));

		String hours = AnvilSidebarDataSource.revealNote(
			event("interval", 2, java.time.Instant.now().plusSeconds((3 * 60 + 10) * 60 + 30).toString()));
		assertTrue(hours, hours.contains("next in 3h 10m"));

		// Malformed server stamp → drop the clock, keep the count.
		String malformed = AnvilSidebarDataSource.revealNote(event("interval", 2, "not-a-time"));
		assertEquals("2 tiles hidden", malformed);
	}
}

package com.anvil;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The Jagex Launcher's character name goes out as X-RSN-Hint, and only until a real RSN is stamped.
 *
 * The two headers mean different things on the site: X-RSN is a played name and claims, links and
 * verifies; the hint only picks which of the person's own characters a read is about. So the hint must
 * never ride alongside X-RSN, and must never be promoted into it.
 */
public class RsnHintHeaderTest
{
	private BingoApiClient client;

	@Before
	public void setUp()
	{
		client = new BingoApiClient(new Gson(), new OkHttpClient());
		client.configure("tok");
	}

	private Request request()
	{
		return client.authedRequest("https://anvilosrs.com/api/plugin/config").build();
	}

	@Test
	public void atTheLoginScreenOnlyTheHintIsSent()
	{
		client.setRsnHint("Main Guy");
		assertEquals("Main Guy", request().header("X-RSN-Hint"));
		assertNull(request().header("X-RSN"));
		assertNull(request().header("X-Account-Hash"));
	}

	@Test
	public void onceLoggedInThePlayedNameReplacesTheHint()
	{
		client.setRsnHint("Main Guy");
		client.setCurrentRsn("Main Guy");
		client.setAccountHash(42L);
		assertEquals("Main Guy", request().header("X-RSN"));
		assertNull(request().header("X-RSN-Hint"));
	}

	@Test
	public void loggingOutBringsTheHintBack()
	{
		client.setRsnHint("Main Guy");
		client.setCurrentRsn("Main Guy");
		client.setCurrentRsn(null);
		assertEquals("Main Guy", request().header("X-RSN-Hint"));
	}

	@Test
	public void offTheLauncherNothingIsSent()
	{
		client.setRsnHint(null);
		assertNull(request().header("X-RSN-Hint"));
		client.setRsnHint("  ");
		assertNull(request().header("X-RSN-Hint"));
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The plugin folds a name the same way the server does, or it matches the wrong account.
 *
 * <p>Every case here is a pair: a name the client read out of the game, and a name the site sent for
 * the same person. The site's rule is
 * {@code rsn.trim().toLowerCase().replace(/[\s_]+/g, ' ')} — the expectations below are that rule's
 * output, not this class's.</p>
 *
 * <p>There were three normalisers in this plugin. Two collapsed whitespace runs and one did not;
 * none of the three folded underscores, which the server has always done.</p>
 */
public class RsnTest
{
	@Test
	public void nothingIsAnEmptyKeyRatherThanNull()
	{
		assertEquals("", Rsn.normalize(null));
		assertEquals("", Rsn.normalize(""));
		assertEquals("", Rsn.normalize("   "));
	}

	@Test
	public void anEmptyKeyMatchesNobody()
	{
		// The guard the call sites rely on: an unknown local name must match no rows, not every row.
		assertFalse(Rsn.same(null, "Zezima"));
		assertFalse(Rsn.same("", "Zezima"));
		assertFalse(Rsn.same("", ""));
	}

	@Test
	public void caseIsCosmetic()
	{
		assertEquals("zezima", Rsn.normalize("ZEZIMA"));
		assertTrue(Rsn.same("ZEZIMA", "zezima"));
	}

	@Test
	public void theGameSNonBreakingSpaceIsAnOrdinarySpace()
	{
		// OSRS encodes the spaces in a display name as U+00A0 so a name never wraps a line; the site
		// stores a plain one. This is the oldest of the mismatches and the only one all three
		// implementations already handled.
		assertEquals("zez alt", Rsn.normalize("Zez\u00A0Alt"));
		assertTrue(Rsn.same("Zez\u00A0Alt", "Zez Alt"));
	}

	@Test
	public void anUnderscoreIsASpace()
	{
		// THE BUG. OSRS treats them as the same character: the game shows "GIM Nisbro", while logins,
		// hiscores lookups and hand-entered roster rows carry "GIM_nisbro". The site folds them
		// together; the plugin did not, so that player matched none of their own rows.
		assertEquals("gim nisbro", Rsn.normalize("GIM_nisbro"));
		assertEquals("gim nisbro", Rsn.normalize("GIM Nisbro"));
		// Both directions of the real pairing: the site's hand-entered underscore form against the
		// plain-space form, and against the non-breaking form the game actually hands us.
		assertTrue(Rsn.same("GIM Nisbro", "GIM_nisbro"));
		assertTrue(Rsn.same("GIM\u00A0Nisbro", "GIM_nisbro"));
	}

	@Test
	public void runsCollapseToOneSpace()
	{
		assertEquals("iron man", Rsn.normalize("Iron  Man"));
		assertEquals("iron man", Rsn.normalize("Iron__Man"));
		assertEquals("iron man", Rsn.normalize("Iron _\u00A0Man"));
	}

	@Test
	public void edgesAreTrimmed_includingTheOnesJavaSTrimWouldNotTouch()
	{
		// String.trim() strips only up to U+0020, so a name padded with non-breaking spaces would keep
		// them and fold to " zezima" — which equals nothing the server ever produces.
		assertEquals("zezima", Rsn.normalize("  Zezima "));
		assertEquals("zezima", Rsn.normalize("\u00A0Zezima\u00A0"));
		assertEquals("zezima", Rsn.normalize("_Zezima_"));
	}

	@Test
	public void aTurkishClientStillMatchesItsOwnRosterRow()
	{
		// The default locale lower-cases 'I' to a dotless 'ı' in Turkish, so an unqualified
		// toLowerCase() folds "IRON MIKE" to something the server has never seen — and that player
		// silently stops matching anything, on their machine only.
		java.util.Locale original = java.util.Locale.getDefault();
		try
		{
			java.util.Locale.setDefault(new java.util.Locale("tr", "TR"));
			assertEquals("iron mike", Rsn.normalize("IRON MIKE"));
			assertTrue(Rsn.same("IRON MIKE", "Iron Mike"));
		}
		finally
		{
			java.util.Locale.setDefault(original);
		}
	}

	/**
	 * The site's rule, transcribed, run over the same inputs.
	 *
	 * Not a second implementation to maintain — a statement of what this class is FOR. If somebody
	 * changes the fold here, this fails and points at the file on the other side that also has to
	 * change (and at the backfill its own comment warns about).
	 */
	@Test
	public void agreesWithTheServerSRuleAcrossTheAwkwardCases()
	{
		String[] names = {
			"Zezima", "ZEZIMA", "  Zezima ", "GIM_nisbro", "GIM Nisbro", "Iron  Man",
			"Iron__Man", "Zez\u00A0Alt", "a", "A B", "x_ y", "Mod\u00A0\u00A0Ash",
		};
		for (String name : names)
		{
			assertEquals("fold of " + escape(name), serverRule(name), Rsn.normalize(name));
		}
	}

	/** {@code rsn.trim().toLowerCase().replace(/[\s_]+/g, ' ')}, with JS's whitespace and trim. */
	private static String serverRule(String rsn)
	{
		// JS trim() and \s both include U+00A0; Java's include neither, so spell it out on both.
		String trimmed = rsn.replaceAll("^[\\s\\u00a0]+|[\\s\\u00a0]+$", "");
		return trimmed.toLowerCase(java.util.Locale.ROOT).replaceAll("[\\s\\u00a0_]+", " ");
	}

	private static String escape(String s)
	{
		return s.replace("\u00A0", "<nbsp>");
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The Hallowed Sepulchre announces itself in its own shape rather than the "Your &lt;X&gt; count
 * is: N" one every other activity uses, so agility tiles targeting it rest entirely on these two
 * patterns. Both lines carry a running total that must stay OUT of the credit path — one line is
 * one credit, so a player arriving with 4,000 coffins already opened starts an event on zero.
 */
public class SepulchreLineTest
{
	private static String floorOf(String line)
	{
		Matcher m = AnvilPlugin.SEPULCHRE_FLOOR_PATTERN.matcher(line);
		return m.find() ? m.group(1) : null;
	}

	@Test
	public void parsesFloorCompletion()
	{
		Matcher m = AnvilPlugin.SEPULCHRE_FLOOR_PATTERN.matcher(
			"You have completed Floor 3 of the Hallowed Sepulchre! Total completions: 1,234.");
		assertTrue(m.find());
		assertEquals("3", m.group(1));
		assertEquals("1,234", m.group(2));
	}

	/** Every floor announces separately — a full 1→5 run emits five lines, so five credits. */
	@Test
	public void parsesEveryFloor()
	{
		for (int floor = 1; floor <= 5; floor++)
		{
			String line = "You have completed Floor " + floor
				+ " of the Hallowed Sepulchre! Total completions: 7.";
			assertEquals(String.valueOf(floor), floorOf(line));
		}
	}

	@Test
	public void parsesGrandHallowedCoffinPlural()
	{
		assertTrue(AnvilPlugin.SEPULCHRE_COFFIN_PATTERN
			.matcher("You have opened the Grand Hallowed Coffin 42 times!").find());
	}

	/** The first-ever coffin says "1 time!", not "1 times!" — the optional s is load-bearing. */
	@Test
	public void parsesGrandHallowedCoffinSingular()
	{
		assertTrue(AnvilPlugin.SEPULCHRE_COFFIN_PATTERN
			.matcher("You have opened the Grand Hallowed Coffin 1 time!").find());
	}

	/**
	 * The Sepulchre lines must not also match the generic KC parser: a double match would credit a
	 * floor twice on clients where a tile happens to carry both name shapes.
	 */
	@Test
	public void sepulchreLinesDoNotMatchTheGenericKcParser()
	{
		assertFalse(AnvilPlugin.KILL_COUNT_PATTERN
			.matcher("You have completed Floor 3 of the Hallowed Sepulchre! Total completions: 12.").find());
		assertFalse(AnvilPlugin.KILL_COUNT_PATTERN
			.matcher("You have opened the Grand Hallowed Coffin 42 times!").find());
	}

	@Test
	public void ignoresUnrelatedChat()
	{
		assertEquals(null, floorOf("You have completed the Hallowed Sepulchre course."));
		assertFalse(AnvilPlugin.SEPULCHRE_COFFIN_PATTERN
			.matcher("You have opened the coffin.").find());
	}

	// ---- Hunter Guild rumours -------------------------------------------------------------

	@Test
	public void parsesRumourCompletion()
	{
		assertTrue(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed 42 rumours for the Hunter Guild.").find());
		assertTrue(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed 1,250 rumours for the Hunter Guild.").find());
	}

	/** The first hand-in reads "1 rumour" — the optional s is load-bearing, as with the coffin. */
	@Test
	public void parsesSingularRumour()
	{
		assertTrue(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed 1 rumour for the Hunter Guild.").find());
	}

	@Test
	public void rumourLineIsNotConfusedWithTheSepulchreFloorLine()
	{
		assertFalse(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed Floor 3 of the Hallowed Sepulchre! Total completions: 12.").find());
		assertEquals(null, floorOf("You have completed 42 rumours for the Hunter Guild."));
	}

	// ---- Woodcutting Guild egg offerings --------------------------------------------------

	@Test
	public void parsesEggOfferings()
	{
		assertTrue(AnvilPlugin.EGG_OFFERING_PATTERN.matcher("You have made 7 offerings.").find());
		assertTrue(AnvilPlugin.EGG_OFFERING_PATTERN.matcher("You have made 1,024 offerings.").find());
	}

	/** The first offering reads "one offering", spelled out — not a digit. */
	@Test
	public void parsesFirstEggOfferingSpelledOut()
	{
		assertTrue(AnvilPlugin.EGG_OFFERING_PATTERN.matcher("You have made one offering.").find());
	}

	/**
	 * The offering line never names the activity, so the trailing full stop is the only thing
	 * stopping it from swallowing longer sentences that merely start the same way.
	 */
	@Test
	public void offeringLineDoesNotSwallowLongerSentences()
	{
		assertFalse(AnvilPlugin.EGG_OFFERING_PATTERN
			.matcher("You have made 3 offerings to the shrine and received nothing").find());
	}

	// ---- Brimhaven Agility Arena ----------------------------------------------------------

	/**
	 * Brimhaven counts TICKETS, and its counter word is two words long. Without it in the pattern
	 * the arena's name parses as "Agility Arena Total Ticket" and matches no tile.
	 */
	@Test
	public void brimhavenTicketCounterWordStaysOutOfTheName()
	{
		Matcher m = AnvilPlugin.KILL_COUNT_PATTERN
			.matcher("Your Agility Arena Total Ticket count is: 480.");
		assertTrue(m.find());
		assertEquals("Agility Arena", m.group(1).trim());
		assertEquals("480", m.group(2));
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * What the plugin says about its own setup.
 *
 * THE CASE THIS EXISTS FOR: nothing configured at all. It used to fall out of the comparison as
 * "both agree, so say nothing", which is right for a connected install and wrong for a fresh one —
 * and a fresh one is now the normal way in, since an Anvil account is a person's rather than a
 * clan's hand-me-down. The cap is the other half: it has to stop, and it has to stop across
 * restarts, or the nudge becomes the reason somebody removes the plugin.
 */
public class SetupNudgeTest
{
	@Test
	public void aFreshInstallIsToldWhereToGo()
	{
		assertEquals(SetupNudge.Kind.FIRST_RUN, SetupNudge.decide("", 0));
		assertEquals(SetupNudge.Kind.FIRST_RUN, SetupNudge.decide(null, 0));
		assertEquals("blank is empty, whitespace included", SetupNudge.Kind.FIRST_RUN,
			SetupNudge.decide("\t", 0));
	}

	@Test
	public void theFreshInstallLineStopsAfterTheCap()
	{
		assertEquals(SetupNudge.Kind.FIRST_RUN, SetupNudge.decide("", SetupNudge.FIRST_RUN_NUDGES - 1));
		assertEquals(SetupNudge.Kind.NONE, SetupNudge.decide("", SetupNudge.FIRST_RUN_NUDGES));
		assertEquals("a count from a mangled config never re-arms it", SetupNudge.Kind.NONE,
			SetupNudge.decide("", 99));
	}

	@Test
	public void aConnectedInstallIsLeftAlone()
	{
		assertEquals(SetupNudge.Kind.NONE, SetupNudge.decide("tok", 0));
		assertArrayEquals(new String[0], SetupNudge.lines(SetupNudge.Kind.NONE));
	}

	@Test
	public void theFreshInstallLinesNameTheSiteAndTheButton()
	{
		String[] lines = SetupNudge.lines(SetupNudge.Kind.FIRST_RUN);
		assertEquals(2, lines.length);
		assertTrue("the instruction names the button that does it", lines[0].contains("Sign in with Discord"));
		assertTrue("the reason names where the account lives", lines[1].contains(SetupNudge.SITE_HOST));
		assertTrue("and that a clan is not a prerequisite", lines[1].contains("No clan needed"));
	}

	@Test
	public void theSiteHostIsTheAddressThePluginUses()
	{
		// One source of truth: the chat line and the plugin's only server cannot drift apart.
		assertEquals("anvilosrs.com", SetupNudge.SITE_HOST);
		assertTrue(BingoApiClient.CANONICAL_SITE.endsWith(SetupNudge.SITE_HOST));
	}
}

package com.anvil;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The lists that moved out of AnvilPlugin into anvil_text.json load back intact — same entries, same
 * order, emoji and quotes included — through the same Gson path startUp uses.
 */
public class ShippedTextTest
{
	@Test
	public void loadsEveryList() throws Exception
	{
		AnvilPlugin.ShippedText text;
		try (Reader r = new InputStreamReader(AnvilPlugin.class.getResourceAsStream("/anvil_text.json"), StandardCharsets.UTF_8))
		{
			text = new Gson().fromJson(r, AnvilPlugin.ShippedText.class);
		}
		assertEquals(24, text.alwaysNotify.size());
		assertEquals("infernal cape", text.alwaysNotify.get(0));
		assertEquals("fire cape", text.alwaysNotify.get(23));
		assertEquals(Arrays.asList(
			"{name} has been sent to Lumbridge to think about their choices.",
			"{name} forgot to flick Protect from Magic. Classic.",
			"{name} died doing what they loved: not eating.",
			"Press F for {name}.",
			"{name} just speedran a trip to Lumbridge."), text.funDeaths);
		assertEquals(Arrays.asList(
			"Sit. 🪑", "L + ratio.", "Skill issue.", "Couldn't be me.", "GG go next.",
			"Have you tried eating?", "That's gotta hurt.", "Prayer was off, wasn't it?", "Get good. 🤡"), text.deathTaunts);
		assertEquals("GRANDMASTER", text.questTiers.get("desert treasure ii"));
		assertEquals("MASTER", text.questTiers.get("recipe for disaster - culinaromancer"));
		assertEquals("MASTER", text.questTiers.get("legends' quest"));
		assertEquals("MASTER", text.questTiers.get("desert treasure"));
		assertEquals("NOVICE", text.questTiers.get("cook's assistant"));
